    function getChatLaborSellExpectedHourlyWage() {
        const expectedM = Number(config.features?.chatLaborSellExpectedHourlyM);
        return Number.isFinite(expectedM) ? expectedM * 1e6 : 0;
    }

    function getChatLaborBuyExpectedHourlyWage() {
        const expectedM = Number(config.features?.chatLaborBuyExpectedHourlyM);
        return Number.isFinite(expectedM) ? expectedM * 1e6 : 15e6;
    }

    function getChatLaborSellExpectedHourlyM() {
        return getChatLaborSellExpectedHourlyWage() / 1e6;
    }

    function getChatLaborBuyExpectedHourlyM() {
        return getChatLaborBuyExpectedHourlyWage() / 1e6;
    }

    function isChatLaborEmphasisEnabled() {
        return config.features?.chatLaborEmphasis !== false;
    }

    function getChatLaborProfitDimBelowM() {
        const value = Number(config.features?.chatLaborProfitDimBelowM);
        return Number.isFinite(value) ? value : 0;
    }

    function getChatLaborProfitHighlightAboveM() {
        const value = Number(config.features?.chatLaborProfitHighlightAboveM);
        return Number.isFinite(value) ? value : 0;
    }

    function mooncakeClassifyChatProfit(profit) {
        if (!isChatLaborEmphasisEnabled() || !Number.isFinite(Number(profit))) return 'neutral';
        const profitM = Number(profit) / 1e6;
        if (profitM < getChatLaborProfitDimBelowM()) return 'dim';
        if (profitM > getChatLaborProfitHighlightAboveM()) return 'highlight';
        return 'neutral';
    }

    function setChatLaborEmphasisEnabled(value) {
        if (!config.features) config.features = {};
        config.features.chatLaborEmphasis = value !== false;
        saveConfig();
        mooncakeUpdateChatLaborControls();
        if (isChatLaborEnabled()) refreshMooncakeChatLabor();
    }

    function setChatLaborProfitThresholdM(kind, value) {
        const text = String(value ?? '').trim();
        if (!text) return false;
        const numeric = Number(text);
        if (!Number.isFinite(numeric)) return false;
        if (!config.features) config.features = {};
        const normalized = Math.max(-1000000, Math.min(1000000, Math.round(numeric * 1000) / 1000));
        if (kind === 'dim') {
            config.features.chatLaborProfitDimBelowM = normalized;
            if (normalized > getChatLaborProfitHighlightAboveM()) {
                config.features.chatLaborProfitHighlightAboveM = normalized;
            }
        } else if (kind === 'highlight') {
            config.features.chatLaborProfitHighlightAboveM = normalized;
            if (normalized < getChatLaborProfitDimBelowM()) {
                config.features.chatLaborProfitDimBelowM = normalized;
            }
        } else {
            return false;
        }
        saveConfig();
        mooncakeUpdateChatLaborControls();
        if (isChatLaborEnabled()) refreshMooncakeChatLabor();
        return true;
    }

    function setChatLaborExpectedHourlyM(side, value) {
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) return false;
        if (!config.features) config.features = {};
        const normalized = Math.max(-1000000, Math.min(1000000, numeric));
        if (side === 'sell') config.features.chatLaborSellExpectedHourlyM = normalized;
        else config.features.chatLaborBuyExpectedHourlyM = normalized;
        saveConfig();
        mooncakeUpdateChatLaborControls();
        if (isChatLaborEnabled()) refreshMooncakeChatLabor();
        return true;
    }

