    function getLootLogContainer() {
        return document.querySelector(LOOT_LOG_LIST_SELECTOR);
    }

    function setupRefreshButtonHook() {
        const panel = document.querySelector(LOOT_LOG_PANEL_SELECTOR);
        if (!panel) return;

        const refreshButton = panel.querySelector(REFRESH_BUTTON_SELECTOR);
        if (!refreshButton || refreshButton.dataset.eltBound === '1') return;

        refreshButton.dataset.eltBound = '1';
        refreshButton.addEventListener('click', () => {
            setTimeout(() => processLootLogs({ force: true }), 0);
        });
    }

    function findLootLogNativeToolbar(panel, lootContainer) {
        const refreshButton = panel?.querySelector(REFRESH_BUTTON_SELECTOR);
        if (!refreshButton) return null;

        let candidate = refreshButton.parentElement;
        while (candidate && candidate !== panel) {
            const buttonCount = candidate.querySelectorAll('button').length;
            if (buttonCount >= 2 && !candidate.contains(lootContainer)) return candidate;
            candidate = candidate.parentElement;
        }
        return null;
    }

    function setupLootLogStickyToolbars(lootContainer, pluginToolbar) {
        const panel = document.querySelector(LOOT_LOG_PANEL_SELECTOR);
        if (!panel || !lootContainer || !pluginToolbar) return;

        const nativeToolbar = findLootLogNativeToolbar(panel, lootContainer);
        if (!nativeToolbar) {
            // 找不到游戏原生工具栏时，插件工具栏仍可独立固定。
            pluginToolbar.style.position = 'sticky';
            pluginToolbar.style.top = '0';
            pluginToolbar.style.zIndex = '75';
            pluginToolbar.style.alignSelf = 'stretch';
            pluginToolbar.style.boxSizing = 'border-box';
            pluginToolbar.style.background = 'rgba(17, 18, 24, 0.98)';
            pluginToolbar.style.boxShadow = '0 4px 10px rgba(0, 0, 0, 0.35)';
            return;
        }

        // 原生工具栏原本位于另一个滚动边界内，导致它会先于记录列表离开视口。
        // 将整个工具栏置于记录列表首位后，原生与插件按钮共享同一粘性容器。
        if (nativeToolbar.parentElement !== lootContainer || lootContainer.firstElementChild !== nativeToolbar) {
            lootContainer.prepend(nativeToolbar);
        }
        if (pluginToolbar.parentElement !== nativeToolbar) {
            nativeToolbar.append(pluginToolbar);
        }

        nativeToolbar.style.position = 'sticky';
        nativeToolbar.style.top = '0';
        nativeToolbar.style.zIndex = '75';
        nativeToolbar.style.display = 'flex';
        nativeToolbar.style.alignItems = 'center';
        nativeToolbar.style.flexWrap = 'wrap';
        nativeToolbar.style.gap = '8px';
        nativeToolbar.style.width = '100%';
        nativeToolbar.style.margin = '0';
        nativeToolbar.style.padding = '8px 12px';
        nativeToolbar.style.boxSizing = 'border-box';
        nativeToolbar.style.background = 'rgba(17, 18, 24, 0.98)';
        nativeToolbar.style.boxShadow = '0 4px 10px rgba(0, 0, 0, 0.35)';

        // display: contents 让插件的三个按钮直接参与原生工具栏的同一行排版；
        // 展开的全局设置面板保留为独占下一行的内容。
        pluginToolbar.style.display = 'contents';
        pluginToolbar.style.position = 'static';
        pluginToolbar.style.margin = '0';
        pluginToolbar.style.padding = '0';
        pluginToolbar.style.background = 'transparent';
        pluginToolbar.style.boxShadow = 'none';

        const settingsPanel = pluginToolbar.querySelector('.enhancement-loot-tracker-global-settings');
        if (settingsPanel) {
            settingsPanel.style.flex = '1 0 100%';
        }
    }

    // ======================
    // 数据访问帮助函数
    // ======================

    function decompressInitClientData(compressedData) {
        try {
            const decompressedJson = LZString.decompressFromUTF16(compressedData);
            if (!decompressedJson) {
                throw new Error("decompressInitClientData: decompressFromUTF16() returned null");
            }
            return JSON.parse(decompressedJson);
        } catch (error) {
            console.error("[Better Loot Tracker] decompressInitClientData: ", error);
            return null;
        }
    }

    let _cachedInitClientData = null;

    function getInitClientData() {
        if (_cachedInitClientData) return _cachedInitClientData;

        const stored = localStorage.getItem("initClientData");
        if (!stored) return null;

        // 解压缩
        const decompressed = decompressInitClientData(stored);
        if (decompressed) {
            _cachedInitClientData = decompressed;
            return decompressed;
        }

        return null;
    }

    // 在控制台输出initData的函数
    function logInitData() {
        const initData = getInitClientData();
        if (initData) {
            console.log('=== Init Client Data ===');
            console.log('Item Detail Map:', Object.keys(initData.itemDetailMap || {}).length, 'items');
            console.log('Action Detail Map:', Object.keys(initData.actionDetailMap || {}).length, 'actions');
            console.log('Shop Item Detail Map:', Object.keys(initData.shopItemDetailMap || {}).length, 'shop items');
            console.log('Full initData:', initData);
        } else {
            console.log('No initClientData found in localStorage');
        }
    }

    // 暴露到全局，方便在控制台调用
    window.logInitData = logInitData;

    const MARKET_CACHE_KEY = 'MWITools_marketAPI_json';
    const MWI_CORE_MARKET_CACHE_KEY = 'MWICore_marketData';
    const OWN_CACHE_KEY = 'MoonCake_marketCache';
    let marketDataCache = null;
    let marketDetailSnapshotCache = {};
    let mooncakeMarketPricingRevision = 0;

    function getMarketApiUrl() {
        const host = location.hostname;
        if (host.includes("test.milkywayidle.com")) {
            return "https://test.milkywayidle.com/game_data/marketplace.json";
        } else if (host.includes("test.milkywayidlecn.com")) {
            return "https://test.milkywayidlecn.com/game_data/marketplace.json";
        } else if (host.includes("milkywayidlecn.com")) {
            return "https://www.milkywayidlecn.com/game_data/marketplace.json";
        }
        return "https://www.milkywayidle.com/game_data/marketplace.json";
    }

    async function fetchMarketApi() {
        try {
            const url = getMarketApiUrl();
            const resp = await fetch(url);
            if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
            const data = await mooncakeReadJsonResponse(resp);
            if (data?.marketData) {
                marketDataCache = data.marketData;
                mooncakeMarketPricingRevision++;
                mooncakeClearEnhancementRouteCache();
                try { mooncakeScheduleMyListingsTargetFilter(0); } catch (_) {}
                try {
                    if (mooncakeMyListingsManagementState?.undercut) mooncakeScheduleMyListingsManagement();
                } catch (_) {}
            }
        } catch (e) {
            console.warn('[MoonCake] Failed to fetch market API:', e);
        }
    }

    function normalizeMWICoreMarketData(raw) {
        const normalized = { marketData: {} };
        if (!raw || typeof raw !== 'object') return normalized;
        for (const [compoundKey, priceObj] of Object.entries(raw)) {
            if (!compoundKey || typeof compoundKey !== 'string' || !priceObj || typeof priceObj !== 'object') continue;
            const splitIndex = compoundKey.lastIndexOf(':');
            if (splitIndex <= 0 || splitIndex >= compoundKey.length - 1) continue;
            const itemHrid = compoundKey.slice(0, splitIndex);
            const level = parseInt(compoundKey.slice(splitIndex + 1), 10);
            if (!itemHrid || !Number.isFinite(level) || level < 0 || level > 20) continue;
            if (!normalized.marketData[itemHrid]) normalized.marketData[itemHrid] = {};
            normalized.marketData[itemHrid][level] = {
                a: Number.isFinite(Number(priceObj.ask)) ? Number(priceObj.ask) : -1,
                b: Number.isFinite(Number(priceObj.bid)) ? Number(priceObj.bid) : -1
            };
        }
        return normalized;
    }

    function readMWIToolsMarketData() {
        try {
            const marketDataStr = localStorage.getItem(MARKET_CACHE_KEY);
            if (!marketDataStr) return null;
            const parsed = JSON.parse(marketDataStr);
            return parsed?.marketData ? parsed : null;
        } catch (e) {
            console.error('[Better Loot Tracker] Error loading MWITools market data:', e);
            return null;
        }
    }

    function readMWICoreMarketData() {
        try {
            const marketDataStr = localStorage.getItem(MWI_CORE_MARKET_CACHE_KEY);
            if (!marketDataStr) return null;
            return normalizeMWICoreMarketData(JSON.parse(marketDataStr));
        } catch (e) {
            console.error('[Better Loot Tracker] Error loading MWICore market data:', e);
            return null;
        }
    }

    function cleanupLegacyMarketCaches() {
        try { localStorage.removeItem(OWN_CACHE_KEY); } catch (_) {}
        try { localStorage.removeItem(MOONCAKE_MARKET_HISTORY_V1_CACHE_KEY); } catch (_) {}
        try { localStorage.removeItem(MOONCAKE_MARKET_HISTORY_V2_CACHE_KEY); } catch (_) {}
    }

    function mooncakeGetOrderBookBestPrice(orderBook, side) {
        const listings = Array.isArray(orderBook?.[side]) ? orderBook[side] : [];
        let best = side === 'asks' ? Infinity : -Infinity;
        for (const listing of listings) {
            const price = Number(listing?.price);
            if (!(price > 0) || !Number.isFinite(price)) continue;
            best = side === 'asks' ? Math.min(best, price) : Math.max(best, price);
        }
        return Number.isFinite(best) ? best : -1;
    }

    function mooncakeGetUsableMarketQuote(...quotes) {
        for (const quote of quotes) {
            const price = Number(quote);
            if (Number.isFinite(price) && price > 0) return price;
        }
        return -1;
    }

    function mooncakeResolveEnhancementMarketQuotes(itemHrid, enhancementLevel, bid, ask, timestamp = null) {
        const level = Math.max(0, Math.min(20, Math.floor(Number(enhancementLevel) || 0)));
        const snapshot = marketDetailSnapshotCache?.[`${itemHrid}:${level}`];
        const marketLevel = getMarketData()?.marketData?.[itemHrid]?.[String(level)];
        return {
            // The order-book snapshot is the newest source. It also makes delayed renders
            // (tab creation and high-level prewarm) use the price that arrived meanwhile.
            bid: mooncakeGetUsableMarketQuote(snapshot?.bid, bid, marketLevel?.b),
            ask: mooncakeGetUsableMarketQuote(snapshot?.ask, ask, marketLevel?.a),
            time: snapshot?.time ?? timestamp
        };
    }

    const MOONCAKE_ORDER_BOOK_ARCHIVE_ENABLED_KEY = 'Mooncake_orderBookArchive_enabled_v1';
    const MOONCAKE_ORDER_BOOK_ARCHIVE_LIMIT_KEY = 'Mooncake_orderBookArchive_limit_v1';
    const MOONCAKE_ORDER_BOOK_ARCHIVE_DB = 'MooncakeOrderBookArchive';
    const MOONCAKE_ORDER_BOOK_ARCHIVE_STORE = 'snapshots';
    const MOONCAKE_ORDER_BOOK_ARCHIVE_DEFAULT_LIMIT = 3000;
    const MOONCAKE_ORDER_BOOK_ARCHIVE_MIN_LIMIT = 100;
    const MOONCAKE_ORDER_BOOK_ARCHIVE_MAX_LIMIT = 100000;
    const MOONCAKE_ORDER_BOOK_ARCHIVE_PANEL_ID = 'MooncakeOrderBookArchivePanel';
    const MOONCAKE_ORDER_BOOK_ARCHIVE_FLOAT_ID = 'MooncakeOrderBookArchiveFloat';
    const MOONCAKE_ORDER_BOOK_ARCHIVE_FLOAT_POSITION_KEY = 'Mooncake_orderBookArchive_floatPosition_v1';
    const MOONCAKE_ORDER_BOOK_ARCHIVE_CAPTURE_DELAY_MS = 350;
    const mooncakeOrderBookArchiveRecent = new Map();
    let mooncakeOrderBookArchiveDbPromise = null;
    let mooncakeOrderBookArchiveTrimAt = 0;
    let mooncakeOrderBookArchiveCaptureTimer = 0;
    let mooncakeOrderBookArchiveCaptureGeneration = 0;
    let mooncakeOrderBookArchivePendingPayload = null;

    function mooncakeIsOrderBookArchiveEnabled() {
        try { return localStorage.getItem(MOONCAKE_ORDER_BOOK_ARCHIVE_ENABLED_KEY) !== '0'; }
        catch (_) { return true; }
    }

    function mooncakeGetOrderBookArchiveLimit() {
        try {
            const value = Number.parseInt(localStorage.getItem(MOONCAKE_ORDER_BOOK_ARCHIVE_LIMIT_KEY) || '', 10);
            return Number.isFinite(value)
                ? Math.min(MOONCAKE_ORDER_BOOK_ARCHIVE_MAX_LIMIT, Math.max(MOONCAKE_ORDER_BOOK_ARCHIVE_MIN_LIMIT, value))
                : MOONCAKE_ORDER_BOOK_ARCHIVE_DEFAULT_LIMIT;
        } catch (_) {
            return MOONCAKE_ORDER_BOOK_ARCHIVE_DEFAULT_LIMIT;
        }
    }

    function mooncakeSetOrderBookArchiveLimit(value) {
        const limit = Math.min(
            MOONCAKE_ORDER_BOOK_ARCHIVE_MAX_LIMIT,
            Math.max(MOONCAKE_ORDER_BOOK_ARCHIVE_MIN_LIMIT, Number.parseInt(value, 10) || MOONCAKE_ORDER_BOOK_ARCHIVE_DEFAULT_LIMIT)
        );
        try { localStorage.setItem(MOONCAKE_ORDER_BOOK_ARCHIVE_LIMIT_KEY, String(limit)); } catch (_) {}
        return limit;
    }

    function mooncakeSetOrderBookArchiveEnabled(enabled) {
        try { localStorage.setItem(MOONCAKE_ORDER_BOOK_ARCHIVE_ENABLED_KEY, enabled ? '1' : '0'); } catch (_) {}
        if (!enabled) mooncakeClearOrderBookArchiveCaptureSchedule();
        document.querySelectorAll('[data-mooncake-order-archive-switch]').forEach(button => {
            button.textContent = isZH ? `挂单记录：${enabled ? '开' : '关'}` : `Order archive: ${enabled ? 'On' : 'Off'}`;
            button.setAttribute('aria-pressed', String(enabled));
            Object.assign(button.style, enabled ? {
                borderColor: 'rgba(112,205,174,.44)', background: 'rgba(30,79,65,.72)', color: '#e2fff5'
            } : {
                borderColor: 'rgba(170,180,198,.28)', background: 'rgba(54,58,68,.58)', color: 'rgba(220,225,233,.72)'
            });
        });
        document.getElementById(MOONCAKE_ORDER_BOOK_ARCHIVE_FLOAT_ID)?.remove();
    }

    function mooncakeClearOrderBookArchiveCaptureSchedule() {
        mooncakeOrderBookArchiveCaptureGeneration++;
        if (mooncakeOrderBookArchiveCaptureTimer) {
            clearTimeout(mooncakeOrderBookArchiveCaptureTimer);
            mooncakeOrderBookArchiveCaptureTimer = 0;
        }
        mooncakeOrderBookArchivePendingPayload = null;
    }

    function mooncakeScheduleOrderBookArchiveCapture(marketItemOrderBooks) {
        if (!mooncakeIsOrderBookArchiveEnabled()) return;
        const itemHrid = marketItemOrderBooks?.itemHrid;
        const orderBooks = marketItemOrderBooks?.orderBooks;
        if (!itemHrid || !orderBooks) return;

        const panelItemHrid = mooncakeParseItemHridFromPanel();
        const activeItemHrid = panelItemHrid || currentMarketItem?.itemHrid || '';
        if (activeItemHrid !== itemHrid) return;

        const panelLevel = panelItemHrid === itemHrid
            ? Number(mooncakeParseEnhanceLevelFromPanel())
            : Number(currentMarketItem?.enhancementLevel);
        const level = Number.isFinite(panelLevel)
            ? Math.max(0, Math.min(20, Math.floor(panelLevel)))
            : 0;
        if (!orderBooks[level]) return;

        mooncakeOrderBookArchivePendingPayload = marketItemOrderBooks;
        const generation = ++mooncakeOrderBookArchiveCaptureGeneration;
        if (mooncakeOrderBookArchiveCaptureTimer) clearTimeout(mooncakeOrderBookArchiveCaptureTimer);
        mooncakeOrderBookArchiveCaptureTimer = setTimeout(() => {
            mooncakeOrderBookArchiveCaptureTimer = 0;
            const run = () => {
                if (generation !== mooncakeOrderBookArchiveCaptureGeneration) return;
                const pending = mooncakeOrderBookArchivePendingPayload;
                mooncakeOrderBookArchivePendingPayload = null;
                if (!pending) return;
                mooncakeCaptureOrderBookArchive(pending).catch(() => {});
            };
            if (typeof requestIdleCallback === 'function') {
                requestIdleCallback(run, { timeout: 500 });
            } else {
                run();
            }
        }, MOONCAKE_ORDER_BOOK_ARCHIVE_CAPTURE_DELAY_MS);
    }

    function mooncakeOpenOrderBookArchiveDb() {
        if (mooncakeOrderBookArchiveDbPromise) return mooncakeOrderBookArchiveDbPromise;
        mooncakeOrderBookArchiveDbPromise = new Promise((resolve, reject) => {
            const request = indexedDB.open(MOONCAKE_ORDER_BOOK_ARCHIVE_DB, 1);
            request.onupgradeneeded = () => {
                const db = request.result;
                const store = db.createObjectStore(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE, { keyPath: 'id' });
                store.createIndex('itemLevel', 'itemLevel', { unique: false });
                store.createIndex('timestamp', 'timestamp', { unique: false });
            };
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        }).catch(error => {
            mooncakeOrderBookArchiveDbPromise = null;
            console.warn('[MoonCake] 挂单记录数据库不可用:', error);
            return null;
        });
        return mooncakeOrderBookArchiveDbPromise;
    }

    function mooncakeNormalizeOrderBookListings(book, side) {
        return (Array.isArray(book?.[side]) ? book[side] : [])
            .map(entry => {
                const rawListingId = Array.isArray(entry) ? entry[2] : (entry?.listingId ?? entry?.id);
                const listingId = rawListingId === undefined || rawListingId === null || rawListingId === ''
                    ? null
                    : (Number.isSafeInteger(Number(rawListingId)) ? Number(rawListingId) : String(rawListingId));
                return {
                    price: Math.max(0, Number(Array.isArray(entry) ? entry[0] : (entry?.price ?? entry?.p)) || 0),
                    quantity: Math.max(0, Number(Array.isArray(entry)
                        ? entry[1]
                        : (entry?.quantity ?? entry?.q ?? entry?.amount ?? entry?.count ?? ((Number(entry?.orderQuantity) || 0) - (Number(entry?.filledQuantity) || 0)))) || 0),
                    ...(listingId === null ? {} : { listingId })
                };
            })
            .filter(entry => entry.price > 0)
            .sort((left, right) => side === 'asks' ? left.price - right.price : right.price - left.price);
    }

    // The public quote cache only retains the first ask/bid price. Keep the
    // corresponding order IDs for the currently filtered personal listings so
    // their own orders can be excluded precisely when finding the next quote.
    const MOONCAKE_MY_LISTINGS_LIVE_ORDER_BOOK_CACHE_LIMIT = 16;
    const mooncakeMyListingsLiveOrderBookCache = new Map();

    function mooncakeClearMyListingsLiveOrderBookCache() {
        mooncakeMyListingsLiveOrderBookCache.clear();
    }

    function mooncakeCacheMyListingsLiveOrderBooks(itemHrid, orderBooks, receivedAt = Date.now()) {
        if (!itemHrid || !orderBooks) return;
        const levels = new Map();
        for (let level = 0; level <= 20; level += 1) {
            const book = orderBooks[level] ?? orderBooks[String(level)];
            if (!book) continue;
            levels.set(level, {
                asks: mooncakeNormalizeOrderBookListings(book, 'asks'),
                bids: mooncakeNormalizeOrderBookListings(book, 'bids')
            });
        }
        mooncakeMyListingsLiveOrderBookCache.delete(itemHrid);
        mooncakeMyListingsLiveOrderBookCache.set(itemHrid, { levels, receivedAt });
        while (mooncakeMyListingsLiveOrderBookCache.size > MOONCAKE_MY_LISTINGS_LIVE_ORDER_BOOK_CACHE_LIMIT) {
            const oldestItemHrid = mooncakeMyListingsLiveOrderBookCache.keys().next().value;
            mooncakeMyListingsLiveOrderBookCache.delete(oldestItemHrid);
        }
    }

    function mooncakeGetMyListingsLiveOrderBook(itemHrid, enhancementLevel) {
        const level = Number(enhancementLevel);
        if (!itemHrid || !Number.isInteger(level)) return null;
        return mooncakeMyListingsLiveOrderBookCache.get(itemHrid)?.levels?.get(level) || null;
    }

    const mooncakeQ7MarketOrderBookCache = new Map();
    const mooncakeQ7LastUploadedAt = new Map();
    let mooncakeQ7MarketReportSocket = null;
    let mooncakeQ7PendingMarketReport = null;
    let mooncakeQ7PendingMarketReportCheckTimer = 0;
    let mooncakeQ7PendingMarketReportExpiryTimer = 0;
    let mooncakeQ7MarketReporterUnavailable = false;

    function mooncakeIsQ7MarketReportHost() {
        return MOONCAKE_Q7_MARKET_REPORT_HOSTS.has(window.location.hostname);
    }

    function mooncakeClearQ7PendingMarketReportTimers() {
        if (mooncakeQ7PendingMarketReportCheckTimer) {
            clearTimeout(mooncakeQ7PendingMarketReportCheckTimer);
            mooncakeQ7PendingMarketReportCheckTimer = 0;
        }
        if (mooncakeQ7PendingMarketReportExpiryTimer) {
            clearTimeout(mooncakeQ7PendingMarketReportExpiryTimer);
            mooncakeQ7PendingMarketReportExpiryTimer = 0;
        }
    }

    function mooncakeCloseQ7MarketReportSocket() {
        const socket = mooncakeQ7MarketReportSocket;
        mooncakeQ7MarketReportSocket = null;
        if (socket && socket.readyState < WebSocket.CLOSING) {
            try { socket.close(); } catch (_) {}
        }
    }

    function mooncakeDisableQ7MarketReporterForSession() {
        // Reporting is optional. Do not keep reopening a broken remote endpoint.
        mooncakeQ7MarketReporterUnavailable = true;
        mooncakeQ7PendingMarketReport = null;
        mooncakeClearQ7PendingMarketReportTimers();
        mooncakeCloseQ7MarketReportSocket();
    }

    function mooncakeAggregateQ7MarketOrders(book, side) {
        const totalsByPrice = new Map();
        const listings = Array.isArray(book?.[side]) ? book[side] : [];
        for (const listing of listings) {
            const rawPrice = Array.isArray(listing) ? listing[0] : (listing?.price ?? listing?.p);
            const rawQuantity = Array.isArray(listing)
                ? listing[1]
                : (listing?.quantity ?? listing?.q ?? listing?.amount ?? listing?.count ??
                    ((Number(listing?.orderQuantity) || 0) - (Number(listing?.filledQuantity) || 0)));
            const price = Math.trunc(Number(rawPrice));
            const quantity = Math.trunc(Number(rawQuantity));
            if (!Number.isSafeInteger(price) || !Number.isSafeInteger(quantity) || price <= 0 || quantity <= 0) continue;
            const total = (totalsByPrice.get(price) || 0) + quantity;
            if (Number.isSafeInteger(total)) totalsByPrice.set(price, total);
        }
        return [...totalsByPrice.entries()]
            .map(([price, quantity]) => ({ price, quantity }))
            .sort((left, right) => side === 'asks' ? left.price - right.price : right.price - left.price)
            .slice(0, MOONCAKE_Q7_MARKET_REPORT_MAX_DEPTH);
    }

    function mooncakeBuildQ7MarketOrderBookReport(level, book) {
        const asks = mooncakeAggregateQ7MarketOrders(book, 'asks');
        const bids = mooncakeAggregateQ7MarketOrders(book, 'bids');
        return {
            level: Math.max(0, Math.min(MOONCAKE_Q7_MARKET_REPORT_MAX_LEVEL, Math.trunc(Number(level) || 0))),
            ask: asks[0]?.price ?? -1,
            bid: bids[0]?.price ?? -1,
            aq: asks[0]?.quantity ?? 0,
            bq: bids[0]?.quantity ?? 0,
            asks,
            bids
        };
    }

    function mooncakeCacheQ7MarketOrderBooks(marketItemOrderBooks) {
        const itemHrid = marketItemOrderBooks?.itemHrid;
        const orderBooks = marketItemOrderBooks?.orderBooks;
        if (typeof itemHrid !== 'string' || !itemHrid.startsWith('/items/') || !Array.isArray(orderBooks)) return;

        const variants = new Map();
        orderBooks.forEach((book, level) => {
            if (!book || level > MOONCAKE_Q7_MARKET_REPORT_MAX_LEVEL) return;
            variants.set(level, mooncakeBuildQ7MarketOrderBookReport(level, book));
        });
        if (!variants.size) return;

        const receivedAt = Date.now();
        mooncakeQ7MarketOrderBookCache.delete(itemHrid);
        mooncakeQ7MarketOrderBookCache.set(itemHrid, { variants, receivedAt });
        while (mooncakeQ7MarketOrderBookCache.size > MOONCAKE_Q7_MARKET_REPORT_CACHE_LIMIT) {
            mooncakeQ7MarketOrderBookCache.delete(mooncakeQ7MarketOrderBookCache.keys().next().value);
        }

        const pending = mooncakeQ7PendingMarketReport;
        if (pending?.itemHrid === itemHrid && variants.has(pending.level) &&
            receivedAt >= pending.selectedAt - MOONCAKE_Q7_MARKET_REPORT_FRESHNESS_MS) {
            pending.ready = true;
            mooncakeTrySendQ7MarketReport(itemHrid);
        }
    }

    function mooncakeConnectQ7MarketReporter() {
        if (!mooncakeQ7PendingMarketReport || mooncakeQ7MarketReporterUnavailable || !mooncakeIsQ7MarketReportHost()) return;
        if (mooncakeQ7MarketReportSocket &&
            (mooncakeQ7MarketReportSocket.readyState === WebSocket.CONNECTING ||
             mooncakeQ7MarketReportSocket.readyState === WebSocket.OPEN)) return;

        let socket;
        try {
            socket = new WebSocket(MOONCAKE_Q7_MARKET_REPORT_SOCKET_URL);
        } catch (_) {
            mooncakeDisableQ7MarketReporterForSession();
            return;
        }
        mooncakeQ7MarketReportSocket = socket;
        socket.addEventListener('open', () => {
            if (mooncakeQ7MarketReportSocket === socket) mooncakeTrySendQ7MarketReport();
        });
        socket.addEventListener('close', () => {
            if (mooncakeQ7MarketReportSocket !== socket) return;
            mooncakeDisableQ7MarketReporterForSession();
        });
        socket.addEventListener('error', () => {
            if (mooncakeQ7MarketReportSocket !== socket) return;
            mooncakeDisableQ7MarketReporterForSession();
        });
    }

    function mooncakeTrySendQ7MarketReport(expectedItemHrid = null) {
        const pending = mooncakeQ7PendingMarketReport;
        if (!pending || (expectedItemHrid && pending.itemHrid !== expectedItemHrid) || !pending.ready) return false;
        const cached = mooncakeQ7MarketOrderBookCache.get(pending.itemHrid);
        if (!cached || cached.receivedAt < pending.selectedAt - MOONCAKE_Q7_MARKET_REPORT_FRESHNESS_MS) return false;
        const data = cached.variants.get(pending.level);
        if (!data) return false;
        const socket = mooncakeQ7MarketReportSocket;
        if (!socket || socket.readyState !== WebSocket.OPEN) {
            mooncakeConnectQ7MarketReporter();
            return false;
        }

        try {
            const now = Date.now();
            socket.send(JSON.stringify({
                type: MOONCAKE_Q7_MARKET_REPORT_PAYLOAD_TYPE,
                itemHrid: pending.itemHrid,
                data: [data],
                time: Math.floor(now / 1000)
            }));
            mooncakeQ7LastUploadedAt.delete(pending.itemHrid);
            mooncakeQ7LastUploadedAt.set(pending.itemHrid, now);
            while (mooncakeQ7LastUploadedAt.size > MOONCAKE_Q7_MARKET_REPORT_CACHE_LIMIT) {
                mooncakeQ7LastUploadedAt.delete(mooncakeQ7LastUploadedAt.keys().next().value);
            }
            if (mooncakeQ7PendingMarketReport === pending) {
                mooncakeQ7PendingMarketReport = null;
                mooncakeClearQ7PendingMarketReportTimers();
                mooncakeCloseQ7MarketReportSocket();
            }
            return true;
        } catch (_) {
            mooncakeDisableQ7MarketReporterForSession();
            return false;
        }
    }

    function mooncakeQueueQ7MarketReport(itemHrid, enhancementLevel) {
        const level = Math.max(0, Math.min(MOONCAKE_Q7_MARKET_REPORT_MAX_LEVEL, Math.trunc(Number(enhancementLevel) || 0)));
        const now = Date.now();
        const itemKey = `${itemHrid}:${level}`;
        if (!mooncakeIsQ7MarketReportHost() || mooncakeQ7MarketReporterUnavailable || typeof itemHrid !== 'string' || !itemHrid.startsWith('/items/') ||
            mooncakeQ7PendingMarketReport?.itemKey === itemKey ||
            now - (mooncakeQ7LastUploadedAt.get(itemHrid) || 0) < MOONCAKE_Q7_MARKET_REPORT_DEBOUNCE_MS) return;

        mooncakeClearQ7PendingMarketReportTimers();
        mooncakeQ7PendingMarketReport = { itemHrid, level, itemKey, selectedAt: now, ready: false };
        mooncakeQ7PendingMarketReportCheckTimer = setTimeout(() => {
            mooncakeQ7PendingMarketReportCheckTimer = 0;
            const pending = mooncakeQ7PendingMarketReport;
            const cached = mooncakeQ7MarketOrderBookCache.get(itemHrid);
            if (!pending || pending.itemKey !== itemKey || !cached || !cached.variants.has(level) ||
                cached.receivedAt < pending.selectedAt - MOONCAKE_Q7_MARKET_REPORT_FRESHNESS_MS) return;
            pending.ready = true;
            mooncakeTrySendQ7MarketReport();
        }, MOONCAKE_Q7_MARKET_REPORT_SELECTION_DELAY_MS);
        mooncakeQ7PendingMarketReportExpiryTimer = setTimeout(() => {
            if (mooncakeQ7PendingMarketReport?.itemKey !== itemKey) return;
            mooncakeQ7PendingMarketReport = null;
            mooncakeClearQ7PendingMarketReportTimers();
            mooncakeCloseQ7MarketReportSocket();
        }, MOONCAKE_Q7_MARKET_REPORT_WAIT_MS);
        mooncakeConnectQ7MarketReporter();
    }

    function mooncakeResetQ7MarketReporter() {
        mooncakeQ7PendingMarketReport = null;
        mooncakeClearQ7PendingMarketReportTimers();
        mooncakeCloseQ7MarketReportSocket();
    }

    function mooncakeQueueQ7MarketReportFromVisiblePanel(expectedItemHrid = '', attemptsLeft = 4) {
        const visibleItemHrid = mooncakeParseItemHridFromPanel();
        if (expectedItemHrid && visibleItemHrid !== expectedItemHrid) {
            if (attemptsLeft > 0) {
                setTimeout(() => mooncakeQueueQ7MarketReportFromVisiblePanel(expectedItemHrid, attemptsLeft - 1), 250);
            }
            return;
        }
        const itemHrid = expectedItemHrid || visibleItemHrid;
        if (itemHrid) {
            mooncakeQueueQ7MarketReport(itemHrid, mooncakeGetCurrentMarketEnhanceLevel(0));
            return;
        }
        if (attemptsLeft > 0) {
            setTimeout(() => mooncakeQueueQ7MarketReportFromVisiblePanel(expectedItemHrid, attemptsLeft - 1), 250);
        }
    }

    function mooncakeIsQ7MarketNavigationClick(target) {
        if (!target || target.closest?.('[class*="MarketplacePanel"], [data-mooncake-market-jump-switch], [data-mooncake-market-history-switch]')) return false;
        const node = target.closest?.('button, [role="button"], [role="tab"], a');
        if (!node) return false;
        const text = [
            node.textContent,
            node.getAttribute?.('aria-label'),
            node.getAttribute?.('title'),
            node.getAttribute?.('data-navigation-target'),
            node.getAttribute?.('data-target'),
            node.className
        ].filter(Boolean).join(' ');
        return /marketplace|market|市场/i.test(text);
    }

    window.addEventListener('pagehide', mooncakeResetQ7MarketReporter);
    window.addEventListener('pagehide', mooncakeClearOrderBookArchiveCaptureSchedule);

    async function mooncakeTrimOrderBookArchive(db) {
        if (!db) return;
        const count = await new Promise(resolve => {
            const request = db.transaction(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE, 'readonly')
                .objectStore(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE).count();
            request.onsuccess = () => resolve(Number(request.result) || 0);
            request.onerror = () => resolve(0);
        });
        const excess = count - mooncakeGetOrderBookArchiveLimit();
        if (excess <= 0) return;
        await new Promise(resolve => {
            const tx = db.transaction(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE, 'readwrite');
            const index = tx.objectStore(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE).index('timestamp');
            let removed = 0;
            const cursor = index.openCursor();
            cursor.onsuccess = () => {
                const row = cursor.result;
                if (!row || removed >= excess) return;
                row.delete();
                removed++;
                row.continue();
            };
            tx.oncomplete = () => resolve();
            tx.onerror = () => resolve();
        });
    }

    async function mooncakeCaptureOrderBookArchive(marketItemOrderBooks) {
        if (!mooncakeIsOrderBookArchiveEnabled()) return;
        const itemHrid = marketItemOrderBooks?.itemHrid;
        const orderBooks = marketItemOrderBooks?.orderBooks;
        if (!itemHrid || !orderBooks) return;
        const timestamp = Date.now();
        const panelItemHrid = mooncakeParseItemHridFromPanel();
        const activeItemHrid = panelItemHrid || currentMarketItem?.itemHrid || '';
        // The archive is a history of the market item the player is viewing.
        // Ignore unrelated order-book broadcasts before any normalization work.
        if (activeItemHrid !== itemHrid) return;
        const livePanelLevel = panelItemHrid === itemHrid ? Number(mooncakeParseEnhanceLevelFromPanel()) : NaN;
        const panelLevel = Number.isFinite(livePanelLevel)
            ? livePanelLevel
            : (currentMarketItem?.itemHrid === itemHrid ? Number(currentMarketItem.enhancementLevel) : NaN);
        const levels = Number.isFinite(panelLevel)
            ? [Math.max(0, Math.min(20, Math.floor(panelLevel)))]
            : [0];
        const rows = [];
        for (const level of levels) {
            const book = orderBooks[level];
            if (!book) continue;
            const asks = mooncakeNormalizeOrderBookListings(book, 'asks');
            const bids = mooncakeNormalizeOrderBookListings(book, 'bids');
            if (!asks.length && !bids.length) continue;
            const itemLevel = `${itemHrid}#${level}`;
            const signature = JSON.stringify([asks, bids]);
            const recent = mooncakeOrderBookArchiveRecent.get(itemLevel);
            // The websocket is intercepted in two compatible ways; suppress only
            // their near-simultaneous duplicate, not a later user visit.
            if (recent?.signature === signature && timestamp - recent.timestamp < 1500) continue;
            mooncakeOrderBookArchiveRecent.set(itemLevel, { signature, timestamp });
            rows.push({
                id: `${timestamp}:${level}:${itemHrid}:${Math.random().toString(36).slice(2, 7)}`,
                itemLevel,
                itemHrid,
                level,
                timestamp,
                asks,
                bids
            });
        }
        if (!rows.length) return;
        const db = await mooncakeOpenOrderBookArchiveDb();
        if (!db) return;
        await new Promise(resolve => {
            const tx = db.transaction(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE, 'readwrite');
            const store = tx.objectStore(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE);
            rows.forEach(row => store.put(row));
            tx.oncomplete = () => resolve();
            tx.onerror = () => resolve();
        });
        if (timestamp - mooncakeOrderBookArchiveTrimAt > 60 * 1000) {
            mooncakeOrderBookArchiveTrimAt = timestamp;
            mooncakeTrimOrderBookArchive(db).catch(() => {});
        }
    }

    async function mooncakeReadOrderBookArchive(itemHrid, level, limit = 60) {
        const db = await mooncakeOpenOrderBookArchiveDb();
        if (!db || !itemHrid) return [];
        const itemLevel = `${itemHrid}#${Math.max(0, Math.floor(Number(level) || 0))}`;
        return new Promise(resolve => {
            const rows = [];
            const tx = db.transaction(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE, 'readonly');
            const request = tx.objectStore(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE)
                .index('itemLevel').openCursor(IDBKeyRange.only(itemLevel), 'prev');
            request.onsuccess = () => {
                const cursor = request.result;
                if (!cursor || rows.length >= limit) return resolve(rows);
                rows.push(cursor.value);
                cursor.continue();
            };
            request.onerror = () => resolve(rows);
        });
    }

    async function mooncakeGetOrderBookArchiveStats(options = {}) {
        const shouldCancel = typeof options.shouldCancel === 'function' ? options.shouldCancel : () => false;
        if (shouldCancel()) return { count: 0, bytes: 0, originUsage: 0, originQuota: 0, cancelled: true };
        const db = await mooncakeOpenOrderBookArchiveDb();
        if (!db) return { count: 0, bytes: 0, originUsage: 0, originQuota: 0 };
        const archiveStats = await new Promise(resolve => {
            let count = 0;
            let bytes = 0;
            let settled = false;
            const finish = cancelled => {
                if (settled) return;
                settled = true;
                resolve({ count, bytes, cancelled: !!cancelled });
            };
            const encoder = typeof TextEncoder === 'function' ? new TextEncoder() : null;
            const tx = db.transaction(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE, 'readonly');
            const request = tx.objectStore(MOONCAKE_ORDER_BOOK_ARCHIVE_STORE).openCursor();
            request.onsuccess = () => {
                if (shouldCancel()) {
                    finish(true);
                    return;
                }
                const cursor = request.result;
                if (!cursor) return;
                count++;
                const json = JSON.stringify(cursor.value);
                bytes += encoder ? encoder.encode(json).byteLength : json.length * 2;
                cursor.continue();
            };
            tx.oncomplete = () => finish(shouldCancel());
            tx.onerror = () => finish(shouldCancel());
        });
        if (archiveStats.cancelled || shouldCancel()) {
            return { ...archiveStats, originUsage: 0, originQuota: 0, cancelled: true };
        }
        let storageEstimate = null;
        try { storageEstimate = await navigator.storage?.estimate?.(); } catch (_) {}
        if (shouldCancel()) return { ...archiveStats, originUsage: 0, originQuota: 0, cancelled: true };
        return {
            ...archiveStats,
            originUsage: Math.max(0, Number(storageEstimate?.usage) || 0),
            originQuota: Math.max(0, Number(storageEstimate?.quota) || 0)
        };
    }

    function mooncakeDescribeOrderBookArchiveStorage(stats) {
        const parts = [isZH
            ? `挂单归档估算：${mooncakeFormatArchiveBytes(stats?.bytes)}`
            : `Archive estimate: ${mooncakeFormatArchiveBytes(stats?.bytes)}`];
        if (Number(stats?.originQuota) > 0) {
            const ratio = Number(stats.originUsage) / Number(stats.originQuota) * 100;
            parts.push(isZH
                ? `站点总存储：${mooncakeFormatArchiveBytes(stats.originUsage)} / ${mooncakeFormatArchiveBytes(stats.originQuota)}（${ratio.toFixed(2)}%）`
                : `Origin storage: ${mooncakeFormatArchiveBytes(stats.originUsage)} / ${mooncakeFormatArchiveBytes(stats.originQuota)} (${ratio.toFixed(2)}%)`);
        }
        parts.push(isZH
            ? '归档正文保存在 IndexedDB；localStorage 仅保存开关和上限。'
            : 'Snapshots use IndexedDB; localStorage only stores small settings.');
        return parts.join('\n');
    }

    function mooncakeFormatArchiveExactNumber(value) {
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) return '-';
        return numeric.toLocaleString('en-US', {
            minimumFractionDigits: 0,
            maximumFractionDigits: 8,
            useGrouping: true
        });
    }

    function mooncakeFormatArchiveBytes(bytes) {
        const numeric = Math.max(0, Number(bytes) || 0);
        if (numeric < 1024) return `${Math.round(numeric)} B`;
        if (numeric < 1024 * 1024) return `${(numeric / 1024).toFixed(1)} KB`;
        return `${(numeric / 1024 / 1024).toFixed(2)} MB`;
    }

    function mooncakeRenderOrderBookArchiveSide(title, rows, color) {
        const body = rows.length
            ? rows.map(row => {
                const listingId = row?.listingId === undefined || row?.listingId === null || row?.listingId === ''
                    ? '-'
                    : String(row.listingId);
                const listingIdHtml = mooncakeEscapeHtml(listingId);
                return `<div style="display:grid;grid-template-columns:minmax(54px,.75fr) minmax(70px,1fr) minmax(76px,1.15fr);gap:6px;min-height:21px;padding:2px 0;border-bottom:1px solid rgba(255,255,255,.045);text-align:center;font-size:12px;line-height:17px;"><span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:rgba(226,232,255,.78);font-variant-numeric:tabular-nums;">${mooncakeEscapeHtml(mooncakeFormatArchiveExactNumber(row.quantity))}</span><b style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:${color};font-variant-numeric:tabular-nums;">${mooncakeEscapeHtml(mooncakeFormatArchiveExactNumber(row.price))}</b><span title="${listingIdHtml}" style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:rgba(205,216,244,.68);font-variant-numeric:tabular-nums;">${listingIdHtml}</span></div>`;
            }).join('')
            : `<div style="padding:12px 0;text-align:center;color:rgba(220,226,240,.45);font-size:12px;">-</div>`;
        return `<section style="min-width:0;font-size:12px;"><div style="margin-bottom:2px;color:rgba(214,224,255,.82);font-size:12px;font-weight:800;text-align:center;line-height:18px;">${title}</div><div style="display:grid;grid-template-columns:minmax(54px,.75fr) minmax(70px,1fr) minmax(76px,1.15fr);gap:6px;padding:2px 0;border-bottom:1px solid rgba(125,151,219,.22);text-align:center;color:rgba(205,216,244,.58);font-size:10px;line-height:15px;"><span>${isZH ? '数量' : 'Quantity'}</span><span>${isZH ? '价格' : 'Price'}</span><span>${isZH ? '订单 ID' : 'Order ID'}</span></div>${body}</section>`;
    }

    function mooncakeShowOrderBookArchiveRecord(panel, row) {
        const detail = panel?.querySelector?.('[data-mooncake-order-archive-detail]');
        if (!detail || !row) return;
        const time = new Date(row.timestamp).toLocaleString();
        detail.innerHTML = `
            <div style="display:flex;justify-content:space-between;gap:10px;margin-bottom:8px;color:rgba(222,231,255,.66);font-size:11px;"><span>${mooncakeEscapeHtml(time)}</span><span>${isZH ? '数量 / 价格 / 订单 ID' : 'Qty / Price / Order ID'}</span></div>
            <div data-mooncake-order-archive-sides style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
                ${mooncakeRenderOrderBookArchiveSide(isZH ? '卖单' : 'Asks', row.asks || [], '#ffd66f')}
                ${mooncakeRenderOrderBookArchiveSide(isZH ? '买单' : 'Bids', row.bids || [], '#9ddfff')}
            </div>`;
    }

    function mooncakeInvalidateOrderBookArchivePage(host) {
        if (!host) return;
        host._mooncakeOrderArchiveRevision = (Number(host._mooncakeOrderArchiveRevision) || 0) + 1;
        if (typeof host._mooncakeCancelOrderArchiveStats === 'function') {
            host._mooncakeCancelOrderArchiveStats();
        }
        host._mooncakeCancelOrderArchiveStats = null;
    }

    function mooncakeIsOrderBookArchiveRenderCurrent(host, revision) {
        if (!host?.isConnected || Number(host._mooncakeOrderArchiveRevision) !== revision) return false;
        const settingsPanel = host.closest('#better-loot-tracker-config-panel');
        return !!settingsPanel && mooncakeIsEnhancementSettingsTabVisible(settingsPanel, 'archive');
    }

    function mooncakeResolveOrderBookArchiveContext() {
        const itemHrid = mooncakeParseItemHridFromPanel() || currentMarketItem?.itemHrid;
        const liveLevel = mooncakeParseEnhanceLevelFromPanel();
        const level = Math.max(0, Math.floor(Number.isFinite(Number(liveLevel))
            ? Number(liveLevel)
            : (Number(currentMarketItem?.enhancementLevel) || 0)));
        return itemHrid ? { itemHrid, level } : null;
    }

    function mooncakeApplyOrderBookArchiveStats(host, stats, rowCount, hasContext) {
        const statsNode = host?.querySelector?.('[data-mooncake-order-archive-stats]');
        const bytesNode = host?.querySelector?.('[data-mooncake-order-archive-bytes]');
        if (statsNode) {
            statsNode.textContent = hasContext
                ? (isZH ? `当前物品 ${rowCount}，全部 ${stats.count}` : `Current item ${rowCount}, total ${stats.count}`)
                : (isZH ? `全部 ${stats.count}` : `Total ${stats.count}`);
            statsNode.title = mooncakeDescribeOrderBookArchiveStorage(stats);
        }
        if (bytesNode) {
            bytesNode.textContent = isZH
                ? `约 ${mooncakeFormatArchiveBytes(stats.bytes)}`
                : `~${mooncakeFormatArchiveBytes(stats.bytes)}`;
            bytesNode.title = mooncakeDescribeOrderBookArchiveStorage(stats);
        }
    }

    function mooncakeScheduleOrderBookArchiveStats(host, revision, rowCount, hasContext) {
        if (!host) return;
        if (typeof host._mooncakeCancelOrderArchiveStats === 'function') {
            host._mooncakeCancelOrderArchiveStats();
        }
        let cancelled = false;
        let handle;
        let cancelScheduled = () => {};
        const cancel = () => {
            cancelled = true;
            cancelScheduled();
        };
        const run = async () => {
            try {
                if (cancelled || !mooncakeIsOrderBookArchiveRenderCurrent(host, revision)) return;
                const stats = await mooncakeGetOrderBookArchiveStats({
                    shouldCancel: () => cancelled || !mooncakeIsOrderBookArchiveRenderCurrent(host, revision)
                });
                if (cancelled || !mooncakeIsOrderBookArchiveRenderCurrent(host, revision)) return;
                mooncakeApplyOrderBookArchiveStats(host, stats, rowCount, hasContext);
            } finally {
                if (host._mooncakeCancelOrderArchiveStats === cancel) host._mooncakeCancelOrderArchiveStats = null;
            }
        };
        if (typeof window.requestIdleCallback === 'function') {
            handle = window.requestIdleCallback(run, { timeout: 900 });
            cancelScheduled = () => window.cancelIdleCallback?.(handle);
        } else {
            handle = setTimeout(run, 80);
            cancelScheduled = () => clearTimeout(handle);
        }
        host._mooncakeCancelOrderArchiveStats = cancel;
    }

    async function mooncakeRenderOrderBookArchivePage(host) {
        if (!host) return;
        mooncakeInvalidateOrderBookArchivePage(host);
        const revision = Number(host._mooncakeOrderArchiveRevision) || 0;
        const context = mooncakeResolveOrderBookArchiveContext();
        const itemHrid = context?.itemHrid || '';
        const level = context?.level || 0;
        const header = document.createElement('div');
        header.setAttribute('data-mooncake-order-archive-page-header', '1');
        const archiveLimit = mooncakeGetOrderBookArchiveLimit();
        const contextTitle = context
            ? `${mooncakeEscapeHtml(getItemName(itemHrid) || itemHrid)} +${level}`
            : (isZH ? '尚未选择市场物品' : 'No marketplace item selected');
        header.innerHTML = `<strong data-mooncake-order-archive-title>${isZH ? '挂单记录' : 'Order archive'} · ${contextTitle}</strong><span data-mooncake-order-archive-stats>${isZH ? '统计中...' : 'Calculating...'}</span><label data-mooncake-order-archive-limit-label title="${isZH ? '所有物品、所有等级合计保留的快照上限' : 'Global snapshot limit across every item and level'}"><span>${isZH ? '保留' : 'Keep'}</span><input type="number" min="${MOONCAKE_ORDER_BOOK_ARCHIVE_MIN_LIMIT}" max="${MOONCAKE_ORDER_BOOK_ARCHIVE_MAX_LIMIT}" step="100" value="${archiveLimit}" data-mooncake-order-archive-limit></label><span data-mooncake-order-archive-bytes></span>`;
        const body = document.createElement('div');
        body.setAttribute('data-mooncake-order-archive-page-body', '1');
        body.innerHTML = `<div data-mooncake-order-archive-list></div><div data-mooncake-order-archive-detail><div data-mooncake-order-archive-empty>${context ? (isZH ? '读取中...' : 'Loading...') : (isZH ? '请先在市场中打开一个物品，再回到这里查看记录。' : 'Open an item in the marketplace, then return here to review its archive.')}</div></div>`;
        host.replaceChildren(header, body);

        const limitInput = header.querySelector('[data-mooncake-order-archive-limit]');
        let appliedLimitValue = limitInput.value;
        const applyLimit = async () => {
            const limit = mooncakeSetOrderBookArchiveLimit(limitInput.value);
            limitInput.value = String(limit);
            if (String(limit) === appliedLimitValue) return;
            appliedLimitValue = String(limit);
            if (typeof host._mooncakeCancelOrderArchiveStats === 'function') {
                host._mooncakeCancelOrderArchiveStats();
                host._mooncakeCancelOrderArchiveStats = null;
            }
            const db = await mooncakeOpenOrderBookArchiveDb();
            await mooncakeTrimOrderBookArchive(db);
            const latestStats = await mooncakeGetOrderBookArchiveStats({
                shouldCancel: () => !mooncakeIsOrderBookArchiveRenderCurrent(host, revision)
            });
            if (!mooncakeIsOrderBookArchiveRenderCurrent(host, revision)) return;
            mooncakeApplyOrderBookArchiveStats(host, latestStats, host._mooncakeOrderArchiveRowCount || 0, !!context);
        };
        limitInput.addEventListener('change', applyLimit);
        limitInput.addEventListener('blur', applyLimit);

        if (!context) {
            body.querySelector('[data-mooncake-order-archive-list]').innerHTML = `<div data-mooncake-order-archive-empty>${isZH ? '暂无当前物品' : 'No current item'}</div>`;
            host._mooncakeOrderArchiveRowCount = 0;
            requestAnimationFrame(() => {
                if (mooncakeIsOrderBookArchiveRenderCurrent(host, revision)) {
                    mooncakeScheduleOrderBookArchiveStats(host, revision, 0, false);
                }
            });
            return;
        }

        const rows = await mooncakeReadOrderBookArchive(itemHrid, level);
        if (!mooncakeIsOrderBookArchiveRenderCurrent(host, revision)) return;
        host._mooncakeOrderArchiveRowCount = rows.length;
        const list = body.querySelector('[data-mooncake-order-archive-list]');
        if (!rows.length) {
            list.innerHTML = `<div data-mooncake-order-archive-empty>${isZH ? '暂无记录' : 'No snapshots'}</div>`;
            body.querySelector('[data-mooncake-order-archive-detail]').innerHTML = `<div data-mooncake-order-archive-empty>${isZH ? '这个物品与等级还没有保存过挂单快照。' : 'No snapshot has been saved for this item and level yet.'}</div>`;
        } else {
            rows.forEach((row, index) => {
                const button = document.createElement('button');
                button.type = 'button';
                button.textContent = new Date(row.timestamp).toLocaleString();
                button.setAttribute('data-mooncake-order-archive-record', index === 0 ? 'active' : '');
                button.addEventListener('click', () => {
                    list.querySelectorAll('[data-mooncake-order-archive-record]').forEach(node => node.setAttribute('data-mooncake-order-archive-record', ''));
                    button.setAttribute('data-mooncake-order-archive-record', 'active');
                    mooncakeShowOrderBookArchiveRecord(host, row);
                });
                list.appendChild(button);
            });
            mooncakeShowOrderBookArchiveRecord(host, rows[0]);
        }
        requestAnimationFrame(() => {
            if (mooncakeIsOrderBookArchiveRenderCurrent(host, revision)) {
                mooncakeScheduleOrderBookArchiveStats(host, revision, rows.length, true);
            }
        });
    }

    async function mooncakeOpenOrderBookArchivePanel(trigger = null) {
        document.getElementById(MOONCAKE_ORDER_BOOK_ARCHIVE_PANEL_ID)?.remove();
        document.getElementById(MOONCAKE_ORDER_BOOK_ARCHIVE_FLOAT_ID)?.remove();
        mooncakeOpenEnhancementSettingsPanel(trigger, 'archive');
    }

    function mooncakeGetOrderBookPriceBandValue(source, level) {
        const value = Array.isArray(source)
            ? source[level]
            : source?.[level] ?? source?.[String(level)];
        const numeric = Number(value);
        return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
    }

    function updateMarketCacheFromWS(marketItemOrderBooks) {
        if (!marketItemOrderBooks?.itemHrid || !marketItemOrderBooks?.orderBooks) return;
        mooncakeCacheQ7MarketOrderBooks(marketItemOrderBooks);
        mooncakeScheduleOrderBookArchiveCapture(marketItemOrderBooks);
        const itemHrid = marketItemOrderBooks.itemHrid;
        const orderBooks = marketItemOrderBooks.orderBooks;
        const receivedAt = Date.now();
        const snapshotTime = Math.floor(receivedAt / 1000);
        const priceBandMins = marketItemOrderBooks.priceBandMins;
        const priceBandMaxs = marketItemOrderBooks.priceBandMaxs;

        if (typeof mooncakeShouldCacheMyListingsLiveOrderBooks === 'function' &&
            mooncakeShouldCacheMyListingsLiveOrderBooks(itemHrid)) {
            mooncakeCacheMyListingsLiveOrderBooks(itemHrid, orderBooks, receivedAt);
        }

        if (!marketDataCache) marketDataCache = {};
        if (!marketDataCache[itemHrid]) marketDataCache[itemHrid] = {};

        let priceChanged = false;
        const changedLevels = new Set();
        const updatedLevels = new Set();
        let snapshotQuotesChanged = false;
        for (let level = 0; level <= 20; level++) {
            const book = orderBooks[level];
            if (!book) continue;
            updatedLevels.add(level);

            const askPrice = mooncakeGetOrderBookBestPrice(book, 'asks');
            const bidPrice = mooncakeGetOrderBookBestPrice(book, 'bids');
            const previous = marketDataCache[itemHrid][level];
            const previousSnapshot = marketDetailSnapshotCache[`${itemHrid}:${level}`];
            const priceBandMin = mooncakeGetOrderBookPriceBandValue(priceBandMins, level);
            const priceBandMax = mooncakeGetOrderBookPriceBandValue(priceBandMaxs, level);
            const hasPriceBand = priceBandMin !== null && priceBandMax !== null && priceBandMin <= priceBandMax;
            if (!previous || previous.a !== askPrice || previous.b !== bidPrice) {
                priceChanged = true;
                changedLevels.add(level);
            }
            if (!previousSnapshot || previousSnapshot.ask !== askPrice || previousSnapshot.bid !== bidPrice) {
                snapshotQuotesChanged = true;
            }
            marketDataCache[itemHrid][level] = { a: askPrice, b: bidPrice };
            marketDetailSnapshotCache[`${itemHrid}:${level}`] = {
                bid: bidPrice,
                ask: askPrice,
                time: snapshotTime,
                // Preserve a prior valid band if this particular payload only
                // contains order-book quotes.
                priceBandMin: hasPriceBand ? priceBandMin : previousSnapshot?.priceBandMin,
                priceBandMax: hasPriceBand ? priceBandMax : previousSnapshot?.priceBandMax
            };
        }

        if (priceChanged) {
            mooncakeMarketPricingRevision++;
            mooncakeClearEnhancementRouteCache();
            if (typeof mooncakeRefreshOrderModalEconomics === 'function') {
                mooncakeRefreshOrderModalEconomics();
            }
        }
        if (!priceChanged && !snapshotQuotesChanged) {
            if (typeof mooncakeNotifyMyListingsManagementMarketUpdate === 'function') {
                mooncakeNotifyMyListingsManagementMarketUpdate(itemHrid, updatedLevels);
            }
            return;
        }

        // Only the visible item is re-rendered, and the scheduler coalesces a full
        // 0-20 order-book payload into one render on the next frame.
        if (typeof mooncakeScheduleCurrentEnhancementMarketRefresh === 'function') {
            mooncakeScheduleCurrentEnhancementMarketRefresh(itemHrid);
        }
        if (typeof scheduleMarketplaceHourlyWageRefresh === 'function') {
            scheduleMarketplaceHourlyWageRefresh();
        }
        if (typeof mooncakeNotifyMyListingsTargetFilterMarketUpdate === 'function') {
            mooncakeNotifyMyListingsTargetFilterMarketUpdate(itemHrid, changedLevels);
        }
        if (typeof mooncakeNotifyMyListingsManagementMarketUpdate === 'function') {
            mooncakeNotifyMyListingsManagementMarketUpdate(itemHrid, updatedLevels);
        }
    }



    function getMarketData() {
        if (marketDataCache) {
            return { marketData: marketDataCache };
        }
        const mwiToolsMarket = readMWIToolsMarketData();
        if (mwiToolsMarket?.marketData && Object.keys(mwiToolsMarket.marketData).length > 0) {
            marketDataCache = mwiToolsMarket.marketData;
            return mwiToolsMarket;
        }
        const coreMarket = readMWICoreMarketData();
        if (coreMarket?.marketData && Object.keys(coreMarket.marketData).length > 0) {
            marketDataCache = coreMarket.marketData;
            return coreMarket;
        }
        return null;
    }

    let tooltipStyleInjected = false;
    let tooltipEl = null;
    const tooltipListenerDocs = new WeakSet();

    function mooncakeClearTooltipHideTimer(tip = tooltipEl) {
        if (!tip?._mooncakeTooltipHideTimer) return;
        clearTimeout(tip._mooncakeTooltipHideTimer);
        tip._mooncakeTooltipHideTimer = 0;
    }

    function mooncakeScheduleInteractiveTooltipHide(tip = tooltipEl) {
        if (tip?._mooncakeTooltipPinned) return;
        if (!tip?.classList.contains('mooncake-tooltip-interactive')) {
            hideTooltip();
            return;
        }
        mooncakeClearTooltipHideTimer(tip);
        tip._mooncakeTooltipHideTimer = setTimeout(() => {
            tip._mooncakeTooltipHideTimer = 0;
            const anchor = tip._mooncakeTooltipAnchor;
            if (tip.matches?.(':hover') || anchor?.matches?.(':hover')) return;
            hideTooltip();
        }, 180);
    }

