    const MOONCAKE_DEFAULT_MARKET_STOCK_NAVIGATION_GROUPS = mooncakeCreateDefaultMarketStockNavigationGroups();

    function mooncakeNormalizeMarketStockNavigationCustomGroups(rawGroups) {
        if (!Array.isArray(rawGroups)) return [];
        const usedIds = new Set(MOONCAKE_DEFAULT_MARKET_STOCK_NAVIGATION_GROUPS.map(group => group.id));
        const groups = [];
        rawGroups.slice(0, 12).forEach((rawGroup, index) => {
            const baseId = String(rawGroup?.id || `group-${index + 1}`)
                .trim()
                .replace(/[^a-zA-Z0-9_-]+/g, '-');
            if (!baseId) return;
            const id = `custom-${baseId}`;
            if (usedIds.has(id)) return;
            const items = [...new Set((Array.isArray(rawGroup?.items) ? rawGroup.items : [])
                .map(item => String(item || '').trim())
                .filter(item => item.startsWith('/items/')))].slice(0, 100);
            if (!items.length) return;
            usedIds.add(id);
            const name = String(rawGroup?.name || rawGroup?.label || `Custom ${index + 1}`).trim();
            groups.push({
                id,
                section: 'custom',
                labelZh: name,
                labelEn: name,
                items
            });
        });
        return groups;
    }

    let mooncakeMarketStockNavigationGroupsCache = null;
    let mooncakeMarketStockNavigationGroupsCacheSource = null;

    function mooncakeGetMarketStockNavigationGroups() {
        // 铺货组是纯配置 + 物品表推导，市场界面会高频调用。物品表和自定义组
        // 引用不变时直接复用上次结果，避免每次渲染都重建全部分组。
        const detailMap = mooncakeEnsureItemDetailMap();
        const customGroups = config.preferences.marketStockNavigationCustomGroups;
        if (mooncakeMarketStockNavigationGroupsCache &&
            mooncakeMarketStockNavigationGroupsCacheSource?.detailMap === detailMap &&
            mooncakeMarketStockNavigationGroupsCacheSource?.customGroups === customGroups) {
            return mooncakeMarketStockNavigationGroupsCache;
        }
        const hasDetailMap = !!detailMap && Object.keys(detailMap).length > 0;
        const normalizeItems = items => [...new Set(items.filter(item => !hasDetailMap || !!detailMap[item]))];
        const groups = [
            ...MOONCAKE_DEFAULT_MARKET_STOCK_NAVIGATION_GROUPS,
            ...mooncakeNormalizeMarketStockNavigationCustomGroups(customGroups)
        ].map(group => ({ ...group, items: normalizeItems(group.items) }))
            .filter(group => group.items.length);
        mooncakeMarketStockNavigationGroupsCache = groups;
        mooncakeMarketStockNavigationGroupsCacheSource = { detailMap, customGroups };
        return groups;
    }

    function mooncakeGetMarketStockNavigationGroupLabel(group) {
        return isZH ? group?.labelZh : group?.labelEn;
    }

    function mooncakeGetMarketStockNavigationGroupsForItem(itemHrid, groups = mooncakeGetMarketStockNavigationGroups()) {
        const targetHrid = String(itemHrid || '');
        if (!targetHrid) return [];
        return groups.filter(group => group.items.includes(targetHrid));
    }

    function mooncakeGetMarketStockNavigationGroupForItem(itemHrid, groups = mooncakeGetMarketStockNavigationGroups()) {
        const matchingGroups = mooncakeGetMarketStockNavigationGroupsForItem(itemHrid, groups);
        if (!matchingGroups.length) return null;
        const savedId = String(config.preferences.marketStockNavigationGroupId || '');
        return matchingGroups.find(group => group.id === savedId) || matchingGroups[0];
    }

    function mooncakeGetActiveMarketStockNavigationGroup(itemHrid, groups = mooncakeGetMarketStockNavigationGroups()) {
        const matchingGroup = mooncakeGetMarketStockNavigationGroupForItem(itemHrid, groups);
        if (!matchingGroup) return null;
        const manualSelection = mooncakeMarketStockNavigationManualSelection;
        if (manualSelection?.itemHrid !== itemHrid) return matchingGroup;
        return groups.find(group => group.id === manualSelection.groupId) || matchingGroup;
    }

    function mooncakeSetSelectedMarketStockNavigationGroup(groupId) {
        const groups = mooncakeGetMarketStockNavigationGroups();
        if (!groups.some(group => group.id === groupId)) return;
        if (config.preferences.marketStockNavigationGroupId === groupId) return;
        config.preferences.marketStockNavigationGroupId = groupId;
        saveConfig();
    }

    function mooncakeGetMarketStockNavigationTarget(group, currentHrid, direction) {
        const items = group?.items || [];
        if (!items.length) return '';
        const currentIndex = items.indexOf(currentHrid);
        if (currentIndex < 0) return direction < 0 ? items[items.length - 1] : items[0];
        return items[(currentIndex + direction + items.length) % items.length];
    }
