    function mooncakeGetFiberKey(el) {
        if (!el) return null;
        const cached = mooncakeFiberKeyCache.get(el);
        if (cached) return cached;
        if (mooncakeFiberKeyName !== null && mooncakeFiberKeyName in el) {
            mooncakeFiberKeyCache.set(el, mooncakeFiberKeyName);
            return mooncakeFiberKeyName;
        }
        const keys = Reflect.ownKeys(el);
        for (const key of keys) {
            if (typeof key === 'string' && key.startsWith('__reactFiber$')) {
                mooncakeFiberKeyName = key;
                mooncakeFiberKeyCache.set(el, key);
                return key;
            }
        }
        return null;
    }

    function mooncakeGetItemDetailOfHrid(hrid) {
        if (!hrid) return null;
        return mooncakeEnsureItemDetailMap()?.[hrid] || null;
    }

    const MOONCAKE_MARKET_HISTORY_API = 'https://q7.nainai.eu.org/api/market/histories';
    const MOONCAKE_MARKET_HISTORY_V1_CACHE_KEY = 'Mooncake_marketHistory_v1';
    const MOONCAKE_MARKET_HISTORY_V2_CACHE_KEY = 'Mooncake_marketHistory_v2';
    const MOONCAKE_MARKET_HISTORY_CACHE_KEY = 'Mooncake_marketHistory_v3';
    const MOONCAKE_MARKET_HISTORY_ENABLED_KEY = 'Mooncake_marketHistory_card_enabled_v1';
    const MOONCAKE_MARKET_HISTORY_CARD_SELL_FIRST_KEY = 'Mooncake_marketHistory_card_sell_first_v1';
    const MOONCAKE_MARKET_HISTORY_FLOAT_POSITION_KEY = 'Mooncake_marketHistory_relativePosition_v2';
    const MOONCAKE_MARKET_HISTORY_TTL = 5 * 60 * 1000;
    const MOONCAKE_MARKET_HISTORY_WINDOWS = [1, 3, 7];
    const MOONCAKE_MARKET_HISTORY_CARD_ID = 'MooncakeMarketHistoryCard';
    const MOONCAKE_MARKET_HISTORY_MOBILE_ID = 'MooncakeMarketHistoryMobileCard';
    const MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR = '[data-mooncake-history-floating="1"]';
    const MOONCAKE_MARKET_HISTORY_FOLLOWING_SELECTOR = '[data-mooncake-history-following="1"]';
    // Anchored cards use the elevated market-detail parent. Dragged cards move
    // to body, so they must sit just above the game's market modal (z-index 800)
    // without using the global maximum layer reserved for dialogs and menus.
    const MOONCAKE_MARKET_HISTORY_CARD_Z_INDEX = '2147483647';
    const MOONCAKE_MARKET_HISTORY_FLOAT_Z_INDEX = '801';
    const MOONCAKE_MARKET_HISTORY_PARENT_Z_INDEX = '11';
    const MOONCAKE_MARKET_HISTORY_LEGACY_ANCHOR_MARGIN = 26;
    const MOONCAKE_MARKET_HISTORY_ANCHOR_MARGIN = 120;
    const MOONCAKE_MARKET_HISTORY_FLOAT_SNAP_DISTANCE = 44;
    const MOONCAKE_MARKET_HISTORY_RANKING_ID = 'MooncakeMarketHistoryRankingPanel';
    const MOONCAKE_MARKET_SHORTAGE_ID = 'MooncakeMarketShortagePanel';
    const MOONCAKE_MARKET_BARGAIN_ID = 'MooncakeMarketBargainPanel';
    const MOONCAKE_MARKET_HISTORY_RANKING_PREFS_KEY = 'Mooncake_marketHistory_ranking_preferences_v1';
    const MOONCAKE_MARKET_SHORTAGE_PREFS_KEY = 'Mooncake_marketShortage_preferences_v1';
    const MOONCAKE_MARKET_BARGAIN_PREFS_KEY = 'Mooncake_marketBargain_preferences_v1';
    const MOONCAKE_MARKET_HISTORY_MAX_ENTRIES = 80;
    const MOONCAKE_MARKET_HISTORY_MEMORY_CACHE = new Map();
    const MOONCAKE_MARKET_HISTORY_DETAIL_MEMORY_CACHE = new Map();
    const MOONCAKE_MARKET_HISTORY_DETAIL_MAX_ENTRIES = 16;
    const MOONCAKE_RANKING_GRID_COLUMNS = '210px repeat(3,72px 128px 86px)';
    const MOONCAKE_RANKING_MIN_WIDTH = '1365px';
    const MOONCAKE_BARGAIN_ITEM_LEVEL = 90;
    const MOONCAKE_BARGAIN_HISTORY_PRICE_MAX_ENTRIES = 300;
    const MOONCAKE_BARGAIN_GRID_COLUMNS = 'minmax(220px,1.5fr) repeat(7,minmax(104px,1fr))';
    const MOONCAKE_BARGAIN_MIN_WIDTH = '1120px';
    let mooncakeMarketHistorySeq = 0;
    let mooncakeMarketHistoryRankingSort = 'turnover7';
    let mooncakeMarketHistoryRankingSeq = 0;
    let mooncakeMarketHistoryRankingAbortController = null;
    let mooncakeMarketBargainSeq = 0;
    let mooncakeMarketBargainAbortController = null;
    let mooncakeMarketHistoryCardAbortController = null;
    let mooncakeMarketHistoryActiveRequestKey = '';
    let mooncakeMarketHistoryScheduleTimer = 0;
    let mooncakeMarketHistoryFloatDrag = null;
    let mooncakeMarketHistoryResizeFrame = 0;
    let mooncakeMarketHistoryLastRenderKey = '';
    let mooncakeMarketHistoryLastRenderAt = 0;
    let mooncakeMarketHistoryWriteTimer = 0;
    let mooncakeMarketHistoryPendingWrites = null;
    let mooncakeMarketHistoryStackingState = null;
    let mooncakeBargainRecipeIndex = null;
    const mooncakeBargainHistoryPriceCache = new Map();

    function mooncakeIsMarketHistoryCardEnabled() {
        try {
            return localStorage.getItem(MOONCAKE_MARKET_HISTORY_ENABLED_KEY) !== '0';
        } catch (_) {
            return true;
        }
    }

    function mooncakeReadMarketHistoryFloatPosition() {
        try {
            const stored = JSON.parse(localStorage.getItem(MOONCAKE_MARKET_HISTORY_FLOAT_POSITION_KEY) || 'null');
            const offsetX = Number(stored?.offsetX);
            const offsetY = Number(stored?.offsetY);
            const anchorMargin = Number(stored?.anchorMargin);
            if (!Number.isFinite(offsetX) || !Number.isFinite(offsetY)) return null;
            return {
                offsetX,
                offsetY,
                anchorMargin: Number.isFinite(anchorMargin) ? anchorMargin : MOONCAKE_MARKET_HISTORY_LEGACY_ANCHOR_MARGIN,
                viewportRatioX: Number(stored?.viewportRatioX),
                viewportRatioY: Number(stored?.viewportRatioY),
                viewportWidth: Number(stored?.viewportWidth),
                viewportHeight: Number(stored?.viewportHeight)
            };
        } catch (_) {
            return null;
        }
    }

    function mooncakeRestoreMarketHistoryStacking() {
        const state = mooncakeMarketHistoryStackingState;
        if (!state) return;
        if (
            state.parent.style.getPropertyValue('z-index') === MOONCAKE_MARKET_HISTORY_PARENT_Z_INDEX &&
            state.parent.style.getPropertyPriority('z-index') === ''
        ) {
            if (state.originalValue) {
                state.parent.style.setProperty('z-index', state.originalValue, state.originalPriority);
            } else {
                state.parent.style.removeProperty('z-index');
            }
        }
        mooncakeMarketHistoryStackingState = null;
    }

    function mooncakeElevateMarketHistoryStacking(currentItem) {
        const stackingParent = currentItem?.closest?.('[class*="MarketplacePanel_infoContainer"]');
        if (!stackingParent) {
            mooncakeRestoreMarketHistoryStacking();
            return;
        }
        if (!mooncakeMarketHistoryStackingState || mooncakeMarketHistoryStackingState.parent !== stackingParent) {
            mooncakeRestoreMarketHistoryStacking();
            mooncakeMarketHistoryStackingState = {
                parent: stackingParent,
                originalValue: stackingParent.style.getPropertyValue('z-index'),
                originalPriority: stackingParent.style.getPropertyPriority('z-index')
            };
        }
        stackingParent.style.setProperty('z-index', MOONCAKE_MARKET_HISTORY_PARENT_Z_INDEX);
    }

    function mooncakeGetMarketHistoryFloatOrigin(currentItem = null) {
        const anchor = currentItem || mooncakeFindCurrentMarketItemNode();
        if (!anchor?.isConnected) return null;
        const rect = anchor.getBoundingClientRect();
        if (!(rect.width > 0 && rect.height > 0)) return null;
        // The temporary card starts at left:100% + the anchor margin and top:-20px, then the
        // floating conversion adds 10px. Keep drag persistence relative to that
        // natural position so alternate market layouts can share one offset.
        return { left: rect.right + MOONCAKE_MARKET_HISTORY_ANCHOR_MARGIN + 10, top: rect.top - 10 };
    }

    function mooncakeWriteMarketHistoryFloatPosition(card, currentItem = null) {
        const rect = card?.getBoundingClientRect?.();
        const origin = mooncakeGetMarketHistoryFloatOrigin(currentItem);
        if (!rect || !origin) return;
        const offsetX = rect.left - origin.left;
        const offsetY = rect.top - origin.top;
        if (!Number.isFinite(offsetX) || !Number.isFinite(offsetY)) return;
        const margin = 8;
        const viewportWidth = Math.max(1, Number(window.innerWidth) || 1);
        const viewportHeight = Math.max(1, Number(window.innerHeight) || 1);
        const availableWidth = Math.max(1, viewportWidth - Number(rect.width || 0) - margin * 2);
        const availableHeight = Math.max(1, viewportHeight - Number(rect.height || 0) - margin * 2);
        const viewportRatioX = Math.min(1, Math.max(0, (rect.left - margin) / availableWidth));
        const viewportRatioY = Math.min(1, Math.max(0, (rect.top - margin) / availableHeight));
        try {
            localStorage.setItem(MOONCAKE_MARKET_HISTORY_FLOAT_POSITION_KEY, JSON.stringify({
                offsetX,
                offsetY,
                anchorMargin: MOONCAKE_MARKET_HISTORY_ANCHOR_MARGIN,
                viewportRatioX,
                viewportRatioY,
                viewportWidth,
                viewportHeight
            }));
        } catch (_) {}
    }

    function mooncakeClearMarketHistoryFloatPosition() {
        try {
            localStorage.removeItem(MOONCAKE_MARKET_HISTORY_FLOAT_POSITION_KEY);
        } catch (_) {}
    }

    function mooncakeHasViewportHistoryPosition(savedPosition) {
        if (!savedPosition) return false;
        const ratioX = Number(savedPosition.viewportRatioX);
        const ratioY = Number(savedPosition.viewportRatioY);
        const previousWidth = Number(savedPosition.viewportWidth);
        const previousHeight = Number(savedPosition.viewportHeight);
        return [ratioX, ratioY, previousWidth, previousHeight].every(Number.isFinite) && previousWidth > 0 && previousHeight > 0;
    }

    function mooncakeShouldUseViewportHistoryPosition(savedPosition) {
        if (!mooncakeHasViewportHistoryPosition(savedPosition)) return false;
        const previousWidth = Number(savedPosition.viewportWidth);
        const previousHeight = Number(savedPosition.viewportHeight);
        const widthChange = Math.abs(window.innerWidth - previousWidth) / previousWidth;
        const heightChange = Math.abs(window.innerHeight - previousHeight) / previousHeight;
        return widthChange >= 0.18 || heightChange >= 0.18;
    }

    function mooncakeGetViewportHistoryPosition(card, savedPosition) {
        const rect = card?.getBoundingClientRect?.();
        if (!rect || !savedPosition) return null;
        const margin = 8;
        const availableWidth = Math.max(1, window.innerWidth - Number(rect.width || 0) - margin * 2);
        const availableHeight = Math.max(1, window.innerHeight - Number(rect.height || 0) - margin * 2);
        const ratioX = Math.min(1, Math.max(0, Number(savedPosition.viewportRatioX)));
        const ratioY = Math.min(1, Math.max(0, Number(savedPosition.viewportRatioY)));
        return {
            left: margin + availableWidth * ratioX,
            top: margin + availableHeight * ratioY
        };
    }

    function mooncakeShouldSnapMarketHistoryCardToOrigin(card, currentItem = null) {
        const rect = card?.getBoundingClientRect?.();
        const origin = mooncakeGetMarketHistoryFloatOrigin(currentItem);
        if (!rect || !origin) return false;
        return Math.hypot(rect.left - origin.left, rect.top - origin.top) <= MOONCAKE_MARKET_HISTORY_FLOAT_SNAP_DISTANCE;
    }

    function mooncakeRestoreFollowingMarketHistoryCardToAnchor(card = mooncakeGetMarketHistoryFollowingCard()) {
        if (!card?.matches?.(MOONCAKE_MARKET_HISTORY_FOLLOWING_SELECTOR)) return false;
        const target = mooncakeGetCurrentMarketHistoryTarget();
        mooncakeClearMarketHistoryFloatPosition();
        if (!target || target.itemHrid !== card.dataset.itemHrid || Number(target.level) !== Number(card.dataset.level)) {
            card.remove();
            scheduleMooncakeMarketHistoryCard(0, { force: true });
            return true;
        }

        card.removeAttribute('data-mooncake-history-floating');
        card.removeAttribute('data-mooncake-history-following');
        card.removeAttribute('data-mooncake-history-float-left');
        card.removeAttribute('data-mooncake-history-float-top');
        card.removeAttribute('data-mooncake-history-float-width');
        card.removeAttribute('data-mooncake-history-float-z-index');
        card.removeAttribute('data-mooncake-history-suppress-click');
        card.dataset.mooncakeHistoryCollapsed = '0';
        card.id = MOONCAKE_MARKET_HISTORY_CARD_ID;
        target.currentItem.appendChild(card);
        card.removeAttribute('style');
        mooncakeRenderMarketHistoryCard(
            target,
            card._mooncakeMarketHistoryWindows,
            card._mooncakeMarketHistoryStateText || ''
        );
        return true;
    }

    function mooncakeResetMarketHistoryCardPosition() {
        mooncakeClearMarketHistoryFloatPosition();
        const floatingCard = mooncakeGetMarketHistoryFollowingCard();
        if (floatingCard) {
            mooncakeRestoreFollowingMarketHistoryCardToAnchor(floatingCard);
            return;
        }
        scheduleMooncakeMarketHistoryCard(0, { force: true });
    }

    const MOONCAKE_MARKET_HISTORY_MOBILE_COLUMN_KEYS = ['average', 'median', 'volume', 'buySell', 'range', 'hourly'];

    function mooncakeGetMarketHistoryMobileColumns() {
        const stored = config.preferences?.marketHistoryMobileColumns;
        const defaults = DEFAULT_PREFERENCES.marketHistoryMobileColumns;
        const columns = {};
        for (const key of MOONCAKE_MARKET_HISTORY_MOBILE_COLUMN_KEYS) {
            columns[key] = stored?.[key] !== undefined ? stored[key] !== false : defaults[key] !== false;
        }
        return columns;
    }

    function mooncakeRefreshMarketHistoryCards() {
        // 桌面端与手机端共用同一份列配置，切换后两个卡片都重新渲染。
        const isMobile = mooncakeIsPhoneMarketUi();
        const cardId = isMobile ? MOONCAKE_MARKET_HISTORY_MOBILE_ID : MOONCAKE_MARKET_HISTORY_CARD_ID;
        const card = document.getElementById(cardId);
        const target = mooncakeGetCurrentMarketHistoryTarget();
        if (!card || !target || card.dataset.itemHrid !== target.itemHrid || Number(card.dataset.level) !== Number(target.level)) return;
        mooncakeRenderMarketHistoryCard(
            target,
            card._mooncakeMarketHistoryWindows,
            card._mooncakeMarketHistoryStateText || ''
        );
    }

    function mooncakeRefreshMobileMarketHistoryCard() {
        if (!mooncakeIsPhoneMarketUi()) return;
        mooncakeRefreshMarketHistoryCards();
    }

    function mooncakeSetMarketHistoryMobileColumn(column, enabled) {
        if (!MOONCAKE_MARKET_HISTORY_MOBILE_COLUMN_KEYS.includes(column)) return;
        const columns = mooncakeGetMarketHistoryMobileColumns();
        columns[column] = enabled !== false;
        if (!Object.values(columns).some(Boolean)) columns.average = true;
        if (!config.preferences) config.preferences = {};
        config.preferences.marketHistoryMobileColumns = columns;
        saveConfig();
        mooncakeRefreshMarketHistoryCards();
    }

    function mooncakeIsMarketHistoryCardSellFirst() {
        try {
            return localStorage.getItem(MOONCAKE_MARKET_HISTORY_CARD_SELL_FIRST_KEY) !== '0';
        } catch (_) {
            return true;
        }
    }

    function mooncakeGetMarketHistoryCardOrderPresentation(sellFirst) {
        const isSellFirst = sellFirst !== false;
        return isSellFirst
            ? {
                priceHeader: 'max/min',
                hourlyHeader: isZH ? '工时' : 'Hourly',
                nextTitle: isZH ? '切换为 min/max 及对应工时顺序' : 'Switch to min/max and matching hourly order',
                toggleLabel: isZH ? '切换价格和工时顺序' : 'Toggle price and hourly order'
            }
            : {
                priceHeader: 'min/max',
                hourlyHeader: isZH ? '工时' : 'Hourly',
                nextTitle: isZH ? '切换为 max/min 及对应工时顺序' : 'Switch to max/min and matching hourly order',
                toggleLabel: isZH ? '切换价格和工时顺序' : 'Toggle price and hourly order'
            };
    }

    function mooncakeApplyMarketHistoryCardOrder(sellFirst) {
        const selectedOrder = sellFirst !== false ? 'sell-first' : 'buy-first';
        const presentation = mooncakeGetMarketHistoryCardOrderPresentation(sellFirst);
        document.querySelectorAll(`#${MOONCAKE_MARKET_HISTORY_CARD_ID}, #${MOONCAKE_MARKET_HISTORY_MOBILE_ID}, ${MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR}`).forEach(card => {
            card.querySelectorAll('[data-mooncake-history-order-value]').forEach(value => {
                value.hidden = value.getAttribute('data-mooncake-history-order-value') !== selectedOrder;
            });
            card.querySelectorAll('[data-mooncake-history-order-label]').forEach(label => {
                label.textContent = selectedOrder === 'sell-first'
                    ? (label.getAttribute('data-sell-first-label') || '')
                    : (label.getAttribute('data-buy-first-label') || '');
            });
            card.querySelectorAll('[data-mooncake-history-order-toggle]').forEach(button => {
                button.title = presentation.nextTitle;
                button.setAttribute('aria-label', presentation.toggleLabel);
                button.setAttribute('aria-pressed', String(selectedOrder === 'buy-first'));
            });
        });
    }

    function mooncakeSetMarketHistoryCardSellFirst(sellFirst) {
        const shouldSellFirst = sellFirst !== false;
        try {
            localStorage.setItem(MOONCAKE_MARKET_HISTORY_CARD_SELL_FIRST_KEY, shouldSellFirst ? '1' : '0');
        } catch (_) {}
        mooncakeApplyMarketHistoryCardOrder(shouldSellFirst);
    }

    function mooncakeUpdateMarketHistoryToggleButtons() {
        const enabled = mooncakeIsMarketHistoryCardEnabled();
        const label = isZH ? `交易卡片：${enabled ? '开' : '关'}` : `Trading card: ${enabled ? 'On' : 'Off'}`;
        const title = isZH
            ? (enabled ? '关闭市场交易卡片' : '开启市场交易卡片')
            : (enabled ? 'Hide market trading card' : 'Show market trading card');
        document.querySelectorAll('[data-mooncake-market-history-switch]').forEach(button => {
            button.textContent = label;
            button.title = title;
            button.setAttribute('aria-pressed', String(enabled));
            Object.assign(button.style, enabled ? {
                borderColor: 'rgba(137,210,155,.42)',
                background: 'rgba(42,78,54,.72)',
                color: 'rgba(225,255,231,.95)'
            } : {
                borderColor: 'rgba(170,180,198,.28)',
                background: 'rgba(54,58,68,.58)',
                color: 'rgba(220,225,233,.72)'
            });
        });
    }

    function mooncakeSetMarketHistoryCardEnabled(enabled) {
        const shouldEnable = !!enabled;
        try {
            localStorage.setItem(MOONCAKE_MARKET_HISTORY_ENABLED_KEY, shouldEnable ? '1' : '0');
        } catch (_) {}
        mooncakeUpdateMarketHistoryToggleButtons();

        if (!shouldEnable) {
            if (mooncakeMarketHistoryScheduleTimer) {
                clearTimeout(mooncakeMarketHistoryScheduleTimer);
                mooncakeMarketHistoryScheduleTimer = 0;
            }
            mooncakeMarketHistorySeq++;
            mooncakeMarketHistoryCardAbortController?.abort();
            mooncakeMarketHistoryCardAbortController = null;
            mooncakeMarketHistoryActiveRequestKey = '';
            mooncakeRemoveMarketHistoryCards({ includeFloating: true });
            mooncakeMarketHistoryLastRenderKey = '';
            mooncakeMarketHistoryLastRenderAt = 0;
            return;
        }

        mooncakeMarketHistoryLastRenderKey = '';
        mooncakeMarketHistoryLastRenderAt = 0;
        scheduleMooncakeMarketHistoryCard(0, { force: true });
    }

    function mooncakeReadMarketHistoryCache() {
        try {
            const raw = localStorage.getItem(MOONCAKE_MARKET_HISTORY_CACHE_KEY);
            return raw ? JSON.parse(raw) || {} : {};
        } catch (_) {
            return {};
        }
    }

    function mooncakeWriteMarketHistoryCache(cache) {
        try {
            const now = Date.now();
            const entries = Object.entries(cache || {})
                .filter(([, entry]) => now - (entry?.timestamp || 0) < MOONCAKE_MARKET_HISTORY_TTL)
                .sort((a, b) => (b[1]?.timestamp || 0) - (a[1]?.timestamp || 0))
                .slice(0, MOONCAKE_MARKET_HISTORY_MAX_ENTRIES);
            localStorage.setItem(MOONCAKE_MARKET_HISTORY_CACHE_KEY, JSON.stringify(Object.fromEntries(entries)));
        } catch (_) {}
    }

    function mooncakeMarketHistoryCacheKey(itemHrid, variant) {
        return `${itemHrid}|${variant}`;
    }

    function mooncakeGetCachedMarketHistory(itemHrid, variant, readPersistentCache = mooncakeReadMarketHistoryCache) {
        const key = mooncakeMarketHistoryCacheKey(itemHrid, variant);
        const memory = MOONCAKE_MARKET_HISTORY_MEMORY_CACHE.get(key);
        if (memory && Date.now() - memory.timestamp < MOONCAKE_MARKET_HISTORY_TTL && memory.windows) {
            mooncakeSetBoundedMapEntry(
                MOONCAKE_MARKET_HISTORY_MEMORY_CACHE,
                key,
                memory,
                MOONCAKE_MARKET_HISTORY_MAX_ENTRIES
            );
            return memory.windows;
        }
        if (memory) MOONCAKE_MARKET_HISTORY_MEMORY_CACHE.delete(key);
        const cache = readPersistentCache();
        const stored = cache[key];
        if (stored && Date.now() - stored.timestamp < MOONCAKE_MARKET_HISTORY_TTL && stored.windows) {
            mooncakeSetBoundedMapEntry(
                MOONCAKE_MARKET_HISTORY_MEMORY_CACHE,
                key,
                stored,
                MOONCAKE_MARKET_HISTORY_MAX_ENTRIES
            );
            return stored.windows;
        }
        return null;
    }

    function mooncakeSetCachedMarketHistory(itemHrid, variant, windows, options = {}) {
        if (!itemHrid || !Number.isFinite(Number(variant)) || !windows || typeof windows !== 'object') return;
        const key = mooncakeMarketHistoryCacheKey(itemHrid, variant);
        if (!options.preserveTimeline) MOONCAKE_MARKET_HISTORY_DETAIL_MEMORY_CACHE.delete(key);
        const entry = { timestamp: Date.now(), windows };
        mooncakeSetBoundedMapEntry(
            MOONCAKE_MARKET_HISTORY_MEMORY_CACHE,
            key,
            entry,
            MOONCAKE_MARKET_HISTORY_MAX_ENTRIES
        );
        if (!mooncakeMarketHistoryPendingWrites) mooncakeMarketHistoryPendingWrites = {};
        mooncakeMarketHistoryPendingWrites[key] = entry;
        if (mooncakeMarketHistoryWriteTimer) return;
        mooncakeMarketHistoryWriteTimer = setTimeout(() => {
            mooncakeMarketHistoryWriteTimer = 0;
            const pending = mooncakeMarketHistoryPendingWrites;
            mooncakeMarketHistoryPendingWrites = null;
            if (!pending) return;
            const cache = mooncakeReadMarketHistoryCache();
            Object.assign(cache, pending);
            mooncakeWriteMarketHistoryCache(cache);
        }, 250);
    }

    function mooncakeGetCachedMarketHistoryTimeline(itemHrid, variant) {
        const key = mooncakeMarketHistoryCacheKey(itemHrid, variant);
        const entry = MOONCAKE_MARKET_HISTORY_DETAIL_MEMORY_CACHE.get(key);
        if (!entry) return null;
        if (Date.now() - entry.timestamp >= MOONCAKE_MARKET_HISTORY_TTL || !entry.timeline) {
            MOONCAKE_MARKET_HISTORY_DETAIL_MEMORY_CACHE.delete(key);
            return null;
        }
        MOONCAKE_MARKET_HISTORY_DETAIL_MEMORY_CACHE.delete(key);
        MOONCAKE_MARKET_HISTORY_DETAIL_MEMORY_CACHE.set(key, entry);
        return entry.timeline;
    }

    function mooncakeSetCachedMarketHistoryTimeline(itemHrid, variant, timeline) {
        if (!itemHrid || !Number.isFinite(Number(variant)) || !timeline || typeof timeline !== 'object') return;
        const key = mooncakeMarketHistoryCacheKey(itemHrid, variant);
        mooncakeSetBoundedMapEntry(
            MOONCAKE_MARKET_HISTORY_DETAIL_MEMORY_CACHE,
            key,
            { timestamp: Date.now(), timeline },
            MOONCAKE_MARKET_HISTORY_DETAIL_MAX_ENTRIES
        );
    }

    function mooncakeAttachMarketHistoryTimeline(windows, timeline) {
        if (!windows || !timeline) return windows;
        const enriched = {};
        for (const days of MOONCAKE_MARKET_HISTORY_WINDOWS) {
            const row = windows[days] || {};
            enriched[days] = {
                ...row,
                timeline: Array.isArray(timeline[days]) ? timeline[days] : []
            };
        }
        return enriched;
    }

    async function mooncakeReadJsonResponse(response) {
        const buffer = await response.arrayBuffer();
        const originalBytes = new Uint8Array(buffer);
        const encoding = (response.headers.get('content-encoding') || '').toLowerCase();
        const attempted = [];

        const parseBytes = (bytes) => {
            const text = new TextDecoder('utf-8').decode(bytes).replace(/^\uFEFF/, '');
            try {
                return JSON.parse(text);
            } catch (_) {
                return null;
            }
        };

        const direct = parseBytes(originalBytes);
        if (direct !== null) return direct;

        const decompress = async (bytes, format) => {
            let nativeError = null;
            if (typeof DecompressionStream === 'function') {
                try {
                    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream(format));
                    return new Uint8Array(await new Response(stream).arrayBuffer());
                } catch (error) {
                    nativeError = error;
                }
            }

            const pakoApi = (typeof globalThis !== 'undefined' && globalThis.pako) ||
                (typeof window !== 'undefined' && window.pako) || null;
            const pakoDecoder = format === 'gzip'
                ? pakoApi?.ungzip
                : format === 'deflate'
                    ? pakoApi?.inflate
                    : pakoApi?.inflateRaw;
            if (typeof pakoDecoder === 'function') {
                try {
                    return new Uint8Array(pakoDecoder(bytes));
                } catch (error) {
                    nativeError = error;
                }
            }
            throw nativeError || new Error('No decompression implementation available');
        };

        const looksGzip = originalBytes.length >= 2 && originalBytes[0] === 0x1f && originalBytes[1] === 0x8b;
        const startsZlib = originalBytes.length >= 2 && originalBytes[0] === 0x78;
        const formats = [];
        const addFormat = format => {
            if (!formats.includes(format)) formats.push(format);
        };
        if (looksGzip || encoding.includes('gzip')) addFormat('gzip');
        if (startsZlib || encoding.includes('deflate')) addFormat('deflate');
        // The history API sometimes returns raw DEFLATE while omitting the encoding header.
        addFormat('deflate-raw');

        let bytes = originalBytes;
        for (const format of formats) {
            attempted.push(format);
            try {
                bytes = await decompress(originalBytes, format);
                const parsed = parseBytes(bytes);
                if (parsed !== null) return parsed;

                // Handle an outer HTTP compression layer around the API's raw DEFLATE body.
                if (format !== 'deflate-raw') {
                    attempted.push(`${format}->deflate-raw`);
                    bytes = await decompress(bytes, 'deflate-raw');
                    const nested = parseBytes(bytes);
                    if (nested !== null) return nested;
                }
            } catch (_) {}
        }

        const firstBytes = Array.from(bytes.slice(0, 4)).map(value => value.toString(16).padStart(2, '0')).join('');
        throw new SyntaxError(`Invalid JSON response (${response.status}, encoding ${encoding || 'none'}, bytes ${firstBytes}, decoders ${attempted.join(',') || 'none'})`);
    }

    async function fetchMarketHistories(itemHrids, variants, days = 7, options = {}) {
        const hrids = [...new Set((Array.isArray(itemHrids) ? itemHrids : [itemHrids]).filter(Boolean))];
        const levels = [...new Set((Array.isArray(variants) ? variants : [variants])
            .map(v => parseInt(v, 10))
            .filter(v => Number.isFinite(v) && v >= 0 && v <= 20))];
        if (!hrids.length || !levels.length) return {};

        const includeTimeline = options.includeTimeline === true;
        const result = {};
        const missingByHrid = new Map();
        if (!options.force) {
            let persistentCache = null;
            let persistentCacheLoaded = false;
            const readPersistentCache = () => {
                if (!persistentCacheLoaded) {
                    persistentCache = mooncakeReadMarketHistoryCache();
                    persistentCacheLoaded = true;
                }
                return persistentCache;
            };
            for (const hrid of hrids) {
                for (const level of levels) {
                    const cached = mooncakeGetCachedMarketHistory(hrid, level, readPersistentCache);
                    const timeline = includeTimeline
                        ? mooncakeGetCachedMarketHistoryTimeline(hrid, level)
                        : null;
                    if (cached && (!includeTimeline || timeline)) {
                        if (!result[hrid]) result[hrid] = {};
                        result[hrid][String(level)] = includeTimeline
                            ? mooncakeAttachMarketHistoryTimeline(cached, timeline)
                            : cached;
                    } else {
                        if (!missingByHrid.has(hrid)) missingByHrid.set(hrid, []);
                        missingByHrid.get(hrid).push(level);
                    }
                }
            }
        } else {
            hrids.forEach(hrid => missingByHrid.set(hrid, levels.slice()));
        }
        if (!missingByHrid.size) return result;

        const requestController = new AbortController();
        const signal = requestController.signal;
        const externalSignal = options.signal;
        let timedOut = false;
        const onExternalAbort = () => requestController.abort();
        if (externalSignal?.aborted) {
            requestController.abort();
        } else if (externalSignal) {
            externalSignal.addEventListener('abort', onExternalAbort, { once: true });
        }
        const timeoutId = setTimeout(() => {
            timedOut = true;
            requestController.abort();
        }, options.timeoutMs || 8000);
        try {
            const missingLevels = [...new Set([...missingByHrid.values()].flat())];
            for (const level of missingLevels) {
                const levelHrids = [...missingByHrid.entries()]
                    .filter(([, levelsForHrid]) => levelsForHrid.includes(level))
                    .map(([hrid]) => hrid);
                if (!levelHrids.length) continue;
                const params = new URLSearchParams();
                for (const hrid of levelHrids) params.append('item_id', hrid);
                params.append('variant', String(level));
                params.set('days', String(days));
                let json = null;
                const maxRetries = Number.isFinite(Number(options.maxRetries))
                    ? Math.max(0, Math.min(2, parseInt(options.maxRetries, 10)))
                    : 2;
                for (let attempt = 0; attempt <= maxRetries; attempt++) {
                    const requestParams = new URLSearchParams(params);
                    if (attempt > 0) requestParams.set('_mooncake_retry', `${Date.now()}_${attempt}`);
                    try {
                        const res = await fetch(`${MOONCAKE_MARKET_HISTORY_API}?${requestParams.toString()}`, {
                            signal,
                            cache: attempt > 0 ? 'no-store' : 'default',
                            headers: { accept: 'application/json' }
                        });
                        if (!res.ok) {
                            const error = new Error(`market histories ${res.status}`);
                            error.status = res.status;
                            throw error;
                        }
                        json = await mooncakeReadJsonResponse(res);
                        break;
                    } catch (error) {
                        if (error?.name === 'AbortError' && !timedOut) throw error;
                        if (error?.name === 'AbortError' && timedOut) {
                            const timeoutError = new Error('market histories timeout');
                            timeoutError.code = 'MOONCAKE_TIMEOUT';
                            error = timeoutError;
                        }
                        const retryableStatus = [408, 425, 429].includes(Number(error?.status)) || Number(error?.status) >= 500;
                        const retryable = error instanceof SyntaxError || error?.name === 'TypeError' || retryableStatus;
                        if (!retryable || attempt >= maxRetries) throw error;
                        await new Promise(resolve => setTimeout(resolve, 150 * (attempt + 1)));
                    }
                }
                for (const [hrid, levelsObj] of Object.entries(json || {})) {
                    const data = levelsObj?.[String(level)];
                    if (!Array.isArray(data)) continue;
                    const processed = processMarketHistory(data, { includeTimeline });
                    const windows = includeTimeline ? processed.windows : processed;
                    const timeline = includeTimeline ? processed.timeline : null;
                    if (!result[hrid]) result[hrid] = {};
                    mooncakeSetCachedMarketHistory(hrid, level, windows, { preserveTimeline: includeTimeline });
                    if (includeTimeline) {
                        mooncakeSetCachedMarketHistoryTimeline(hrid, level, timeline);
                        result[hrid][String(level)] = mooncakeAttachMarketHistoryTimeline(windows, timeline);
                    } else {
                        result[hrid][String(level)] = windows;
                    }
                }
            }
        } finally {
            clearTimeout(timeoutId);
            externalSignal?.removeEventListener?.('abort', onExternalAbort);
        }
        return result;
    }

    function mooncakeGetMarketHistoryPriceStats(history, options = {}) {
        const includeTimeline = options.includeTimeline === true;
        const points = [];
        const timeline = includeTimeline ? [] : null;
        let latestTradeAt = 0;
        for (const item of history || []) {
            const price = Number(item?.p);
            const volume = Number(item?.v);
            if (!Number.isFinite(price) || price <= 0 || !Number.isFinite(volume) || volume <= 0) continue;
            points.push({ price, volume });
            const tradeAt = Number(item?.time);
            if (Number.isFinite(tradeAt) && tradeAt > 0) {
                if (tradeAt > latestTradeAt) latestTradeAt = tradeAt;
                if (timeline) timeline.push({ time: Math.floor(tradeAt), price, volume });
            }
        }
        if (!points.length) {
            return {
                minPrice: 0,
                maxPrice: 0,
                p10Price: 0,
                medianPrice: 0,
                p90Price: 0,
                activeTradePeriods: 0,
                latestTradeAt: 0,
                timeline: []
            };
        }

        points.sort((a, b) => a.price - b.price);
        const total = points.reduce((sum, item) => sum + item.volume, 0);
        const priceAtPercentile = percentile => {
            const target = total * percentile;
            let accumulated = 0;
            for (const item of points) {
                accumulated += item.volume;
                if (accumulated >= target) return item.price;
            }
            return points.at(-1)?.price || 0;
        };

        return {
            minPrice: points[0]?.price || 0,
            maxPrice: points.at(-1)?.price || 0,
            p10Price: priceAtPercentile(0.1),
            medianPrice: priceAtPercentile(0.5),
            p90Price: priceAtPercentile(0.9),
            activeTradePeriods: points.length,
            latestTradeAt,
            timeline: timeline
                ? timeline.sort((left, right) => left.time - right.time || left.price - right.price)
                : []
        };
    }

    // Marketplace ticks are now one tenth of the former values. Prices remain
    // integer coins, so the smallest valid tick is one coin.
    const MOONCAKE_MARKET_PRICE_TIERS = [
            { max: 500, step: 1, offset: 0 },
            { max: 1000, step: 2, offset: 500 },
            { max: 3000, step: 5, offset: 1000 },
            { max: 5000, step: 10, offset: 3000 },
            { max: 10000, step: 20, offset: 5000 },
            { max: 30000, step: 50, offset: 10000 },
            { max: 50000, step: 100, offset: 30000 },
            { max: 100000, step: 200, offset: 50000 },
            { max: 300000, step: 500, offset: 100000 },
            { max: 500000, step: 1000, offset: 300000 },
            { max: 1000000, step: 2000, offset: 500000 },
            { max: 3000000, step: 5000, offset: 1000000 },
            { max: 5000000, step: 10000, offset: 3000000 },
            { max: 10000000, step: 20000, offset: 5000000 },
            { max: 30000000, step: 50000, offset: 10000000 },
            { max: 50000000, step: 100000, offset: 30000000 },
            { max: 100000000, step: 200000, offset: 50000000 },
            { max: 300000000, step: 500000, offset: 100000000 },
            { max: 500000000, step: 1000000, offset: 300000000 },
            { max: 1000000000, step: 2000000, offset: 500000000 },
            { max: 3000000000, step: 5000000, offset: 1000000000 },
            { max: 5000000000, step: 10000000, offset: 3000000000 },
            { max: 10000000000, step: 20000000, offset: 5000000000 },
            { max: 30000000000, step: 50000000, offset: 10000000000 },
            { max: 50000000000, step: 100000000, offset: 30000000000 }
    ];

    function mooncakeGetMarketPriceTier(price) {
        const num = Math.abs(Number(price));
        if (!Number.isFinite(num)) return null;
        const tier = MOONCAKE_MARKET_PRICE_TIERS.find(item => num < item.max);
        if (tier) return tier;

        // Continue the game's leading-digit progression above the explicit
        // common ranges instead of freezing prices above 50B on one step.
        const integer = Math.max(1, Math.floor(num));
        const digits = Math.floor(Math.log10(integer)) + 1;
        const magnitude = Math.pow(10, digits - 1);
        const leadingDigit = Math.floor(integer / magnitude);
        if (leadingDigit <= 2) {
            return {
                max: 3 * magnitude,
                step: Math.max(1, 5 * Math.pow(10, digits - 4)),
                offset: magnitude
            };
        }
        if (leadingDigit <= 4) {
            return {
                max: 5 * magnitude,
                step: Math.max(1, Math.pow(10, digits - 3)),
                offset: 3 * magnitude
            };
        }
        return {
            max: 10 * magnitude,
            step: Math.max(1, 2 * Math.pow(10, digits - 3)),
            offset: 5 * magnitude
        };
    }

    function mooncakeGetMarketPriceDisplayParts(value) {
        const num = Number(value);
        if (!Number.isFinite(num)) return null;
        const abs = Math.abs(num);
        const sign = num < 0 ? '-' : '';
        let divisor = 1;
        let unit = '';
        if (abs >= 1e12) {
            divisor = 1e12;
            unit = 'T';
        } else if (abs >= 1e9) {
            divisor = 1e9;
            unit = 'B';
        } else if (abs >= 1e6) {
            divisor = 1e6;
            unit = 'M';
        } else if (abs >= 1e3) {
            divisor = 1e3;
            unit = 'K';
        }
        const priceStep = Number(mooncakeGetMarketPriceTier(abs)?.step);
        const decimalPlaces = priceStep > 0 && priceStep < divisor
            ? Math.min(4, Math.max(3, Math.ceil(Math.log10(divisor / priceStep) - 1e-9)))
            : 3;
        const text = (abs / divisor).toFixed(decimalPlaces)
            .replace(/\.0+$/, '')
            .replace(/(\.\d*[1-9])0+$/, '$1');
        return { text: sign + text, unit };
    }

    function mooncakeFormatMarketPrice(value) {
        const parts = mooncakeGetMarketPriceDisplayParts(value);
        return parts ? `${parts.text}${parts.unit}` : '-';
    }

    function mooncakeSnapMarketPrice(price, direction = 'down') {
        const num = Number(price);
        if (!Number.isFinite(num) || num <= 0) return 0;
        const tier = mooncakeGetMarketPriceTier(num);
        if (!tier) return 0;
        const rawIndex = (num - tier.offset) / tier.step;
        const epsilon = 1e-9;
        const index = direction === 'up'
            ? Math.ceil(rawIndex - epsilon)
            : Math.floor(rawIndex + epsilon);
        return Math.max(1, tier.offset + Math.max(0, index) * tier.step);
    }

    function mooncakeMarketHistoryPriceTier(price, direction) {
        return mooncakeSnapMarketPrice(price, direction === 'up' ? 'up' : 'down');
    }

    function mooncakeEstimateMarketHistorySideVolumes(rows) {
        const orderedRows = (rows || []).map((item, index) => ({ item, index, time: Number(item?.time) }));
        let lastTime = -Infinity;
        const needsSort = orderedRows.some(entry => {
            if (!Number.isFinite(entry.time)) return false;
            if (entry.time < lastTime) return true;
            lastTime = entry.time;
            return false;
        });
        if (needsSort) {
            orderedRows.sort((left, right) => {
                const leftTime = Number.isFinite(left.time) ? left.time : Infinity;
                const rightTime = Number.isFinite(right.time) ? right.time : Infinity;
                return leftTime - rightTime || left.index - right.index;
            });
        }
        const fallbackQuoteMaxAge = 2 * 60 * 60;
        let previousQuote = null;
        let buyVolume = 0;
        let totalVolume = 0;

        for (const entry of orderedRows) {
            const item = entry.item;
            const time = entry.time;
            const ask = Number(item?.a);
            const bid = Number(item?.b);
            const hasCurrentQuote = Number.isFinite(ask) && Number.isFinite(bid) && ask > bid && bid > 0;
            const hasFreshFallback = previousQuote && Number.isFinite(time)
                && time >= previousQuote.time && time - previousQuote.time <= fallbackQuoteMaxAge;
            const price = Number(item?.p);
            const volume = Number(item?.v);

            if (Number.isFinite(volume) && volume > 0) {
                let quoteAsk = ask;
                let quoteBid = bid;
                if (!hasCurrentQuote && hasFreshFallback) {
                    if (!(quoteAsk > 0)) quoteAsk = previousQuote.ask;
                    if (!(quoteBid > 0)) quoteBid = previousQuote.bid;
                    if (!(quoteAsk > quoteBid && quoteBid > 0)) {
                        quoteAsk = previousQuote.ask;
                        quoteBid = previousQuote.bid;
                    }
                }

                let buyRatio = 0.5;
                if (Number.isFinite(price) && price > 0 && quoteAsk > quoteBid && quoteBid > 0) {
                    buyRatio = Math.max(0, Math.min(1, (price - quoteBid) / (quoteAsk - quoteBid)));
                } else if (Number.isFinite(price) && price > 0 && ask > 0 && !(bid > 0) && price >= ask) {
                    buyRatio = 1;
                } else if (Number.isFinite(price) && price > 0 && bid > 0 && !(ask > 0) && price <= bid) {
                    buyRatio = 0;
                }
                buyVolume += volume * buyRatio;
                totalVolume += volume;
            }

            // Keep the latest complete quote for a nearby incomplete historical record.
            if (hasCurrentQuote && Number.isFinite(time)) {
                previousQuote = { ask, bid, time };
            }
        }

        const roundedTotal = Math.max(0, Math.round(totalVolume));
        const roundedBuy = Math.max(0, Math.min(roundedTotal, Math.round(buyVolume)));
        return {
            buyVolume: roundedBuy,
            sellVolume: roundedTotal - roundedBuy
        };
    }

    function processMarketHistory(history, options = {}) {
        const includeTimeline = options.includeTimeline === true;
        const now = Date.now();
        const windows = {};
        const timeline = includeTimeline ? {} : null;
        for (const days of MOONCAKE_MARKET_HISTORY_WINDOWS) {
            const minTime = now - days * 24 * 60 * 60 * 1000;
            const rows = (history || []).filter(item => Number(item?.time) * 1000 >= minTime);
            const volume = rows.reduce((sum, item) => sum + Math.max(0, Number(item.v) || 0), 0);
            const turnover = rows.reduce((sum, item) => {
                const v = Math.max(0, Number(item.v) || 0);
                const p = Math.max(0, Number(item.p) || 0);
                return sum + v * p;
            }, 250);
            let buyVolume = 0;
            let sellVolume = 0;
            const priceStats = mooncakeGetMarketHistoryPriceStats(rows, { includeTimeline });
            const minPrice = priceStats.minPrice > 0
                ? mooncakeMarketHistoryPriceTier(priceStats.minPrice, 'down')
                : 0;
            const maxPrice = priceStats.maxPrice > 0
                ? mooncakeMarketHistoryPriceTier(priceStats.maxPrice, 'up')
                : 0;
            ({ buyVolume, sellVolume } = mooncakeEstimateMarketHistorySideVolumes(rows));
            windows[days] = {
                volume,
                turnover,
                avgPrice: volume > 0 ? turnover / volume : 0,
                medianPrice: priceStats.medianPrice,
                p10Price: priceStats.p10Price,
                p90Price: priceStats.p90Price,
                activeTradePeriods: priceStats.activeTradePeriods,
                latestTradeAt: priceStats.latestTradeAt,
                buyVolume,
                sellVolume,
                minPrice,
                maxPrice
            };
            if (timeline) timeline[days] = mooncakeBuildMarketHistoryTimelinePoints(priceStats.timeline, days, Math.floor(now / 1000));
        }
        return includeTimeline ? { windows, timeline } : windows;
    }

    function mooncakeFormatCompactNumber(value) {
        const num = Number(value);
        if (!Number.isFinite(num) || num <= 0) return '0';
        const abs = Math.abs(num);
        const trim = (v) => {
            const s = v.toFixed(v >= 100 ? 0 : v >= 10 ? 1 : 2);
            return s.replace(/\.0+$/, '').replace(/(\.\d*[1-9])0+$/, '$1');
        };
        if (abs >= 1e12) return `${trim(num / 1e12)}T`;
        if (abs >= 1e9) return `${trim(num / 1e9)}B`;
        if (abs >= 1e6) return `${trim(num / 1e6)}M`;
        if (abs >= 1e3) return `${trim(num / 1e3)}K`;
        return `${Math.round(num)}`;
    }

    function mooncakeGetCurrentMarketHistoryTarget() {
        const currentItem = mooncakeFindCurrentMarketItemNode();
        if (!mooncakeShouldShowMarketJumpHelpers(currentItem)) return null;
        const itemHrid = mooncakeParseItemHridFromPanel(currentItem);
        if (!itemHrid) return null;
        return {
            currentItem,
            itemHrid,
            level: mooncakeGetCurrentMarketEnhanceLevel(0)
        };
    }

    function mooncakeRemoveMarketHistoryCards(options = {}) {
        if (options.includeFloating) mooncakeMarketHistoryFloatDrag = null;
        const selector = [
            `#${MOONCAKE_MARKET_HISTORY_CARD_ID}`,
            `#${MOONCAKE_MARKET_HISTORY_MOBILE_ID}`,
            options.includeFloating ? MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR : ''
        ].filter(Boolean).join(', ');
        document.querySelectorAll(selector).forEach(el => el.remove());
        if (!document.getElementById(MOONCAKE_MARKET_HISTORY_CARD_ID)) {
            mooncakeRestoreMarketHistoryStacking();
        }
    }

    function mooncakeFormatHistoryPrice(value) {
        return Number(value) > 0 ? mooncakeFormatCompactNumber(value) : '-';
    }

    function mooncakeFormatMarketHistoryPrice(value) {
        return Number(value) > 0 ? mooncakeFormatMarketPrice(value) : '-';
    }

    function mooncakeFormatSignedCompactNumber(value) {
        const num = Number(value);
        if (!Number.isFinite(num)) return '-';
        if (num === 0) return '0';
        const prefix = num < 0 ? '-' : '';
        return `${prefix}${mooncakeFormatMarketPrice(Math.abs(num))}`;
    }

    function mooncakeFormatMarketHistoryTradeAge(tradeAt) {
        const timestamp = Number(tradeAt);
        if (!Number.isFinite(timestamp) || timestamp <= 0) return '-';
        const elapsedSeconds = Math.max(0, Math.floor(Date.now() / 1000 - timestamp));
        if (elapsedSeconds < 60) return isZH ? '刚刚' : 'just now';
        if (elapsedSeconds < 60 * 60) {
            const minutes = Math.floor(elapsedSeconds / 60);
            return isZH ? `${minutes}分钟前` : `${minutes}m ago`;
        }
        if (elapsedSeconds < 24 * 60 * 60) {
            const hours = Math.floor(elapsedSeconds / (60 * 60));
            return isZH ? `${hours}小时前` : `${hours}h ago`;
        }
        const days = Math.floor(elapsedSeconds / (24 * 60 * 60));
        return isZH ? `${days}天前` : `${days}d ago`;
    }

    function mooncakeFormatMarketHistoryDetailPrice(value) {
        return mooncakeFormatMarketHistoryPrice(value);
    }

    function mooncakeFormatMarketHistoryTimelineTime(timestamp) {
        const seconds = Number(timestamp);
        if (!Number.isFinite(seconds) || seconds <= 0) return '-';
        const date = new Date(seconds * 1000);
        if (!Number.isFinite(date.getTime())) return '-';
        const pad = value => String(value).padStart(2, '0');
        return `${pad(date.getMonth() + 1)}/${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
    }

    function mooncakeBuildMarketHistoryTimelinePoints(rawPoints, days, nowSeconds = Math.floor(Date.now() / 1000)) {
        const windowDays = Math.max(1, Math.floor(Number(days) || 1));
        const binSeconds = windowDays <= 1 ? 15 * 60 : windowDays <= 3 ? 60 * 60 : 2 * 60 * 60;
        const windowEnd = Math.floor(Number(nowSeconds) || Date.now() / 1000);
        const windowStart = windowEnd - windowDays * 24 * 60 * 60;
        const points = (Array.isArray(rawPoints) ? rawPoints : [])
            .map(point => ({
                time: Math.floor(Number(point?.time)),
                price: Number(point?.price),
                volume: Number(point?.volume)
            }))
            .filter(point => Number.isFinite(point.time) && point.time > 0
                && Number.isFinite(point.price) && point.price > 0
                && Number.isFinite(point.volume) && point.volume > 0
                && point.time >= windowStart && point.time <= windowEnd)
            .sort((left, right) => left.time - right.time || left.price - right.price);
        const bins = new Map();
        for (const point of points) {
            const bucketStart = Math.floor(point.time / binSeconds) * binSeconds;
            const bin = bins.get(bucketStart) || {
                startTime: Math.max(windowStart, bucketStart),
                endTime: Math.min(windowEnd, bucketStart + binSeconds),
                volume: 0,
                turnover: 0,
                minPrice: point.price,
                maxPrice: point.price,
                periods: 0
            };
            bin.volume += point.volume;
            bin.turnover += point.price * point.volume;
            bin.minPrice = Math.min(bin.minPrice, point.price);
            bin.maxPrice = Math.max(bin.maxPrice, point.price);
            bin.periods += 1;
            bins.set(bucketStart, bin);
        }
        return [...bins.values()].map(bin => ({
            time: (bin.startTime + bin.endTime) / 2,
            price: bin.volume > 0 ? bin.turnover / bin.volume : 0,
            volume: bin.volume,
            startTime: bin.startTime,
            endTime: bin.endTime,
            minPrice: bin.minPrice,
            maxPrice: bin.maxPrice,
            periods: bin.periods
        }));
    }

    function mooncakeBuildMarketHistoryTimelinePointDetail(point) {
        const start = mooncakeFormatMarketHistoryTimelineTime(point?.startTime || point?.time);
        const end = mooncakeFormatMarketHistoryTimelineTime(point?.endTime || point?.time);
        const period = start === end ? start : `${start} - ${end}`;
        const price = mooncakeFormatMarketHistoryDetailPrice(point?.price);
        const volume = mooncakeFormatCompactNumber(point?.volume);
        const hasPriceRange = Number(point?.maxPrice) > Number(point?.minPrice);
        const priceRange = hasPriceRange
            ? `${mooncakeFormatMarketHistoryDetailPrice(point.minPrice)}-${mooncakeFormatMarketHistoryDetailPrice(point.maxPrice)}`
            : '';
        const periods = Math.max(1, Math.floor(Number(point?.periods) || 1));
        if (isZH) {
            return `时段：${period} · 均价：${price} · 数量：${volume}`
                + (priceRange ? ` · 区间：${priceRange}` : '')
                + (periods > 1 ? ` · 合并 ${periods} 个时段` : '');
        }
        return `Period: ${period} | Avg: ${price} | Volume: ${volume}`
            + (priceRange ? ` | Range: ${priceRange}` : '')
            + (periods > 1 ? ` | ${periods} buckets` : '');
    }

    function mooncakeUpdateMarketHistoryTimelineDetail(point, tip = tooltipEl) {
        const detail = point?.getAttribute?.('data-mooncake-history-timeline-hover');
        const output = tip?.querySelector?.('[data-mooncake-history-timeline-detail]');
        if (!detail || !output || output.textContent === detail) return;
        output.textContent = detail;
    }

    function mooncakeBuildMarketHistoryTimelineTooltip(days, row) {
        const windowDays = Math.max(1, Math.floor(Number(days) || 1));
        const binSeconds = windowDays <= 1 ? 15 * 60 : windowDays <= 3 ? 60 * 60 : 2 * 60 * 60;
        const points = (Array.isArray(row?.timeline) ? row.timeline : [])
            .filter(point => Number(point?.time) > 0 && Number(point?.price) > 0 && Number(point?.volume) > 0)
            .sort((left, right) => Number(left.time) - Number(right.time));
        const latestTradeAge = mooncakeFormatMarketHistoryTradeAge(row?.latestTradeAt);
        const header = isZH ? `近 ${windowDays}d 交易时间轴` : `${windowDays}d trade timeline`;
        if (!points.length) {
            return `<div class="tt-header">${header}</div>`
                + `<div class="mooncake-history-tooltip-note">${isZH ? '暂无可绘制的时段成交数据' : 'No timestamped trade records available'}</div>`;
        }

        const width = 360;
        const left = 8;
        const right = 312;
        const axisLabelX = 352;
        const priceTop = 20;
        const priceBottom = 88;
        const volumeTop = 116;
        const volumeBottom = 149;
        const plotWidth = right - left;
        const lastTime = Math.floor(Date.now() / 1000);
        const firstTime = lastTime - windowDays * 24 * 60 * 60;
        const rawMinPrice = Math.min(...points.map(point => Math.min(point.minPrice, point.price)));
        const rawMaxPrice = Math.max(...points.map(point => Math.max(point.maxPrice, point.price)));
        const sortedPointPrices = points.map(point => point.price).sort((left, right) => left - right);
        const priceAt = percentile => sortedPointPrices[Math.max(0, Math.min(
            sortedPointPrices.length - 1,
            Math.round((sortedPointPrices.length - 1) * percentile)
        ))] || 0;
        const q25Price = priceAt(0.25);
        const q50Price = priceAt(0.5);
        const q75Price = priceAt(0.75);
        const mainPriceSpread = Math.max(q75Price - q25Price, q50Price * 0.03, 1);
        const highPriceFence = q75Price + mainPriceSpread * 2.5;
        const compressHighOutliers = points.length >= 5 && rawMaxPrice > highPriceFence;
        const displayMaxPrice = compressHighOutliers ? highPriceFence : rawMaxPrice;
        const highOutlierPoints = compressHighOutliers
            ? points.filter(point => Math.max(Number(point.price) || 0, Number(point.maxPrice) || 0) > displayMaxPrice)
            : [];
        const pricePadding = Math.max((displayMaxPrice - rawMinPrice) * 0.08, displayMaxPrice * 0.015, 1);
        const minPrice = Math.max(0, rawMinPrice - pricePadding);
        const maxPrice = displayMaxPrice + pricePadding;
        const priceSpan = Math.max(1, maxPrice - minPrice);
        const maxVolume = Math.max(1, ...points.map(point => point.volume));
        const timeSpan = Math.max(1, lastTime - firstTime);
        const xFor = time => firstTime === lastTime
            ? left + plotWidth / 2
            : left + (Math.max(firstTime, Math.min(lastTime, time)) - firstTime) / timeSpan * plotWidth;
        const priceYFor = price => priceTop + (maxPrice - price) / priceSpan * (priceBottom - priceTop);
        const number = value => Number(value).toFixed(1);
        const rowMedianPrice = Number(row?.medianPrice);
        const medianPrice = Number.isFinite(rowMedianPrice) && rowMedianPrice > 0 ? rowMedianPrice : 0;
        const tickSpacing = Math.max((displayMaxPrice - rawMinPrice) * 0.015, displayMaxPrice * 0.005, 1);
        const priceTicks = [
            { label: compressHighOutliers ? (isZH ? '主上' : 'Ceiling') : (isZH ? '高' : 'High'), value: displayMaxPrice, color: '#FFD700', dashed: false },
            ...(medianPrice > rawMinPrice + tickSpacing && medianPrice < displayMaxPrice - tickSpacing
                ? [{ label: isZH ? '中' : 'Median', value: medianPrice, color: '#FFA500', dashed: true }]
                : []),
            { label: isZH ? '低' : 'Low', value: rawMinPrice, color: '#B9E6A3', dashed: false }
        ];
        const priceGuides = priceTicks.map(tick => {
            const y = priceYFor(tick.value);
            const labelY = Math.max(priceTop + 8, Math.min(priceBottom - 1, y + 3));
            const label = mooncakeEscapeHtml(`${tick.label} ${mooncakeFormatMarketHistoryDetailPrice(tick.value)}`);
            return `<line x1="${left}" y1="${number(y)}" x2="${right}" y2="${number(y)}" stroke="${tick.dashed ? 'rgba(164,190,238,.34)' : 'rgba(164,190,238,.2)'}" stroke-width="1"${tick.dashed ? ' stroke-dasharray="3 3"' : ''}/>`
                + `<text x="${axisLabelX}" y="${number(labelY)}" text-anchor="end" fill="${tick.color}" font-size="9" font-weight="${tick.dashed ? '700' : '600'}">${label}</text>`;
        }).join('');
        const avgPriceLabel = mooncakeEscapeHtml(mooncakeFormatMarketHistoryPrice(row?.avgPrice));
        const medianPriceLabel = mooncakeEscapeHtml(mooncakeFormatMarketHistoryPrice(row?.medianPrice));
        const totalVolumeLabel = mooncakeEscapeHtml(mooncakeFormatCompactNumber(row?.volume));
        const maxVolumeLabel = mooncakeEscapeHtml(mooncakeFormatCompactNumber(maxVolume));
        const outlierSummary = compressHighOutliers
            ? `<span style="color:#ff9a70;">${isZH ? '异常高价' : 'High outlier'} <b>↑${mooncakeEscapeHtml(mooncakeFormatMarketHistoryDetailPrice(rawMaxPrice))}</b></span>`
            : '';
        const summary = `<div style="display:flex;flex-wrap:wrap;align-items:center;gap:4px 10px;margin:0 0 5px;color:rgba(230,238,255,.72);font-size:11px;font-variant-numeric:tabular-nums;">
            <span>${isZH ? '均价' : 'Avg'} <b style="color:#FFD700;">${avgPriceLabel}</b></span>
            <span>${isZH ? '中位' : 'Median'} <b style="color:#FFA500;">${medianPriceLabel}</b></span>
            <span>${isZH ? '成交量' : 'Volume'} <b style="color:#87CEEB;">${totalVolumeLabel}</b></span>
            ${outlierSummary}
        </div>`;
        const barWidth = Math.max(3, Math.min(10, plotWidth / Math.max(1, points.length) * 0.68));
        const detailFor = point => mooncakeEscapeHtml(mooncakeBuildMarketHistoryTimelinePointDetail(point));
        const attrsFor = point => `data-mooncake-history-timeline-hover="${detailFor(point)}"`;
        const lineSegments = [];
        let segment = [];
        for (const point of points) {
            const previous = segment.at(-1);
            if (compressHighOutliers && Number(point.price) > displayMaxPrice) {
                if (segment.length) lineSegments.push(segment);
                segment = [];
                continue;
            }
            if (previous && Number(point.startTime) - Number(previous.startTime) > binSeconds * 1.5) {
                lineSegments.push(segment);
                segment = [];
            }
            segment.push(point);
        }
        if (segment.length) lineSegments.push(segment);
        const linePaths = lineSegments.map(part => {
            const path = part.map((point, index) => `${index ? 'L' : 'M'}${number(xFor(point.time))} ${number(priceYFor(Math.min(point.price, displayMaxPrice)))}`).join(' ');
            return `<path d="${path}" fill="none" stroke="#FFD700" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/>`;
        }).join('');
        const areaPaths = lineSegments.filter(part => part.length > 1).map(part => {
            const first = part[0];
            const last = part.at(-1);
            const path = `M${number(xFor(first.time))} ${priceBottom} L${part.map(point => `${number(xFor(point.time))} ${number(priceYFor(Math.min(point.price, displayMaxPrice)))}`).join(' L')} L${number(xFor(last.time))} ${priceBottom} Z`;
            return `<path d="${path}" fill="rgba(255,215,0,.13)"/>`;
        }).join('');
        const rangeLines = points.map(point => {
            if (!(point.maxPrice > point.minPrice)) return '';
            const x = number(xFor(point.time));
            return `<line class="mooncake-history-timeline-target" ${attrsFor(point)} x1="${x}" y1="${number(priceYFor(Math.min(point.maxPrice, displayMaxPrice)))}" x2="${x}" y2="${number(priceYFor(Math.min(point.minPrice, displayMaxPrice)))}" stroke="rgba(255,215,0,.42)" stroke-width="1.5"/>`;
        }).join('');
        const bars = points.map(point => {
            const height = Math.max(1, point.volume / maxVolume * (volumeBottom - volumeTop));
            const x = xFor(point.time) - barWidth / 2;
            return `<rect class="mooncake-history-timeline-target" ${attrsFor(point)} x="${number(x)}" y="${number(volumeBottom - height)}" width="${number(barWidth)}" height="${number(height)}" rx="1" fill="rgba(135,206,235,.66)"/>`;
        }).join('');
        const pointMarkers = points
            .filter(point => !compressHighOutliers || Number(point.price) <= displayMaxPrice)
            .map(point => `<circle class="mooncake-history-timeline-target" ${attrsFor(point)} cx="${number(xFor(point.time))}" cy="${number(priceYFor(Math.min(point.price, displayMaxPrice)))}" r="2.8" fill="#FFD700" stroke="#171d2a" stroke-width="1.1"/>`)
            .join('');
        const outlierMarkers = highOutlierPoints.map(point => {
            const x = number(xFor(point.time));
            const top = priceTop + 3;
            return `<path class="mooncake-history-timeline-target" ${attrsFor(point)} d="M${x} ${top} l-4 7 h8 Z" fill="#ff8e5a" stroke="#171d2a" stroke-width="1"/>`;
        }).join('');
        const firstLabel = mooncakeEscapeHtml(mooncakeFormatMarketHistoryTimelineTime(firstTime));
        const lastLabel = mooncakeEscapeHtml(mooncakeFormatMarketHistoryTimelineTime(lastTime));
        const defaultDetail = mooncakeEscapeHtml(mooncakeBuildMarketHistoryTimelinePointDetail(points.at(-1)));
        return `<div class="tt-header">${header}</div>`
            + summary
            + `<div class="mooncake-history-timeline"><svg class="mooncake-history-timeline-chart" viewBox="0 0 ${width} 177" role="img" aria-label="${isZH ? '成交均价与成交量时间轴' : 'Average price and volume timeline'}">
                <text x="${left}" y="12" fill="#d6e7ff" font-size="10" font-weight="700">${isZH ? '成交均价' : 'Average price'}</text>
                ${priceGuides}
                ${areaPaths}
                ${rangeLines}
                ${linePaths}
                ${pointMarkers}
                ${outlierMarkers}
                <line x1="${left}" y1="102" x2="${right}" y2="102" stroke="rgba(164,190,238,.2)" stroke-width="1"/>
                <text x="${left}" y="${volumeTop - 4}" fill="#d6e7ff" font-size="10" font-weight="700">${isZH ? '成交量' : 'Volume'}</text>
                <text x="${axisLabelX}" y="${volumeTop + 3}" text-anchor="end" fill="#87CEEB" font-size="9" font-weight="600">${isZH ? '峰' : 'Peak'} ${maxVolumeLabel}</text>
                ${bars}
                <line x1="${left}" y1="${number((volumeTop + volumeBottom) / 2)}" x2="${right}" y2="${number((volumeTop + volumeBottom) / 2)}" stroke="rgba(164,190,238,.12)" stroke-width="1" stroke-dasharray="2 3"/>
                <line x1="${left}" y1="${volumeBottom}" x2="${right}" y2="${volumeBottom}" stroke="rgba(164,190,238,.25)" stroke-width="1"/>
                <text x="${axisLabelX}" y="${volumeBottom + 3}" text-anchor="end" fill="rgba(230,238,255,.5)" font-size="9">0</text>
                <text x="${left}" y="172" fill="rgba(230,238,255,.55)" font-size="8.5">${firstLabel}</text>
                <text x="${right}" y="172" text-anchor="end" fill="rgba(230,238,255,.55)" font-size="8.5">${lastLabel}</text>
            </svg></div>`
            + `<div class="mooncake-history-timeline-detail" data-mooncake-history-timeline-detail>${defaultDetail}</div>`
            + `<div style="margin-top:5px;padding-top:5px;border-top:1px solid #444;color:#aaa;font-size:11px;">${isZH ? '最近成交：' : 'Latest trade: '}${latestTradeAge}</div>`;
    }

    function mooncakeBuildMarketHistoryMedianTitle(medianPrice, medianResult, includeHourly = true) {
        const medianText = mooncakeFormatMarketHistoryPrice(medianPrice);
        if (!includeHourly) {
            return isZH ? `成交量加权中位价：${medianText}` : `Volume-weighted median: ${medianText}`;
        }
        const hourlyWage = Number(medianResult?.hourlyWage);
        const hourlyText = Number.isFinite(hourlyWage) ? `${mooncakeFormatSignedHourlyWage(hourlyWage)}/h` : '-';
        return isZH
            ? `成交量加权中位价：${medianText}\n中位价对应工时：${hourlyText}`
            : `Volume-weighted median: ${medianText}\nHourly wage at median: ${hourlyText}`;
    }

    function mooncakeCalcHourlyWageResultByPrice(itemHrid, level, price, marketData = null) {
        const enhLevel = Number(level) || 0;
        const sellPrice = Number(price) || 0;
        if (enhLevel <= 0 || sellPrice <= 0 || !mooncakeIsEnhanceableItem(itemHrid)) return null;
        const sourceMarketData = marketData || getMarketData();
        if (!sourceMarketData) return null;
        return calcHourlyWageAndMetrics(itemHrid, enhLevel, sourceMarketData, sellPrice);
    }

    function mooncakeFormatHourlyWageCompact(value, color = null) {
        if (value === null || value === undefined) return '-';
        const resolvedColor = color || (Number(value) >= 0 ? '#B9E6A3' : '#FF9A9A');
        return `<span style="color:${resolvedColor};font-weight:800;font-variant-numeric:tabular-nums;white-space:nowrap;">${mooncakeFormatSignedHourlyWage(value)}</span>`;
    }

    function mooncakeBuildMarketHistoryHourlyRange(itemHrid, level, minPrice, maxPrice, medianPrice = 0, marketData = undefined, resultByPrice = null) {
        const emptyRange = { sellFirst: '-', buyFirst: '-', medianResult: null };
        if (Number(level) <= 0) return emptyRange;
        const sourceMarketData = marketData === undefined ? getMarketData() : marketData;
        if (!sourceMarketData) return emptyRange;
        const getHourlyResult = price => {
            const numericPrice = Number(price);
            if (!(numericPrice > 0)) return null;
            const key = String(numericPrice);
            if (resultByPrice?.has(key)) return resultByPrice.get(key);
            const result = mooncakeCalcHourlyWageResultByPrice(itemHrid, level, numericPrice, sourceMarketData);
            resultByPrice?.set(key, result);
            return result;
        };
        const minResult = getHourlyResult(minPrice);
        const maxResult = getHourlyResult(maxPrice);
        const medianResult = getHourlyResult(medianPrice);
        if (!minResult && !maxResult && !medianResult) return emptyRange;
        const formatHourly = (result) => mooncakeFormatHourlyWageCompact(result?.hourlyWage, result?.evaluation?.combinedColor);
        const divider = '<span style="color:rgba(230,238,255,.45);padding:0 2px;">/</span>';
        return {
            sellFirst: `${formatHourly(maxResult)}${divider}${formatHourly(minResult)}`,
            buyFirst: `${formatHourly(minResult)}${divider}${formatHourly(maxResult)}`,
            medianResult
        };
    }

    function mooncakeIsMarketHistoryEquipmentTarget(itemHrid) {
        return !!(itemHrid && mooncakeIsEnhanceableItem(itemHrid));
    }

    function mooncakeBuildMarketHistoryOrderValue(sellFirstValue, buyFirstValue, sellFirst) {
        return `<span data-mooncake-history-order-value="sell-first"${sellFirst ? '' : ' hidden'}>${sellFirstValue}</span>`
            + `<span data-mooncake-history-order-value="buy-first"${sellFirst ? ' hidden' : ''}>${buyFirstValue}</span>`;
    }

    function mooncakeBuildMarketHistoryRows(itemHrid, level, windows, sellFirst, options = {}) {
        const dayColors = { 1: '#FF6B6B', 3: '#4ECDC4', 7: '#95E1D3' };
        const showHourly = mooncakeIsMarketHistoryEquipmentTarget(itemHrid);
        const compact = options.compact === true;
        const visibleColumns = mooncakeGetMarketHistoryMobileColumns();
        const cellPad = compact ? '1px 2px' : '2px 2px';
        const dayCellPad = compact ? '1px 2px 1px 0' : '2px 2px 2px 0';
        const hourlyCellPad = compact ? '1px 0 1px 2px' : '2px 0 2px 2px';
        const marketData = showHourly ? getMarketData() : null;
        const hourlyResultByPrice = new Map();
        return MOONCAKE_MARKET_HISTORY_WINDOWS.map(days => {
            const row = windows?.[days] || {};
            const hourlyRange = showHourly
                ? mooncakeBuildMarketHistoryHourlyRange(itemHrid, level, row.minPrice, row.maxPrice, row.medianPrice, marketData, hourlyResultByPrice)
                : null;
            const medianTitle = mooncakeBuildMarketHistoryMedianTitle(row.medianPrice, hourlyRange?.medianResult, showHourly);
            return `
                <tr>
                    <td style="padding:${dayCellPad};color:${dayColors[days] || '#95E1D3'};font-weight:800;">${days}d</td>
                    ${visibleColumns.average ? `<td style="padding:${cellPad};text-align:center;color:#FFD700;font-weight:700;font-variant-numeric:tabular-nums;">${mooncakeFormatMarketHistoryPrice(row.avgPrice)}</td>` : ''}
                    ${visibleColumns.median ? `<td title="${medianTitle}" style="padding:${cellPad};text-align:center;color:#FFA500;font-weight:700;font-variant-numeric:tabular-nums;">${mooncakeFormatMarketHistoryPrice(row.medianPrice)}</td>` : ''}
                    ${visibleColumns.volume ? `<td style="padding:${cellPad};text-align:center;color:#87CEEB;font-weight:700;font-variant-numeric:tabular-nums;">${mooncakeFormatHistoryPrice(row.volume)}</td>` : ''}
                    ${visibleColumns.buySell ? `<td style="padding:${cellPad};text-align:center;color:#90EE90;font-weight:700;font-variant-numeric:tabular-nums;">${mooncakeFormatHistoryPrice(row.buyVolume)}/${mooncakeFormatHistoryPrice(row.sellVolume)}</td>` : ''}
                    ${visibleColumns.range ? `<td class="mooncake-market-history-price-cell" data-mooncake-history-price-window="${days}" style="padding:${cellPad};text-align:center;color:#FFFF00;font-weight:700;font-variant-numeric:tabular-nums;">${mooncakeBuildMarketHistoryOrderValue(`${mooncakeFormatMarketHistoryPrice(row.maxPrice)}/${mooncakeFormatMarketHistoryPrice(row.minPrice)}`, `${mooncakeFormatMarketHistoryPrice(row.minPrice)}/${mooncakeFormatMarketHistoryPrice(row.maxPrice)}`, sellFirst)}</td>` : ''}
                    ${showHourly && visibleColumns.hourly ? `<td title="${medianTitle}" style="padding:${hourlyCellPad};text-align:center;font-variant-numeric:tabular-nums;">${mooncakeBuildMarketHistoryOrderValue(hourlyRange.sellFirst, hourlyRange.buyFirst, sellFirst)}</td>` : ''}
                </tr>
            `;
        }).join('');
    }

    function mooncakeBindMarketHistoryPriceTooltips(card, windows) {
        if (!card?.querySelectorAll) return;
        card.querySelectorAll('.mooncake-market-history-price-cell').forEach(cell => {
            const days = Math.max(1, Math.floor(Number(cell.getAttribute('data-mooncake-history-price-window')) || 1));
            const row = windows?.[days] || {};
            bindTooltip(cell, () => mooncakeBuildMarketHistoryTimelineTooltip(days, row), { interactive: true });
        });
    }

    function mooncakeBuildMarketHistoryCardHtml(itemHrid, level, windows, stateText = '', options = {}) {
        const showHourly = mooncakeIsMarketHistoryEquipmentTarget(itemHrid);
        const sellFirst = mooncakeIsMarketHistoryCardSellFirst();
        const orderPresentation = mooncakeGetMarketHistoryCardOrderPresentation(sellFirst);
        const compact = options.compact === true;
        const visibleColumns = mooncakeGetMarketHistoryMobileColumns();
        const showOrderToggle = visibleColumns.range || (showHourly && visibleColumns.hourly);
        const headPad = compact ? '0 2px 2px' : '0 2px 3px';
        const tableFontSize = compact ? '10px' : '11px';
        const tableLineHeight = compact ? '1.2' : '1.35';
        const tableWidth = compact || showHourly ? '100%' : 'auto';
        const sideVolumeTitle = isZH
            ? '买/卖：估算的成交数量，非人数。左为主动买入（成交价更接近卖一 a），右为主动卖出（更接近买一 b）。接口没有逐笔成交方向，仅供参考。'
            : 'Buy/Sell: estimated item quantity, not player count. Left is aggressive buying (price closer to ask a); right is aggressive selling (closer to bid b). The API has no per-trade side, so this is indicative only.';
        const body = stateText
            ? `<div style="display:flex;align-items:center;gap:8px;padding:3px 2px;color:rgba(230,238,255,.68);font-size:${compact ? '12px' : '13px'};white-space:nowrap;"><span>${stateText}</span>${stateText === '加载失败' ? '<button type="button" data-mooncake-history-refresh="1" style="cursor:pointer;border:1px solid rgba(144,166,235,.35);border-radius:5px;background:rgba(144,166,235,.16);color:#eef6ff;padding:2px 6px;font-size:11px;">重试</button>' : ''}</div>`
            : `<div style="overflow-x:${compact ? 'hidden' : 'auto'};overflow-y:hidden;max-width:100%;">
                    <table style="width:${tableWidth};border-collapse:collapse;font-size:${tableFontSize};line-height:${tableLineHeight};white-space:nowrap;table-layout:auto;">
                        <thead>
                            <tr style="color:#AAAAAA;font-size:${tableFontSize};">
                                <th style="padding:0 2px 3px 0;font-weight:700;">${showOrderToggle ? `<button type="button" data-mooncake-history-order-toggle="1" title="${orderPresentation.nextTitle}" aria-label="${orderPresentation.toggleLabel}" aria-pressed="${!sellFirst}" style="width:18px;height:16px;padding:0;border:0;background:transparent;color:rgba(220,232,255,.42);font-size:${tableFontSize};font-weight:400;line-height:1;cursor:pointer;opacity:.72;">⇄</button>` : ''}</th>
                                ${visibleColumns.average ? `<th style="padding:${headPad};text-align:center;font-weight:700;">均价</th>` : ''}
                                ${visibleColumns.median ? `<th style="padding:${headPad};text-align:center;font-weight:700;">中位</th>` : ''}
                                ${visibleColumns.volume ? `<th style="padding:${headPad};text-align:center;font-weight:700;">量</th>` : ''}
                                ${visibleColumns.buySell ? `<th title="${sideVolumeTitle}" style="padding:${headPad};text-align:center;font-weight:700;">${isZH ? '买/卖' : 'Buy/Sell'}</th>` : ''}
                                ${visibleColumns.range ? `<th data-mooncake-history-order-label="1" data-sell-first-label="max/min" data-buy-first-label="min/max" style="padding:${headPad};text-align:center;font-weight:700;">${orderPresentation.priceHeader}</th>` : ''}
                                ${showHourly && visibleColumns.hourly ? `<th data-mooncake-history-order-label="1" data-sell-first-label="${isZH ? '工时' : 'Hourly'}" data-buy-first-label="${isZH ? '工时' : 'Hourly'}" style="padding:0 0 2px 2px;text-align:center;font-weight:700;">${orderPresentation.hourlyHeader}</th>` : ''}
                            </tr>
                        </thead>
                        <tbody>${mooncakeBuildMarketHistoryRows(itemHrid, level, windows, sellFirst, { compact })}</tbody>
                    </table>
               </div>`;
        return body;
    }

    function mooncakeStyleMarketHistoryCard(card, isMobile) {
        Object.assign(card.style, {
            boxSizing: 'border-box',
            border: '1px solid rgba(144,166,235,.22)',
            background: 'rgba(18,22,34,.72)',
            borderRadius: '8px',
            color: '#eef6ff',
            fontSize: '12px',
            lineHeight: '1.25',
            boxShadow: isMobile ? '0 8px 22px rgba(0,0,0,.42)' : 'none',
            pointerEvents: 'auto'
        });
    }

    function mooncakeGetMobileMarketHistoryCardWidth(itemHrid) {
        const columns = mooncakeGetMarketHistoryMobileColumns();
        let width = 40; // day label and the order toggle
        if (columns.average) width += 54;
        if (columns.median) width += 54;
        if (columns.volume) width += 48;
        if (columns.buySell) width += 62;
        if (columns.range) width += 78;
        if (columns.hourly && mooncakeIsMarketHistoryEquipmentTarget(itemHrid)) width += 82;
        return Math.max(168, Math.min(420, width + 18));
    }

    function mooncakePositionMobileHistoryCard(card, currentItem) {
        const margin = 8;
        const itemRect = currentItem?.getBoundingClientRect?.();
        const iconNode = currentItem?.querySelector?.('[class*="Item_iconContainer"], svg[role="img"], svg');
        const iconRect = iconNode?.getBoundingClientRect?.();
        const anchorRect = iconRect && iconRect.width > 0 && iconRect.height > 0 ? iconRect : itemRect;
        const expanded = card.dataset.expanded === '1';
        const width = expanded
            ? Math.min(mooncakeGetMobileMarketHistoryCardWidth(card.dataset.itemHrid), window.innerWidth - margin * 2)
            : 34;
        const height = expanded ? Math.max(122, Math.min(170, card.offsetHeight || 138)) : 28;
        const anchorLeft = anchorRect ? anchorRect.right + 6 : window.innerWidth - width - margin;
        const collapsedLeft = Math.min(Math.max(margin, anchorLeft), window.innerWidth - width - margin);
        const expandedLeft = Math.min(Math.max(margin, anchorLeft), window.innerWidth - width - margin);
        const collapsedTop = anchorRect
            ? anchorRect.top + (anchorRect.height - height) / 2
            : window.innerHeight - height - 72;
        let expandedTop = anchorRect ? anchorRect.top - 8 : window.innerHeight - height - 72;
        if (expandedTop + height > window.innerHeight - margin) {
            expandedTop = Math.max(margin, window.innerHeight - height - margin);
        }
        const left = expanded ? expandedLeft : collapsedLeft;
        const top = Math.max(margin, Math.min(expanded ? expandedTop : collapsedTop, window.innerHeight - height - margin));
        Object.assign(card.style, {
            position: 'fixed',
            left: `${left}px`,
            top: `${top}px`,
            width: `${width}px`,
            minHeight: `${height}px`,
            zIndex: MOONCAKE_MARKET_HISTORY_CARD_Z_INDEX,
            padding: expanded ? '7px 42px 7px 8px' : '0'
        });
    }

    function mooncakeCreateMarketHistoryCardControl(text, title, attribute) {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = text;
        button.title = title;
        button.setAttribute('aria-label', title);
        button.setAttribute(attribute, '1');
        Object.assign(button.style, {
            width: '18px',
            minWidth: '18px',
            height: '18px',
            minHeight: '18px',
            padding: '0',
            border: '0',
            borderRadius: '3px',
            background: 'transparent',
            color: 'rgba(238,246,255,.64)',
            cursor: 'pointer',
            fontSize: '13px',
            fontWeight: '700',
            lineHeight: '1'
        });
        return button;
    }

    function mooncakeGetMarketHistoryFloatingCards() {
        return Array.from(document.querySelectorAll(MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR));
    }

    function mooncakeGetMarketHistoryFollowingCard() {
        return document.querySelector(MOONCAKE_MARKET_HISTORY_FOLLOWING_SELECTOR);
    }

    function mooncakeApplyFloatingMarketHistoryLayout(card) {
        if (!card?.matches?.(MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR)) return;
        card.style.overflowX = 'hidden';
        const table = card.querySelector('table');
        if (!table) return;
        const shell = table.parentElement;
        if (shell) {
            shell.style.overflowX = 'hidden';
            shell.style.overflowY = 'hidden';
            shell.style.maxWidth = '100%';
        }
        Object.assign(table.style, {
            width: '100%',
            maxWidth: '100%',
            tableLayout: 'fixed'
        });
        table.querySelectorAll('th, td').forEach(cell => {
            Object.assign(cell.style, {
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap'
            });
        });
        table.querySelectorAll('tr > :first-child').forEach(cell => {
            cell.style.width = '26px';
        });
    }

    function mooncakeBringMarketHistoryFloatingCardToFront(card) {
        if (!card?.isConnected) return;
        // A floating card is attached to body, so it must not use the anchored
        // card's maximum z-index or it would cover game dialogs and menus.
        card.dataset.mooncakeHistoryFloatZIndex = MOONCAKE_MARKET_HISTORY_FLOAT_Z_INDEX;
        card.style.zIndex = MOONCAKE_MARKET_HISTORY_FLOAT_Z_INDEX;
    }

    function mooncakeInstallMarketHistoryMobileControl(card) {
        if (!card) return;
        card.querySelectorAll('[data-mooncake-history-card-controls]').forEach(node => node.remove());

        const controls = document.createElement('span');
        controls.setAttribute('data-mooncake-history-card-controls', '1');
        controls.appendChild(mooncakeCreateMarketHistoryCardControl('×', isZH ? '收起' : 'Collapse', 'data-mooncake-history-toggle'));
        Object.assign(controls.style, {
            position: 'absolute',
            right: '4px',
            top: '3px',
            gap: '2px'
        });
        card.appendChild(controls);
    }

    function mooncakeMoveFloatingMarketHistoryCard(card, requestedLeft, requestedTop, measuredSize = null) {
        if (!card?.isConnected) return;
        const margin = 8;
        const rect = measuredSize || card.getBoundingClientRect();
        const maxLeft = Math.max(margin, window.innerWidth - Number(rect.width || 0) - margin);
        const maxTop = Math.max(margin, window.innerHeight - Number(rect.height || 0) - margin);
        const finalLeft = Math.min(maxLeft, Math.max(margin, Number.isFinite(requestedLeft) ? requestedLeft : maxLeft));
        const finalTop = Math.min(maxTop, Math.max(margin, Number.isFinite(requestedTop) ? requestedTop : margin));
        card.dataset.mooncakeHistoryFloatLeft = String(finalLeft);
        card.dataset.mooncakeHistoryFloatTop = String(finalTop);
        card.style.left = `${finalLeft}px`;
        card.style.top = `${finalTop}px`;
    }

    function mooncakePositionFloatingMarketHistoryCard(card, sourceRect = null, currentItem = null) {
        if (!card) return;
        const margin = 8;
        const viewportWidth = Math.max(1, window.innerWidth - margin * 2);
        const collapsed = card.dataset.mooncakeHistoryCollapsed === '1';
        const sourceWidth = Number(sourceRect?.width);
        const savedWidth = Number(card.dataset.mooncakeHistoryFloatWidth);
        const defaultWidth = mooncakeIsMarketHistoryEquipmentTarget(card.dataset.itemHrid) ? 440 : 380;
        const requestedWidth = collapsed
            ? 34
            : Math.max(defaultWidth, sourceWidth > 0 ? sourceWidth : 0, savedWidth > 0 ? savedWidth : 0);
        const width = collapsed
            ? Math.min(34, viewportWidth)
            : Math.min(Math.max(160, requestedWidth), viewportWidth);
        if (!collapsed) card.dataset.mooncakeHistoryFloatWidth = String(width);
        mooncakeBringMarketHistoryFloatingCardToFront(card);
        Object.assign(card.style, {
            position: 'fixed',
            left: '0px',
            top: '0px',
            width: `${width}px`,
            height: collapsed ? '28px' : '',
            minHeight: collapsed ? '28px' : '',
            maxWidth: `calc(100vw - ${margin * 2}px)`,
            maxHeight: collapsed ? '28px' : `calc(100vh - ${margin * 2}px)`,
            overflowX: 'hidden',
            overflowY: collapsed ? 'hidden' : 'auto',
            zIndex: MOONCAKE_MARKET_HISTORY_FLOAT_Z_INDEX,
            padding: collapsed ? '0' : '6px 8px 8px',
            border: '1px solid rgba(144,166,235,.40)',
            borderRadius: '7px',
            background: 'rgba(17,21,32,.97)',
            boxShadow: '0 10px 28px rgba(0,0,0,.5)',
            cursor: 'grab',
            touchAction: 'none',
            userSelect: 'none'
        });
        const sourceLeft = Number(sourceRect?.left);
        const sourceTop = Number(sourceRect?.top);
        const isDragging = mooncakeMarketHistoryFloatDrag?.card === card;
        const savedPosition = isDragging ? null : mooncakeReadMarketHistoryFloatPosition();
        const shouldMigrateLegacyPosition = !!savedPosition &&
            !isDragging &&
            !sourceRect &&
            !mooncakeHasViewportHistoryPosition(savedPosition);
        const origin = savedPosition ? mooncakeGetMarketHistoryFloatOrigin(currentItem) : null;
        const savedAnchorMargin = Number(savedPosition?.anchorMargin);
        const relativeLeft = origin
            ? origin.left + savedPosition.offsetX + (Number.isFinite(savedAnchorMargin) ? savedAnchorMargin : MOONCAKE_MARKET_HISTORY_LEGACY_ANCHOR_MARGIN) - MOONCAKE_MARKET_HISTORY_ANCHOR_MARGIN
            : NaN;
        const relativeTop = origin ? origin.top + savedPosition.offsetY : NaN;
        const viewportPosition = mooncakeShouldUseViewportHistoryPosition(savedPosition)
            ? mooncakeGetViewportHistoryPosition(card, savedPosition)
            : null;
        const left = Number.isFinite(sourceLeft)
            ? sourceLeft + 10
            : (Number.isFinite(viewportPosition?.left)
                ? viewportPosition.left
                : (Number.isFinite(relativeLeft) ? relativeLeft : parseFloat(card.dataset.mooncakeHistoryFloatLeft || '')));
        const top = Number.isFinite(sourceTop)
            ? sourceTop + 10
            : (Number.isFinite(viewportPosition?.top)
                ? viewportPosition.top
                : (Number.isFinite(relativeTop) ? relativeTop : parseFloat(card.dataset.mooncakeHistoryFloatTop || '')));
        mooncakeMoveFloatingMarketHistoryCard(card, left, top);
        if (shouldMigrateLegacyPosition) {
            mooncakeWriteMarketHistoryFloatPosition(card, currentItem);
        }
        if (mooncakeMarketHistoryFloatDrag?.card === card) {
            const currentRect = card.getBoundingClientRect();
            mooncakeMarketHistoryFloatDrag.width = currentRect.width;
            mooncakeMarketHistoryFloatDrag.height = currentRect.height;
        }
    }

    function mooncakeBuildMarketHistoryCollapsedHtml() {
        const title = isZH ? '点击展开交易卡片' : 'Expand trading card';
        return `<span title="${title}" aria-label="${title}" style="display:flex;width:32px;height:26px;align-items:center;justify-content:center;color:#eef6ff;font-size:13px;font-weight:900;line-height:1;cursor:pointer;">量</span>`;
    }

    function mooncakeRenderFloatingMarketHistoryCard(card, target, windows, stateText = '') {
        if (!card?.isConnected || !card.matches?.(MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR) || !target?.itemHrid) return false;
        card.dataset.itemHrid = target.itemHrid;
        card.dataset.level = String(target.level);
        card._mooncakeMarketHistoryWindows = windows;
        card._mooncakeMarketHistoryStateText = stateText;
        const collapsed = card.dataset.mooncakeHistoryCollapsed === '1';
        if (collapsed) {
            card.innerHTML = mooncakeBuildMarketHistoryCollapsedHtml();
            card.setAttribute('aria-expanded', 'false');
        } else {
            card.innerHTML = mooncakeBuildMarketHistoryCardHtml(target.itemHrid, target.level, windows, stateText, { compact: false });
            card.setAttribute('aria-expanded', 'true');
            mooncakeBindMarketHistoryPriceTooltips(card, windows);
        }
        mooncakeApplyFloatingMarketHistoryLayout(card);
        mooncakeStyleMarketHistoryCard(card, true);
        mooncakePositionFloatingMarketHistoryCard(card, null, target.currentItem);
        return true;
    }

    function mooncakeSetFloatingMarketHistoryCardCollapsed(card, collapsed) {
        if (!card?.matches?.(MOONCAKE_MARKET_HISTORY_FOLLOWING_SELECTOR)) return;
        card.dataset.mooncakeHistoryCollapsed = collapsed ? '1' : '0';
        hideTooltip();
        mooncakeRenderFloatingMarketHistoryCard(card, {
            currentItem: mooncakeFindCurrentMarketItemNode(),
            itemHrid: card.dataset.itemHrid,
            level: Number(card.dataset.level) || 0
        }, card._mooncakeMarketHistoryWindows, card._mooncakeMarketHistoryStateText || '');
    }

    function mooncakeSetAnchoredMarketHistoryCardCollapsed(card, collapsed) {
        if (!card?.matches?.(`#${MOONCAKE_MARKET_HISTORY_CARD_ID}`)) return;
        const target = mooncakeGetCurrentMarketHistoryTarget();
        if (!target || target.itemHrid !== card.dataset.itemHrid || Number(target.level) !== Number(card.dataset.level)) return;
        card.dataset.mooncakeHistoryCollapsed = collapsed ? '1' : '0';
        hideTooltip();
        mooncakeRenderMarketHistoryCard(
            target,
            card._mooncakeMarketHistoryWindows,
            card._mooncakeMarketHistoryStateText || ''
        );
    }

    function mooncakeFloatMarketHistoryCard(card, options = {}) {
        if (!card || card.matches?.(MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR) || !card.dataset.itemHrid) return;
        const currentItem = options.currentItem || card.parentElement;
        const target = {
            currentItem,
            itemHrid: card.dataset.itemHrid,
            level: Number(card.dataset.level) || 0
        };
        const followingCard = mooncakeGetMarketHistoryFollowingCard();
        if (followingCard) {
            if (mooncakeRenderFloatingMarketHistoryCard(followingCard, target, card._mooncakeMarketHistoryWindows)) {
                card.remove();
            }
            return;
        }
        const savedPosition = options.ignoreSavedPosition ? null : mooncakeReadMarketHistoryFloatPosition();
        const sourceRect = options.sourceRect || (savedPosition ? null : card.getBoundingClientRect());
        mooncakeMarketHistoryFloatDrag = null;
        card.removeAttribute('id');
        card.dataset.mooncakeHistoryFloating = '1';
        card.dataset.mooncakeHistoryFollowing = '1';
        document.body.appendChild(card);
        mooncakeRestoreMarketHistoryStacking();
        card.removeAttribute('style');
        mooncakeRenderFloatingMarketHistoryCard(card, target, card._mooncakeMarketHistoryWindows, '');
        mooncakePositionFloatingMarketHistoryCard(card, sourceRect, currentItem);
        if (options.keepSourcePosition && sourceRect) {
            mooncakeMoveFloatingMarketHistoryCard(card, sourceRect.left, sourceRect.top);
        }
        return card;
    }

    function mooncakeStartMarketHistoryFloatingDrag(event) {
        if (event.button !== 0 || event.isPrimary === false) return;
        const eventTarget = event.target;
        if (eventTarget?.closest?.('button, a, input, select, textarea, [contenteditable="true"], [data-mooncake-history-card-controls], .mooncake-history-timeline-target, [data-mooncake-history-timeline-detail]')) return;
        const floatingCard = eventTarget?.closest?.(MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR);
        const anchoredCard = floatingCard
            ? null
            : eventTarget?.closest?.(`#${MOONCAKE_MARKET_HISTORY_CARD_ID}`);
        const card = floatingCard || anchoredCard;
        if (!card) return;
        const handle = card;
        const rect = card.getBoundingClientRect();
        mooncakeMarketHistoryFloatDrag = {
            card,
            handle,
            pointerId: event.pointerId,
            startX: event.clientX,
            startY: event.clientY,
            offsetX: event.clientX - rect.left,
            offsetY: event.clientY - rect.top,
            width: rect.width,
            height: rect.height,
            currentItem: anchoredCard ? card.parentElement : mooncakeFindCurrentMarketItemNode(),
            sourceRect: anchoredCard ? rect : null,
            startedAnchored: !!anchoredCard,
            moved: false,
            pendingLeft: null,
            pendingTop: null,
            frame: 0
        };
        handle.style.cursor = 'grabbing';
        try { handle.setPointerCapture?.(event.pointerId); } catch (_) {}
        if (!anchoredCard) {
            event.preventDefault();
            event.stopPropagation();
        }
    }

    function mooncakeMoveMarketHistoryFloatingDrag(event) {
        const drag = mooncakeMarketHistoryFloatDrag;
        if (!drag || drag.pointerId !== event.pointerId) return;
        if (!drag.card?.isConnected) {
            if (drag.frame) cancelAnimationFrame(drag.frame);
            mooncakeMarketHistoryFloatDrag = null;
            return;
        }
        if (!drag.moved) {
            const deltaX = event.clientX - drag.startX;
            const deltaY = event.clientY - drag.startY;
            if (Math.hypot(deltaX, deltaY) < 5) {
                event.preventDefault();
                return;
            }
            if (drag.startedAnchored) {
                const floatingCard = mooncakeFloatMarketHistoryCard(drag.card, {
                    currentItem: drag.currentItem,
                    sourceRect: drag.sourceRect,
                    ignoreSavedPosition: true,
                    keepSourcePosition: true
                });
                if (!floatingCard) {
                    mooncakeMarketHistoryFloatDrag = null;
                    return;
                }
                drag.card = floatingCard;
                drag.handle = floatingCard;
                const floatingRect = floatingCard.getBoundingClientRect();
                drag.offsetX = event.clientX - floatingRect.left;
                drag.offsetY = event.clientY - floatingRect.top;
                drag.width = floatingRect.width;
                drag.height = floatingRect.height;
                try { floatingCard.setPointerCapture?.(event.pointerId); } catch (_) {}
            }
            drag.moved = true;
        }
        drag.pendingLeft = event.clientX - drag.offsetX;
        drag.pendingTop = event.clientY - drag.offsetY;
        if (!drag.frame) {
            drag.frame = requestAnimationFrame(() => {
                drag.frame = 0;
                mooncakeMoveFloatingMarketHistoryCard(
                    drag.card,
                    drag.pendingLeft,
                    drag.pendingTop,
                    { width: drag.width, height: drag.height }
                );
            });
        }
        event.preventDefault();
    }

    function mooncakeEndMarketHistoryFloatingDrag(event) {
        const drag = mooncakeMarketHistoryFloatDrag;
        if (!drag || drag.pointerId !== event.pointerId) return;
        if (drag.frame) cancelAnimationFrame(drag.frame);
        drag.frame = 0;
        if (drag.moved) {
            const finalLeft = Number.isFinite(drag.pendingLeft)
                ? drag.pendingLeft
                : parseFloat(drag.card?.dataset.mooncakeHistoryFloatLeft || '');
            const finalTop = Number.isFinite(drag.pendingTop)
                ? drag.pendingTop
                : parseFloat(drag.card?.dataset.mooncakeHistoryFloatTop || '');
            mooncakeMoveFloatingMarketHistoryCard(drag.card, finalLeft, finalTop);
            const shouldSnap = mooncakeShouldSnapMarketHistoryCardToOrigin(drag.card, drag.currentItem);
            if (shouldSnap) mooncakeClearMarketHistoryFloatPosition();
            else mooncakeWriteMarketHistoryFloatPosition(drag.card, drag.currentItem);
            drag.card.dataset.mooncakeHistorySuppressClick = '1';
            setTimeout(() => {
                if (drag.card?.dataset.mooncakeHistorySuppressClick === '1') {
                    delete drag.card.dataset.mooncakeHistorySuppressClick;
                }
            }, 250);
            try { drag.handle?.releasePointerCapture?.(event.pointerId); } catch (_) {}
            if (drag.handle?.isConnected) drag.handle.style.cursor = 'grab';
            if (shouldSnap) mooncakeRestoreFollowingMarketHistoryCardToAnchor(drag.card);
        } else if (event.type === 'pointerup' && !drag.startedAnchored) {
            drag.card.dataset.mooncakeHistorySuppressClick = '1';
            mooncakeSetFloatingMarketHistoryCardCollapsed(
                drag.card,
                drag.card.dataset.mooncakeHistoryCollapsed !== '1'
            );
            setTimeout(() => {
                if (drag.card?.dataset.mooncakeHistorySuppressClick === '1') {
                    delete drag.card.dataset.mooncakeHistorySuppressClick;
                }
            }, 0);
        }
        if (!drag.moved) {
            try { drag.handle?.releasePointerCapture?.(event.pointerId); } catch (_) {}
            if (drag.handle?.isConnected) drag.handle.style.cursor = 'grab';
        }
        mooncakeMarketHistoryFloatDrag = null;
    }

    function mooncakeRenderMarketHistoryCard(target, windows = null, stateText = '') {
        if (!target?.currentItem || !target.itemHrid) {
            mooncakeRemoveMarketHistoryCards({ includeFloating: true });
            return null;
        }
        const isMobile = mooncakeIsPhoneMarketUi();
        if (!isMobile) mooncakeElevateMarketHistoryStacking(target.currentItem);
        const id = isMobile ? MOONCAKE_MARKET_HISTORY_MOBILE_ID : MOONCAKE_MARKET_HISTORY_CARD_ID;
        const otherId = isMobile ? MOONCAKE_MARKET_HISTORY_CARD_ID : MOONCAKE_MARKET_HISTORY_MOBILE_ID;
        document.getElementById(otherId)?.remove();

        let card = document.getElementById(id);
        if (!card) {
            card = document.createElement('div');
            card.id = id;
            card.dataset.expanded = isMobile ? '0' : '1';
            if (isMobile) document.body.appendChild(card);
            else target.currentItem.appendChild(card);
        } else if (!isMobile && card.parentElement !== target.currentItem) {
            target.currentItem.appendChild(card);
        }
        card.dataset.itemHrid = target.itemHrid;
        card.dataset.level = String(target.level);
        card._mooncakeMarketHistoryWindows = windows;
        card._mooncakeMarketHistoryStateText = stateText;
        mooncakeStyleMarketHistoryCard(card, isMobile);
        if (!isMobile) {
            const currentStyle = getComputedStyle(target.currentItem);
            if (currentStyle.position === 'static') target.currentItem.style.position = 'relative';
            target.currentItem.style.overflow = 'visible';
            Object.assign(card.style, {
                position: 'absolute',
                display: 'block',
                flex: '',
                alignSelf: '',
                margin: '0',
                marginLeft: `${MOONCAKE_MARKET_HISTORY_ANCHOR_MARGIN}px`,
                left: '100%',
                top: '-20px',
                right: '',
                bottom: '',
                padding: '4px 6px',
                width: mooncakeIsMarketHistoryEquipmentTarget(target.itemHrid) ? '340px' : 'fit-content',
                height: '',
                minHeight: '',
                maxWidth: 'calc(100vw - 16px)',
                overflow: 'hidden',
                zIndex: MOONCAKE_MARKET_HISTORY_CARD_Z_INDEX,
                boxShadow: '0 5px 16px rgba(0,0,0,.22)',
                cursor: 'grab',
                touchAction: 'none',
                userSelect: 'none'
            });
            if (card.dataset.mooncakeHistoryCollapsed === '1') {
                Object.assign(card.style, {
                    width: '34px',
                    height: '28px',
                    minHeight: '28px',
                    padding: '0',
                    overflow: 'hidden'
                });
                card.innerHTML = mooncakeBuildMarketHistoryCollapsedHtml();
                card.setAttribute('aria-expanded', 'false');
                return card;
            }
        }

        if (isMobile && card.dataset.expanded !== '1') {
            card.innerHTML = `<button type="button" data-mooncake-history-toggle="1" title="交易量" style="width:34px;height:28px;border:0;background:transparent;color:#eef6ff;font-size:13px;font-weight:900;cursor:pointer;">量</button>`;
            mooncakePositionMobileHistoryCard(card, target.currentItem);
            return card;
        }

        card.innerHTML = mooncakeBuildMarketHistoryCardHtml(target.itemHrid, target.level, windows, stateText, { compact: isMobile });
        mooncakeBindMarketHistoryPriceTooltips(card, windows);
        if (isMobile) {
            mooncakeInstallMarketHistoryMobileControl(card);
            mooncakePositionMobileHistoryCard(card, target.currentItem);
        }
        return card;
    }

    async function ensureMooncakeMarketHistoryCard(options = {}) {
        if (!mooncakeIsMarketHistoryCardEnabled()) {
            mooncakeMarketHistorySeq++;
            mooncakeMarketHistoryCardAbortController?.abort();
            mooncakeMarketHistoryCardAbortController = null;
            mooncakeMarketHistoryActiveRequestKey = '';
            mooncakeRemoveMarketHistoryCards({ includeFloating: true });
            mooncakeMarketHistoryLastRenderKey = '';
            return;
        }
        const target = mooncakeGetCurrentMarketHistoryTarget();
        if (!target) {
            mooncakeMarketHistorySeq++;
            mooncakeMarketHistoryCardAbortController?.abort();
            mooncakeMarketHistoryCardAbortController = null;
            mooncakeMarketHistoryActiveRequestKey = '';
            mooncakeRemoveMarketHistoryCards({ includeFloating: true });
            mooncakeMarketHistoryLastRenderKey = '';
            return;
        }
        const renderKey = `${target.itemHrid}|${target.level}`;
        const isPhone = mooncakeIsPhoneMarketUi();
        const regularCard = document.getElementById(isPhone ? MOONCAKE_MARKET_HISTORY_MOBILE_ID : MOONCAKE_MARKET_HISTORY_CARD_ID);
        const regularCardIsCurrent = regularCard?.isConnected &&
            regularCard.dataset.itemHrid === target.itemHrid &&
            Number(regularCard.dataset.level) === Number(target.level) &&
            (isPhone ? regularCard.parentElement === document.body : target.currentItem.contains(regularCard));
        if (!options.force && mooncakeMarketHistoryCardAbortController && mooncakeMarketHistoryActiveRequestKey === renderKey) {
            if (!regularCardIsCurrent) mooncakeRenderMarketHistoryCard(target, null, '加载中...');
            return;
        }
        const followingCard = mooncakeGetMarketHistoryFollowingCard();
        const followingCurrentTarget = followingCard
            && followingCard.dataset.itemHrid === target.itemHrid
            && Number(followingCard.dataset.level) === Number(target.level);
        if (followingCurrentTarget && !options.force) {
            mooncakePositionFloatingMarketHistoryCard(followingCard, null, target.currentItem);
            if (mooncakeMarketHistoryCardAbortController) {
                mooncakeMarketHistorySeq++;
                mooncakeMarketHistoryCardAbortController?.abort();
                mooncakeMarketHistoryCardAbortController = null;
                mooncakeMarketHistoryActiveRequestKey = '';
            } else {
                mooncakeMarketHistoryActiveRequestKey = '';
            }
            mooncakeRemoveMarketHistoryCards();
            mooncakeMarketHistoryLastRenderKey = '';
            mooncakeMarketHistoryLastRenderAt = 0;
            return;
        }
        const isStillCurrentTarget = () => {
            const currentTarget = mooncakeGetCurrentMarketHistoryTarget();
            return !!currentTarget && currentTarget.itemHrid === target.itemHrid && Number(currentTarget.level) === Number(target.level);
        };
        const renderResolvedTargetCard = (windows, stateText = '') => {
            let floatingCard = mooncakeGetMarketHistoryFollowingCard();
            // The default remains anchored beside the market item. Existing users
            // who already saved a manual position retain that choice.
            if (!floatingCard && !mooncakeIsPhoneMarketUi() && mooncakeReadMarketHistoryFloatPosition()) {
                const regularCard = document.getElementById(MOONCAKE_MARKET_HISTORY_CARD_ID);
                if (regularCard?.dataset.itemHrid === target.itemHrid && Number(regularCard.dataset.level) === Number(target.level)) {
                    mooncakeFloatMarketHistoryCard(regularCard);
                    floatingCard = mooncakeGetMarketHistoryFollowingCard();
                }
            }
            if (floatingCard && mooncakeRenderFloatingMarketHistoryCard(floatingCard, target, windows, stateText)) {
                mooncakeRemoveMarketHistoryCards();
                return floatingCard;
            }
            return mooncakeRenderMarketHistoryCard(target, windows, stateText);
        };
        const now = Date.now();
        if (!options.force && regularCardIsCurrent && renderKey === mooncakeMarketHistoryLastRenderKey && now - mooncakeMarketHistoryLastRenderAt < 4500) {
            return;
        }
        mooncakeMarketHistoryLastRenderKey = renderKey;
        mooncakeMarketHistoryLastRenderAt = now;
        const seq = ++mooncakeMarketHistorySeq;
        mooncakeMarketHistoryCardAbortController?.abort();
        const cardAbortController = new AbortController();
        mooncakeMarketHistoryCardAbortController = cardAbortController;
        mooncakeMarketHistoryActiveRequestKey = renderKey;
        mooncakeRenderMarketHistoryCard(target, null, '加载中...');
        try {
            const data = await fetchMarketHistories([target.itemHrid], [target.level], 7, {
                ...options,
                includeTimeline: true,
                signal: cardAbortController.signal
            });
            if (seq !== mooncakeMarketHistorySeq || !isStillCurrentTarget()) return;
            const windows = data?.[target.itemHrid]?.[String(target.level)] || {};
            const hasData = MOONCAKE_MARKET_HISTORY_WINDOWS.some(days => windows[days]?.volume > 0);
            renderResolvedTargetCard(windows, hasData ? '' : '无交易记录');
        } catch (err) {
            if (seq !== mooncakeMarketHistorySeq || !isStillCurrentTarget()) return;
            if (err?.name === 'AbortError') return;
            console.warn('[MoonCake] 交易量获取失败:', err);
            renderResolvedTargetCard(null, '加载失败');
        } finally {
            if (mooncakeMarketHistoryCardAbortController === cardAbortController) {
                mooncakeMarketHistoryCardAbortController = null;
                mooncakeMarketHistoryActiveRequestKey = '';
            }
        }
    }

    function scheduleMooncakeMarketHistoryCard(delay = 0, options = {}) {
        if (!mooncakeIsMarketHistoryCardEnabled()) return;
        if (options.force && mooncakeMarketHistoryScheduleTimer) {
            clearTimeout(mooncakeMarketHistoryScheduleTimer);
            mooncakeMarketHistoryScheduleTimer = 0;
        } else if (mooncakeMarketHistoryScheduleTimer) {
            return;
        }
        const wait = options.force ? 0 : (Number.isFinite(Number(delay)) && Number(delay) > 0 ? Number(delay) : 80);
        mooncakeMarketHistoryScheduleTimer = setTimeout(() => {
            mooncakeMarketHistoryScheduleTimer = 0;
            ensureMooncakeMarketHistoryCard(options);
        }, wait);
    }

    function hookMooncakeMarketHistoryEvents() {
        if (window.__mooncakeMarketHistoryEventsBound) return;
        window.__mooncakeMarketHistoryEventsBound = true;
        document.addEventListener('click', (event) => {
            const target = event.target;
            const enhancementSettingsOpen = target.closest?.(`[${MOONCAKE_ENHANCEMENT_SETTINGS_TRIGGER_ATTR}]`);
            if (enhancementSettingsOpen) {
                mooncakeOpenEnhancementSettingsPanel(
                    enhancementSettingsOpen,
                    enhancementSettingsOpen.getAttribute(MOONCAKE_ENHANCEMENT_SETTINGS_TRIGGER_ATTR)
                );
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const marketJumpSwitch = target.closest?.('[data-mooncake-market-jump-switch]');
            if (marketJumpSwitch) {
                mooncakeSetMarketJumpHelpersEnabled(!mooncakeIsMarketJumpHelpersEnabled());
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const historyCardSwitch = target.closest?.('[data-mooncake-market-history-switch]');
            if (historyCardSwitch) {
                mooncakeSetMarketHistoryCardEnabled(!mooncakeIsMarketHistoryCardEnabled());
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const historyPositionReset = target.closest?.('[data-mooncake-market-history-reset-position]');
            if (historyPositionReset) {
                mooncakeResetMarketHistoryCardPosition();
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const marketHourlySwitch = target.closest?.('[data-mooncake-market-hourly-switch]');
            if (marketHourlySwitch) {
                setMarketplaceHourlyWageEnabled(!isMarketplaceHourlyWageEnabled());
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const orderArchiveSwitch = target.closest?.('[data-mooncake-order-archive-switch]');
            if (orderArchiveSwitch) {
                mooncakeSetOrderBookArchiveEnabled(!mooncakeIsOrderBookArchiveEnabled());
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const orderArchiveOpen = target.closest?.('[data-mooncake-order-archive-open]');
            if (orderArchiveOpen) {
                mooncakeOpenOrderBookArchivePanel().catch(error => console.warn('[MoonCake] 挂单记录打开失败:', error));
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const protectionAssistantSwitch = target.closest?.('[data-mooncake-protection-assistant-switch]');
            if (protectionAssistantSwitch) {
                mooncakeSetProtectionAssistantEnabled(!mooncakeIsProtectionAssistantEnabled());
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const inventoryWarehouseSwitch = target.closest?.('[data-mooncake-inventory-warehouse-switch]');
            if (inventoryWarehouseSwitch) {
                mooncakeSetEnhancementInventoryWarehouseEnabled(!mooncakeIsEnhancementInventoryWarehouseEnabled());
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const chatLaborSwitch = target.closest?.('[data-mooncake-chat-labor-switch]');
            if (chatLaborSwitch) {
                setChatLaborEnabled(!isChatLaborEnabled());
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const historyOrderToggle = target.closest?.('[data-mooncake-history-order-toggle]');
            if (historyOrderToggle) {
                mooncakeSetMarketHistoryCardSellFirst(!mooncakeIsMarketHistoryCardSellFirst());
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const floatingCard = target.closest?.(MOONCAKE_MARKET_HISTORY_FOLLOWING_SELECTOR);
            if (floatingCard) {
                const interactiveTarget = target.closest?.(
                    'button, a, input, select, textarea, [contenteditable="true"], [data-mooncake-history-card-controls], .mooncake-history-timeline-target, [data-mooncake-history-timeline-detail]'
                );
                if (!interactiveTarget) {
                    const suppressClick = floatingCard.dataset.mooncakeHistorySuppressClick === '1';
                    delete floatingCard.dataset.mooncakeHistorySuppressClick;
                    if (!suppressClick) {
                        mooncakeSetFloatingMarketHistoryCardCollapsed(
                            floatingCard,
                            floatingCard.dataset.mooncakeHistoryCollapsed !== '1'
                        );
                    }
                    event.preventDefault();
                    event.stopPropagation();
                    return;
                }
            }
            const anchoredCard = target.closest?.(`#${MOONCAKE_MARKET_HISTORY_CARD_ID}`);
            if (anchoredCard) {
                const interactiveTarget = target.closest?.(
                    'button, a, input, select, textarea, [contenteditable="true"], .mooncake-history-timeline-target, [data-mooncake-history-timeline-detail]'
                );
                if (!interactiveTarget) {
                    const suppressClick = anchoredCard.dataset.mooncakeHistorySuppressClick === '1';
                    delete anchoredCard.dataset.mooncakeHistorySuppressClick;
                    if (!suppressClick) {
                        mooncakeSetAnchoredMarketHistoryCardCollapsed(
                            anchoredCard,
                            anchoredCard.dataset.mooncakeHistoryCollapsed !== '1'
                        );
                    }
                    event.preventDefault();
                    event.stopPropagation();
                    return;
                }
            }
            const rankPanel = mooncakeGetOpenMarketStatisticsPanel();
            const rankTrigger = target.closest?.('[data-mooncake-history-ranking]');
            const shortageTrigger = target.closest?.('[data-mooncake-shortage]');
            const bargainTrigger = target.closest?.('[data-mooncake-bargain]');
            if (rankPanel && !rankTrigger && !shortageTrigger && !bargainTrigger && !target.closest?.(`#${MOONCAKE_MARKET_HISTORY_RANKING_ID}, #${MOONCAKE_MARKET_SHORTAGE_ID}, #${MOONCAKE_MARKET_BARGAIN_ID}`)) {
                mooncakeCloseMarketStatisticsPanels();
            }
            const toggle = target.closest?.('[data-mooncake-history-toggle]');
            if (toggle) {
                const card = toggle.closest(`#${MOONCAKE_MARKET_HISTORY_MOBILE_ID}`);
                if (card) {
                    card.dataset.expanded = card.dataset.expanded === '1' ? '0' : '1';
                    const marketTarget = mooncakeGetCurrentMarketHistoryTarget();
                    const windows = card._mooncakeMarketHistoryWindows;
                    const stateText = card._mooncakeMarketHistoryStateText || '';
                    const canRenderCurrentState = marketTarget
                        && marketTarget.itemHrid === card.dataset.itemHrid
                        && Number(marketTarget.level) === Number(card.dataset.level)
                        && ((windows && typeof windows === 'object') || stateText);
                    if (canRenderCurrentState) {
                        mooncakeRenderMarketHistoryCard(marketTarget, windows, stateText);
                    } else {
                        ensureMooncakeMarketHistoryCard({ force: true });
                    }
                    event.preventDefault();
                    event.stopPropagation();
                }
                return;
            }
            if (target.closest?.('[data-mooncake-history-refresh]')) {
                ensureMooncakeMarketHistoryCard({ force: true });
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            if (rankTrigger) {
                mooncakeOpenMarketHistoryRankingPanel(rankTrigger);
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            if (shortageTrigger) {
                mooncakeOpenMarketShortagePanel();
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            if (bargainTrigger) {
                mooncakeOpenMarketBargainPanel();
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const rankJump = target.closest?.('[data-mooncake-rank-jump], [data-mooncake-bargain-jump]');
            if (rankJump) {
                const hrid = rankJump.getAttribute('data-hrid');
                const level = parseInt(rankJump.getAttribute('data-level') || '0', 10) || 0;
                mooncakeOpenMarketplaceForHrid(hrid, level).then((opened) => {
                    if (opened) {
                        if (event.isTrusted) mooncakeQueueQ7MarketReport(hrid, level);
                        mooncakeCloseMarketStatisticsPanels();
                    }
                });
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            const rankSort = target.closest?.('[data-mooncake-history-sort]');
            if (rankSort) {
                mooncakeSetMarketHistoryRankingSort(rankSort.getAttribute('data-mooncake-history-sort'));
                mooncakeRunMarketHistoryRanking();
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            if (target.closest?.('[data-mooncake-history-rank-close]')) {
                mooncakeCloseMarketStatisticsPanels();
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            if (target.closest?.('[data-mooncake-history-rank-run]')) {
                mooncakeRunMarketHistoryRanking({ force: true });
                event.preventDefault();
                event.stopPropagation();
                return;
            }
            if (target.closest?.('[data-mooncake-bargain-run]')) {
                mooncakeRunMarketBargainScan({ force: true });
                event.preventDefault();
                event.stopPropagation();
            }
        }, true);
        document.addEventListener('pointerdown', mooncakeStartMarketHistoryFloatingDrag, true);
        window.addEventListener('pointermove', mooncakeMoveMarketHistoryFloatingDrag, { capture: true, passive: false });
        window.addEventListener('pointerup', mooncakeEndMarketHistoryFloatingDrag, true);
        window.addEventListener('pointercancel', mooncakeEndMarketHistoryFloatingDrag, true);
        document.addEventListener('change', (event) => {
            const enhancementRouteObjective = event.target.closest?.('[data-mooncake-enhancement-route-objective]');
            if (enhancementRouteObjective) {
                setEnhancementRouteObjective(enhancementRouteObjective.value);
                return;
            }
            const chatLaborFormat = event.target.closest?.('[data-mooncake-chat-labor-format]');
            if (chatLaborFormat) {
                setChatLaborFormat(chatLaborFormat.value);
                return;
            }
            const chatLaborExpected = event.target.closest?.('[data-mooncake-chat-labor-expected]');
            if (chatLaborExpected) {
                const side = chatLaborExpected.getAttribute('data-mooncake-chat-labor-expected');
                const accepted = setChatLaborExpectedHourlyM(side, chatLaborExpected.value);
                if (!accepted) {
                    chatLaborExpected.value = String(side === 'sell'
                        ? getChatLaborSellExpectedHourlyM()
                        : getChatLaborBuyExpectedHourlyM());
                }
                return;
            }
            const chatProfitThreshold = event.target.closest?.('[data-mooncake-chat-profit-threshold]');
            if (chatProfitThreshold) {
                const kind = chatProfitThreshold.getAttribute('data-mooncake-chat-profit-threshold');
                const accepted = setChatLaborProfitThresholdM(kind, chatProfitThreshold.value);
                if (!accepted) {
                    chatProfitThreshold.value = String(kind === 'dim'
                        ? getChatLaborProfitDimBelowM()
                        : getChatLaborProfitHighlightAboveM());
                }
                return;
            }
            const materialEquipmentLevel = event.target.closest?.('[data-mooncake-material-equipment-level]');
            if (materialEquipmentLevel) {
                setMaterialEquipmentJumpLevel(materialEquipmentLevel.value);
                return;
            }
            const mobileHistoryColumn = event.target.closest?.('[data-mooncake-history-mobile-column]');
            if (mobileHistoryColumn) {
                mooncakeSetMarketHistoryMobileColumn(
                    mobileHistoryColumn.getAttribute('data-mooncake-history-mobile-column'),
                    mobileHistoryColumn.checked
                );
                return;
            }
            const option = event.target.closest?.('[data-mooncake-rank-filter-option]');
            if (!option) return;
            const panel = option.closest(`#${MOONCAKE_MARKET_HISTORY_RANKING_ID}, #${MOONCAKE_MARKET_SHORTAGE_ID}`);
            const kind = option.getAttribute('data-mooncake-rank-filter-option');
            if (panel && kind) mooncakeUpdateRankingMultiSelectLabel(panel, kind);
        }, true);
        document.addEventListener('keydown', (event) => {
            const nameInput = event.target.closest?.('[data-mooncake-rank-item-name]');
            const bargainNameInput = event.target.closest?.('[data-mooncake-bargain-item-name]');
            if ((!nameInput && !bargainNameInput) || event.key !== 'Enter' || event.isComposing) return;
            if (bargainNameInput) mooncakeRunMarketBargainScan({ force: true });
            else mooncakeRunMarketHistoryRanking({ force: true });
            event.preventDefault();
            event.stopPropagation();
        }, true);
        window.addEventListener('resize', () => {
            if (mooncakeMarketHistoryResizeFrame) return;
            mooncakeMarketHistoryResizeFrame = requestAnimationFrame(() => {
                mooncakeMarketHistoryResizeFrame = 0;
                const currentItem = mooncakeFindCurrentMarketItemNode();
                const phoneCard = document.getElementById(MOONCAKE_MARKET_HISTORY_MOBILE_ID);
                if (phoneCard) mooncakePositionMobileHistoryCard(phoneCard, currentItem);
                mooncakeGetMarketHistoryFloatingCards().forEach(floating => mooncakePositionFloatingMarketHistoryCard(floating, null, currentItem));
            });
        }, true);
    }

    function mooncakeSetMarketHistoryRankingSort(requestedKey) {
        if (!requestedKey) return;
        if (requestedKey === 'currentHourly' && mooncakeMarketHistoryRankingSort === 'currentHourly') {
            requestedKey = 'opportunity';
        } else if (requestedKey === 'currentHourly' && mooncakeMarketHistoryRankingSort === 'opportunity') {
            requestedKey = 'currentHourly';
        }
        const avgHourlyMap = { avg1: 'avgHourly1', avg3: 'avgHourly3', avg7: 'avgHourly7' };
        mooncakeMarketHistoryRankingSort = mooncakeMarketHistoryRankingSort === requestedKey && avgHourlyMap[requestedKey]
            ? avgHourlyMap[requestedKey]
            : requestedKey;
        mooncakeWriteRankingPreferences({ sort: mooncakeMarketHistoryRankingSort });
    }

    function mooncakeReadRankingPreferences(storageKey = MOONCAKE_MARKET_HISTORY_RANKING_PREFS_KEY, defaultItemLevels = [95]) {
        const defaults = { itemLevels: defaultItemLevels, enhancementLevel: 10, nameQuery: '', minVolume: 0, sort: 'turnover7' };
        try {
            const parsed = JSON.parse(localStorage.getItem(storageKey) || '{}');
            const itemLevels = Array.isArray(parsed.itemLevels) ? parsed.itemLevels.map(Number).filter(v => Number.isFinite(v) && v > 0) : defaults.itemLevels;
            const legacyEnhancementLevels = Array.isArray(parsed.enhancementLevels) ? parsed.enhancementLevels : [];
            const enhancementLevel = Number.isFinite(Number(parsed.enhancementLevel))
                ? Number(parsed.enhancementLevel)
                : Number(legacyEnhancementLevels[0]);
            const minVolume = Number(parsed.minVolume);
            const validSort = ['name', 'currentHourly', 'opportunity', 'volume1', 'avg1', 'avgHourly1', 'turnover1', 'volume3', 'avg3', 'avgHourly3', 'turnover3', 'volume7', 'avg7', 'avgHourly7', 'turnover7'];
            return {
                itemLevels: itemLevels.length ? [...new Set(itemLevels)] : defaults.itemLevels,
                enhancementLevel: Number.isFinite(enhancementLevel) && enhancementLevel >= 0 && enhancementLevel <= 20
                    ? parseInt(enhancementLevel, 10)
                    : defaults.enhancementLevel,
                nameQuery: typeof parsed.nameQuery === 'string' ? parsed.nameQuery : defaults.nameQuery,
                minVolume: Number.isFinite(minVolume) && minVolume >= 0 ? minVolume : defaults.minVolume,
                sort: validSort.includes(parsed.sort) ? parsed.sort : defaults.sort
            };
        } catch (_) {
            return defaults;
        }
    }

    function mooncakeReadShortagePreferences() {
        return mooncakeReadRankingPreferences(MOONCAKE_MARKET_SHORTAGE_PREFS_KEY, [95, 90, 85, 60]);
    }

    function mooncakeWriteRankingPreferences(changes = {}, storageKey = MOONCAKE_MARKET_HISTORY_RANKING_PREFS_KEY) {
        try {
            const current = mooncakeReadRankingPreferences(storageKey);
            localStorage.setItem(storageKey, JSON.stringify({ ...current, ...changes }));
        } catch (_) {}
    }

    function mooncakeGetRankingItemLevelOptions() {
        const initData = getInitClientData();
        const detailMap = itemDetailMap || initData?.itemDetailMap || {};
        const levels = new Set([95]);
        for (const detail of Object.values(detailMap)) {
            if (!detail?.equipmentDetail || !detail?.enhancementCosts) continue;
            const level = Number(detail.itemLevel);
            if (Number.isFinite(level) && level > 0) levels.add(level);
        }
        return [...levels].sort((a, b) => b - a);
    }

    function mooncakeBuildRankingMultiSelect(kind, label, options, selectedValues, width = 118) {
        const selected = new Set(selectedValues.map(Number));
        const selectedText = options.filter(value => selected.has(Number(value))).join(', ') || '未选择';
        const optionHtml = options.map(value => `
            <label style="display:flex;align-items:center;gap:7px;padding:5px 8px;cursor:pointer;white-space:nowrap;">
                <input type="checkbox" data-mooncake-rank-filter-option="${kind}" value="${value}" ${selected.has(Number(value)) ? 'checked' : ''}>
                <span>${value}</span>
            </label>
        `).join('');
        return `
            <div style="display:flex;align-items:center;gap:4px;color:rgba(230,238,255,.72);"><span>${label}</span>
                <details data-mooncake-rank-filter="${kind}" style="position:relative;width:${width}px;">
                    <summary style="display:flex;align-items:center;justify-content:space-between;gap:8px;list-style:none;cursor:pointer;background:rgba(255,255,255,.08);border:1px solid rgba(144,166,235,.25);border-radius:6px;color:#eef6ff;padding:4px 7px;box-sizing:border-box;">
                        <span data-mooncake-rank-filter-label="${kind}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${selectedText}</span>
                        <span aria-hidden="true" style="color:rgba(238,246,255,.58);">▾</span>
                    </summary>
                    <div style="position:absolute;left:0;top:calc(100% + 4px);z-index:5;min-width:100%;max-height:260px;overflow:auto;background:rgba(25,30,44,.99);border:1px solid rgba(144,166,235,.32);border-radius:6px;box-shadow:0 8px 22px rgba(0,0,0,.42);padding:4px 0;">${optionHtml}</div>
                </details>
            </div>
        `;
    }

    function mooncakeBuildRankingSingleSelect(kind, label, options, selectedValue, width = 118) {
        const selected = Number(selectedValue);
        const optionHtml = options.map(value => `
            <option value="${value}" ${Number(value) === selected ? 'selected' : ''}>+${value}</option>
        `).join('');
        return `
            <label style="display:flex;align-items:center;gap:4px;color:rgba(230,238,255,.72);"><span>${label}</span>
                <select data-mooncake-rank-filter-single="${kind}" aria-label="${label}" style="width:${width}px;background:rgba(25,30,44,.99);border:1px solid rgba(144,166,235,.25);border-radius:6px;color:#eef6ff;padding:4px 7px;box-sizing:border-box;">${optionHtml}</select>
            </label>
        `;
    }

    function mooncakeGetRankingEnhancementLevelOptions() {
        const common = [5, 7, 10, 12];
        const remaining = Array.from({ length: 21 }, (_, level) => level)
            .filter(level => !common.includes(level));
        return [...common, ...remaining];
    }

    function mooncakeReadRankingMultiSelect(panel, kind, fallbackValues) {
        const values = [...panel.querySelectorAll(`[data-mooncake-rank-filter-option="${kind}"]:checked`)]
            .map(input => parseInt(input.value, 10))
            .filter(Number.isFinite);
        return values.length ? [...new Set(values)] : [...fallbackValues];
    }

    function mooncakeReadRankingSingleSelect(panel, kind, fallbackValue) {
        const value = Number(panel.querySelector(`[data-mooncake-rank-filter-single="${kind}"]`)?.value);
        return Number.isFinite(value) && value >= 0 && value <= 20 ? parseInt(value, 10) : fallbackValue;
    }

    function mooncakeUpdateRankingMultiSelectLabel(panel, kind) {
        const label = panel?.querySelector(`[data-mooncake-rank-filter-label="${kind}"]`);
        if (!label) return;
        const values = mooncakeReadRankingMultiSelect(panel, kind, []);
        label.textContent = values.length ? values.join(', ') : '未选择';
        label.title = label.textContent;
    }

    function mooncakeGetEnhanceableEquipmentHrids(itemLevelFilter) {
        const initData = getInitClientData();
        const detailMap = itemDetailMap || initData?.itemDetailMap || {};
        const itemLevelSet = Array.isArray(itemLevelFilter) && itemLevelFilter.length
            ? new Set(itemLevelFilter.map(level => Number(level)))
            : null;
        return Object.entries(detailMap)
            .filter(([, detail]) => detail?.equipmentDetail && detail?.enhancementCosts)
            .filter(([, detail]) => !itemLevelSet || itemLevelSet.has(Number(detail.itemLevel || 0)))
            .map(([hrid]) => hrid)
            .sort((a, b) => {
                const la = Number(detailMap[a]?.itemLevel || 0);
                const lb = Number(detailMap[b]?.itemLevel || 0);
                return (lb - la) || getItemName(a).localeCompare(getItemName(b));
            });
    }

    function mooncakeFilterEquipmentHridsByName(hrids, query) {
        const terms = String(query || '')
            .trim()
            .toLocaleLowerCase()
            .split(/\s+/)
            .filter(Boolean);
        if (!terms.length) return hrids;
        return hrids.filter(hrid => {
            const haystack = getItemName(hrid).toLocaleLowerCase();
            return terms.every(term => haystack.includes(term));
        });
    }

    function mooncakeResolveMarketHistoryRankingTarget(trigger = null) {
        const card = trigger?.closest?.(`#${MOONCAKE_MARKET_HISTORY_CARD_ID}, #${MOONCAKE_MARKET_HISTORY_MOBILE_ID}, ${MOONCAKE_MARKET_HISTORY_FLOAT_SELECTOR}`);
        const itemHrid = trigger?.getAttribute?.('data-hrid') || card?.dataset?.itemHrid || '';
        const levelText = trigger?.getAttribute?.('data-level') || card?.dataset?.level || '';
        if (itemHrid) {
            return {
                currentItem: card?.closest?.('[class*="MarketplacePanel_currentItem"], [class*="Item_item"], [class*="Item_itemContainer"]') || mooncakeFindCurrentMarketItemNode(),
                itemHrid,
                level: parseInt(levelText, 10) || 0
            };
        }
        return mooncakeGetCurrentMarketHistoryTarget() || { currentItem: null, itemHrid: '', level: 0 };
    }

    function mooncakeOpenMarketHistoryRankingPanel(trigger = null, mode = 'ranking') {
        const panelId = mode === 'shortage' ? MOONCAKE_MARKET_SHORTAGE_ID : MOONCAKE_MARKET_HISTORY_RANKING_ID;
        const otherPanelId = mode === 'shortage' ? MOONCAKE_MARKET_HISTORY_RANKING_ID : MOONCAKE_MARKET_SHORTAGE_ID;
        document.getElementById(otherPanelId)?.remove();
        mooncakeMarketBargainSeq++;
        mooncakeMarketBargainAbortController?.abort();
        document.getElementById(MOONCAKE_MARKET_BARGAIN_ID)?.remove();
        let panel = document.getElementById(panelId);
        const target = mooncakeResolveMarketHistoryRankingTarget(trigger);
        const preferences = mode === 'shortage' ? mooncakeReadShortagePreferences() : mooncakeReadRankingPreferences();
        mooncakeMarketHistoryRankingSort = preferences.sort;
        const defaultItemLevels = preferences.itemLevels;
        const defaultEnhancementLevel = preferences.enhancementLevel;
        if (!panel) {
            panel = document.createElement('div');
            panel.id = panelId;
            document.body.appendChild(panel);
        }
        panel.dataset.itemHrid = target?.itemHrid || '';
        panel.dataset.level = '10';
        Object.assign(panel.style, {
            position: 'fixed',
            left: '50%',
            top: '50%',
            transform: 'translate(-50%, -50%)',
            width: 'min(1400px, calc(100vw - 16px))',
            maxHeight: 'min(720px, calc(100vh - 24px))',
            overflow: 'hidden',
            zIndex: '100000',
            boxSizing: 'border-box',
            border: '1px solid rgba(144,166,235,.35)',
            borderRadius: '12px',
            background: 'rgba(18,22,34,.98)',
            boxShadow: '0 16px 42px rgba(0,0,0,.55)',
            color: '#eef6ff',
            fontSize: '12px',
            display: 'flex',
            flexDirection: 'column'
        });
        const controlsHtml = `
            <label style="display:flex;align-items:center;gap:4px;color:rgba(230,238,255,.72);"><span>装备名称</span>
                <input type="search" data-mooncake-rank-item-name value="${mooncakeEscapeHtml(preferences.nameQuery)}" placeholder="输入名称" autocomplete="off" aria-label="装备名称" style="width:168px;background:rgba(255,255,255,.08);border:1px solid rgba(144,166,235,.25);border-radius:6px;color:#eef6ff;padding:4px 7px;box-sizing:border-box;">
            </label>
            ${mooncakeBuildRankingMultiSelect('item', '装备等级', mooncakeGetRankingItemLevelOptions(), defaultItemLevels, 118)}
            ${mooncakeBuildRankingSingleSelect('enhancement', '强化等级', mooncakeGetRankingEnhancementLevelOptions(), defaultEnhancementLevel, 94)}
            <label style="display:flex;align-items:center;gap:4px;color:rgba(230,238,255,.72);"><span>最低7日量</span>
                <input type="number" data-mooncake-rank-min-volume min="0" step="1" value="${preferences.minVolume}" aria-label="最低7日成交量" style="width:92px;background:rgba(255,255,255,.08);border:1px solid rgba(144,166,235,.25);border-radius:6px;color:#eef6ff;padding:4px 7px;box-sizing:border-box;">
            </label>
        `;
        panel.innerHTML = `
            <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.08);">
                <div style="font-size:15px;font-weight:900;">${mode === 'shortage' ? '缺货统计' : '交易统计'}</div>
                <button type="button" data-mooncake-history-rank-close="1" style="cursor:pointer;border:0;background:transparent;color:rgba(238,246,255,.72);font-size:18px;line-height:1;">×</button>
            </div>
            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.08);">
                ${controlsHtml}
                <button type="button" data-mooncake-history-rank-run="1" style="cursor:pointer;border:1px solid rgba(144,166,235,.35);background:rgba(144,166,235,.18);color:#eef6ff;border-radius:7px;padding:5px 10px;font-weight:800;">刷新</button>
                <span data-mooncake-rank-status style="color:rgba(230,238,255,.58);font-size:11px;"></span>
            </div>
            <div data-mooncake-rank-body style="overflow:auto;overscroll-behavior:contain;padding:0 12px 16px;"></div>
        `;
        panel.dataset.mode = mode;
        mooncakeRunMarketHistoryRanking();
    }

    function mooncakeOpenMarketShortagePanel() {
        mooncakeOpenMarketHistoryRankingPanel(null, 'shortage');
    }

    function mooncakeBuildRankingHeader() {
        const columns = MOONCAKE_RANKING_GRID_COLUMNS;
        const divider = 'border-left:1px solid rgba(255,255,255,.08);padding-left:8px;';
        const activeSortKeys = new Set([mooncakeMarketHistoryRankingSort]);
        if (mooncakeMarketHistoryRankingSort === 'opportunity') activeSortKeys.add('currentHourly');
        if (mooncakeMarketHistoryRankingSort === 'avgHourly1') activeSortKeys.add('avg1');
        if (mooncakeMarketHistoryRankingSort === 'avgHourly3') activeSortKeys.add('avg3');
        if (mooncakeMarketHistoryRankingSort === 'avgHourly7') activeSortKeys.add('avg7');
        const sortLabel = (key, label) => {
            const hourlyMap = { avg1: 'avgHourly1', avg3: 'avgHourly3', avg7: 'avgHourly7' };
            if (hourlyMap[key] && mooncakeMarketHistoryRankingSort === hourlyMap[key]) return `${label}·工时`;
            return label;
        };
        const sortButton = (key, label, gridColumn, color = 'rgba(230,238,255,.62)', extraStyle = '') => `
            <button type="button" data-mooncake-history-sort="${key}" style="grid-column:${gridColumn};grid-row:2;cursor:pointer;text-align:center;border:0;background:transparent;color:${activeSortKeys.has(key) ? '#FFD27A' : color};font-size:11px;font-weight:800;padding:0;${extraStyle}">${sortLabel(key, label)}</button>
        `;
        const groupStyle = 'text-align:center;color:rgba(230,238,255,.78);font-size:11px;font-weight:900;letter-spacing:.02em;';
        return `<div style="display:grid;grid-template-columns:${columns};min-width:${MOONCAKE_RANKING_MIN_WIDTH};gap:5px;position:sticky;top:0;background:rgba(18,22,34,.98);padding:8px 0 7px;border-bottom:1px solid rgba(255,255,255,.08);z-index:1;">
            <button type="button" data-mooncake-history-sort="name" style="grid-column:1;grid-row:1 / span 2;align-self:center;cursor:pointer;text-align:center;border:0;background:transparent;color:${mooncakeMarketHistoryRankingSort === 'name' ? '#FFD27A' : 'rgba(230,238,255,.72)'};font-size:11px;font-weight:900;padding:0;">装备</button>
            <div style="grid-column:2 / span 3;${groupStyle}${divider}">1d</div>
            <div style="grid-column:5 / span 3;${groupStyle}${divider}">3d</div>
            <div style="grid-column:8 / span 3;${groupStyle}${divider}">7d</div>
            ${sortButton('volume1', '数量', 2, '#87CEEB', divider)}
            ${sortButton('avg1', '均价/工时', 3, '#B9E6A3')}
            ${sortButton('turnover1', '总额', 4, '#FFD27A')}
            ${sortButton('volume3', '数量', 5, '#87CEEB', divider)}
            ${sortButton('avg3', '均价/工时', 6, '#B9E6A3')}
            ${sortButton('turnover3', '总额', 7, '#FFD27A')}
            ${sortButton('volume7', '数量', 8, '#87CEEB', divider)}
            ${sortButton('avg7', '均价/工时', 9, '#B9E6A3')}
            ${sortButton('turnover7', '总额', 10, '#FFD27A')}
        </div>`;
    }

    function mooncakeFormatRankingHourlyWage(value, color = null) {
        if (value === null || value === undefined) return '-';
        const resolvedColor = color || (Number(value) >= 0 ? '#B9E6A3' : 'rgba(230,238,255,.48)');
        return `<span style="color:${resolvedColor};font-weight:800;font-variant-numeric:tabular-nums;white-space:nowrap;">${mooncakeFormatSignedHourlyWage(value)}</span>`;
    }

    function mooncakeFormatRankingAvgHourly(avgPrice, hourlyWage, hourlyColor = null) {
        if (!(Number(avgPrice) > 0)) return '-';
        return `<span style="color:#B9E6A3;font-weight:800;">${mooncakeFormatMarketPrice(avgPrice)}</span><span style="color:rgba(230,238,255,.45);padding:0 2px;">/</span>${mooncakeFormatRankingHourlyWage(hourlyWage, hourlyColor)}`;
    }

    function mooncakeEscapeHtml(value) {
        return String(value == null ? '' : value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function mooncakeBuildRankingNameButton(row, displayName, title) {
        return `<button type="button" data-mooncake-rank-jump="1" data-hrid="${mooncakeEscapeHtml(row.itemHrid)}" data-level="${mooncakeEscapeHtml(row.variant || 0)}" title="${mooncakeEscapeHtml(title)}" style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:0;background:transparent;color:#eef6ff;font:inherit;font-weight:800;padding:0;cursor:pointer;text-align:left;">${mooncakeEscapeHtml(displayName)}</button>`;
    }

    function mooncakeRenderRankingRows(rows) {
        if (!rows.length) {
            return `${mooncakeBuildRankingHeader()}<div style="min-width:${MOONCAKE_RANKING_MIN_WIDTH};padding:18px;text-align:center;color:rgba(230,238,255,.62);">无交易记录</div>`;
        }
        const columns = MOONCAKE_RANKING_GRID_COLUMNS;
        const divider = 'border-left:1px solid rgba(255,255,255,.08);padding-left:8px;';
        return mooncakeBuildRankingHeader() + rows.map(row => {
            const icon = mooncakeCreateItemIconSvg(row.itemHrid, 24);
            const iconHtml = icon ? `<span data-icon="${row.itemHrid}"></span>` : '';
            const displayName = `${getItemName(row.itemHrid)}+${row.variant}`;
            const nameTitle = `${displayName} · 装备等级 ${row.itemLevel || '-'}`;
            return `
                <div data-mooncake-rank-row="${row.itemHrid}|${row.variant}" style="display:grid;grid-template-columns:${columns};min-width:${MOONCAKE_RANKING_MIN_WIDTH};gap:5px;align-items:center;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.045);">
                    <div style="display:flex;align-items:center;gap:6px;min-width:0;">${iconHtml}${mooncakeBuildRankingNameButton(row, displayName, nameTitle)}</div>
                    <div style="text-align:center;color:#87CEEB;font-weight:700;${divider}">${mooncakeFormatCompactNumber(row.volume1)}</div>
                    <div style="text-align:center;white-space:nowrap;">${mooncakeFormatRankingAvgHourly(row.avg1, row.avgHourly1, row.avgHourly1Color)}</div>
                    <div style="text-align:center;color:#FFD27A;font-weight:700;">${mooncakeFormatMarketPrice(row.turnover1)}</div>
                    <div style="text-align:center;color:#87CEEB;font-weight:700;${divider}">${mooncakeFormatCompactNumber(row.volume3)}</div>
                    <div style="text-align:center;white-space:nowrap;">${mooncakeFormatRankingAvgHourly(row.avg3, row.avgHourly3, row.avgHourly3Color)}</div>
                    <div style="text-align:center;color:#FFD27A;font-weight:700;">${mooncakeFormatMarketPrice(row.turnover3)}</div>
                    <div style="text-align:center;color:#87CEEB;font-weight:700;${divider}">${mooncakeFormatCompactNumber(row.volume7)}</div>
                    <div style="text-align:center;white-space:nowrap;">${mooncakeFormatRankingAvgHourly(row.avg7, row.avgHourly7, row.avgHourly7Color)}</div>
                    <div style="text-align:center;color:#FFD27A;font-weight:700;">${mooncakeFormatMarketPrice(row.turnover7)}</div>
                </div>
            `;
        }).join('');
    }

    function mooncakeHydrateRankingIcons(body) {
        body.querySelectorAll('[data-icon]').forEach(slot => {
            const icon = mooncakeCreateItemIconSvg(slot.getAttribute('data-icon'), 24);
            if (icon) slot.replaceWith(icon);
        });
    }

    async function mooncakeRunMarketHistoryRanking(options = {}) {
        const panel = document.getElementById(MOONCAKE_MARKET_HISTORY_RANKING_ID);
        const shortagePanel = document.getElementById(MOONCAKE_MARKET_SHORTAGE_ID);
        const activePanel = panel || shortagePanel;
        if (!activePanel) return;
        const isShortage = activePanel.dataset.mode === 'shortage';
        const runSeq = ++mooncakeMarketHistoryRankingSeq;
        if (mooncakeMarketHistoryRankingAbortController) mooncakeMarketHistoryRankingAbortController.abort();
        const abortController = new AbortController();
        mooncakeMarketHistoryRankingAbortController = abortController;
        const body = activePanel.querySelector('[data-mooncake-rank-body]');
        const status = activePanel.querySelector('[data-mooncake-rank-status]');
        const nameQuery = activePanel.querySelector('[data-mooncake-rank-item-name]')?.value?.trim() || '';
        const itemLevelFilter = mooncakeReadRankingMultiSelect(activePanel, 'item', [95]);
        const variants = [mooncakeReadRankingSingleSelect(activePanel, 'enhancement', 10)];
        const minVolumeValue = Number(activePanel.querySelector('[data-mooncake-rank-min-volume]')?.value);
        const minVolume = Number.isFinite(minVolumeValue) && minVolumeValue > 0 ? minVolumeValue : 0;
        mooncakeWriteRankingPreferences(
            { itemLevels: itemLevelFilter, enhancementLevel: variants[0], nameQuery, minVolume },
            isShortage ? MOONCAKE_MARKET_SHORTAGE_PREFS_KEY : MOONCAKE_MARKET_HISTORY_RANKING_PREFS_KEY
        );
        const allHrids = mooncakeFilterEquipmentHridsByName(
            mooncakeGetEnhanceableEquipmentHrids(itemLevelFilter),
            nameQuery
        );
        const marketData = getMarketData();
        const hrids = (isShortage ? allHrids.filter(hrid => {
            const levelData = marketData?.marketData?.[hrid]?.[String(variants[0])];
            return !levelData || !Number.isFinite(Number(levelData.a)) || Number(levelData.a) <= 0;
        }) : allHrids).slice(0, 120);
        const levelText = itemLevelFilter?.length ? `，装备等级 ${itemLevelFilter.join('/')}` : '';
        const nameText = nameQuery ? `，名称“${nameQuery}”` : '';
        const volumeText = minVolume > 0 ? `，7日量≥${minVolume}` : '';
        if (status) status.textContent = `装备 ${hrids.length}${allHrids.length > hrids.length ? `/${allHrids.length}` : ''} 个${nameText}${levelText}${volumeText}，强化 ${variants.map(v => `+${v}`).join('/')}`;
        if (body) body.innerHTML = `<div style="padding:18px;text-align:center;color:rgba(230,238,255,.62);">加载中...</div>`;
        try {
            const rows = [];
            const batchSize = 20;
            for (let i = 0; i < hrids.length; i += batchSize) {
                const batch = hrids.slice(i, i + batchSize);
                if (status) status.textContent = `加载 ${Math.min(i + batch.length, hrids.length)} / ${hrids.length}`;
                const data = await fetchMarketHistories(batch, variants, 7, { ...options, signal: abortController.signal });
                if (runSeq !== mooncakeMarketHistoryRankingSeq) return;
                for (const itemHrid of batch) {
                    const detail = mooncakeGetItemDetailOfHrid(itemHrid);
                    for (const variant of variants) {
                        const windows = data?.[itemHrid]?.[String(variant)] || {};
                        const avgHourly1Result = mooncakeCalcHourlyWageResultByPrice(itemHrid, variant, windows[1]?.avgPrice || 0, marketData);
                        const avgHourly3Result = mooncakeCalcHourlyWageResultByPrice(itemHrid, variant, windows[3]?.avgPrice || 0, marketData);
                        const avgHourly7Result = mooncakeCalcHourlyWageResultByPrice(itemHrid, variant, windows[7]?.avgPrice || 0, marketData);
                        rows.push({
                            itemHrid,
                            name: getItemName(itemHrid),
                            itemLevel: Number(detail?.itemLevel || 0),
                            variant,
                            volume1: windows[1]?.volume || 0,
                            avg1: windows[1]?.avgPrice || 0,
                            avgHourly1: avgHourly1Result?.hourlyWage ?? null,
                            avgHourly1Color: avgHourly1Result?.evaluation?.combinedColor || null,
                            turnover1: windows[1]?.turnover || 0,
                            volume3: windows[3]?.volume || 0,
                            avg3: windows[3]?.avgPrice || 0,
                            avgHourly3: avgHourly3Result?.hourlyWage ?? null,
                            avgHourly3Color: avgHourly3Result?.evaluation?.combinedColor || null,
                            turnover3: windows[3]?.turnover || 0,
                            volume7: windows[7]?.volume || 0,
                            turnover7: windows[7]?.turnover || 0,
                            avg7: windows[7]?.avgPrice || 0,
                            avgHourly7: avgHourly7Result?.hourlyWage ?? null,
                            avgHourly7Color: avgHourly7Result?.evaluation?.combinedColor || null
                        });
                    }
                }
            }
            const key = ['currentHourly', 'opportunity'].includes(mooncakeMarketHistoryRankingSort) ? 'turnover7' : mooncakeMarketHistoryRankingSort;
            const sortValue = (row, sortKey) => {
                const value = Number(row[sortKey]);
                return Number.isFinite(value) ? value : -Infinity;
            };
            rows.sort((a, b) => {
                if (key === 'name') return a.name.localeCompare(b.name) || (Number(b.variant) || 0) - (Number(a.variant) || 0);
                return sortValue(b, key) - sortValue(a, key);
            });
            const visibleRows = rows
                .filter(row => (row.volume7 > 0 || row.turnover7 > 0) && Number(row.volume7 || 0) >= minVolume)
                .slice(0, 120);
            if (body) {
                body.innerHTML = mooncakeRenderRankingRows(visibleRows);
                mooncakeHydrateRankingIcons(body);
            }
            if (status) status.textContent = `完成，显示 ${visibleRows.length} 条`;
        } catch (err) {
            if (runSeq !== mooncakeMarketHistoryRankingSeq || err?.name === 'AbortError') return;
            console.warn('[MoonCake] 排行榜加载失败:', err);
            if (body) body.innerHTML = `<div style="padding:18px;text-align:center;color:#FF8A8A;">加载失败</div>`;
            if (status) status.textContent = '加载失败';
        }
    }

    function mooncakeGetBargainPreferences() {
        try {
            const parsed = JSON.parse(localStorage.getItem(MOONCAKE_MARKET_BARGAIN_PREFS_KEY) || '{}');
            return { nameQuery: typeof parsed.nameQuery === 'string' ? parsed.nameQuery : '' };
        } catch (_) {
            return { nameQuery: '' };
        }
    }

    function mooncakeWriteBargainPreferences(changes = {}) {
        try {
            localStorage.setItem(MOONCAKE_MARKET_BARGAIN_PREFS_KEY, JSON.stringify({
                ...mooncakeGetBargainPreferences(),
                ...changes
            }));
        } catch (_) {}
    }

    function mooncakeBuildBargainRecipeIndex() {
        const initData = getInitClientData();
        const actionDetailMap = initData?.actionDetailMap;
        const shopItemDetailMap = initData?.shopItemDetailMap;
        if (!actionDetailMap) return null;
        if (mooncakeBargainRecipeIndex?.actionDetailMap === actionDetailMap &&
            mooncakeBargainRecipeIndex?.shopItemDetailMap === shopItemDetailMap) {
            return mooncakeBargainRecipeIndex;
        }

        const recipesByOutput = new Map();
        const addRecipe = (outputHrid, recipe) => {
            if (!outputHrid || !recipe?.inputs?.length) return;
            if (!recipesByOutput.has(outputHrid)) recipesByOutput.set(outputHrid, []);
            recipesByOutput.get(outputHrid).push(recipe);
        };
        const addInput = (inputs, itemHrid, count, teaDiscountable) => {
            const quantity = Number(count);
            if (!itemHrid || !(quantity > 0)) return;
            inputs.push({ itemHrid, count: quantity, teaDiscountable: !!teaDiscountable });
        };

        for (const [actionHrid, actionDetail] of Object.entries(actionDetailMap)) {
            if (!Array.isArray(actionDetail?.outputItems)) continue;
            const inputs = [];
            if (actionDetail.upgradeItemHrid) addInput(inputs, actionDetail.upgradeItemHrid, 1, false);
            for (const input of actionDetail.inputItems || []) {
                addInput(inputs, input?.itemHrid, input?.count, true);
            }
            if (!inputs.length) continue;
            for (const output of actionDetail.outputItems) {
                const outputCount = Number(output?.count) || 1;
                if (!output?.itemHrid || !(outputCount > 0)) continue;
                addRecipe(output.itemHrid, {
                    kind: 'action',
                    actionHrid,
                    inputs,
                    outputCount
                });
            }
        }

        for (const [shopHrid, shopDetail] of Object.entries(shopItemDetailMap || {})) {
            const inferredItemHrid = String(shopHrid || '').startsWith('/shop_items/')
                ? `/items/${String(shopHrid).slice('/shop_items/'.length)}`
                : '';
            const outputHrid = String(shopDetail?.itemHrid || '').startsWith('/items/')
                ? shopDetail.itemHrid
                : inferredItemHrid;
            const inputs = [];
            for (const cost of shopDetail?.costs || []) {
                addInput(inputs, cost?.itemHrid, cost?.count, false);
            }
            if (!outputHrid || !inputs.length) continue;
            addRecipe(outputHrid, {
                kind: 'shop',
                shopHrid,
                inputs,
                outputCount: Math.max(1, Number(shopDetail?.outputCount) || 1)
            });
        }

        mooncakeBargainRecipeIndex = { actionDetailMap, shopItemDetailMap, recipesByOutput };
        return mooncakeBargainRecipeIndex;
    }

    function mooncakeGetBargainRecipes(itemHrid) {
        return mooncakeBuildBargainRecipeIndex()?.recipesByOutput?.get(itemHrid) || [];
    }

    function mooncakeGetBargainFixedMaterialPrice(itemHrid) {
        if (itemHrid === '/items/coin' || itemHrid === '/items/coins') return 1;
        if (typeof itemHrid === 'string' && itemHrid.startsWith('/items/trainee_') && itemHrid.endsWith('_charm')) {
            return 250000;
        }
        return 0;
    }

    function mooncakeGetBargainLiveBid(itemHrid, marketData) {
        const fixedPrice = mooncakeGetBargainFixedMaterialPrice(itemHrid);
        if (fixedPrice > 0) return fixedPrice;
        const bid = Number(marketData?.marketData?.[itemHrid]?.['0']?.b);
        return Number.isFinite(bid) && bid > 0 ? bid : 0;
    }

    function mooncakeGetBargainHistoryPrice(itemHrid) {
        const cached = mooncakeBargainHistoryPriceCache.get(itemHrid);
        if (!cached) return null;
        if (cached.expiresAt <= Date.now()) {
            mooncakeBargainHistoryPriceCache.delete(itemHrid);
            return null;
        }
        return cached;
    }

    function mooncakeSetBargainHistoryPrice(itemHrid, price) {
        if (!itemHrid) return;
        if (!mooncakeBargainHistoryPriceCache.has(itemHrid) &&
            mooncakeBargainHistoryPriceCache.size >= MOONCAKE_BARGAIN_HISTORY_PRICE_MAX_ENTRIES) {
            mooncakeBargainHistoryPriceCache.delete(mooncakeBargainHistoryPriceCache.keys().next().value);
        }
        const validPrice = Number(price);
        mooncakeBargainHistoryPriceCache.set(itemHrid, {
            price: Number.isFinite(validPrice) && validPrice > 0 ? validPrice : 0,
            expiresAt: Date.now() + MOONCAKE_MARKET_HISTORY_TTL
        });
    }

    async function mooncakeFetchBargainFallbackPrices(itemHrids, marketData, options = {}) {
        const uniqueHrids = [...new Set((itemHrids || []).filter(Boolean))];
        const missing = uniqueHrids.filter(itemHrid => {
            if (mooncakeGetBargainLiveBid(itemHrid, marketData) > 0) return false;
            return options.force || !mooncakeGetBargainHistoryPrice(itemHrid);
        });
        if (!missing.length) return { requested: 0, completed: 0, failed: 0 };

        const batchSize = 20;
        let completed = 0;
        let failed = 0;
        for (let offset = 0; offset < missing.length; offset += batchSize) {
            if (options.signal?.aborted) throw new DOMException('Aborted', 'AbortError');
            const batch = missing.slice(offset, offset + batchSize);
            options.onProgress?.(Math.min(offset + batch.length, missing.length), missing.length);
            try {
                const data = await fetchMarketHistories(batch, [0], 7, {
                    force: !!options.force,
                    signal: options.signal,
                    maxRetries: 1,
                    timeoutMs: 7000
                });
                for (const itemHrid of batch) {
                    const window3 = data?.[itemHrid]?.['0']?.[3];
                    const median = Number(window3?.medianPrice);
                    const average = Number(window3?.avgPrice);
                    const fallbackPrice = median > 0 ? median : average;
                    if (fallbackPrice > 0 || !(mooncakeBargainHistoryPriceCache.get(itemHrid)?.price > 0)) {
                        mooncakeSetBargainHistoryPrice(itemHrid, fallbackPrice);
                    }
                }
                completed += batch.length;
            } catch (error) {
                if (error?.name === 'AbortError') throw error;
                failed += batch.length;
                console.warn('[MoonCake] 捡漏材料历史价格获取失败:', error);
                batch.forEach(itemHrid => {
                    if (!(mooncakeBargainHistoryPriceCache.get(itemHrid)?.price > 0)) {
                        mooncakeSetBargainHistoryPrice(itemHrid, 0);
                    }
                });
            }
        }
        return { requested: missing.length, completed, failed };
    }

    function mooncakeResolveBargainMaterialPrice(itemHrid, marketData) {
        const liveBid = mooncakeGetBargainLiveBid(itemHrid, marketData);
        if (liveBid > 0) return liveBid;
        return mooncakeGetBargainHistoryPrice(itemHrid)?.price || 0;
    }

    function mooncakeGetBargainArtisanMultiplier() {
        return mooncakeGetArtisanMaterialMultiplier();
    }

    function mooncakeCalculateBargainRecipeCost(recipe, marketData) {
        if (!recipe?.inputs?.length) return null;
        const artisanMultiplier = recipe.kind === 'action' ? mooncakeGetBargainArtisanMultiplier() : 1;
        let totalCost = 0;
        for (const input of recipe.inputs) {
            const price = mooncakeResolveBargainMaterialPrice(input.itemHrid, marketData);
            if (!(price > 0)) return null;
            const count = Number(input.count) * (input.teaDiscountable ? artisanMultiplier : 1);
            if (!(count >= 0)) return null;
            totalCost += price * count;
        }
        const outputCount = Number(recipe.outputCount) || 1;
        return outputCount > 0 ? totalCost / outputCount : null;
    }

    function mooncakeFindLowestBargainCraftCost(itemHrid, marketData, recipes = mooncakeGetBargainRecipes(itemHrid)) {
        let best = null;
        for (const recipe of recipes) {
            const cost = mooncakeCalculateBargainRecipeCost(recipe, marketData);
            if (!(cost > 0) || (best && cost >= best.cost)) continue;
            best = { cost, recipe };
        }
        return best;
    }

    function mooncakeBuildBargainEnhancementRouteCandidates(itemHrid, targetLevel, marketData, state = null) {
        const routeState = state || { candidates: new Map(), baseCosts: new Map() };
        const cacheKey = `${itemHrid}|${targetLevel}`;
        if (routeState.candidates.has(cacheKey)) return routeState.candidates.get(cacheKey);

        const getBaseCraftCost = hrid => {
            if (routeState.baseCosts.has(hrid)) return routeState.baseCosts.get(hrid);
            const result = mooncakeFindLowestBargainCraftCost(hrid, marketData);
            const cost = result?.cost || 0;
            routeState.baseCosts.set(hrid, cost);
            return cost;
        };
        const resolveMirrorUnitCost = () => {
            const marketAsk = Number(marketData?.marketData?.[MOONCAKE_PHILOSOPHERS_MIRROR_HRID]?.['0']?.a);
            const craftCost = getBaseCraftCost(MOONCAKE_PHILOSOPHERS_MIRROR_HRID);
            const choices = [];
            if (marketAsk > 0) choices.push({ unitCost: marketAsk, source: 'market' });
            if (craftCost > 0) choices.push({ unitCost: craftCost, source: 'craft' });
            if (!choices.length) return null;
            choices.sort((a, b) => a.unitCost - b.unitCost || a.source.localeCompare(b.source));
            return { ...choices[0], marketAsk: marketAsk > 0 ? marketAsk : 0, craftCost: craftCost > 0 ? craftCost : 0 };
        };
        const candidates = mooncakeBuildEnhancementRouteCandidates(itemHrid, targetLevel, marketData, {
            buildCostContext: (hrid, sourceMarketData) => mooncakeBuildEnhancementCostContext(hrid, sourceMarketData, {
                resolveMaterialPrice: mooncakeResolveBargainMaterialPrice,
                resolveProtectionPrice: mooncakeResolveBargainMaterialPrice,
                resolveBaseItemPrice: candidateHrid => getBaseCraftCost(candidateHrid)
            }),
            resolveMirrorUnitCost,
            resolveRefinementMaterialPrice: mooncakeResolveBargainMaterialPrice
        });
        routeState.candidates.set(cacheKey, candidates || null);
        return candidates;
    }

    function mooncakeFindLowestExpectedBargainEnhancementCost(itemHrid, targetLevel, marketData, state = null) {
        if (!(targetLevel > 0)) return null;
        const candidates = mooncakeBuildBargainEnhancementRouteCandidates(itemHrid, targetLevel, marketData, state);
        const route = mooncakeSelectEnhancementRoute(candidates, 0, 'minCost');
        if (!route) return null;
        return {
            ...route,
            protectCount: route.expectedProtects,
            protectionUnitCost: route.minProtectCost,
            expectedSeconds: route.totalTimeHours * 3600,
            enhancementCost: route.materialCost + route.protectCost + route.mirrorCost
        };
    }

    function mooncakeGetBargainSellVariants(itemHrid, marketData) {
        const marketRoot = marketData?.marketData?.[itemHrid];
        if (!marketRoot) return [];
        const variants = [];
        for (let level = 0; level <= 20; level++) {
            const ask = Number(marketRoot[String(level)]?.a);
            if (Number.isFinite(ask) && ask > 0) variants.push({ level, ask });
        }
        return variants;
    }

    function mooncakeCollectBargainMaterialHrids(candidates) {
        const hrids = new Set();
        for (const candidate of candidates) {
            const itemHrids = [candidate.itemHrid];
            if (String(candidate.itemHrid || '').endsWith('_refined')) {
                const relation = mooncakeGetRefinementActionForItem(candidate.itemHrid);
                if (relation?.refinedHrid === candidate.itemHrid && relation.baseHrid) itemHrids.push(relation.baseHrid);
            }
            for (const itemHrid of [...new Set(itemHrids)]) {
                const recipes = itemHrid === candidate.itemHrid ? candidate.recipes : mooncakeGetBargainRecipes(itemHrid);
                for (const recipe of recipes) {
                    recipe.inputs.forEach(input => {
                        if (input?.itemHrid) hrids.add(input.itemHrid);
                    });
                }
                for (const cost of getEnhancementCosts(itemHrid) || []) {
                    if (cost?.itemHrid) hrids.add(cost.itemHrid);
                }
                for (const protectHrid of getProtectionItems(itemHrid) || []) {
                    if (protectHrid) hrids.add(protectHrid);
                }
            }
        }
        for (const recipe of mooncakeGetBargainRecipes(MOONCAKE_PHILOSOPHERS_MIRROR_HRID)) {
            recipe.inputs.forEach(input => {
                if (input?.itemHrid) hrids.add(input.itemHrid);
            });
        }
        return [...hrids];
    }

    function mooncakeFormatBargainPrice(value, color = 'rgba(238,246,255,.9)') {
        if (!(Number(value) > 0)) return '<span style="color:rgba(230,238,255,.38);">-</span>';
        return `<span style="color:${color};font-weight:800;white-space:nowrap;">${mooncakeFormatMarketPrice(value)}</span>`;
    }

    function mooncakeFormatBargainHourly(value) {
        if (!Number.isFinite(Number(value))) return '<span style="color:rgba(230,238,255,.38);">-</span>';
        return `<span style="color:#FF9A9A;font-weight:800;font-variant-numeric:tabular-nums;white-space:nowrap;">${mooncakeFormatSignedHourlyWage(value)}/h</span>`;
    }

    function mooncakeBuildBargainHeader() {
        const columns = MOONCAKE_BARGAIN_GRID_COLUMNS;
        return `<div style="display:grid;grid-template-columns:${columns};min-width:${MOONCAKE_BARGAIN_MIN_WIDTH};gap:7px;position:sticky;top:0;z-index:1;background:rgba(18,22,34,.98);padding:8px 0 7px;border-bottom:1px solid rgba(255,255,255,.08);color:rgba(230,238,255,.72);font-size:11px;font-weight:900;text-align:center;">
            <div style="text-align:left;">装备</div>
            <div>当前售价</div>
            <div>期望总成本</div>
            <div>便宜多少</div>
            <div>等效负工时费</div>
            <div>最优保护</div>
            <div>材料费用</div>
            <div>强化费用</div>
        </div>`;
    }

    function mooncakeRenderBargainRows(rows) {
        if (!rows.length) {
            return `${mooncakeBuildBargainHeader()}<div style="min-width:${MOONCAKE_BARGAIN_MIN_WIDTH};padding:18px;text-align:center;color:rgba(230,238,255,.62);">没有符合条件的装备</div>`;
        }
        const columns = MOONCAKE_BARGAIN_GRID_COLUMNS;
        return mooncakeBuildBargainHeader() + rows.map(row => {
            const displayName = `${getItemName(row.itemHrid)} +${row.level}`;
            const protectionLabel = row.routeType === 'philosophersMirror'
                ? `贤镜 +${row.mirrorStartLevel} 起`
                : (row.protectionItemHrid ? `+${row.protectAt}` : '-');
            const protectionTitle = row.routeType === 'philosophersMirror'
                ? `贤者之镜 × ${mooncakeFormatRefinementQuantity(row.mirrorCount)}，${row.mirrorSource === 'craft' ? '制作' : '市场'}单价 ${formatMoney(row.mirrorUnitCost)}`
                : (row.protectionItemHrid
                    ? `${getItemName(row.protectionItemHrid)} × ${mooncakeFormatRefinementQuantity(row.protectCount)}`
                    : '');
            const title = `制造材料 ${formatMoney(row.baseCost)}；强化材料 ${formatMoney(row.enhancementMaterialCost)}；保护费用 ${formatMoney(row.protectCost)}；贤镜费用 ${formatMoney(row.mirrorCost)}`;
            return `
                <div data-mooncake-bargain-row="${mooncakeEscapeHtml(row.itemHrid)}|${row.level}" style="display:grid;grid-template-columns:${columns};min-width:${MOONCAKE_BARGAIN_MIN_WIDTH};gap:7px;align-items:center;padding:8px 0;border-bottom:1px solid rgba(255,255,255,.045);">
                    <div style="display:flex;align-items:center;gap:6px;min-width:0;"><span data-icon="${mooncakeEscapeHtml(row.itemHrid)}"></span><button type="button" data-mooncake-bargain-jump="1" data-hrid="${mooncakeEscapeHtml(row.itemHrid)}" data-level="${row.level}" title="${mooncakeEscapeHtml(displayName)}" style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;border:0;background:transparent;color:#eef6ff;font:inherit;font-weight:800;padding:0;cursor:pointer;text-align:left;">${mooncakeEscapeHtml(displayName)}</button></div>
                    <div style="text-align:center;">${mooncakeFormatBargainPrice(row.ask)}</div>
                    <div style="text-align:center;" title="${mooncakeEscapeHtml(title)}">${mooncakeFormatBargainPrice(row.totalCost)}</div>
                    <div style="text-align:center;">${mooncakeFormatBargainPrice(row.cheapAmount, '#FFD27A')}</div>
                    <div style="text-align:center;">${mooncakeFormatBargainHourly(row.negativeHourly)}</div>
                    <div style="text-align:center;color:#C7D9FF;font-weight:800;white-space:nowrap;" title="${mooncakeEscapeHtml(protectionTitle)}">${protectionLabel}</div>
                    <div style="text-align:center;">${mooncakeFormatBargainPrice(row.baseCost, '#B9E6A3')}</div>
                    <div style="text-align:center;" title="${mooncakeEscapeHtml(`强化材料 ${formatMoney(row.enhancementMaterialCost)}；保护费用 ${formatMoney(row.protectCost)}；贤镜费用 ${formatMoney(row.mirrorCost)}`)}">${mooncakeFormatBargainPrice(row.enhancementCost, '#FFCC8A')}</div>
                </div>
            `;
        }).join('');
    }

    function mooncakeOpenMarketBargainPanel() {
        mooncakeMarketHistoryRankingSeq++;
        mooncakeMarketHistoryRankingAbortController?.abort();
        document.getElementById(MOONCAKE_MARKET_HISTORY_RANKING_ID)?.remove();
        document.getElementById(MOONCAKE_MARKET_SHORTAGE_ID)?.remove();
        let panel = document.getElementById(MOONCAKE_MARKET_BARGAIN_ID);
        if (!panel) {
            panel = document.createElement('div');
            panel.id = MOONCAKE_MARKET_BARGAIN_ID;
            document.body.appendChild(panel);
        }
        const preferences = mooncakeGetBargainPreferences();
        Object.assign(panel.style, {
            position: 'fixed',
            left: '50%',
            top: '50%',
            transform: 'translate(-50%, -50%)',
            width: 'min(1280px, calc(100vw - 16px))',
            maxHeight: 'min(720px, calc(100vh - 24px))',
            overflow: 'hidden',
            zIndex: '100000',
            boxSizing: 'border-box',
            border: '1px solid rgba(236,190,112,.38)',
            borderRadius: '12px',
            background: 'rgba(18,22,34,.98)',
            boxShadow: '0 16px 42px rgba(0,0,0,.55)',
            color: '#eef6ff',
            fontSize: '12px',
            display: 'flex',
            flexDirection: 'column'
        });
        panel.innerHTML = `
            <div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.08);">
                <div style="font-size:15px;font-weight:900;">捡漏统计</div>
                <button type="button" data-mooncake-history-rank-close="1" style="cursor:pointer;border:0;background:transparent;color:rgba(238,246,255,.72);font-size:18px;line-height:1;">×</button>
            </div>
            <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.08);">
                <label style="display:flex;align-items:center;gap:4px;color:rgba(230,238,255,.72);"><span>装备名称</span>
                    <input type="search" data-mooncake-bargain-item-name value="${mooncakeEscapeHtml(preferences.nameQuery)}" placeholder="输入名称" autocomplete="off" aria-label="装备名称" style="width:168px;background:rgba(255,255,255,.08);border:1px solid rgba(236,190,112,.3);border-radius:6px;color:#eef6ff;padding:4px 7px;box-sizing:border-box;">
                </label>
                <span style="color:rgba(230,238,255,.72);">装备等级 ${MOONCAKE_BARGAIN_ITEM_LEVEL}</span>
                <button type="button" data-mooncake-bargain-run="1" style="cursor:pointer;border:1px solid rgba(236,190,112,.4);background:rgba(105,77,38,.7);color:#fff0cf;border-radius:7px;padding:5px 10px;font-weight:800;">刷新</button>
                <span data-mooncake-bargain-status style="color:rgba(230,238,255,.58);font-size:11px;"></span>
            </div>
            <div data-mooncake-bargain-body style="overflow:auto;overscroll-behavior:contain;padding:0 12px 16px;"></div>
        `;
        mooncakeRunMarketBargainScan();
    }

    async function mooncakeRunMarketBargainScan(options = {}) {
        const panel = document.getElementById(MOONCAKE_MARKET_BARGAIN_ID);
        if (!panel) return;
        const runSeq = ++mooncakeMarketBargainSeq;
        if (mooncakeMarketBargainAbortController) mooncakeMarketBargainAbortController.abort();
        const abortController = new AbortController();
        mooncakeMarketBargainAbortController = abortController;
        const body = panel.querySelector('[data-mooncake-bargain-body]');
        const status = panel.querySelector('[data-mooncake-bargain-status]');
        const nameQuery = panel.querySelector('[data-mooncake-bargain-item-name]')?.value?.trim() || '';
        mooncakeWriteBargainPreferences({ nameQuery });
        const marketData = getMarketData();
        if (!marketData?.marketData) {
            if (body) body.innerHTML = '<div style="padding:18px;text-align:center;color:#FF8A8A;">市场数据未加载</div>';
            if (status) status.textContent = '市场数据未加载';
            if (mooncakeMarketBargainAbortController === abortController) mooncakeMarketBargainAbortController = null;
            return;
        }
        if (!mooncakeBuildBargainRecipeIndex()) {
            if (body) body.innerHTML = '<div style="padding:18px;text-align:center;color:#FF8A8A;">配方数据未加载</div>';
            if (status) status.textContent = '配方数据未加载';
            if (mooncakeMarketBargainAbortController === abortController) mooncakeMarketBargainAbortController = null;
            return;
        }
        if (body) body.innerHTML = '<div style="padding:18px;text-align:center;color:rgba(230,238,255,.62);">准备价格数据...</div>';

        try {
            const candidates = mooncakeFilterEquipmentHridsByName(
                mooncakeGetEnhanceableEquipmentHrids([MOONCAKE_BARGAIN_ITEM_LEVEL]),
                nameQuery
            ).map(itemHrid => ({
                itemHrid,
                recipes: mooncakeGetBargainRecipes(itemHrid),
                sellVariants: mooncakeGetBargainSellVariants(itemHrid, marketData)
            })).filter(candidate => candidate.recipes.length && candidate.sellVariants.length);

            const materialHrids = mooncakeCollectBargainMaterialHrids(candidates);
            if (status) status.textContent = `补充材料价格 0 / ${materialHrids.length}`;
            const historyResult = await mooncakeFetchBargainFallbackPrices(materialHrids, marketData, {
                force: !!options.force,
                signal: abortController.signal,
                onProgress: (done, total) => {
                    if (runSeq === mooncakeMarketBargainSeq && status) status.textContent = `补充材料价格 ${done} / ${total}`;
                }
            });
            if (runSeq !== mooncakeMarketBargainSeq || abortController.signal.aborted) return;

            const rows = [];
            const bargainRouteState = { candidates: new Map(), baseCosts: new Map() };
            for (let index = 0; index < candidates.length; index++) {
                if (runSeq !== mooncakeMarketBargainSeq || abortController.signal.aborted) return;
                const candidate = candidates[index];
                if (status) status.textContent = `计算 ${index + 1} / ${candidates.length}`;
                const base = mooncakeFindLowestBargainCraftCost(candidate.itemHrid, marketData, candidate.recipes);
                if (!base) continue;
                bargainRouteState.baseCosts.set(candidate.itemHrid, base.cost);

                const enhancementLevels = candidate.sellVariants.filter(variant => variant.level > 0).map(variant => variant.level);
                if (enhancementLevels.length) {
                    try {
                        const prewarmLevels = new Set(enhancementLevels);
                        if (enhancementLevels.some(level => level >= MOONCAKE_MIRROR_OUTPUT_MIN_LEVEL)) {
                            const maxLevel = Math.max(...enhancementLevels);
                            for (let level = 1; level <= maxLevel; level++) prewarmLevels.add(level);
                        }
                        const prewarmItemHrids = [candidate.itemHrid];
                        if (String(candidate.itemHrid || '').endsWith('_refined')) {
                            const relation = mooncakeGetRefinementActionForItem(candidate.itemHrid);
                            if (relation?.refinedHrid === candidate.itemHrid && relation.baseHrid) {
                                prewarmItemHrids.push(relation.baseHrid);
                            }
                        }
                        for (const prewarmItemHrid of [...new Set(prewarmItemHrids)]) {
                            await prewarmEnhancelateLevels(prewarmItemHrid, [...prewarmLevels], { includeExact: true });
                            if (runSeq !== mooncakeMarketBargainSeq || abortController.signal.aborted) return;
                        }
                    } catch (_) {}
                    if (runSeq !== mooncakeMarketBargainSeq || abortController.signal.aborted) return;
                }

                const strategyByLevel = new Map();
                for (const variant of candidate.sellVariants) {
                    const strategy = variant.level > 0
                        ? (strategyByLevel.get(variant.level) || mooncakeFindLowestExpectedBargainEnhancementCost(candidate.itemHrid, variant.level, marketData, bargainRouteState))
                        : {
                            routeType: 'traditional',
                            baseItemCost: base.cost,
                            materialCost: 0,
                            protectCost: 0,
                            mirrorCost: 0,
                            mirrorCount: 0,
                            totalCost: base.cost,
                            expectedSeconds: 0,
                            protectAt: null,
                            protectionItemHrid: null,
                            protectCount: 0
                        };
                    if (variant.level > 0) strategyByLevel.set(variant.level, strategy);
                    if (variant.level > 0 && !strategy) continue;
                    const enhancementCost = strategy?.enhancementCost ?? ((strategy?.materialCost || 0) + (strategy?.protectCost || 0) + (strategy?.mirrorCost || 0));
                    const totalCost = strategy?.totalCost || 0;
                    if (!(totalCost > 0) || !(variant.ask < totalCost * 0.9)) continue;
                    const cheapAmount = totalCost - variant.ask;
                    const negativeHourly = strategy?.expectedSeconds > 0
                        ? (variant.ask * MOONCAKE_MARKET_SELL_NET_FACTOR - totalCost) / (strategy.expectedSeconds / 3600)
                        : null;
                    rows.push({
                        itemHrid: candidate.itemHrid,
                        level: variant.level,
                        ask: variant.ask,
                        baseCost: strategy?.baseItemCost || 0,
                        totalCost,
                        cheapAmount,
                        negativeHourly,
                        protectAt: strategy?.protectAt ?? null,
                        protectionItemHrid: strategy?.protectionItemHrid || null,
                        protectCount: strategy?.protectCount || 0,
                        protectCost: strategy?.protectCost || 0,
                        enhancementMaterialCost: strategy?.materialCost || 0,
                        enhancementCost,
                        routeType: strategy?.routeType || 'traditional',
                        mirrorStartLevel: strategy?.mirrorStartLevel ?? null,
                        mirrorCount: strategy?.mirrorCount || 0,
                        mirrorUnitCost: strategy?.mirrorUnitCost || 0,
                        mirrorCost: strategy?.mirrorCost || 0,
                        mirrorSource: strategy?.mirrorSource || null
                    });
                }
                if (index % 2 === 1) await new Promise(resolve => setTimeout(resolve, 0));
            }
            rows.sort((a, b) => b.cheapAmount - a.cheapAmount || b.level - a.level || getItemName(a.itemHrid).localeCompare(getItemName(b.itemHrid)));
            if (body) {
                body.innerHTML = mooncakeRenderBargainRows(rows);
                mooncakeHydrateRankingIcons(body);
            }
            if (status) status.textContent = `完成，显示 ${rows.length} 条${historyResult.failed ? `，${historyResult.failed} 项材料历史价不可用` : ''}`;
        } catch (error) {
            if (runSeq !== mooncakeMarketBargainSeq || error?.name === 'AbortError') return;
            console.warn('[MoonCake] 捡漏统计加载失败:', error);
            if (body) body.innerHTML = '<div style="padding:18px;text-align:center;color:#FF8A8A;">加载失败</div>';
            if (status) status.textContent = '加载失败';
        } finally {
            if (mooncakeMarketBargainAbortController === abortController) {
                mooncakeMarketBargainAbortController = null;
            }
        }
    }

    function mooncakeGetOpenMarketStatisticsPanel() {
        return document.getElementById(MOONCAKE_MARKET_HISTORY_RANKING_ID) ||
            document.getElementById(MOONCAKE_MARKET_SHORTAGE_ID) ||
            document.getElementById(MOONCAKE_MARKET_BARGAIN_ID);
    }

    function mooncakeCloseMarketStatisticsPanels() {
        mooncakeMarketHistoryRankingSeq++;
        mooncakeMarketBargainSeq++;
        mooncakeMarketHistoryRankingAbortController?.abort();
        mooncakeMarketBargainAbortController?.abort();
        [MOONCAKE_MARKET_HISTORY_RANKING_ID, MOONCAKE_MARKET_SHORTAGE_ID, MOONCAKE_MARKET_BARGAIN_ID]
            .forEach(id => document.getElementById(id)?.remove());
    }

    function mooncakeIsCurrentMarketItemDetailNode(node) {
        if (!node || !(node instanceof Element) || !node.isConnected || !mooncakeIsVisibleElement(node)) return false;
        const panel = node.closest('[class*="MarketplacePanel_marketplacePanel"], [class*="MarketplacePanel"]');
        if (!panel || !mooncakeIsVisibleElement(panel)) return false;
        if (node.closest('tr, [class*="MarketplacePanel_itemSummaryTable"], [class*="MarketplacePanel_orderBooksContainer"]')) return false;
        const hrid = extractItemHridFromElement(node);
        if (!hrid) return false;
        const rect = node.getBoundingClientRect();
        const panelRect = panel.getBoundingClientRect();
        if (rect.width <= 0 || rect.height <= 0 || panelRect.width <= 0 || panelRect.height <= 0) return false;
        if (rect.bottom < panelRect.top || rect.top > panelRect.bottom || rect.right < panelRect.left || rect.left > panelRect.right) return false;
        return true;
    }

    function mooncakeFindCurrentMarketItemNode() {
        const selectors = '.MarketplacePanel_currentItem__3ercC, [class*="MarketplacePanel_currentItem"]';
        const candidates = Array.from(document.querySelectorAll(selectors));
        return candidates.find(mooncakeIsCurrentMarketItemDetailNode) || null;
    }

    function mooncakeParseItemHridFromPanel(currentItemNode = null) {
        currentItemNode = currentItemNode || mooncakeFindCurrentMarketItemNode();
        if (!currentItemNode) return null;
        return extractItemHridFromElement(currentItemNode);
    }

    function mooncakeShouldShowMarketJumpHelpers(currentItem) {
        return mooncakeIsCurrentMarketItemDetailNode(currentItem) && !!extractItemHridFromElement(currentItem);
    }

    function mooncakeParseEnhanceLevelFromPanel() {
        const currentItemNode = mooncakeFindCurrentMarketItemNode();
        if (!currentItemNode) return null;
        const levelEl = currentItemNode.querySelector('[class*="Item_enhancementLevel"], [class*="enhancementLevel"]');
        if (levelEl?.textContent) {
            const match = levelEl.textContent.match(/\+?(\d{1,2})/);
            if (match?.[1]) return parseInt(match[1], 10) || 0;
        }
        return extractEnhancementLevelFromElement(currentItemNode) || 0;
    }

    function mooncakeGetCurrentMarketEnhanceLevel(defaultLevel = 0) {
        const panelLevel = mooncakeParseEnhanceLevelFromPanel();
        if (Number.isFinite(panelLevel)) return panelLevel;
        const cachedLevel = currentMarketItem?.enhancementLevel;
        if (Number.isFinite(Number(cachedLevel))) return parseInt(cachedLevel, 10) || 0;
        return defaultLevel;
    }

    function mooncakeIsEnhanceableItem(hrid) {
        const detail = mooncakeGetItemDetailOfHrid(hrid);
        return Array.isArray(detail?.enhancementCosts) && detail.enhancementCosts.length > 0;
    }

    function mooncakeFindGameStateNode() {
        const selectors = [
            '[class^="GamePage"]',
            '[class*="GamePage_gamePage"]',
            '[class*="GamePage"]'
        ];
        for (const selector of selectors) {
            const el = document.querySelector(selector);
            if (!el) continue;
            const key = mooncakeGetFiberKey(el);
            if (!key) continue;
            let fiber = el[key];
            let fallback = null;
            while (fiber) {
                const node = fiber.stateNode;
                if (node) {
                    if (typeof node.handleGoToMarketplace === 'function' ||
                        typeof node.goToMarketplace === 'function' ||
                        typeof node.openMarketplace === 'function' ||
                        typeof node.handleOpenMarketplace === 'function') {
                        return node;
                    }
                    if (!fallback && node.state?.navTarget !== undefined) fallback = node;
                }
                fiber = fiber.return;
            }
            if (fallback) return fallback;
        }
        try {
            const host = window.mwi?.game || window.PGE?.core;
            if (host) return host;
        } catch (_) {}
        return null;
    }

    function mooncakeOpenMarketplaceByCore(hrid, enhanceLevel) {
        const host = mooncakeFindGameStateNode();
        if (!host) return false;
        const fn = host.handleGoToMarketplace ||
                   host.goToMarketplace ||
                   host.openMarketplace ||
                   host.handleOpenMarketplace;
        if (typeof fn !== 'function') return false;
        const level = Number.isFinite(Number(enhanceLevel)) ? parseInt(enhanceLevel, 10) : 0;
        const argLists = [
            [hrid, level],
            [{ itemHrid: hrid, enhancementLevel: level }],
            [hrid]
        ];
        for (const args of argLists) {
            try {
                fn.call(host, ...args);
                return true;
            } catch (_) {}
        }
        return false;
    }

    function mooncakeIsVisibleElement(el) {
        if (!el || !(el instanceof Element) || !el.isConnected) return false;
        for (let node = el; node instanceof Element; node = node.parentElement) {
            const style = getComputedStyle(node);
            if (style.display === 'none' || style.visibility === 'hidden' || style.opacity === '0') return false;
        }
        return true;
    }

    function mooncakeFindVisibleItemNodeByHrid(hrid) {
        const id = String(hrid || '').replace(/^\/items\//, '');
        if (!id) return null;
        const nodes = document.querySelectorAll('[class*="Item_item"], [class*="Item_itemContainer"]');
        for (const node of nodes) {
            if (!mooncakeIsVisibleElement(node)) continue;
            const use = node.querySelector('use');
            const href = use?.href?.baseVal || use?.getAttribute?.('href') || '';
            if (href.includes(`#${id}`) || href.includes(`/items/${id}`) || href.endsWith(id)) return node;
        }
        return null;
    }

    function mooncakeSafeText(value, maxLen = 120) {
        const text = String(value == null ? '' : value);
        return text.length > maxLen ? text.slice(0, maxLen) : text;
    }

    async function mooncakeOpenMarketplaceByVisibleMenu(hrid) {
        const visibleItemNode = mooncakeFindVisibleItemNodeByHrid(hrid);
        const currentItemNode = mooncakeFindCurrentMarketItemNode();
        const itemNode = visibleItemNode || (mooncakeParseItemHridFromPanel() === hrid ? currentItemNode : null);
        if (!itemNode) return false;
        try {
            itemNode.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
        } catch (_) {
            return false;
        }

        let menu = null;
        for (let i = 0; i < 10; i++) {
            menu = [...document.querySelectorAll('[class*="Item_actionMenu"], [class*="Item_contextMenu"]')]
                .find(mooncakeIsVisibleElement) || null;
            if (menu) break;
            await new Promise(resolve => setTimeout(resolve, 50));
        }
        if (!menu) return false;

        const buttons = [...menu.querySelectorAll('button, [role="button"]')];
        const marketBtn = buttons.find(btn => /前往市场|市场|market/i.test(mooncakeSafeText(btn.textContent, 80)));
        if (!marketBtn) return false;
        try {
            marketBtn.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
            return true;
        } catch (_) {
            return false;
        }
    }

    async function mooncakeOpenMarketplaceForHrid(hrid, enhanceLevel = 0) {
        if (!hrid) return false;
        const level = Number.isFinite(Number(enhanceLevel)) ? parseInt(enhanceLevel, 10) : 0;
        const opened = mooncakeOpenMarketplaceByCore(hrid, level) ||
                       await mooncakeOpenMarketplaceByVisibleMenu(hrid);
        if (opened) {
            currentMarketItem = { itemHrid: hrid, enhancementLevel: level };
            userSelectedEnhancement = level > 0;
            const marketData = getMarketData();
            const row = marketData?.marketData?.[hrid]?.[String(level)];
            updateEnhancementTabContent(hrid, level, row?.b ?? -1, row?.a ?? -1, null);
            setTimeout(ensureMooncakeMarketJumpHelpers, 300);
        }
        return opened;
    }

    function mooncakeFindMarketplacePanelStateNode() {
        const panels = document.querySelectorAll('[class*="MarketplacePanel_marketplacePanel"], [class*="MarketplacePanel"]');
        for (const element of panels) {
            if (!mooncakeIsVisibleElement(element)) continue;
            const fiberKey = mooncakeGetFiberKey(element);
            if (!fiberKey) continue;
            let fiber = element[fiberKey];
            while (fiber) {
                const node = fiber.stateNode;
                if (typeof node?.handleViewItemSummary === 'function' &&
                    typeof node?.handleViewOrderBook === 'function') {
                    return node;
                }
                fiber = fiber.return;
            }
        }
        return null;
    }

    async function mooncakeOpenMarketplaceAllLevelsForHrid(hrid) {
        if (!hrid || !mooncakeIsEnhanceableItem(hrid)) return false;
        const marketPanel = mooncakeFindMarketplacePanelStateNode();
        if (marketPanel) {
            try {
                marketPanel.handleViewItemSummary(hrid);
                currentMarketItem = { itemHrid: hrid, enhancementLevel: 0 };
                userSelectedEnhancement = false;
                const marketData = getMarketData();
                const row = marketData?.marketData?.[hrid]?.['0'];
                updateEnhancementTabContent(hrid, 0, row?.b ?? -1, row?.a ?? -1, null);
                setTimeout(ensureMooncakeMarketJumpHelpers, 0);
                return true;
            } catch (error) {
                console.warn('[MoonCake] 直接跳转全部强化等级失败:', error);
            }
        }

        const opened = await mooncakeOpenMarketplaceForHrid(hrid, 0);
        if (!opened) return false;
        return mooncakeClickAllLevelsButton(hrid);
    }

    function mooncakeGetItemHridFromContainer(container) {
        const use = container?.querySelector?.('svg use');
        const href = use?.href?.baseVal || use?.getAttribute?.('href') || use?.getAttribute?.('xlink:href') || '';
        const hashIndex = href.lastIndexOf('#');
        if (hashIndex >= 0 && hashIndex < href.length - 1) {
            return `/items/${href.slice(hashIndex + 1)}`;
        }
        const match = String(href).match(/\/items\/([^/?#]+)$/);
        return match ? `/items/${match[1]}` : null;
    }

    function mooncakeGetItemEnhancementLevelFromContainer(container) {
        const levelText = container?.querySelector?.('[class*="Item_enhancementLevel"]')?.textContent || '';
        const match = levelText.match(/\+?(\d+)/);
        return match ? Math.max(0, parseInt(match[1], 10) || 0) : 0;
    }

    function mooncakeCanOpenMarketplaceForInventoryItem(itemHrid) {
        const itemDetail = mooncakeEnsureItemDetailMap()?.[itemHrid];
        if (!itemDetail) return true;
        if (itemDetail.isTradable === false) return false;
        return ![
            '/item_categories/loot',
            '/item_categories/currency',
            '/item_categories/scroll'
        ].includes(itemDetail.categoryHrid);
    }

    function hookMooncakeInventoryRightClickMarket() {
        if (window.__mooncakeInventoryRightClickMarketBound) return;
        window.__mooncakeInventoryRightClickMarketBound = true;

        // 捕获阶段的事件委托能覆盖 React 重绘后的背包格子，也不会作用到市场、掉落记录等其他物品节点。
        document.addEventListener('contextmenu', event => {
            if (mooncakeWarehouseHasSunnyConflict()) return;
            const target = event.target;
            const container = target?.closest?.('[class*="Item_itemContainer"]');
            if (!container || !container.closest('[class*="Inventory_items"]')) return;

            const itemHrid = mooncakeGetItemHridFromContainer(container);
            if (!itemHrid || !mooncakeCanOpenMarketplaceForInventoryItem(itemHrid)) return;

            const enhancementLevel = mooncakeGetItemEnhancementLevelFromContainer(container);
            const shouldReportMarketVisit = event.isTrusted;
            event.preventDefault();
            event.stopPropagation();
            mooncakeOpenMarketplaceForHrid(itemHrid, enhancementLevel)
                .then(opened => {
                    if (opened && shouldReportMarketVisit) {
                        setTimeout(() => mooncakeQueueQ7MarketReport(itemHrid, enhancementLevel), 350);
                    }
                })
                .catch(error => {
                    console.warn('[MoonCake] 右键跳转市场失败:', error);
                });
        }, true);
    }

    // ======================
    // 背包分区：持久分类 + 强化材料投影 + 当前强化队列
    // ======================
