    const MOONCAKE_WAREHOUSE_SYSTEM_SECTIONS = new Set([
        MOONCAKE_WAREHOUSE_SECTION_QUEUE,
        MOONCAKE_WAREHOUSE_SECTION_ENHANCE,
        MOONCAKE_WAREHOUSE_SECTION_MATERIALS
    ]);
    // 可参与自定义排序的系统仓库（当前强化队列始终固定在顶部）。
    const MOONCAKE_WAREHOUSE_SORTABLE_SYSTEM_SECTIONS = [
        MOONCAKE_WAREHOUSE_SECTION_ENHANCE,
        MOONCAKE_WAREHOUSE_SECTION_MATERIALS
    ];
    const MOONCAKE_WAREHOUSE_PANEL_ATTR = 'data-mooncake-warehouse-panel';
    const MOONCAKE_WAREHOUSE_PINNED_ATTR = 'data-mooncake-warehouse-pinned';
    const MOONCAKE_WAREHOUSE_ROLE_ATTR = 'data-mooncake-warehouse-role';
    const MOONCAKE_WAREHOUSE_MENU_ATTR = 'data-mooncake-warehouse-menu-action';
    const MOONCAKE_WAREHOUSE_UI_ATTR = 'data-mooncake-inventory-zone-ui';
    const MOONCAKE_WAREHOUSE_CUSTOM_ID_RE = /^custom:[A-Za-z0-9_-]{1,80}$/;
    const MOONCAKE_WAREHOUSE_STYLE_PROPS = [
        'position', 'left', 'top', 'z-index', 'margin', 'width', 'height',
        'pointer-events', 'transform', 'transition', 'visibility'
    ];
    const MOONCAKE_WAREHOUSE_ROOT_STYLE_PROPS = ['position', 'padding-top'];

    let mooncakeWarehouseState = null;
    let mooncakeWarehouseLoadedCharacterId = null;
    let mooncakeWarehouseRenderTimer = 0;
    let mooncakeWarehouseRenderFrame = 0;
    let mooncakeWarehouseInventoryRoot = null;
    let mooncakeWarehouseRootStyleSnapshot = null;
    let mooncakeWarehousePinnedNodes = new Set();
    const mooncakeWarehouseNodeStyleSnapshots = new WeakMap();
    let mooncakeWarehouseMutationUnsubscribe = null;
    let mooncakeWarehouseMenuTarget = null;
    let mooncakeWarehouseMenuSequence = 0;
    let mooncakeWarehouseResizeObserver = null;
    let mooncakeWarehouseVisibilityObserver = null;
    let mooncakeWarehouseObservedRoot = null;
    let mooncakeWarehouseObservedWidth = null;
    let mooncakeWarehouseObservedRootVisible = false;
    let mooncakeWarehouseSunnyConflictNotified = false;
    let mooncakeWarehouseActiveDialogClose = null;
    let mooncakeWarehouseDialogSequence = 0;
    let mooncakeWarehousePanel = null;
    let mooncakeWarehousePanelSignature = '';
    let mooncakeWarehouseProjectionSignature = '';
    let mooncakeWarehouseLayoutSignature = '';
    let mooncakeWarehouseLayoutMetrics = null;
    let mooncakeWarehousePendingVisibleRender = false;
    let mooncakeWarehouseGeometryDirty = true;

