    function mooncakeWarehouseFormatText(key, values = {}) {
        return mooncakeWarehouseText(key).replace(/\{([^}]+)\}/g, (_, name) => String(values[name] ?? ''));
    }

    function mooncakeWarehouseNormalizeItemHrid(value) {
        const hrid = String(value || '').trim();
        return /^\/items\/[^\s/+]+$/i.test(hrid) ? hrid : null;
    }

    function mooncakeWarehouseNormalizeLevel(value) {
        const numeric = Number(value);
        return Number.isFinite(numeric) ? Math.max(0, Math.min(20, Math.trunc(numeric))) : 0;
    }

    function mooncakeWarehouseIdentityKey(itemHrid, enhancementLevel = 0) {
        return `${itemHrid}\u0001${mooncakeWarehouseNormalizeLevel(enhancementLevel)}`;
    }

    function mooncakeWarehouseDefaultState() {
        return {
            version: MOONCAKE_WAREHOUSE_VERSION,
            updatedAt: 0,
            categories: [],
            memberships: [],
            sectionCollapsed: {},
            hiddenSections: {},
            sectionOrder: []
        };
    }

    function mooncakeWarehouseStorageKey(characterId = mooncakeCharacterId) {
        const id = characterId == null ? '' : String(characterId).trim();
        return id ? `${MOONCAKE_WAREHOUSE_STORAGE_PREFIX}${id}` : null;
    }

    function mooncakeWarehouseCreateCategoryId() {
        const suffix = typeof crypto?.randomUUID === 'function'
            ? crypto.randomUUID().replace(/-/g, '')
            : `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 10)}`;
        return `custom:${suffix}`;
    }

    function mooncakeWarehouseNormalizeState(raw) {
        const base = mooncakeWarehouseDefaultState();
        if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return base;
        const categories = [];
        const categoryIds = new Set();
        const categoryNames = new Set();
        for (const input of Array.isArray(raw.categories) ? raw.categories : []) {
            const id = typeof input?.id === 'string' ? input.id : '';
            const name = String(input?.name || '').trim().replace(/\s+/g, ' ').slice(0, 24);
            const nameKey = name.toLocaleLowerCase();
            if (!MOONCAKE_WAREHOUSE_CUSTOM_ID_RE.test(id) || !name || categoryIds.has(id) || categoryNames.has(nameKey)) continue;
            categoryIds.add(id);
            categoryNames.add(nameKey);
            categories.push({
                id,
                name,
                order: Number.isFinite(Number(input?.order)) ? Math.max(0, Math.trunc(Number(input.order))) : categories.length,
                collapsed: input?.collapsed === true,
                createdAt: Number.isFinite(Number(input?.createdAt)) ? Math.max(0, Number(input.createdAt)) : 0,
                updatedAt: Number.isFinite(Number(input?.updatedAt)) ? Math.max(0, Number(input.updatedAt)) : 0
            });
        }
        categories.sort((a, b) => a.order - b.order || a.createdAt - b.createdAt || a.name.localeCompare(b.name));

        const memberships = [];
        const membershipKeys = new Set();
        for (const input of Array.isArray(raw.memberships) ? raw.memberships : []) {
            const itemHrid = mooncakeWarehouseNormalizeItemHrid(input?.itemHrid);
            const levelMode = input?.levelMode === 'exact' ? 'exact' : 'all';
            const categoryId = input?.categoryId === MOONCAKE_WAREHOUSE_SECTION_ENHANCE
                ? MOONCAKE_WAREHOUSE_SECTION_ENHANCE
                : (input?.categoryId === MOONCAKE_WAREHOUSE_SECTION_UNCLASSIFIED && levelMode === 'exact'
                    ? MOONCAKE_WAREHOUSE_SECTION_UNCLASSIFIED
                    : (typeof input?.categoryId === 'string' && categoryIds.has(input.categoryId) ? input.categoryId : null));
            const enhancementLevel = levelMode === 'exact' ? mooncakeWarehouseNormalizeLevel(input?.enhancementLevel) : null;
            if (!itemHrid || !categoryId) continue;
            const key = `${itemHrid}\u0001${levelMode}\u0001${enhancementLevel ?? '*'}`;
            if (membershipKeys.has(key)) continue;
            membershipKeys.add(key);
            memberships.push({
                itemHrid,
                categoryId,
                levelMode,
                enhancementLevel,
                createdAt: Number.isFinite(Number(input?.createdAt)) ? Math.max(0, Number(input.createdAt)) : 0,
                updatedAt: Number.isFinite(Number(input?.updatedAt)) ? Math.max(0, Number(input.updatedAt)) : 0
            });
        }
        const sectionCollapsed = {};
        for (const [id, collapsed] of Object.entries(raw.sectionCollapsed || {})) {
            if (MOONCAKE_WAREHOUSE_SYSTEM_SECTIONS.has(id) || categoryIds.has(id)) {
                sectionCollapsed[id] = collapsed === true;
            }
        }
        const hiddenSections = {};
        for (const [id, hidden] of Object.entries(raw.hiddenSections || {})) {
            if (MOONCAKE_WAREHOUSE_SYSTEM_SECTIONS.has(id) || categoryIds.has(id)) {
                hiddenSections[id] = hidden === true;
            }
        }

        // 可排序分区（强化仓库、强化材料仓库、自定义分区）的统一顺序。
        // 历史数据没有该字段时按“系统仓库在前、自定义分区按 order 在后”补齐。
        const sortableIds = new Set([...MOONCAKE_WAREHOUSE_SORTABLE_SYSTEM_SECTIONS, ...categoryIds]);
        const sectionOrder = [];
        const sectionOrderSeen = new Set();
        for (const id of Array.isArray(raw.sectionOrder) ? raw.sectionOrder : []) {
            if (typeof id === 'string' && sortableIds.has(id) && !sectionOrderSeen.has(id)) {
                sectionOrder.push(id);
                sectionOrderSeen.add(id);
            }
        }
        for (const id of MOONCAKE_WAREHOUSE_SORTABLE_SYSTEM_SECTIONS) {
            if (!sectionOrderSeen.has(id)) {
                sectionOrder.push(id);
                sectionOrderSeen.add(id);
            }
        }
        for (const category of categories) {
            if (!sectionOrderSeen.has(category.id)) {
                sectionOrder.push(category.id);
                sectionOrderSeen.add(category.id);
            }
        }

        return {
            version: MOONCAKE_WAREHOUSE_VERSION,
            updatedAt: Number.isFinite(Number(raw.updatedAt)) ? Math.max(0, Number(raw.updatedAt)) : 0,
            categories,
            memberships,
            sectionCollapsed,
            hiddenSections,
            sectionOrder
        };
    }

    function mooncakeWarehouseEnsureState() {
        const characterId = mooncakeCharacterId == null ? null : String(mooncakeCharacterId);
        if (mooncakeWarehouseState && mooncakeWarehouseLoadedCharacterId === characterId) return mooncakeWarehouseState;
        const storageKey = mooncakeWarehouseStorageKey(characterId);
        let raw = null;
        if (storageKey) {
            try { raw = JSON.parse(localStorage.getItem(storageKey) || 'null'); } catch (_) {}
        }
        mooncakeWarehouseState = mooncakeWarehouseNormalizeState(raw);
        mooncakeWarehouseLoadedCharacterId = characterId;
        return mooncakeWarehouseState;
    }

    function mooncakeWarehouseSaveState() {
        const state = mooncakeWarehouseEnsureState();
        const storageKey = mooncakeWarehouseStorageKey();
        state.updatedAt = Date.now();
        if (storageKey) {
            try { localStorage.setItem(storageKey, JSON.stringify(state)); } catch (_) {}
        }
    }

    function mooncakeWarehouseGetCustomCategory(categoryId) {
        return mooncakeWarehouseEnsureState().categories.find(category => category.id === categoryId) || null;
    }

    function mooncakeWarehouseCreateCategory(name) {
        const state = mooncakeWarehouseEnsureState();
        const normalized = String(name || '').trim().replace(/\s+/g, ' ').slice(0, 24);
        if (!normalized || state.categories.some(category => category.name.localeCompare(normalized, undefined, { sensitivity: 'accent' }) === 0)) return null;
        const now = Date.now();
        const category = {
            id: mooncakeWarehouseCreateCategoryId(),
            name: normalized,
            order: state.categories.length,
            collapsed: false,
            createdAt: now,
            updatedAt: now
        };
        state.categories.push(category);
        if (!state.sectionOrder.includes(category.id)) state.sectionOrder.push(category.id);
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('category-created');
        return category;
    }

    function mooncakeWarehouseRenameCategory(categoryId, name) {
        const state = mooncakeWarehouseEnsureState();
        const category = state.categories.find(entry => entry.id === categoryId);
        const normalized = String(name || '').trim().replace(/\s+/g, ' ').slice(0, 24);
        if (!category || !normalized || state.categories.some(entry => entry.id !== categoryId &&
            entry.name.localeCompare(normalized, undefined, { sensitivity: 'accent' }) === 0)) return false;
        category.name = normalized;
        category.updatedAt = Date.now();
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('category-renamed');
        return true;
    }

    function mooncakeWarehouseDeleteCategory(categoryId) {
        const state = mooncakeWarehouseEnsureState();
        const index = state.categories.findIndex(entry => entry.id === categoryId);
        if (index < 0) return false;
        state.categories.splice(index, 1);
        state.categories.forEach((entry, order) => { entry.order = order; });
        state.memberships = state.memberships.filter(entry => entry.categoryId !== categoryId);
        state.sectionOrder = state.sectionOrder.filter(id => id !== categoryId);
        delete state.sectionCollapsed[categoryId];
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('category-deleted');
        return true;
    }

    function mooncakeWarehouseMoveCategory(categoryId, direction) {
        // 兼容旧调用：改为按统一 sectionOrder 移动。
        return mooncakeWarehouseMoveSection(categoryId, direction);
    }

    function mooncakeWarehouseMoveSection(sectionId, direction) {
        const state = mooncakeWarehouseEnsureState();
        const order = state.sectionOrder || [];
        const index = order.indexOf(sectionId);
        const nextIndex = index + (direction < 0 ? -1 : 1);
        if (index < 0 || nextIndex < 0 || nextIndex >= order.length) return false;
        const [moved] = order.splice(index, 1);
        order.splice(nextIndex, 0, moved);
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('section-reordered');
        return true;
    }

    function mooncakeWarehouseSetSectionCollapsed(sectionId, collapsed) {
        const state = mooncakeWarehouseEnsureState();
        if (!MOONCAKE_WAREHOUSE_SYSTEM_SECTIONS.has(sectionId) && !mooncakeWarehouseGetCustomCategory(sectionId)) return false;
        state.sectionCollapsed[sectionId] = collapsed === true;
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('section-collapsed');
        return true;
    }

    function mooncakeWarehouseClearSection(sectionId) {
        const state = mooncakeWarehouseEnsureState();
        if (!MOONCAKE_WAREHOUSE_SYSTEM_SECTIONS.has(sectionId) && !mooncakeWarehouseGetCustomCategory(sectionId)) return false;
        state.memberships = state.memberships.filter(entry => entry.categoryId !== sectionId);
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('section-cleared');
        return true;
    }

    function mooncakeWarehouseSetSectionHidden(sectionId, hidden) {
        const state = mooncakeWarehouseEnsureState();
        if (!MOONCAKE_WAREHOUSE_SYSTEM_SECTIONS.has(sectionId) && !mooncakeWarehouseGetCustomCategory(sectionId)) return false;
        if (hidden) {
            // 隐藏会清空该分类内容（强化仓库 = 移除已加入的装备；材料仓库为自动派生，无需存储清理）
            state.memberships = state.memberships.filter(entry => entry.categoryId !== sectionId);
        }
        state.hiddenSections[sectionId] = hidden === true;
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('section-hidden');
        return true;
    }

    function mooncakeWarehouseGetManualMembership(itemHrid, enhancementLevel) {
        const state = mooncakeWarehouseEnsureState();
        const normalizedHrid = mooncakeWarehouseNormalizeItemHrid(itemHrid);
        if (!normalizedHrid) return null;
        const level = mooncakeWarehouseNormalizeLevel(enhancementLevel);
        const exact = state.memberships.find(entry => entry.itemHrid === normalizedHrid && entry.levelMode === 'exact' && entry.enhancementLevel === level);
        return exact || state.memberships.find(entry => entry.itemHrid === normalizedHrid && entry.levelMode === 'all') || null;
    }

    function mooncakeWarehouseGetStoredMembership(itemHrid, enhancementLevel, levelMode) {
        const state = mooncakeWarehouseEnsureState();
        const normalizedHrid = mooncakeWarehouseNormalizeItemHrid(itemHrid);
        if (!normalizedHrid) return null;
        const normalizedMode = levelMode === 'exact' ? 'exact' : 'all';
        const level = mooncakeWarehouseNormalizeLevel(enhancementLevel);
        return state.memberships.find(entry => entry.itemHrid === normalizedHrid && entry.levelMode === normalizedMode &&
            (normalizedMode !== 'exact' || entry.enhancementLevel === level)) || null;
    }

    function mooncakeWarehouseSetManualMembership(itemHrid, enhancementLevel, categoryId, levelMode = 'all') {
        const state = mooncakeWarehouseEnsureState();
        const normalizedHrid = mooncakeWarehouseNormalizeItemHrid(itemHrid);
        const level = mooncakeWarehouseNormalizeLevel(enhancementLevel);
        const normalizedMode = levelMode === 'exact' ? 'exact' : 'all';
        const isEnhanceSection = categoryId === MOONCAKE_WAREHOUSE_SECTION_ENHANCE;
        if (!normalizedHrid || (!isEnhanceSection && !mooncakeWarehouseGetCustomCategory(categoryId))) return false;
        if (isEnhanceSection && !mooncakeIsEnhanceableItem(normalizedHrid)) return false;

        state.memberships = state.memberships.filter(entry => {
            if (entry.itemHrid !== normalizedHrid) return true;
            if (normalizedMode === 'all') return false;
            return entry.levelMode !== 'exact' || entry.enhancementLevel !== level;
        });
        const now = Date.now();
        state.memberships.push({
            itemHrid: normalizedHrid,
            categoryId,
            levelMode: normalizedMode,
            enhancementLevel: normalizedMode === 'exact' ? level : null,
            createdAt: now,
            updatedAt: now
        });
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('membership-set');
        return true;
    }

    function mooncakeWarehouseRemoveManualMembership(itemHrid, enhancementLevel, levelMode = 'all') {
        const state = mooncakeWarehouseEnsureState();
        const normalizedHrid = mooncakeWarehouseNormalizeItemHrid(itemHrid);
        if (!normalizedHrid) return false;
        const level = mooncakeWarehouseNormalizeLevel(enhancementLevel);
        const normalizedMode = levelMode === 'exact' ? 'exact' : 'all';
        const before = state.memberships.length;
        state.memberships = state.memberships.filter(entry => {
            if (entry.itemHrid !== normalizedHrid) return true;
            if (normalizedMode === 'all') return false;
            return entry.levelMode !== 'exact' || entry.enhancementLevel !== level;
        });
        if (normalizedMode === 'exact' && state.memberships.some(entry => entry.itemHrid === normalizedHrid && entry.levelMode === 'all')) {
            state.memberships.push({
                itemHrid: normalizedHrid,
                categoryId: MOONCAKE_WAREHOUSE_SECTION_UNCLASSIFIED,
                levelMode: 'exact',
                enhancementLevel: level,
                createdAt: Date.now(),
                updatedAt: Date.now()
            });
        }
        if (before === state.memberships.length && normalizedMode !== 'exact') return false;
        mooncakeWarehouseSaveState();
        mooncakeScheduleWarehouseRender('membership-removed');
        return true;
    }

    function mooncakeWarehouseGetEnhancementTargets() {
        const targets = new Map();
        for (const membership of mooncakeWarehouseEnsureState().memberships) {
            if (membership.categoryId !== MOONCAKE_WAREHOUSE_SECTION_ENHANCE) continue;
            targets.set(membership.itemHrid, membership);
        }
        return targets;
    }

    function mooncakeWarehouseBuildMaterialRelations() {
        const relations = new Map();
        const add = (itemHrid, role, sourceHrid) => {
            const hrid = mooncakeWarehouseNormalizeItemHrid(itemHrid);
            if (!hrid || hrid === '/items/coin') return;
            const key = mooncakeWarehouseIdentityKey(hrid, 0);
            const relation = relations.get(key) || {
                itemHrid: hrid,
                enhancementLevel: 0,
                roles: new Set(),
                sourceHrids: new Set()
            };
            relation.roles.add(role);
            relation.sourceHrids.add(sourceHrid);
            relations.set(key, relation);
        };
        for (const sourceHrid of mooncakeWarehouseGetEnhancementTargets().keys()) {
            for (const protectionHrid of getProtectionItems(sourceHrid) || []) {
                if (protectionHrid === sourceHrid) continue;
                add(protectionHrid, 'protection', sourceHrid);
            }
            for (const cost of getEnhancementCosts(sourceHrid) || []) {
                add(cost?.itemHrid, 'material', sourceHrid);
            }
        }
        return relations;
    }

    function mooncakeWarehouseBuildQueueRecords() {
        const equipment = [];
        const protection = [];
        const materials = [];
        let enhanceActionCount = 0;
        mooncakeWarehouseGetStableQueueActions().forEach((action, actionIndex) => {
            if (!mooncakeIsWarehouseEnhanceAction(action)) return;
            const primary = parseMooncakeEnhanceItemHash(action.primaryItemHash || '');
            if (!primary?.hrid) return;
            const queueIndex = enhanceActionCount++;
            equipment.push({
                itemHrid: primary.hrid,
                enhancementLevel: mooncakeWarehouseNormalizeLevel(primary.level),
                role: actionIndex === 0 ? 'current-equipment' : 'queued-equipment',
                sectionId: MOONCAKE_WAREHOUSE_SECTION_QUEUE,
                group: 'equipment',
                priority: 400,
                sort: [queueIndex, 0],
                actionIndexes: [actionIndex],
                allowLevelReconcile: Number(action._mooncakeWarehouseLevelReconcileUntil || 0) > Date.now()
            });
            const secondary = parseMooncakeEnhanceItemHash(action.secondaryItemHash || '');
            if (secondary?.hrid && secondary.hrid !== '/items/coin') {
                protection.push({
                    itemHrid: secondary.hrid,
                    enhancementLevel: mooncakeWarehouseNormalizeLevel(secondary.level),
                    role: 'queue-protection',
                    sectionId: MOONCAKE_WAREHOUSE_SECTION_QUEUE,
                    group: 'protection',
                    priority: 390,
                    sort: [queueIndex, 0],
                    actionIndexes: [actionIndex]
                });
            }
            (getEnhancementCosts(primary.hrid) || []).forEach((cost, costIndex) => {
                const itemHrid = mooncakeWarehouseNormalizeItemHrid(cost?.itemHrid);
                if (!itemHrid || itemHrid === '/items/coin') return;
                materials.push({
                    itemHrid,
                    enhancementLevel: 0,
                    role: 'queue-material',
                    sectionId: MOONCAKE_WAREHOUSE_SECTION_QUEUE,
                    group: 'material',
                    priority: 380,
                    sort: [queueIndex, costIndex],
                    actionIndexes: [actionIndex]
                });
            });
        });
        return { equipment, protection, materials, actionCount: enhanceActionCount };
    }

    function mooncakeWarehouseCompareSort(left, right) {
        const a = Array.isArray(left) ? left : [];
        const b = Array.isArray(right) ? right : [];
        const length = Math.max(a.length, b.length);
        for (let index = 0; index < length; index += 1) {
            const leftValue = a[index] ?? 0;
            const rightValue = b[index] ?? 0;
            const leftNumber = Number(leftValue);
            const rightNumber = Number(rightValue);
            if (Number.isFinite(leftNumber) && Number.isFinite(rightNumber)) {
                const diff = leftNumber - rightNumber;
                if (diff) return diff;
                continue;
            }
            const diff = String(leftValue).localeCompare(String(rightValue));
            if (diff) return diff;
        }
        return 0;
    }

    function mooncakeWarehouseBuildProjection(inventoryNodes) {
        const inventoryByKey = new Map();
        const inventoryByHrid = new Map();
        const inventoryStateLevelsByHrid = new Map();
        for (const item of mooncakeInventoryCharacterItems(characterInventoryItems)) {
            if (!(Number(item?.count ?? 1) > 0)) continue;
            const levels = inventoryStateLevelsByHrid.get(item.itemHrid) || new Set();
            levels.add(mooncakeWarehouseNormalizeLevel(item.enhancementLevel));
            inventoryStateLevelsByHrid.set(item.itemHrid, levels);
        }
        for (const entry of inventoryNodes) {
            const key = mooncakeWarehouseIdentityKey(entry.itemHrid, entry.enhancementLevel);
            if (!inventoryByKey.has(key)) inventoryByKey.set(key, entry);
            const sameItemEntries = inventoryByHrid.get(entry.itemHrid) || [];
            sameItemEntries.push(entry);
            inventoryByHrid.set(entry.itemHrid, sameItemEntries);
        }
        const candidates = new Map();
        const add = candidate => {
            const requestedKey = mooncakeWarehouseIdentityKey(candidate.itemHrid, candidate.enhancementLevel);
            let inventoryEntry = inventoryByKey.get(requestedKey);
            let reconciledLevel = false;
            if (!inventoryEntry && candidate.allowLevelReconcile === true) {
                const sameItemEntries = inventoryByHrid.get(candidate.itemHrid) || [];
                const stateLevels = inventoryStateLevelsByHrid.get(candidate.itemHrid) || new Set();
                if (sameItemEntries.length === 1 && stateLevels.size <= 1) {
                    inventoryEntry = sameItemEntries[0];
                    reconciledLevel = true;
                }
            }
            if (!inventoryEntry) return;
            const key = mooncakeWarehouseIdentityKey(inventoryEntry.itemHrid, inventoryEntry.enhancementLevel);
            const next = {
                ...candidate,
                enhancementLevel: inventoryEntry.enhancementLevel,
                key,
                node: inventoryEntry.node,
                reconciledLevel
            };
            const previous = candidates.get(key);
            if (!previous || next.priority > previous.priority ||
                (next.priority === previous.priority && mooncakeWarehouseCompareSort(next.sort, previous.sort) < 0)) {
                candidates.set(key, next);
            }
        };

        const queue = mooncakeWarehouseBuildQueueRecords();
        queue.equipment.forEach(add);
        queue.protection.forEach(add);
        queue.materials.forEach(add);

        const materialRelations = mooncakeWarehouseBuildMaterialRelations();
        for (const relation of materialRelations.values()) {
            add({
                itemHrid: relation.itemHrid,
                enhancementLevel: relation.enhancementLevel,
                role: relation.roles.has('protection') ? 'warehouse-protection' : 'warehouse-material',
                sectionId: MOONCAKE_WAREHOUSE_SECTION_MATERIALS,
                group: relation.roles.has('protection') ? 'protection' : 'material',
                priority: relation.roles.has('protection') ? 300 : 290,
                sort: [getItemName(relation.itemHrid)],
                relation
            });
        }

        for (const entry of inventoryNodes) {
            const membership = mooncakeWarehouseGetManualMembership(entry.itemHrid, entry.enhancementLevel);
            if (!membership || membership.categoryId === MOONCAKE_WAREHOUSE_SECTION_UNCLASSIFIED) continue;
            add({
                itemHrid: entry.itemHrid,
                enhancementLevel: entry.enhancementLevel,
                role: membership.categoryId === MOONCAKE_WAREHOUSE_SECTION_ENHANCE ? 'warehouse-equipment' : 'custom',
                sectionId: membership.categoryId,
                group: 'items',
                // A deliberate manual grouping overrides the automatic material view,
                // while the live enhancement queue remains the highest-priority view.
                priority: 350,
                sort: [membership.createdAt || 0, getItemName(entry.itemHrid)],
                membership
            });
        }

        const bySection = new Map();
        for (const candidate of candidates.values()) {
            const records = bySection.get(candidate.sectionId) || [];
            records.push(candidate);
            bySection.set(candidate.sectionId, records);
        }
        for (const records of bySection.values()) {
            records.sort((left, right) => mooncakeWarehouseCompareSort(left.sort, right.sort) ||
                getItemName(left.itemHrid).localeCompare(getItemName(right.itemHrid)) ||
                left.enhancementLevel - right.enhancementLevel);
        }
        return { bySection, candidates, queue, materialRelations };
    }

    function mooncakeWarehouseGetUnavailableSectionCount(sectionId, records, projection, shared) {
        const inventoryKeys = shared?.inventoryKeys || new Set(mooncakeInventoryCharacterItems(characterInventoryItems)
            .map(item => mooncakeWarehouseIdentityKey(item.itemHrid, item.enhancementLevel)));
        if (!inventoryKeys.size) return 0;
        const expected = new Set();
        const queueKeys = shared?.queueKeys || new Set([
            ...[...projection.queue.equipment, ...projection.queue.protection, ...projection.queue.materials]
                .map(record => mooncakeWarehouseIdentityKey(record.itemHrid, record.enhancementLevel)),
            ...(projection.bySection.get(MOONCAKE_WAREHOUSE_SECTION_QUEUE) || []).map(record => record.key)
        ]);
        if (sectionId === MOONCAKE_WAREHOUSE_SECTION_QUEUE) {
            for (const record of [...projection.queue.equipment, ...projection.queue.protection, ...projection.queue.materials]) {
                const key = mooncakeWarehouseIdentityKey(record.itemHrid, record.enhancementLevel);
                if (inventoryKeys.has(key)) expected.add(key);
            }
        } else if (sectionId === MOONCAKE_WAREHOUSE_SECTION_MATERIALS) {
            for (const key of projection.materialRelations.keys()) {
                if (!inventoryKeys.has(key) || queueKeys.has(key)) continue;
                const [itemHrid, enhancementLevel] = key.split('\u0001');
                const membership = mooncakeWarehouseGetManualMembership(itemHrid, enhancementLevel);
                if (!membership || membership.categoryId === MOONCAKE_WAREHOUSE_SECTION_UNCLASSIFIED) expected.add(key);
            }
        } else {
            for (const item of mooncakeInventoryCharacterItems(characterInventoryItems)) {
                const membership = mooncakeWarehouseGetManualMembership(item.itemHrid, item.enhancementLevel);
                const key = mooncakeWarehouseIdentityKey(item.itemHrid, item.enhancementLevel);
                if (membership?.categoryId === sectionId && !queueKeys.has(key)) {
                    expected.add(key);
                }
            }
        }
        const visible = new Set(records.map(record => record.key));
        let unavailable = 0;
        for (const key of expected) {
            if (!visible.has(key)) unavailable += 1;
        }
        return unavailable;
    }

    function mooncakeWarehouseUnavailableText(count) {
        return isZH
            ? `${count} \u4ef6\u7269\u54c1\u5728\u539f\u751f\u80cc\u5305\u7684\u6298\u53e0\u5206\u7c7b\u4e2d\uff0c\u5c55\u5f00\u540e\u5373\u53ef\u663e\u793a\u3002`
            : `${count} item${count === 1 ? '' : 's'} is in a collapsed native inventory category. Expand it to show here.`;
    }

    function mooncakeWarehouseHasSunnyConflict() {
        return !!document.querySelector('#sunnyMwi-fav-bar, .sunnyMwi-fav-wrap, [data-sunnymwi-fav-pinned]');
    }

    function mooncakeWarehouseShowSunnyConflictNotice() {
        if (mooncakeWarehouseSunnyConflictNotified || !document.body) return;
        mooncakeWarehouseSunnyConflictNotified = true;
        const notice = document.createElement('div');
        notice.setAttribute(MOONCAKE_WAREHOUSE_UI_ATTR, '1');
        notice.textContent = mooncakeWarehouseText('conflict');
        notice.style.cssText = 'position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:10060;max-width:min(520px,calc(100vw - 32px));padding:9px 12px;background:#34251f;border:1px solid #b78b57;color:#ffe2bb;border-radius:5px;box-shadow:0 7px 22px rgba(0,0,0,.45);font:13px system-ui,sans-serif;';
        document.body.appendChild(notice);
        setTimeout(() => notice.remove(), 6500);
    }

    function mooncakeWarehouseSnapshotInlineStyles(element, properties) {
        const snapshot = {};
        for (const property of properties) {
            snapshot[property] = {
                value: element.style.getPropertyValue(property),
                priority: element.style.getPropertyPriority(property)
            };
        }
        return snapshot;
    }

    function mooncakeWarehouseRestoreInlineStyles(element, snapshot) {
        if (!element || !snapshot) return;
        for (const [property, state] of Object.entries(snapshot)) {
            if (state?.value) element.style.setProperty(property, state.value, state.priority || '');
            else element.style.removeProperty(property);
        }
    }

    function mooncakeWarehouseSetInlineStyle(element, property, value, priority = '') {
        if (!element) return;
        const nextValue = String(value ?? '');
        if (element.style.getPropertyValue(property) === nextValue &&
            element.style.getPropertyPriority(property) === priority) return;
        if (nextValue) element.style.setProperty(property, nextValue, priority);
        else element.style.removeProperty(property);
    }

    function mooncakeWarehouseRestorePinnedNode(node) {
        if (!node) return;
        mooncakeWarehouseRestoreInlineStyles(node, mooncakeWarehouseNodeStyleSnapshots.get(node));
        node.removeAttribute(MOONCAKE_WAREHOUSE_PINNED_ATTR);
        node.removeAttribute(MOONCAKE_WAREHOUSE_ROLE_ATTR);
    }

    function mooncakeWarehouseRestorePresentation() {
        for (const panel of document.querySelectorAll(`[${MOONCAKE_WAREHOUSE_PANEL_ATTR}]`)) panel.remove();
        for (const node of mooncakeWarehousePinnedNodes) {
            mooncakeWarehouseRestorePinnedNode(node);
        }
        mooncakeWarehousePinnedNodes = new Set();
        if (mooncakeWarehouseInventoryRoot && mooncakeWarehouseRootStyleSnapshot) {
            mooncakeWarehouseRestoreInlineStyles(mooncakeWarehouseInventoryRoot, mooncakeWarehouseRootStyleSnapshot);
        }
        mooncakeWarehouseInventoryRoot = null;
        mooncakeWarehouseRootStyleSnapshot = null;
        mooncakeWarehousePanel = null;
        mooncakeWarehousePanelSignature = '';
        mooncakeWarehouseProjectionSignature = '';
        mooncakeWarehouseLayoutSignature = '';
        mooncakeWarehouseLayoutMetrics = null;
        mooncakeWarehouseGeometryDirty = true;
    }

    function mooncakeWarehouseStopObservingInventoryRoot() {
        if (mooncakeWarehouseResizeObserver) mooncakeWarehouseResizeObserver.disconnect();
        if (mooncakeWarehouseVisibilityObserver) mooncakeWarehouseVisibilityObserver.disconnect();
        mooncakeWarehouseResizeObserver = null;
        mooncakeWarehouseVisibilityObserver = null;
        mooncakeWarehouseObservedRoot = null;
        mooncakeWarehouseObservedWidth = null;
        mooncakeWarehouseObservedRootVisible = false;
    }

    function mooncakeWarehouseIsInventoryRootVisible(root) {
        if (!mooncakeIsVisibleElement(root)) return false;
        return root.getBoundingClientRect().width > 0;
    }

    function mooncakeWarehouseObserveInventoryVisibility(root) {
        if (!root || typeof MutationObserver !== 'function') return;
        mooncakeWarehouseVisibilityObserver = new MutationObserver(() => {
            const observedRoot = mooncakeWarehouseObservedRoot;
            if (!observedRoot?.isConnected) {
                mooncakeWarehouseObservedRootVisible = false;
                mooncakeWarehousePendingVisibleRender = true;
                return;
            }
            const wasVisible = mooncakeWarehouseObservedRootVisible;
            const isVisible = mooncakeWarehouseIsInventoryRootVisible(observedRoot);
            mooncakeWarehouseObservedRootVisible = isVisible;
            if (!isVisible) {
                mooncakeWarehousePendingVisibleRender = true;
                return;
            }
            if (!wasVisible || mooncakeWarehousePendingVisibleRender) {
                mooncakeWarehousePendingVisibleRender = false;
                mooncakeWarehouseGeometryDirty = true;
                mooncakeScheduleWarehouseRender('inventory-visible');
            }
        });
        for (let node = root; node instanceof Element; node = node.parentElement) {
            mooncakeWarehouseVisibilityObserver.observe(node, {
                attributes: true,
                attributeFilter: ['class', 'style', 'hidden', 'aria-hidden']
            });
        }
    }

    function mooncakeWarehouseObserveInventoryRoot(root) {
        if (!root) return;
        if (mooncakeWarehouseObservedRoot !== root) {
            mooncakeWarehouseStopObservingInventoryRoot();
            mooncakeWarehouseObservedRoot = root;
            mooncakeWarehouseObservedRootVisible = mooncakeWarehouseIsInventoryRootVisible(root);
            mooncakeWarehouseObserveInventoryVisibility(root);
        }
        if (typeof ResizeObserver !== 'function' || mooncakeWarehouseResizeObserver) return;
        mooncakeWarehouseResizeObserver = new ResizeObserver(entries => {
            const entry = entries.find(candidate => candidate.target === mooncakeWarehouseObservedRoot);
            const width = entry?.contentRect?.width;
            if (!(width > 0)) {
                mooncakeWarehouseObservedRootVisible = false;
                mooncakeWarehousePendingVisibleRender = true;
                return;
            }
            const roundedWidth = Math.round(width);
            const wasPending = mooncakeWarehousePendingVisibleRender;
            if (mooncakeWarehouseObservedWidth == null) {
                mooncakeWarehouseObservedWidth = roundedWidth;
                if (!wasPending) return;
            }
            const widthChanged = roundedWidth !== mooncakeWarehouseObservedWidth;
            if (!widthChanged && !wasPending) return;
            mooncakeWarehouseObservedWidth = roundedWidth;
            mooncakeWarehouseObservedRootVisible = true;
            mooncakeWarehousePendingVisibleRender = false;
            // Responsive CSS may change the native item size/gap at the same
            // breakpoint. Re-measure only for an actual width change.
            if (widthChanged) mooncakeWarehouseLayoutMetrics = null;
            mooncakeWarehouseGeometryDirty = true;
            mooncakeScheduleWarehouseRender(widthChanged ? 'inventory-resize' : 'inventory-visible');
        });
        mooncakeWarehouseResizeObserver.observe(root);
    }

    function mooncakeWarehouseFindInventoryRoot() {
        const roots = document.querySelectorAll('[class*="Inventory_inventory"] [class*="Inventory_items"], [class*="Inventory_items"]');
        for (const root of roots) {
            if (!mooncakeIsVisibleElement(root)) continue;
            const rect = root.getBoundingClientRect();
            // An empty native inventory may legitimately start at zero height;
            // width plus the ancestor visibility check is the reliable gate.
            if (!(rect.width > 0)) continue;
            return root;
        }
        return null;
    }

    function mooncakeWarehouseCollectInventoryNodes(root) {
        if (!root) return [];
        const entries = [];
        const seen = new Set();
        const visibleGrids = new Map();
        for (const node of root.querySelectorAll('[class*="Item_itemContainer"]')) {
            if (node.closest(`[${MOONCAKE_WAREHOUSE_PANEL_ATTR}], [${MOONCAKE_WAREHOUSE_UI_ATTR}]`)) continue;
            const grid = node.closest('[class*="Inventory_itemGrid"]');
            if (!grid || !root.contains(grid)) continue;
            if (!visibleGrids.has(grid)) {
                const rect = grid.getBoundingClientRect();
                // Absolutely positioned managed items no longer contribute to
                // the native grid height. A zero-height grid can therefore still
                // be active, while display:none native categories must stay out.
                const hasManagedItems = !!grid.querySelector(`[${MOONCAKE_WAREHOUSE_PINNED_ATTR}]`);
                visibleGrids.set(grid, mooncakeIsVisibleElement(grid) && rect.width > 0 && (rect.height > 0 || hasManagedItems));
            }
            if (!visibleGrids.get(grid)) continue;
            const itemHrid = mooncakeWarehouseNormalizeItemHrid(mooncakeGetItemHridFromContainer(node));
            if (!itemHrid) continue;
            const enhancementLevel = mooncakeWarehouseNormalizeLevel(mooncakeGetItemEnhancementLevelFromContainer(node));
            const key = mooncakeWarehouseIdentityKey(itemHrid, enhancementLevel);
            if (seen.has(key)) continue;
            seen.add(key);
            entries.push({ node, grid, itemHrid, enhancementLevel });
        }
        return entries;
    }

    function mooncakeWarehouseGetLayoutMetrics(root, entries, originalPaddingTop = null) {
        // This path runs only for a new root or a real width change. Geometry is
        // read before any item style is changed, and only enough native items are
        // measured to recover the grid step.
        const measuredEntries = [];
        for (const entry of entries) {
            const rect = entry.node.getBoundingClientRect();
            if (!(rect.width > 0) || !(rect.height > 0)) continue;
            measuredEntries.push({ ...entry, rect });
            if (measuredEntries.length >= 12) break;
        }
        const first = measuredEntries[0] || null;
        const rootStyle = getComputedStyle(root);
        const fallbackGrid = root.querySelector('[class*="Inventory_itemGrid"]');
        const gridStyle = getComputedStyle(first?.grid || fallbackGrid || root);
        const inventoryItemSize = parseFloat(rootStyle.getPropertyValue('--item-size-normal')) || 52;
        const itemWidth = Math.max(1, Math.round(first?.rect.width || inventoryItemSize));
        const itemHeight = Math.max(1, Math.round(first?.rect.height || inventoryItemSize));
        const columnGap = Math.max(2, parseFloat(gridStyle.columnGap) || 4);
        const rowGap = Math.max(2, parseFloat(gridStyle.rowGap) || columnGap);
        const paddingLeft = Math.max(0, parseFloat(rootStyle.paddingLeft) || 0);
        const paddingRight = Math.max(0, parseFloat(rootStyle.paddingRight) || 0);
        const computedPaddingTop = Math.max(0, parseFloat(rootStyle.paddingTop) || 0);
        // When an initially empty inventory receives its first item, the root
        // already contains our panel padding. Preserve the fallback measurement's
        // native padding so the panel height cannot be counted a second time.
        const paddingTop = Number.isFinite(originalPaddingTop)
            ? Math.max(0, originalPaddingTop)
            : computedPaddingTop;
        const columnsFromTemplate = String(gridStyle.gridTemplateColumns || '')
            .trim().split(/\s+/).filter(value => /(?:px|rem|%|fr)$/.test(value)).length;
        const availableWidth = Math.max(itemWidth, root.clientWidth - paddingLeft - paddingRight);
        const columns = Math.max(1, columnsFromTemplate || Math.floor((availableWidth + columnGap) / (itemWidth + columnGap)));
        // 与默认网格保持一致：以第一个物品相对容器的实际偏移作为左基准，
        // 用同一行相邻物品的实际间距作为列距，避免物品整体偏左贴边。
        const rootRect = root.getBoundingClientRect();
        const firstRow = first
            ? measuredEntries
                .filter(entry => entry.rect.width > 0 && entry.rect.height > 0 && Math.abs(entry.rect.top - first.rect.top) < 2)
                .sort((a, b) => a.rect.left - b.rect.left)
            : [];
        const second = firstRow[1];
        const baseLeft = first ? Math.max(0, first.rect.left - rootRect.left) : paddingLeft;
        const columnStep = second && second.rect.left > first.rect.left
            ? second.rect.left - first.rect.left
            : itemWidth + columnGap;
        const signature = [
            Math.round(root.clientWidth), itemWidth, itemHeight, columnGap, rowGap,
            paddingLeft, paddingTop, columns, Math.round(baseLeft), Math.round(columnStep)
        ].join('|');
        return { itemWidth, itemHeight, columnGap, rowGap, paddingLeft, paddingTop, columns, baseLeft, columnStep, signature, measured: !!first };
    }

