    function mooncakeIsProtectionAssistantEnabled() {
        try { return localStorage.getItem(MOONCAKE_PROTECTION_ASSISTANT_ENABLED_KEY) !== '0'; }
        catch (_) { return true; }
    }

    function mooncakeRestoreProtectionAssistantOptions() {
        document.querySelectorAll('[data-mooncake-protection-assistant-hidden]').forEach(option => {
            const originalDisplay = option.getAttribute('data-mooncake-protection-assistant-display');
            if (originalDisplay) option.style.setProperty('display', originalDisplay);
            else option.style.removeProperty('display');
            const originalTitle = option.getAttribute('data-mooncake-protection-assistant-title');
            if (originalTitle !== null) option.setAttribute('title', originalTitle);
            else option.removeAttribute('title');
            option.removeAttribute('data-mooncake-protection-assistant-hidden');
            option.removeAttribute('data-mooncake-protection-assistant-display');
            option.removeAttribute('data-mooncake-protection-assistant-title');
        });
    }

    function mooncakeSetProtectionAssistantEnabled(enabled) {
        try { localStorage.setItem(MOONCAKE_PROTECTION_ASSISTANT_ENABLED_KEY, enabled ? '1' : '0'); } catch (_) {}
        document.querySelectorAll('[data-mooncake-protection-assistant-switch]').forEach(button => {
            button.textContent = isZH ? `保护助手：${enabled ? '开' : '关'}` : `Protection assistant: ${enabled ? 'On' : 'Off'}`;
            button.setAttribute('aria-pressed', String(enabled));
            Object.assign(button.style, enabled ? {
                borderColor: 'rgba(243,184,95,.48)', background: 'rgba(86,60,27,.74)', color: '#fff0c9'
            } : {
                borderColor: 'rgba(170,180,198,.28)', background: 'rgba(54,58,68,.58)', color: 'rgba(220,225,233,.72)'
            });
        });
        if (enabled) mooncakeScheduleProtectionAssistant(0);
        else mooncakeRestoreProtectionAssistantOptions();
    }

    function mooncakeGetProtectionAssistantOptionCount(element) {
        const countNode = element?.querySelector?.('[class*="Item_count"], [class*="itemCount"]');
        if (!countNode) return null;
        const count = mooncakeParseLootQuantity(countNode.textContent);
        return Number.isFinite(count) ? count : null;
    }

    function mooncakeIsUnavailableSelfProtectionCandidate(baseHrid, option) {
        return !!baseHrid &&
            mooncakeEnhanceHridsMatch(option?.itemHrid, baseHrid) &&
            option?.availableCount === 0;
    }

    function mooncakeApplyProtectionAssistant() {
        mooncakeProtectionAssistantTimer = 0;
        mooncakeRestoreProtectionAssistantOptions();
        if (!mooncakeIsProtectionAssistantEnabled()) return;
        // Only the protection-material picker is in scope. The game's primary
        // equipment picker uses the same ItemSelector component and must never
        // have its equipment options filtered.
        if (Date.now() > mooncakeProtectionAssistantArmedUntil) return;
        const panel = mooncakeFindEnhancingPanel();
        const baseHrid = mooncakeGetEnhanceBaseItemHrid(panel);
        if (!baseHrid) return;
        const allowed = new Set((getProtectionItems(baseHrid) || []).filter(Boolean));
        if (!allowed.size) return;
        const lists = [...document.querySelectorAll('[class*="ItemSelector_itemList"]')];
        for (const list of lists) {
            const options = [...list.children].map(element => ({
                element,
                itemHrid: mooncakeGetItemHridFromContainer(element),
                availableCount: mooncakeGetProtectionAssistantOptionCount(element)
            })).filter(option => option.itemHrid);
            const allowedOptions = options.filter(option => allowed.has(option.itemHrid));
            if (!allowedOptions.length) continue;

            // The active primary item is normally removed from inventory by the
            // game, but its zero-count self-protection entry can remain in the
            // selector. Self-protection is legal when an extra copy exists, so
            // hide only an explicitly unavailable entry rather than every
            // option with the base item's HRID.
            const unavailableSelfOptions = allowedOptions.filter(option =>
                mooncakeIsUnavailableSelfProtectionCandidate(baseHrid, option)
            );
            const selectableAllowedOptions = allowedOptions.filter(option => !unavailableSelfOptions.includes(option));
            const quoted = selectableAllowedOptions.map(option => ({
                ...option,
                ask: mooncakeGetMarketAskPrice(option.itemHrid, getMarketData()),
                bid: mooncakeGetMarketBidPrice(option.itemHrid, getMarketData())
            }));
            const usableAsks = quoted.map(option => option.ask).filter(price => price > 0);
            const cheapestAsk = usableAsks.length ? Math.min(...usableAsks) : 0;
            for (const option of options.filter(option => !allowed.has(option.itemHrid))) {
                option.element.setAttribute('data-mooncake-protection-assistant-display', option.element.style.display || '');
                if (option.element.hasAttribute('title')) {
                    option.element.setAttribute('data-mooncake-protection-assistant-title', option.element.getAttribute('title') || '');
                }
                option.element.style.setProperty('display', 'none', 'important');
                option.element.setAttribute('data-mooncake-protection-assistant-hidden', '1');
                option.element.title = isZH ? '保护助手：不是当前装备的保护材料' : 'Protection assistant: invalid material for this item';
            }
            for (const option of unavailableSelfOptions) {
                option.element.setAttribute('data-mooncake-protection-assistant-display', option.element.style.display || '');
                if (option.element.hasAttribute('title')) {
                    option.element.setAttribute('data-mooncake-protection-assistant-title', option.element.getAttribute('title') || '');
                }
                option.element.style.setProperty('display', 'none', 'important');
                option.element.setAttribute('data-mooncake-protection-assistant-hidden', '1');
                option.element.title = isZH
                    ? '保护助手：当前装备已被占用，没有可用副本'
                    : 'Protection assistant: the current item has no available extra copy';
            }
            for (const option of quoted) {
                const enhanced = !!option.element.querySelector('[class*="Item_enhancementLevel"]');
                const referenceValue = option.bid > 0 ? option.bid : option.ask;
                const economicallyRisky = cheapestAsk > 0 && referenceValue > cheapestAsk;
                if (!enhanced && !economicallyRisky) continue;
                option.element.setAttribute('data-mooncake-protection-assistant-display', option.element.style.display || '');
                if (option.element.hasAttribute('title')) {
                    option.element.setAttribute('data-mooncake-protection-assistant-title', option.element.getAttribute('title') || '');
                }
                option.element.style.setProperty('display', 'none', 'important');
                option.element.setAttribute('data-mooncake-protection-assistant-hidden', '1');
                option.element.title = enhanced
                    ? (isZH ? '保护助手：隐藏已强化物品' : 'Protection assistant: enhanced item hidden')
                    : (isZH ? '保护助手：该物品买一价值高于更便宜的保护材料' : 'Protection assistant: a cheaper protection material exists');
            }
        }
    }

    function mooncakeScheduleProtectionAssistant(delay = 60) {
        if (mooncakeProtectionAssistantTimer) clearTimeout(mooncakeProtectionAssistantTimer);
        mooncakeProtectionAssistantTimer = setTimeout(mooncakeApplyProtectionAssistant, Math.max(0, Number(delay) || 0));
    }

    function hookMooncakeProtectionAssistant() {
        if (window.__mooncakeProtectionAssistantBound) return;
        window.__mooncakeProtectionAssistantBound = true;
        document.addEventListener('click', event => {
            if (!mooncakeIsProtectionAssistantEnabled()) return;
            const panel = event.target?.closest?.('[class*="EnhancingPanel"]') || mooncakeFindEnhancingPanel();
            const protectionSlot = mooncakeGetEnhanceProtectionSlot(panel);
            if (protectionSlot?.contains?.(event.target)) {
                mooncakeProtectionAssistantArmedUntil = Date.now() + 5000;
                mooncakeScheduleProtectionAssistant(80);
                return;
            }
            // A primary-equipment click must cancel a prior protection-picker
            // arm window. Keep the window while users search or choose within
            // the already-open protection list, which is rendered in a portal.
            if (!event.target?.closest?.('[class*="ItemSelector_itemList"]')) {
                mooncakeProtectionAssistantArmedUntil = 0;
                mooncakeRestoreProtectionAssistantOptions();
            }
        }, true);
        subscribeDocumentMutations('protection-assistant', mutations => {
            if (!mooncakeIsProtectionAssistantEnabled() || Date.now() > mooncakeProtectionAssistantArmedUntil) return;
            const relevant = mutations.some(mutation => [...mutation.addedNodes].some(node =>
                node instanceof Element && (node.matches?.('[class*="ItemSelector"]') || node.querySelector?.('[class*="ItemSelector"]'))
            ));
            if (relevant) mooncakeScheduleProtectionAssistant();
        });
    }

    function mooncakeFindEnhancingPanel() {
        return document.querySelector('[class*="EnhancingPanel_enhancingPanel"]');
    }

    function mooncakeBuildEnhanceCostPurchaseTooltipHtml(itemHrid) {
        const itemName = getItemName(itemHrid) || itemHrid;
        const shopItem = mooncakeGetCoinShopItem(itemHrid);
        if (shopItem) {
            return `<div class="tt-header">${isZH ? '材料商店' : 'Material shop'}</div>`
                + `<span class="tt-label">${isZH ? '材料:' : 'Material:'}</span> <span class="tt-value">${itemName}</span>\n`
                + `<span class="tt-label">${isZH ? '金币价格:' : 'Coin price:'}</span> <span class="tt-value">${formatMoney(shopItem.price)}</span>\n`
                + `<span class="tt-label">${isZH ? '说明:' : 'Note:'}</span> <span class="tt-value">${isZH ? '点击前往系统商店购买' : 'Click to open the system shop'}</span>`;
        }
        return `<div class="tt-header">${isZH ? '材料市场' : 'Material market'}</div>`
            + `<span class="tt-label">${isZH ? '材料:' : 'Material:'}</span> <span class="tt-value">${itemName}</span>\n`
            + `<span class="tt-label">${isZH ? '说明:' : 'Note:'}</span> <span class="tt-value">${isZH ? '点击跳转到该材料的 +0 市场' : 'Click to open this material at +0'}</span>`;
    }

    function mooncakeRemoveEnhanceCostMarketButtons(root = document) {
        root.querySelectorAll?.(`[${MOONCAKE_ENH_COST_MARKET_ATTR}="1"]`).forEach(button => {
            const host = button.parentElement;
            button.remove();
            if (!host?.querySelector?.(`[${MOONCAKE_ENH_COST_MARKET_ATTR}="1"]`)) {
                mooncakeRestoreEnhanceCostPurchaseHost(host);
            }
        });
        if (root.matches?.(`[${MOONCAKE_ENH_COST_MARKET_SIG_ATTR}]`)) {
            root.removeAttribute(MOONCAKE_ENH_COST_MARKET_SIG_ATTR);
        }
        root.querySelectorAll?.(`[${MOONCAKE_ENH_COST_MARKET_SIG_ATTR}]`).forEach(node => {
            node.removeAttribute(MOONCAKE_ENH_COST_MARKET_SIG_ATTR);
        });
    }

    function mooncakeGetEnhanceCostItemHrid(itemContainer) {
        const useNode = [...(itemContainer?.querySelectorAll?.('use') || [])].find(use => {
            const href = use.getAttribute('href') || use.getAttribute('xlink:href') || use.href?.baseVal || '';
            return href.includes('items_sprite');
        });
        return mooncakeHridFromUseNode(useNode);
    }

    function mooncakePrepareEnhanceCostPurchaseHost(itemContainer) {
        const host = itemContainer;
        if (!host) return null;
        const isProcurementHost = !!host.closest?.('.mwi-procurement-requirement-grid, .mwi-procurement-panel');

        if (!mooncakeEnhanceCostPurchaseHostStyles.has(host)) {
            mooncakeEnhanceCostPurchaseHostStyles.set(host, {
                display: host.style.display,
                flexFlow: host.style.flexFlow,
                alignItems: host.style.alignItems,
                gap: host.style.gap,
                position: host.style.position,
                paddingRight: host.style.paddingRight,
                overflow: host.style.overflow,
                maxWidth: host.style.maxWidth,
                minWidth: host.style.minWidth,
                width: host.style.width,
                boxSizing: host.style.boxSizing,
                whiteSpace: host.style.whiteSpace
            });
        }

        if (isProcurementHost) {
            // MWITools owns this four-column grid. Reserve space inside the
            // material cell and overlay the market button there, so no new grid
            // column can push the shortage badge or resize the panel.
            Object.assign(host.style, {
                position: 'relative',
                paddingRight: '26px',
                minWidth: '0',
                maxWidth: '100%',
                boxSizing: 'border-box',
                overflow: 'hidden'
            });
            host.setAttribute(MOONCAKE_ENH_COST_MARKET_HOST_ATTR, '1');
            return host;
        }

        // Keep the material and its action together without making the native
        // requirement column wider than the enhancement information panel.
        Object.assign(host.style, {
            display: 'inline-flex',
            flexFlow: 'row wrap',
            alignItems: 'center',
            gap: '2px 4px',
            maxWidth: '100%',
            minWidth: '0',
            width: 'auto',
            boxSizing: 'border-box',
            whiteSpace: 'normal'
        });
        host.setAttribute(MOONCAKE_ENH_COST_MARKET_HOST_ATTR, '1');

        const primaryItem = host.firstElementChild;
        if (primaryItem) {
            if (!mooncakeEnhanceCostPurchaseFirstChildStyles.has(primaryItem)) {
                mooncakeEnhanceCostPurchaseFirstChildStyles.set(primaryItem, {
                    flex: primaryItem.style.flex,
                    minWidth: primaryItem.style.minWidth,
                    maxWidth: primaryItem.style.maxWidth,
                    whiteSpace: primaryItem.style.whiteSpace
                });
            }
            Object.assign(primaryItem.style, {
                flex: '0 1 auto',
                minWidth: '0',
                maxWidth: '100%',
                whiteSpace: 'normal'
            });
        }
        return host;
    }

    function mooncakeRestoreEnhanceCostPurchaseHost(host) {
        if (!host) return;
        const hostStyle = mooncakeEnhanceCostPurchaseHostStyles.get(host);
        if (hostStyle) {
            Object.assign(host.style, hostStyle);
            mooncakeEnhanceCostPurchaseHostStyles.delete(host);
        }
        host.removeAttribute(MOONCAKE_ENH_COST_MARKET_HOST_ATTR);
        const primaryItem = host.firstElementChild;
        const primaryItemStyle = mooncakeEnhanceCostPurchaseFirstChildStyles.get(primaryItem);
        if (primaryItemStyle) {
            Object.assign(primaryItem.style, primaryItemStyle);
            mooncakeEnhanceCostPurchaseFirstChildStyles.delete(primaryItem);
        }
    }

    function ensureMooncakeEnhanceCostMarketButtons(panel) {
        const costRoot = panel?.querySelector?.('[class*="SkillActionDetail_costs"]');
        const requirements = costRoot?.querySelector?.('[class*="SkillActionDetail_itemRequirements"]');
        if (!requirements) {
            mooncakeRemoveEnhanceCostMarketButtons(panel || document);
            return;
        }

        // MWITools may wrap the material cells while rebuilding its shortage
        // grid. Query descendants rather than relying on React's direct-child
        // shape so the shortcuts return after either rendering path.
        const itemContainers = [...new Set(
            [...requirements.querySelectorAll('[class*="Item_itemContainer"]')]
        )];
        const materialEntries = itemContainers
            .map(itemContainer => ({ itemContainer, itemHrid: mooncakeGetEnhanceCostItemHrid(itemContainer) }))
            .filter(entry => entry.itemHrid && entry.itemHrid !== '/items/coin' && entry.itemHrid !== '/items/coins')
            .map(entry => ({ ...entry, shopItem: mooncakeGetCoinShopItem(entry.itemHrid) }));
        if (!materialEntries.length) {
            // A transient MWITools rebuild may expose an empty grid for one
            // frame. Do not cache that empty result or discard still-mounted
            // controls; a later material refresh can then inject normally.
            requirements.removeAttribute(MOONCAKE_ENH_COST_MARKET_SIG_ATTR);
            if (itemContainers.length) mooncakeRemoveEnhanceCostMarketButtons(requirements);
            return;
        }
        const signature = materialEntries
            .map(entry => `${entry.itemHrid}:${entry.shopItem ? `shop:${entry.shopItem.price}` : 'market'}`)
            .join('|');
        const existingButtonsMatch = requirements.getAttribute(MOONCAKE_ENH_COST_MARKET_SIG_ATTR) === signature &&
            materialEntries.every(({ itemContainer, itemHrid }) =>
                [...itemContainer.querySelectorAll(`[${MOONCAKE_ENH_COST_MARKET_ATTR}="1"]`)]
                    .some(button => button.dataset.itemHrid === itemHrid)
            );
        if (existingButtonsMatch) return;

        mooncakeRemoveEnhanceCostMarketButtons(requirements);
        for (const { itemContainer, itemHrid, shopItem } of materialEntries) {
            const purchaseLabel = shopItem
                ? (isZH ? `前往${getItemName(itemHrid) || '材料'}系统商店` : `Open ${getItemName(itemHrid) || 'material'} shop`)
                : (isZH ? `打开${getItemName(itemHrid) || '材料'}市场` : `Open ${getItemName(itemHrid) || 'material'} market`);
            const host = mooncakePrepareEnhanceCostPurchaseHost(itemContainer);
            if (!host) continue;
            const isProcurementHost = !!host.closest?.('.mwi-procurement-requirement-grid, .mwi-procurement-panel');

            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'mooncake-enh-cost-market-btn';
            button.setAttribute(MOONCAKE_ENH_COST_MARKET_ATTR, '1');
            button.dataset.itemHrid = itemHrid;
            button.setAttribute('aria-label', purchaseLabel);
            Object.assign(button.style, {
                position: 'static',
                width: '22px',
                minWidth: '22px',
                maxWidth: '22px',
                height: '22px',
                minHeight: '22px',
                maxHeight: '22px',
                padding: '3px',
                display: 'inline-flex',
                flex: '0 0 22px',
                margin: '0',
                alignItems: 'center',
                justifyContent: 'center',
                border: shopItem ? '1px solid rgba(228,184,99,.52)' : '1px solid rgba(133,165,229,.42)',
                borderRadius: '4px',
                background: shopItem ? 'rgba(64,48,25,.9)' : 'rgba(31,39,63,.9)',
                color: 'rgba(213,229,255,.96)',
                cursor: 'pointer',
                lineHeight: '1',
                boxSizing: 'border-box'
            });
            const icon = mooncakeCreateMiscIconSvg(shopItem ? 'shop' : 'marketplace', 14);
            if (icon) button.appendChild(icon);
            else button.textContent = shopItem ? 'S' : 'M';
            if (isProcurementHost) {
                Object.assign(button.style, {
                    position: 'absolute',
                    top: '50%',
                    right: '0',
                    transform: 'translateY(-50%)',
                    zIndex: '1'
                });
            }
            bindTooltip(button, () => mooncakeBuildEnhanceCostPurchaseTooltipHtml(itemHrid));
            button.addEventListener('click', async event => {
                event.preventDefault();
                event.stopPropagation();
                hideTooltip();
                const opened = await mooncakeOpenMaterialPurchaseSource(itemHrid, 1);
                if (opened && !mooncakeGetCoinShopItem(itemHrid) && event.isTrusted) {
                    mooncakeQueueQ7MarketReport(itemHrid, 0);
                }
            });

            host.appendChild(button);
        }
        requirements.setAttribute(MOONCAKE_ENH_COST_MARKET_SIG_ATTR, signature);
    }

    function mooncakeIsEnhanceCurrentActionTab(panel) {
        if (!panel) return false;
        const container = panel.closest('[class*="MainPanel_subPanelContainer"]') ||
                          panel.closest('[class*="MainPanel_mainPanel"]') ||
                          panel.parentElement;
        const searchRoot = container || document;
        const selectedTabs = searchRoot.querySelectorAll('button.Mui-selected[role="tab"], button[aria-selected="true"][role="tab"]');
        for (const tab of selectedTabs) {
            const text = (tab.textContent || '').replace(/\s+/g, ' ').trim();
            if (/当前行动|current\s*action/i.test(text)) return true;
            const tabs = [...(tab.parentElement?.querySelectorAll?.('[role="tab"]') || [])];
            if (tabs.length >= 2 && tabs[1] === tab) return true;
        }
        const tabPanels = panel.querySelectorAll('[class*="TabsComponent_tabPanelsContainer"] [class*="TabPanel_tabPanel"]');
        if (tabPanels.length >= 2) {
            const secondPanel = tabPanels[1];
            const className = typeof secondPanel.className === 'string' ? secondPanel.className : '';
            if (!secondPanel.hidden && !className.includes('TabPanel_hidden')) return true;
        }
        return false;
    }

    function mooncakeGetItemIdFromSlot(slotNode) {
        const useNodes = [...(slotNode?.querySelectorAll?.('use') || [])];
        const useNode = useNodes.find(node => {
            const href = node.getAttribute('href') || node.getAttribute('xlink:href') || node.href?.baseVal || '';
            return href.includes('items_sprite');
        }) || useNodes[0];
        if (!useNode) return null;
        const href = useNode.getAttribute('href') || useNode.getAttribute('xlink:href') || useNode.href?.baseVal || '';
        const sharpIndex = href.indexOf('#');
        if (sharpIndex < 0) return null;
        return href.slice(sharpIndex + 1) || null;
    }

    function mooncakeNormalizeItemIdToHrid(itemId) {
        const id = String(itemId || '').trim().replace(/^items_/, '').replace(/^item_/, '');
        return id ? `/items/${id}` : null;
    }

    function mooncakeHridFromUseNode(useNode) {
        if (!useNode) return null;
        const href = useNode.getAttribute('href') || useNode.getAttribute('xlink:href') || useNode.href?.baseVal || '';
        const sharpIndex = href.indexOf('#');
        if (sharpIndex < 0) return null;
        return mooncakeNormalizeItemIdToHrid(href.slice(sharpIndex + 1));
    }

    function mooncakeGetEnhanceProtectionSlot(panel) {
        if (!panel) return null;
        const namedContainer = panel.querySelector('[class*="SkillActionDetail_protectionItemInputContainer"]');
        const namedSlot = namedContainer?.matches?.('[class*="ItemSelector_itemSelector"], [class*="ItemSelector_empty"]')
            ? namedContainer
            : namedContainer?.querySelector?.('[class*="ItemSelector_itemSelector"], [class*="ItemSelector_empty"]');
        if (namedSlot && !namedSlot.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL)) return namedSlot;
        const slots = [...panel.querySelectorAll('[class*="ItemSelector_itemSelector"]')]
            .filter(slot => !slot.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL));
        if (slots.length >= 2) return slots[1];
        const emptySlots = [...panel.querySelectorAll('[class*="ItemSelector_empty"]')]
            .filter(slot => !slot.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL));
        // With no selected primary item the only empty selector is the
        // equipment slot itself, not a protection slot.
        return emptySlots[1] || null;
    }

    function mooncakeGetEnhanceBaseItemSlot(panel) {
        if (!panel) return null;
        const namedSlot = panel.querySelector('[class*="SkillActionDetail_primaryItemSelectorContainer"]');
        if (namedSlot && !namedSlot.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL)) return namedSlot;
        const slots = [...panel.querySelectorAll('[class*="ItemSelector_itemSelector"]')]
            .filter(slot => !slot.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL));
        if (slots.length >= 1) return slots[0];
        const itemSelector = panel.querySelector('[class*="ItemSelector_itemContainer"], [class*="SkillActionDetail_itemContainer"]');
        return itemSelector && !itemSelector.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL) ? itemSelector : null;
    }

    function mooncakeGetEnhanceBaseItemHrid(panel) {
        const baseSlot = mooncakeGetEnhanceBaseItemSlot(panel);
        const baseHrid = mooncakeNormalizeItemIdToHrid(mooncakeGetItemIdFromSlot(baseSlot));
        if (mooncakeIsEnhanceableItem(baseHrid)) return baseHrid;

        const protSlot = mooncakeGetEnhanceProtectionSlot(panel);
        const uses = panel.querySelectorAll('use');
        for (const use of uses) {
            if (use.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL)) continue;
            if (use.closest?.('[class*="ItemSelector_itemList"]')) continue;
            if (protSlot?.contains?.(use)) continue;
            const hrid = mooncakeHridFromUseNode(use);
            if (mooncakeIsEnhanceableItem(hrid)) return hrid;
        }
        return null;
    }

    function mooncakeGetEnhanceBaseItemLevel(panel, isCurrentAction = false) {
        const snapshotFresh = mooncakeEnhanceSnapshot && Date.now() - mooncakeEnhanceSnapshot.ts < 90 * 1000;
        if (isCurrentAction && snapshotFresh && Number.isFinite(mooncakeEnhanceSnapshot.itemLevel)) {
            return Math.max(0, Math.min(20, mooncakeEnhanceSnapshot.itemLevel | 0));
        }

        const baseSlot = mooncakeGetEnhanceBaseItemSlot(panel);
        const levelNode = baseSlot?.querySelector?.('[class*="Item_enhancementLevel"], [class*="enhancementLevel"]');
        const fromNode = mooncakeParseEnhanceLevelText(levelNode?.textContent);
        if (Number.isFinite(fromNode)) return fromNode;

        // Do not parse a bare number from the slot: it can be the inventory stack count.
        const plusMatch = String(baseSlot?.textContent || '').match(/\+\s*(\d{1,2})/);
        if (plusMatch) return Math.max(0, Math.min(20, parseInt(plusMatch[1], 10) || 0));
        return 0;
    }

    function mooncakeGetEnhanceProtectionHrid(panel, baseHrid = null) {
        const protSlot = mooncakeGetEnhanceProtectionSlot(panel);
        const itemId = mooncakeGetItemIdFromSlot(protSlot);
        const hrid = mooncakeNormalizeItemIdToHrid(itemId);
        if (!mooncakeGetItemDetailOfHrid(hrid)) return null;
        const selectedBaseHrid = baseHrid || mooncakeGetEnhanceBaseItemHrid(panel);
        if (!selectedBaseHrid) return null;
        const allowed = new Set((getProtectionItems(selectedBaseHrid) || []).filter(Boolean));
        return allowed.has(hrid) ? hrid : null;
    }

    function mooncakeGetEnhanceProtectionSlotCount(panel, protectionHrid = null) {
        const slot = mooncakeGetEnhanceProtectionSlot(panel);
        if (!slot) return null;
        const selected = mooncakeNormalizeItemIdToHrid(mooncakeGetItemIdFromSlot(slot));
        if (protectionHrid && !mooncakeEnhanceHridsMatch(selected, protectionHrid)) return null;
        const countNode = slot.querySelector('[class*="Item_count"], [class*="itemCount"]');
        const values = mooncakeParseEnhanceRequirementNumbers(countNode?.textContent || '');
        return values.length ? values.at(-1) : null;
    }

    function mooncakeParseEnhanceLevelText(value) {
        const match = String(value || '').match(/\+?\s*(\d{1,2})/);
        if (!match) return null;
        const level = parseInt(match[1], 10);
        return Number.isFinite(level) ? Math.max(0, Math.min(20, level)) : null;
    }

    function mooncakeFindEnhanceRepeatCountInput(panel) {
        const scope = panel || mooncakeFindEnhancingPanel();
        if (!scope) return null;

        const selectors = [
            '[class*="maxActionCountInput"] input',
            '[class*="maxActionCountInputContainer"] input',
            'input[placeholder*="重复"]',
            'input[placeholder*="Repeat"]',
            'input[placeholder*="Count"]'
        ];
        for (const selector of selectors) {
            const input = scope.querySelector(selector);
            if (input && !input.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL)) return input;
        }

        return [...scope.querySelectorAll('input')].find(input => {
            if (input.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL)) return false;
            const label = `${input.placeholder || ''} ${input.getAttribute('aria-label') || ''} ${input.name || ''}`;
            return /重复|repeat|count/i.test(label);
        }) || null;
    }

    function mooncakeFindEnhancePlanCountInput(panel) {
        const scope = panel || mooncakeFindEnhancingPanel();
        if (!scope) return null;

        // Mooncake's current-action plan input takes priority.
        const mooncakeInput = scope.querySelector(`input[${MOONCAKE_ENH_CURRENT_PLAN_INPUT_ATTR}="1"]`);
        if (mooncakeInput instanceof HTMLInputElement && !mooncakeInput.disabled && !mooncakeInput.readOnly) {
            return mooncakeInput;
        }

        // Do not write another plugin's manual-plan control. Its own event
        // sequence and observers are outside Mooncake's render transaction.
        return null;
    }

    function mooncakeFindEnhanceTargetLevelInput(panel) {
        const scope = panel || mooncakeFindEnhancingPanel();
        if (!scope) return null;
        const named = scope.querySelector('[class*="enhancingMaxLevelInputContainer"] input, [class*="EnhancingMaxLevelInputContainer"] input');
        if (named && !named.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL)) return named;
        return [...scope.querySelectorAll('input[type="number"]')]
            .filter(input => !input.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL))[0] || null;
    }

    function mooncakeFindEnhanceProtectionLevelInput(panel) {
        const scope = panel || mooncakeFindEnhancingPanel();
        if (!scope) return null;
        const named = scope.querySelector('[class*="protectionMinLevelInputContainer"] input, [class*="ProtectionMinLevelInputContainer"] input');
        if (named && !named.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL)) return named;
        return [...scope.querySelectorAll('input[type="number"]')]
            .filter(input => !input.closest?.(MOONCAKE_ENH_PREVIEW_EXCLUDE_SEL))[1] || null;
    }

    function mooncakeReadEnhanceRepeatCount(input) {
        const raw = String(input?.value ?? input?.getAttribute?.('value') ?? '').trim();
        if (!raw || /∞|无限|unlimited|infinity/i.test(raw)) return 0;
        const numeric = Number.parseInt(raw.replace(/[\s,]/g, ''), 10);
        return Number.isFinite(numeric) && numeric > 0 ? Math.floor(numeric) : 0;
    }

    function mooncakeSetEnhanceRepeatCount(input, value, options = null) {
        if (!(input instanceof HTMLInputElement)) return false;
        const nextValue = String(value);
        const previousValue = input.value;
        const dispatchChange = options?.dispatchChange !== false;
        const nativeValueSetter = Object.getOwnPropertyDescriptor(
            HTMLInputElement.prototype,
            'value'
        )?.set;

        // Use the native setter once, then restore React's previous-value
        // tracker before dispatching. Writing through the wrapped setter first
        // and the native setter second can make React restore the old value.
        if (nativeValueSetter) nativeValueSetter.call(input, nextValue);
        else input.value = nextValue;
        if (input._valueTracker) input._valueTracker.setValue(previousValue);
        input.dispatchEvent(new Event('input', { bubbles: true }));
        if (dispatchChange) input.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
    }

    function mooncakeIsEnhanceNativeRepeatWriteSuppressed() {
        return Date.now() < mooncakeEnhanceNativeRepeatSuppressUntil;
    }

    function mooncakeWriteNativeEnhanceRepeatCount(panel, input, value) {
        if (!(input instanceof HTMLInputElement)) return false;

        const token = ++mooncakeEnhanceNativeRepeatWriteToken;
        const scope = panel || mooncakeFindEnhancingPanel();
        const itemHrid = mooncakeGetEnhanceBaseItemHrid(scope);
        if (mooncakeEnhanceNativeRepeatSettleTimer) {
            clearTimeout(mooncakeEnhanceNativeRepeatSettleTimer);
            mooncakeEnhanceNativeRepeatSettleTimer = 0;
        }
        if (mooncakeEnhanceNativeRepeatWriteInput instanceof HTMLInputElement) {
            mooncakeEnhanceNativeRepeatWriteInput.removeAttribute('data-mooncake-enhance-native-repeat-write');
        }
        // A refresh queued just before this write can otherwise run while the
        // game and MWITools are replacing the requirement rows. It would read
        // that transient tree and rebuild the enhancement reference against it.
        if (_pendingEnhanceProtectionBuyRaf) {
            clearTimeout(_pendingEnhanceProtectionBuyRaf);
            _pendingEnhanceProtectionBuyRaf = null;
        }
        if (mooncakeEnhancePlanLayoutRefreshTimer) {
            clearTimeout(mooncakeEnhancePlanLayoutRefreshTimer);
            mooncakeEnhancePlanLayoutRefreshTimer = 0;
        }
        mooncakeEnhanceNativeRepeatWriteInput = input;
        // The game and companion plugins can replace several enhancement nodes
        // after an input event. MWITools completes its own 0/80/220/450 ms
        // passes before Mooncake is allowed to reconcile the compact shortage
        // view; do not rebuild the market layout in the meantime.
        mooncakeEnhanceNativeRepeatSuppressUntil = Date.now() + MOONCAKE_ENH_NATIVE_REPEAT_SETTLE_MS;
        mooncakeEnhanceNativeRepeatRefreshPending = false;
        mooncakeEnhanceNativeRepeatLayoutPending = false;
        input.setAttribute('data-mooncake-enhance-native-repeat-write', '1');

        // Preserve the game's normal input/change contract. Mooncake's own
        // observers are held by this transaction until React finishes replacing
        // the affected enhancement controls.
        const applied = mooncakeSetEnhanceRepeatCount(input, value);
        if (!applied) {
            input.removeAttribute('data-mooncake-enhance-native-repeat-write');
            mooncakeEnhanceNativeRepeatWriteInput = null;
            mooncakeEnhanceNativeRepeatSuppressUntil = 0;
            return false;
        }

        let settleRetryCount = 0;
        const settle = () => {
            if (token !== mooncakeEnhanceNativeRepeatWriteToken) return;
            const remaining = mooncakeEnhanceNativeRepeatSuppressUntil - Date.now();
            if (remaining > 0) {
                mooncakeEnhanceNativeRepeatSettleTimer = setTimeout(settle, remaining);
                return;
            }
            mooncakeEnhanceNativeRepeatSettleTimer = 0;
            if (mooncakeEnhanceNativeRepeatWriteInput === input) {
                input.removeAttribute('data-mooncake-enhance-native-repeat-write');
                mooncakeEnhanceNativeRepeatWriteInput = null;
            }
            mooncakeEnhanceNativeRepeatRefreshPending = false;
            mooncakeEnhanceNativeRepeatLayoutPending = false;
            const livePanel = mooncakeFindEnhancingPanel();
            const snapshotFresh = mooncakeEnhanceSnapshot && Date.now() - mooncakeEnhanceSnapshot.ts < 90 * 1000;
            const liveItemHrid = mooncakeGetEnhanceBaseItemHrid(livePanel) ||
                (snapshotFresh ? mooncakeEnhanceSnapshot.itemHrid : null);
            const liveComponent = livePanel?.querySelector?.('[class*="SkillActionDetail_enhancingComponent"]') || null;
            const sameItem = !!livePanel?.isConnected && (!itemHrid || liveItemHrid === itemHrid);
            if (!sameItem || !liveComponent?.isConnected) {
                // React occasionally commits the new panel just after the
                // suppression window. Retry that transient state once, but do
                // not revive a reference after the player changed items.
                const canRetry = settleRetryCount < 1 &&
                    (!livePanel?.isConnected || !liveItemHrid || !liveComponent?.isConnected);
                if (canRetry) {
                    settleRetryCount += 1;
                    mooncakeEnhanceNativeRepeatSettleTimer = setTimeout(settle, 100);
                }
                return;
            }
            // React can replace the complete enhancing component while applying
            // the repeat value. Recreate the reference only if that removed
            // its shell; otherwise preserve the existing no-layout refresh.
            requestAnimationFrame(() => {
                if (token !== mooncakeEnhanceNativeRepeatWriteToken) return;
                try {
                    const currentPanel = mooncakeFindEnhancingPanel();
                    const currentComponent = currentPanel?.querySelector?.('[class*="SkillActionDetail_enhancingComponent"]') || null;
                    const column = document.getElementById(MOONCAKE_ENH_MARKET_PLAN_COLUMN_ID);
                    const marketPlanSurvived = column?.isConnected && column.parentElement === currentComponent;
                    ensureMooncakeEnhanceProtectionBuyBox({ skipMarketPlan: marketPlanSurvived });

                    // MWITools can replace the procurement requirement rows a
                    // little after the native repeat input settles. Recheck
                    // only the compact material shortcuts against that final
                    // DOM; do not rebuild the market reference or recalculate
                    // the planning layout.
                    setTimeout(() => {
                        if (token !== mooncakeEnhanceNativeRepeatWriteToken) return;
                        const settledPanel = mooncakeFindEnhancingPanel();
                        const settledItemHrid = mooncakeGetEnhanceBaseItemHrid(settledPanel) ||
                            (snapshotFresh ? mooncakeEnhanceSnapshot?.itemHrid : null);
                        if (!settledPanel?.isConnected || (itemHrid && settledItemHrid !== itemHrid)) return;
                        ensureMooncakeEnhanceCostMarketButtons(settledPanel);
                    }, 180);
                } catch (error) {
                    console.error('[MoonCake] 重复次数收尾刷新失败:', error);
                }
            });
        };

        requestAnimationFrame(() => requestAnimationFrame(() => {
            if (token !== mooncakeEnhanceNativeRepeatWriteToken) return;
            mooncakeEnhanceNativeRepeatSettleTimer = setTimeout(settle, 120);
        }));
        return true;
    }

    function mooncakeAddExpectedEnhanceAttempts(panel, expectedActions) {
        const increment = Math.max(1, Math.ceil(Number(expectedActions) || 0));
        if (!(increment > 0)) return { applied: false, increment: 0 };

        // Current action updates Mooncake's plan count, while older non-current
        // views retain compatibility with the standalone Market Mate input.
        const planInput = mooncakeFindEnhancePlanCountInput(panel);
        if (planInput) {
            const previousValue = mooncakeReadEnhanceRepeatCount(planInput);
            const maxAttr = String(planInput.max || '').trim();
            const inputMax = maxAttr ? Number(maxAttr) : NaN;
            const maxCount = Number.isFinite(inputMax) && inputMax >= 0
                ? Math.floor(inputMax)
                : Number.MAX_SAFE_INTEGER;
            const next = Math.min(maxCount, previousValue + increment);
            if (next <= previousValue) {
                return {
                    applied: false,
                    mode: 'plan',
                    increment,
                    current: previousValue,
                    next
                };
            }

            const applied = mooncakeSetEnhanceRepeatCount(planInput, next);
            if (applied) scheduleMooncakeEnhanceProtectionBuyBox(0);
            return {
                applied,
                mode: 'plan',
                increment,
                current: previousValue,
                next
            };
        }

        // The current-action page no longer has Market Mate's input. Never
        // write to the native repeat control here: it expands the game's preset
        // buttons and changes the panel layout.
        if (mooncakeIsEnhanceCurrentActionTab(panel)) {
            scheduleMooncakeEnhanceProtectionBuyBox(0);
            return { applied: false, mode: 'plan', increment, current: 0, next: 0 };
        }

        const input = mooncakeFindEnhanceRepeatCountInput(panel);
        if (!input) return { applied: false, increment: 0 };

        const current = mooncakeReadEnhanceRepeatCount(input);
        const maxAttr = String(input.max || '').trim();
        const inputMax = maxAttr ? Number(maxAttr) : NaN;
        const maxCount = Number.isFinite(inputMax) && inputMax >= 0
            ? Math.floor(inputMax)
            : Number.MAX_SAFE_INTEGER;
        const next = Math.min(maxCount, current + increment);
        if (next <= current) return { applied: false, increment, current, next };

        const applied = mooncakeWriteNativeEnhanceRepeatCount(panel, input, next);
        return { applied, mode: 'repeat', increment, current, next };
    }

    function mooncakeGetEnhanceTargetLevel(panel, isCurrentAction) {
        if (isCurrentAction) {
            const currentActionInput = panel?.querySelector?.('[class*="SkillActionDetail_enhancingMaxLevelInputContainer"] [class*="SkillActionDetail_input"]') ||
                panel?.querySelector?.('[class*="SkillActionDetail_enhancingMaxLevelInputContainer"]');
            const currentActionLevel = mooncakeParseEnhanceLevelText(currentActionInput?.textContent);
            if (Number.isFinite(currentActionLevel)) return currentActionLevel;
            if (Number.isFinite(mooncakeEnhanceSnapshot?.targetLevel)) {
                return Math.max(0, Math.min(20, mooncakeEnhanceSnapshot.targetLevel | 0));
            }
        }
        const raw = mooncakeFindEnhanceTargetLevelInput(panel)?.value;
        const level = parseInt(String(raw ?? ''), 10);
        if (Number.isFinite(level)) return Math.max(0, Math.min(20, level));
        if (Number.isFinite(mooncakeEnhanceSnapshot?.targetLevel)) {
            return Math.max(0, Math.min(20, mooncakeEnhanceSnapshot.targetLevel | 0));
        }
        return null;
    }

    function mooncakeGetEnhanceProtectLevel(panel, targetLevel, isCurrentAction, protHrid) {
        const tl = Number(targetLevel);
        if (!Number.isFinite(tl) || tl <= 0) return 2;

        let raw = NaN;
        if (isCurrentAction) {
            const currentActionInput = panel?.querySelector?.('[class*="SkillActionDetail_protectionMinLevelInputContainer"] [class*="SkillActionDetail_input"]') ||
                panel?.querySelector?.('[class*="SkillActionDetail_protectionMinLevelInputContainer"]');
            const currentActionLevel = mooncakeParseEnhanceLevelText(currentActionInput?.textContent);
            if (Number.isFinite(currentActionLevel)) {
                raw = currentActionLevel;
            } else if (Number.isFinite(mooncakeEnhanceSnapshot?.protectionMinLevel)) {
                raw = mooncakeEnhanceSnapshot.protectionMinLevel;
            }
        } else {
            raw = parseInt(String(mooncakeFindEnhanceProtectionLevelInput(panel)?.value ?? ''), 10);
        }

        if (!protHrid || !Number.isFinite(raw) || raw <= 0 || raw >= tl) return tl;
        return Math.max(1, Math.min(tl, raw | 0));
    }

    function mooncakeGetNearLowestAskProtectionCandidates(itemHrid, sourceMarketData = null) {
        if (!itemHrid) return [];
        const protectionItems = [...new Set((getProtectionItems(itemHrid) || []).filter(Boolean))];
        if (!protectionItems.length) return [];

        const marketData = sourceMarketData || getMarketData();
        const candidates = protectionItems
            .map((hrid, index) => ({
                hrid,
                index,
                ask: mooncakeGetMarketAskPrice(hrid, marketData),
                bid: mooncakeGetMarketBidPrice(hrid, marketData)
            }))
            // The shortcut is for buying materials, so a buy order must not
            // make an unavailable material appear cheaper than a sell order.
            .filter(candidate => candidate.ask > 0);

        if (!candidates.length) return [];
        const lowestAsk = Math.min(...candidates.map(candidate => candidate.ask));
        const upperAsk = lowestAsk * (1 + MOONCAKE_ENH_PROTECTION_NEAR_ASK_RATIO);
        return candidates
            .filter(candidate => candidate.ask <= upperAsk + 1e-8)
            .map(candidate => ({
                ...candidate,
                priceDeltaRatio: lowestAsk > 0 ? (candidate.ask - lowestAsk) / lowestAsk : 0
            }))
            .sort((left, right) => left.ask - right.ask || left.index - right.index)
            .slice(0, MOONCAKE_ENH_PROTECTION_NEAR_ASK_LIMIT);
    }

    function mooncakeFormatEnhanceProtectionOrderPrice(value) {
        const price = mooncakeGetPositivePrice(value);
        if (!(price > 0)) return '-';
        return mooncakeFormatMarketPrice(price).replace(/K$/, 'k');
    }

    function mooncakeBuildProtectionBuyTooltipHtml(protHrid, shortage = null) {
        const itemName = getItemName(protHrid) || protHrid;
        let html = `<div class="tt-header">${isZH ? '保护材料购买' : 'Protection material'}</div>`
            + `<span class="tt-label">${isZH ? '材料:' : 'Material:'}</span> <span class="tt-value">${itemName}</span>\n`
            + `<span class="tt-label">HRID:</span> <span class="tt-value">${protHrid}</span>`;
        if (shortage?.suggested > 0) {
            html += `\n<span class="tt-label">${isZH ? '计划所需:' : 'Plan needs:'}</span> <span class="tt-value">${mooncakeFormatEnhanceShortage(shortage.suggested)}</span>`
                + `\n<span class="tt-label">${isZH ? '可用库存:' : 'Available:'}</span> <span class="tt-value">${mooncakeFormatEnhanceShortage(shortage.effectiveOwned)}</span>`
                + `\n<span class="tt-label">${isZH ? '缺少:' : 'Short:'}</span> <span class="${shortage.shortage > 0 ? 'tt-profit-neg' : 'tt-profit-pos'}">${mooncakeFormatEnhanceShortage(shortage.shortage)}</span>`;
            if (shortage.cartQuantity > 0) {
                html += `\n<span class="tt-label">${isZH ? '清单已含:' : 'Already in cart:'}</span> <span class="tt-value">${mooncakeFormatEnhanceShortage(shortage.cartQuantity)}</span>`;
            }
        }
        return html;
    }

    function mooncakeBuildEnhanceTargetMarketTooltipHtml(itemHrid, targetLevel) {
        const itemName = getItemName(itemHrid) || itemHrid;
        return `<div class="tt-header">${isZH ? '目标装备市场' : 'Target equipment market'}</div>`
            + `<span class="tt-label">${isZH ? '装备:' : 'Equipment:'}</span> <span class="tt-value">${itemName}</span>\n`
            + `<span class="tt-label">${isZH ? '目标等级:' : 'Target level:'}</span> <span class="tt-value">+${targetLevel}</span>\n`
            + `<span class="tt-label">HRID:</span> <span class="tt-value">${itemHrid}</span>`;
    }

    function mooncakeFormatExpectedQty(value) {
        if (!Number.isFinite(value)) return '-';
        if (value >= 100) return value.toFixed(0);
        if (value >= 10) return value.toFixed(1);
        return value.toFixed(2);
    }

    function mooncakeGetEnhanceExpectedUse(itemHrid, targetLevel, protectLevel, protHrid, startLevel = 0) {
        if (!itemHrid || !Number.isFinite(targetLevel) || targetLevel <= 0) return null;

        let sim = null;
        try {
            sim = Enhancelate(itemHrid, targetLevel, protectLevel, null, startLevel);
        } catch (err) {
            console.error('[Better Loot Tracker] 强化期望消耗计算失败:', err);
            return null;
        }
        if (!sim || !Number.isFinite(sim.actions) || sim.actions <= 0) return null;

        const expectedProtectQty = protHrid && Number(protectLevel) < Number(targetLevel)
            ? (Number(sim.protectCount) || 0)
            : 0;
        return { actions: Number(sim.actions) || 0, expectedProtectQty };
    }

    function mooncakeGetEnhancePanelMarketLevelPrice(itemHrid, level, marketData) {
        const entry = marketData?.marketData?.[itemHrid]?.[String(level)];
        return Number(entry?.a) > 0 ? Number(entry.a) : (Number(entry?.b) > 0 ? Number(entry.b) : 0);
    }

    function mooncakeGetEnhanceSimulationProfiles(itemHrid, startLevel, targetLevel, characterKey) {
        const start = Math.max(0, Math.min(20, Math.floor(Number(startLevel) || 0)));
        const target = Math.max(1, Math.min(20, Math.floor(Number(targetLevel) || 0)));
        if (!itemHrid || target <= start) return [];
        // This cache intentionally excludes every market-price revision. The
        // probability matrix only depends on the character/equipment profile;
        // quote changes merely reprice these stable expected-use results.
        const cacheKey = `${characterKey}|${itemHrid}|${start}|${target}`;
        const cached = mooncakeEnhanceSimulationProfileCache.get(cacheKey);
        if (cached) {
            mooncakeEnhanceSimulationProfileCache.delete(cacheKey);
            mooncakeEnhanceSimulationProfileCache.set(cacheKey, cached);
            return cached;
        }

        const profiles = [];
        const firstProtectAt = target === 1 ? 1 : 2;
        for (let protectAt = firstProtectAt; protectAt <= target; protectAt++) {
            let simulation = null;
            try {
                simulation = Enhancelate(itemHrid, target, protectAt, null, start);
            } catch (_) {
                continue;
            }
            const expectedActions = Number(simulation?.actions);
            if (!(expectedActions > 0)) continue;
            profiles.push({
                protectAt,
                expectedActions,
                expectedProtects: Math.max(0, Number(simulation?.protectCount) || 0)
            });
        }
        return mooncakeSetBoundedMapEntry(
            mooncakeEnhanceSimulationProfileCache,
            cacheKey,
            profiles,
            MOONCAKE_ENHANCE_SIMULATION_PROFILE_CACHE_LIMIT
        );
    }

    function mooncakeBuildEnhancePanelPricingContext(itemHrid, startLevel, marketData) {
        const start = Math.max(0, Math.min(20, Math.floor(Number(startLevel) || 0)));
        const costContext = mooncakeBuildGenericEnhancementCostContext(itemHrid, marketData);
        if (!costContext || !(Number(costContext.perActionCost) >= 0) || !(Number(costContext.secondsPerAction) > 0)) {
            return null;
        }
        const protectionCandidate = mooncakeGetNearLowestAskProtectionCandidates(itemHrid, marketData)[0] || null;
        const protectionPrice = Number(protectionCandidate?.ask) || 0;
        const startResolution = mooncakeResolveEnhancementStartItemPrice(itemHrid, start, marketData);
        const baseItemCost = Number(startResolution?.price) || 0;
        if (!(baseItemCost > 0)) return null;
        const selectionMode = mooncakeGetEnhancementRouteSelectionMode();
        const characterKey = mooncakeCharacterCalcSignature || JSON.stringify(getPlayerEnhanceParams());
        const simulationCharacterKey = `${characterKey}|total=${getEnhancelateTotalSkillLevel()}`;
        return {
            start,
            costContext,
            protectionCandidate,
            protectionPrice,
            startResolution,
            baseItemCost,
            selectionMode,
            simulationCharacterKey,
            dependencySignature: JSON.stringify([
                selectionMode,
                simulationCharacterKey,
                itemHrid,
                start,
                Number(costContext.perActionCost),
                Number(costContext.secondsPerAction),
                baseItemCost,
                protectionCandidate?.hrid || '',
                protectionPrice
            ])
        };
    }

    // This is deliberately separate from the market route engine. The live
    // enhancement panel can only fill a normal protection route, and it may
    // start from an already enhanced item.
    function mooncakeGetEnhancePanelTraditionalRecommendation(
        itemHrid,
        startLevel,
        targetLevel,
        marketData,
        targetPriceOverride = null,
        sharedPricingContext = null
    ) {
        const target = Math.max(1, Math.min(20, Math.floor(Number(targetLevel) || 0)));
        const start = Math.max(0, Math.min(20, Math.floor(Number(startLevel) || 0)));
        if (!itemHrid || target <= start) return null;

        const pricingContext = sharedPricingContext || mooncakeBuildEnhancePanelPricingContext(itemHrid, start, marketData);
        if (!pricingContext) return null;
        const {
            costContext,
            protectionCandidate,
            protectionPrice,
            baseItemCost,
            selectionMode,
            simulationCharacterKey
        } = pricingContext;
        const overriddenTargetPrice = Number(targetPriceOverride) || 0;
        const targetPrice = overriddenTargetPrice > 0
            ? overriddenTargetPrice
            : mooncakeGetEnhancePanelMarketLevelPrice(itemHrid, target, marketData);
        const cacheKey = JSON.stringify([
            pricingContext.dependencySignature,
            target,
            targetPrice
        ]);
        const cached = mooncakeEnhanceQuickRecommendationCache.get(cacheKey);
        if (cached) {
            mooncakeEnhanceQuickRecommendationCache.delete(cacheKey);
            mooncakeEnhanceQuickRecommendationCache.set(cacheKey, cached);
            return cached;
        }

        const recommendations = [];

        const simulationProfiles = mooncakeGetEnhanceSimulationProfiles(itemHrid, start, target, simulationCharacterKey);
        for (const profile of simulationProfiles) {
            const protectAt = Number(profile.protectAt);
            const expectedActions = Number(profile.expectedActions);
            const expectedProtects = Number(profile.expectedProtects) || 0;
            if (expectedProtects > 1e-9 && !(protectionPrice > 0)) continue;

            const totalTimeHours = Number(costContext.secondsPerAction) * expectedActions / 3600;
            if (!(totalTimeHours > 0)) continue;
            const materialCost = Number(costContext.perActionCost) * expectedActions;
            const protectCost = protectionPrice * expectedProtects;
            const totalCost = baseItemCost + materialCost + protectCost;
            const hourlyWage = targetPrice > 0
                ? (targetPrice * MOONCAKE_MARKET_SELL_NET_FACTOR - totalCost) / totalTimeHours
                : null;
            const candidate = {
                routeType: 'traditional',
                itemHrid,
                startLevel: start,
                targetLevel: target,
                protectAt,
                protectionItemHrid: expectedProtects > 1e-9 ? protectionCandidate?.hrid || null : null,
                protectionPrice,
                expectedActions,
                expectedProtects,
                expectedTimeSeconds: totalTimeHours * 3600,
                totalTimeHours,
                materialCost,
                protectCost,
                totalCost,
                targetPrice,
                hourlyWage,
                priceMode: targetPrice > 0 ? selectionMode : 'minCost'
            };
            recommendations.push(candidate);
        }
        const best = mooncakeSelectTraditionalRouteByObjective(
            recommendations,
            selectionMode,
            targetPrice > 0,
            { price: targetPrice }
        );
        if (best) mooncakeSetBoundedMapEntry(
            mooncakeEnhanceQuickRecommendationCache,
            cacheKey,
            best,
            MOONCAKE_ENH_QUICK_RECOMMENDATION_CACHE_LIMIT
        );
        return best;
    }

    function mooncakeDelay(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    function mooncakeNextEnhanceFrame() {
        return new Promise(resolve => {
            if (typeof requestAnimationFrame === 'function') requestAnimationFrame(resolve);
            else setTimeout(resolve, 16);
        });
    }

    async function mooncakeWaitForEnhanceDomValue(readValue, isCurrent = () => true, timeout = 180) {
        const deadline = Date.now() + Math.max(0, Number(timeout) || 0);
        while (isCurrent()) {
            const value = readValue();
            if (value) return value;
            if (Date.now() >= deadline) break;
            await mooncakeNextEnhanceFrame();
        }
        return null;
    }

    async function mooncakeWaitForEnhanceFrames(isCurrent = () => true, frames = 1) {
        const count = Math.max(0, Math.floor(Number(frames) || 0));
        for (let index = 0; index < count; index += 1) {
            if (!isCurrent()) return false;
            await mooncakeNextEnhanceFrame();
        }
        return isCurrent();
    }

    function mooncakeNormalizeEnhanceItemHrid(value) {
        const raw = String(value || '').trim();
        if (!raw) return null;
        return raw.startsWith('/items/') ? raw : mooncakeNormalizeItemIdToHrid(raw);
    }

    function mooncakeEnhanceHridsMatch(left, right) {
        return mooncakeNormalizeEnhanceItemHrid(left) === mooncakeNormalizeEnhanceItemHrid(right);
    }

    function mooncakeHasRenderedLayout(element) {
        return !!element && !!(element.offsetWidth || element.offsetHeight || element.getClientRects?.().length);
    }

    function mooncakeGetVisibleEnhanceItemSelectorLists() {
        return [...document.querySelectorAll('[class*="ItemSelector_itemList"]')]
            .filter(mooncakeHasRenderedLayout);
    }

    async function mooncakeOpenEnhanceProtectionSelector(panel, isCurrent = () => true) {
        if (!isCurrent()) return null;
        let slot = mooncakeGetEnhanceProtectionSlot(panel);
        if (!slot) return null;

        const before = new Set(mooncakeGetVisibleEnhanceItemSelectorLists());
        const clickSlot = () => {
            if (!isCurrent()) return false;
            const clickable = slot?.querySelector?.('[class*="Item_clickable"]') || slot;
            clickable?.click();
            return true;
        };
        const findItemList = () => {
            const visibleLists = mooncakeGetVisibleEnhanceItemSelectorLists();
            return visibleLists.find(list => !before.has(list)) || visibleLists[visibleLists.length - 1] || null;
        };
        if (!clickSlot()) return null;
        let itemList = await mooncakeWaitForEnhanceDomValue(findItemList, isCurrent, 180);
        if (itemList) return itemList;

        // React can replace the protection slot when the enhancement input changes.
        slot = mooncakeGetEnhanceProtectionSlot(panel);
        if (!clickSlot()) return null;
        return mooncakeWaitForEnhanceDomValue(findItemList, isCurrent, 200);
    }

    async function mooncakeSelectEnhanceProtectionMaterial(panel, targetHrid, isCurrent = () => true) {
        const target = mooncakeNormalizeEnhanceItemHrid(targetHrid);
        if (!panel || !target || !isCurrent()) return false;
        let slot = mooncakeGetEnhanceProtectionSlot(panel);
        if (!slot) return false;
        if (mooncakeEnhanceHridsMatch(mooncakeGetItemIdFromSlot(slot), target)) return true;

        let itemList = await mooncakeOpenEnhanceProtectionSelector(panel, isCurrent);
        if (!itemList || !isCurrent()) return false;

        const item = [...itemList.querySelectorAll('[class*="ItemSelector_itemContainer"]')].find(candidate => {
            const candidateHrid = mooncakeNormalizeItemIdToHrid(mooncakeGetItemIdFromSlot(candidate));
            const isEnhanced = !!candidate.querySelector('[class*="Item_enhancementLevel"], [class*="enhancementLevel"]');
            return !isEnhanced && mooncakeEnhanceHridsMatch(candidateHrid, target);
        });
        if (!item) {
            if (!isCurrent()) return false;
            const closeSlot = mooncakeGetEnhanceProtectionSlot(panel);
            (closeSlot?.querySelector?.('[class*="Item_clickable"]') || closeSlot)?.click();
            return false;
        }
        if (!isCurrent()) return false;
        (item.querySelector('[class*="Item_clickable"]') || item).click();
        if (await mooncakeWaitForEnhanceDomValue(
            () => mooncakeEnhanceHridsMatch(mooncakeGetEnhanceProtectionHrid(panel), target),
            isCurrent,
            180
        )) return true;

        // One retry handles the selector reopening after an item-list rebuild.
        itemList = await mooncakeOpenEnhanceProtectionSelector(panel, isCurrent);
        if (!isCurrent()) return false;
        const retryItem = [...(itemList?.querySelectorAll?.('[class*="ItemSelector_itemContainer"]') || [])].find(candidate => {
            const candidateHrid = mooncakeNormalizeItemIdToHrid(mooncakeGetItemIdFromSlot(candidate));
            const isEnhanced = !!candidate.querySelector('[class*="Item_enhancementLevel"], [class*="enhancementLevel"]');
            return !isEnhanced && mooncakeEnhanceHridsMatch(candidateHrid, target);
        });
        if (!retryItem) return false;
        if (!isCurrent()) return false;
        (retryItem.querySelector('[class*="Item_clickable"]') || retryItem).click();
        return !!await mooncakeWaitForEnhanceDomValue(
            () => mooncakeEnhanceHridsMatch(mooncakeGetEnhanceProtectionHrid(panel), target),
            isCurrent,
            200
        );
    }

    async function mooncakeClearEnhanceProtectionMaterial(panel, isCurrent = () => true) {
        if (!panel || !isCurrent()) return false;
        let slot = mooncakeGetEnhanceProtectionSlot(panel);
        if (!slot) return false;
        if (!mooncakeGetEnhanceProtectionHrid(panel)) return true;

        const itemList = await mooncakeOpenEnhanceProtectionSelector(panel, isCurrent);
        if (!itemList || !isCurrent()) return false;
        const removeButton = itemList.querySelector('[class*="ItemSelector_removeButton"]');
        const emptySlot = itemList.querySelector('[class*="ItemSelector_empty"]');
        const action = removeButton || emptySlot?.querySelector('[class*="Item_clickable"]') || emptySlot;
        if (!action) return false;
        if (!isCurrent()) return false;
        action.click();
        return !!await mooncakeWaitForEnhanceDomValue(
            () => !mooncakeGetEnhanceProtectionHrid(panel),
            isCurrent,
            180
        );
    }

    function mooncakeSetEnhanceMarketPlanApplying(active) {
        const column = document.getElementById(MOONCAKE_ENH_MARKET_PLAN_COLUMN_ID);
        if (!column) return;
        if (active) column.setAttribute('data-applying', '1');
        else column.removeAttribute('data-applying');
        column.querySelectorAll('.mooncake-enh-market-plan-quote').forEach(button => {
            const rowPending = button.closest('.mooncake-enh-market-plan-row')?.dataset.pending === '1';
            button.disabled = !!active || rowPending || button.dataset.routeReady !== '1';
        });
    }

    function mooncakeSetEnhanceQuickStatus(itemHrid, message, tone = 'normal', token = mooncakeEnhanceQuickApplyToken) {
        if (token !== mooncakeEnhanceQuickApplyToken) return false;
        mooncakeEnhanceQuickStatus = { itemHrid, message, tone, token, ts: Date.now() };
        scheduleMooncakeEnhanceProtectionBuyBox(0);
        setTimeout(() => {
            if (mooncakeEnhanceQuickStatus?.token === token && Date.now() - mooncakeEnhanceQuickStatus.ts >= 4400) {
                mooncakeEnhanceQuickStatus = null;
                scheduleMooncakeEnhanceProtectionBuyBox(0);
            }
        }, 4500);
        return true;
    }

    async function mooncakeApplyEnhanceQuickRecommendationNow(panel, recommendation, token) {
        const itemHrid = recommendation?.itemHrid;
        const targetLevel = Number(recommendation?.targetLevel);
        const protectAt = Number(recommendation?.protectAt);
        const protectionItemHrid = recommendation?.protectionItemHrid || null;
        const expectedStartLevel = Number(recommendation?.expectedStartLevel);
        const checksStartLevel = Number.isInteger(expectedStartLevel) && expectedStartLevel >= 0 && expectedStartLevel <= 20;
        const needsProtection = !!protectionItemHrid && protectAt > 0 && protectAt < targetLevel;
        const isStillCurrent = () => token === mooncakeEnhanceQuickApplyToken &&
            document.body.contains(panel) &&
            !mooncakeIsEnhanceCurrentActionTab(panel) &&
            mooncakeGetEnhanceBaseItemHrid(panel) === itemHrid &&
            (!checksStartLevel || mooncakeGetEnhanceBaseItemLevel(panel, false) === expectedStartLevel);
        const settleProtectionLevel = async () => {
            if (!needsProtection) return true;
            const deadline = Date.now() + 650;
            let stableMatches = 0;
            while (Date.now() < deadline) {
                if (!isStillCurrent()) return false;
                if (!mooncakeEnhanceHridsMatch(mooncakeGetEnhanceProtectionHrid(panel), protectionItemHrid)) {
                    return false;
                }
                const currentLevel = mooncakeGetEnhanceProtectLevel(panel, targetLevel, false, protectionItemHrid);
                if (currentLevel === protectAt) {
                    // A React-controlled input can briefly retain our value and
                    // then be replaced. Require two reads before declaring it set.
                    stableMatches += 1;
                    if (stableMatches >= 2) return true;
                } else {
                    stableMatches = 0;
                    const input = mooncakeFindEnhanceProtectionLevelInput(panel);
                    if (input) mooncakeSetEnhanceRepeatCount(input, protectAt);
                }
                await mooncakeDelay(35);
            }
            return isStillCurrent() &&
                mooncakeEnhanceHridsMatch(mooncakeGetEnhanceProtectionHrid(panel), protectionItemHrid) &&
                mooncakeGetEnhanceProtectLevel(panel, targetLevel, false, protectionItemHrid) === protectAt;
        };

        if (!panel || !itemHrid || !(targetLevel > 0) || !isStillCurrent()) {
            return { applied: false, message: isZH ? '强化面板已变化，未写入方案' : 'Enhancement panel changed; strategy was not applied' };
        }
        if (!mooncakeFindEnhanceTargetLevelInput(panel)) {
            return { applied: false, message: isZH ? '未找到目标等级输入框' : 'Target-level input not found' };
        }

        const targetInput = mooncakeFindEnhanceTargetLevelInput(panel);
        if (!targetInput || !mooncakeSetEnhanceRepeatCount(targetInput, targetLevel)) {
            return { applied: false, message: isZH ? '目标等级写入失败' : 'Could not set target level' };
        }
        // The game may mount or replace an empty protection selector after the
        // target changes. Let React commit for two frames instead of always
        // delaying a fixed 110 ms; the selector helper still waits longer when
        // a slow client genuinely needs it.
        if (!await mooncakeWaitForEnhanceFrames(isStillCurrent, 2)) {
            return { applied: false, message: isZH ? '装备已切换，已取消旧方案' : 'Item changed; cancelled the previous strategy' };
        }

        let materialReady = true;
        if (needsProtection) {
            materialReady = await mooncakeSelectEnhanceProtectionMaterial(panel, protectionItemHrid, isStillCurrent);
        } else {
            materialReady = await mooncakeClearEnhanceProtectionMaterial(panel, isStillCurrent);
        }
        if (!isStillCurrent()) {
            return { applied: false, message: isZH ? '装备已切换，已取消旧方案' : 'Item changed; cancelled the previous strategy' };
        }
        if (!materialReady) {
            const materialName = getItemName(protectionItemHrid) || protectionItemHrid || (isZH ? '保护材料' : 'protection material');
            return {
                applied: false,
                message: isZH
                    ? `目标 +${targetLevel} 已填入，但未能选择 ${materialName}`
                    : `Target +${targetLevel} was set, but ${materialName} could not be selected`
            };
        }

        // Selecting a material rebuilds the protection-level input in React.
        // Wait for the replacement to settle instead of writing to a stale input.
        let protectionLevelSettled = !needsProtection;
        if (needsProtection) {
            protectionLevelSettled = await settleProtectionLevel();
            if (!protectionLevelSettled) {
                if (!isStillCurrent()) return { applied: false, cancelled: true, message: '' };
                return { applied: false, message: isZH ? '保护等级写入失败' : 'Could not set protection level' };
            }
        }

        // React may also rebuild the target input when it accepts the selection.
        if (!await mooncakeWaitForEnhanceFrames(isStillCurrent, 1)) {
            return { applied: false, message: isZH ? '装备已切换，已取消旧方案' : 'Item changed; cancelled the previous strategy' };
        }
        if (mooncakeGetEnhanceTargetLevel(panel, false) !== targetLevel) {
            const retryTarget = mooncakeFindEnhanceTargetLevelInput(panel);
            if (retryTarget) mooncakeSetEnhanceRepeatCount(retryTarget, targetLevel);
            if (!await mooncakeWaitForEnhanceFrames(isStillCurrent, 1)) {
                return { applied: false, cancelled: true, message: '' };
            }
        }
        if (needsProtection && !mooncakeEnhanceHridsMatch(mooncakeGetEnhanceProtectionHrid(panel), protectionItemHrid)) {
            if (!await mooncakeSelectEnhanceProtectionMaterial(panel, protectionItemHrid, isStillCurrent)) {
                if (!isStillCurrent()) return { applied: false, cancelled: true, message: '' };
                return { applied: false, message: isZH ? '保护材料未能写入' : 'Could not set protection material' };
            }
            protectionLevelSettled = false;
        }
        if (needsProtection && (!protectionLevelSettled ||
            mooncakeGetEnhanceProtectLevel(panel, targetLevel, false, protectionItemHrid) !== protectAt)) {
            if (!await settleProtectionLevel()) {
                if (!isStillCurrent()) return { applied: false, cancelled: true, message: '' };
                return { applied: false, message: isZH ? '保护等级写入失败' : 'Could not set protection level' };
            }
        }

        if (!isStillCurrent()) return { applied: false, cancelled: true, message: '' };
        const targetOk = mooncakeGetEnhanceTargetLevel(panel, false) === targetLevel;
        const materialOk = needsProtection
            ? mooncakeEnhanceHridsMatch(mooncakeGetEnhanceProtectionHrid(panel), protectionItemHrid)
            : !mooncakeGetEnhanceProtectionHrid(panel);
        const protectOk = !needsProtection || mooncakeGetEnhanceProtectLevel(panel, targetLevel, false, protectionItemHrid) === protectAt;
        if (!targetOk || !materialOk || !protectOk) {
            return { applied: false, message: isZH ? '方案未完全写入，请再点一次' : 'Strategy was not fully applied; please try once more' };
        }
        return {
            applied: true,
            message: needsProtection
                ? (isZH ? `已填入 +${targetLevel}，保护 +${protectAt}` : `Applied +${targetLevel}, protect +${protectAt}`)
                : (isZH ? `已填入 +${targetLevel}，不使用保护` : `Applied +${targetLevel} without protection`)
        };
    }

    async function mooncakeApplyEnhanceQuickRecommendation(panel, recommendation) {
        const token = ++mooncakeEnhanceQuickApplyToken;
        mooncakeEnhanceQuickApplyDepth += 1;
        mooncakeEnhanceQuickRefreshPending = true;
        mooncakeSetEnhanceMarketPlanApplying(true);
        try {
            const result = await mooncakeApplyEnhanceQuickRecommendationNow(panel, recommendation, token);
            if (token === mooncakeEnhanceQuickApplyToken && !result.cancelled) {
                mooncakeSetEnhanceQuickStatus(
                    recommendation?.itemHrid,
                    result.message,
                    result.applied ? 'success' : 'error',
                    token
                );
            }
            return { ...result, token, latest: token === mooncakeEnhanceQuickApplyToken };
        } catch (error) {
            const result = {
                applied: false,
                cancelled: token !== mooncakeEnhanceQuickApplyToken,
                message: isZH ? '方案填入失败，请重试' : 'Could not apply the strategy; please retry',
                token,
                latest: token === mooncakeEnhanceQuickApplyToken
            };
            if (result.latest) mooncakeSetEnhanceQuickStatus(recommendation?.itemHrid, result.message, 'error', token);
            console.error('[MoonCake] 强化方案填入失败:', error);
            return result;
        } finally {
            mooncakeEnhanceQuickApplyDepth = Math.max(0, mooncakeEnhanceQuickApplyDepth - 1);
            if (mooncakeEnhanceQuickApplyDepth === 0) mooncakeSetEnhanceMarketPlanApplying(false);
            if (mooncakeEnhanceQuickApplyDepth === 0 && mooncakeEnhanceQuickRefreshPending) {
                mooncakeEnhanceQuickRefreshPending = false;
                scheduleMooncakeEnhanceProtectionBuyBox(0, true);
            }
        }
    }

    function mooncakeIsLazyEnhancementEnabled() {
        return config.features?.lazyEnhancement !== false;
    }

    function mooncakeCloneLazyEnhancementShortcutDefaults() {
        return {
            target: [...MOONCAKE_LAZY_ENHANCEMENT_SHORTCUT_DEFAULTS.target],
            protect: [...MOONCAKE_LAZY_ENHANCEMENT_SHORTCUT_DEFAULTS.protect],
            repeat: [...MOONCAKE_LAZY_ENHANCEMENT_SHORTCUT_DEFAULTS.repeat],
            combined: MOONCAKE_LAZY_ENHANCEMENT_SHORTCUT_DEFAULTS.combined.map(item => ({ ...item }))
        };
    }

    function mooncakeNormalizeLazyEnhancementShortcutNumber(values, minimum, maximum, fallback) {
        if (!Array.isArray(values)) return [...fallback];
        const unique = new Set();
        values.forEach(value => {
            const parsed = Math.round(Number(value));
            if (Number.isInteger(parsed) && parsed >= minimum && parsed <= maximum) unique.add(parsed);
        });
        return [...unique].slice(0, MOONCAKE_LAZY_ENHANCEMENT_SHORTCUT_LIMIT);
    }

    function mooncakeNormalizeLazyEnhancementCombinedShortcuts(values, fallback) {
        if (!Array.isArray(values)) return fallback.map(item => ({ ...item }));
        const normalized = [];
        const identities = new Set();
        values.forEach(value => {
            if (!value || typeof value !== 'object') return;
            const targetLevel = Math.round(Number(value.targetLevel ?? value.target ?? value.enhanceLevel));
            const protectionLevel = Math.round(Number(value.protectionLevel ?? value.protectLevel ?? value.protectAt));
            const repeatCount = Math.round(Number(value.repeatCount ?? value.count ?? 0));
            if (
                !Number.isInteger(targetLevel) || targetLevel < 1 || targetLevel > 20 ||
                !Number.isInteger(protectionLevel) || protectionLevel < 0 || protectionLevel >= targetLevel ||
                !Number.isInteger(repeatCount) || repeatCount < 0 || repeatCount > 99999
            ) return;
            const identity = `${targetLevel}|${protectionLevel}|${repeatCount}`;
            if (identities.has(identity) || normalized.length >= MOONCAKE_LAZY_ENHANCEMENT_SHORTCUT_LIMIT) return;
            identities.add(identity);
            normalized.push({ targetLevel, protectionLevel, repeatCount });
        });
        return normalized;
    }

    function mooncakeNormalizeLazyEnhancementShortcuts(value) {
        const defaults = mooncakeCloneLazyEnhancementShortcutDefaults();
        const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
        return {
            target: mooncakeNormalizeLazyEnhancementShortcutNumber(source.target, 1, 20, defaults.target),
            protect: mooncakeNormalizeLazyEnhancementShortcutNumber(source.protect, 1, 19, defaults.protect),
            repeat: mooncakeNormalizeLazyEnhancementShortcutNumber(source.repeat, 1, 99999, defaults.repeat),
            combined: mooncakeNormalizeLazyEnhancementCombinedShortcuts(source.combined, defaults.combined)
        };
    }

    function mooncakeGetLazyEnhancementShortcuts() {
        return mooncakeNormalizeLazyEnhancementShortcuts(config.lazyEnhancementShortcuts);
    }

    function mooncakeSaveLazyEnhancementShortcuts(value) {
        config.lazyEnhancementShortcuts = mooncakeNormalizeLazyEnhancementShortcuts(value);
        saveConfig();
        mooncakeRemoveLazyEnhancementBar();
        mooncakeScheduleLazyEnhancement();
        return config.lazyEnhancementShortcuts;
    }

    function mooncakeRestoreLazyEnhancementShortcutDefaults() {
        return mooncakeSaveLazyEnhancementShortcuts(mooncakeCloneLazyEnhancementShortcutDefaults());
    }

    function mooncakeNormalizeLazyEnhancementPreset(value) {
        if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
        const itemHrid = mooncakeNormalizeEnhanceItemHrid(value.itemHrid || value.itemId);
        const startLevel = Number(value.startLevel);
        const targetLevel = Number(value.targetLevel);
        if (!itemHrid || !Number.isInteger(targetLevel) || targetLevel < 1 || targetLevel > 20) return null;

        let protectionItemHrid = mooncakeNormalizeEnhanceItemHrid(
            value.protectionItemHrid || value.protectionItemId
        );
        let protectionLevel = Number(value.protectionLevel ?? value.protectAt);
        if (!protectionItemHrid || !Number.isInteger(protectionLevel) || protectionLevel < 1 || protectionLevel >= targetLevel) {
            protectionItemHrid = null;
            protectionLevel = null;
        }
        const updatedAt = Number(value.updatedAt);
        const presetIdentity = `${itemHrid}|${targetLevel}|${protectionItemHrid || ''}|${protectionLevel || ''}`;
        const rawId = String(value.id || '').trim();
        return {
            // startLevel is retained only to migrate old data.  Presets are keyed
            // by the base item now, so selecting the same item at another +level
            // still restores the selected default strategy.
            id: rawId || `legacy:${presetIdentity}`,
            itemHrid,
            startLevel: Number.isInteger(startLevel) && startLevel >= 0 && startLevel <= 20 ? startLevel : null,
            targetLevel,
            protectionItemHrid,
            protectionLevel,
            isDefault: value.isDefault === true,
            updatedAt: Number.isFinite(updatedAt) && updatedAt > 0 ? updatedAt : Date.now()
        };
    }

    function mooncakeGetLazyEnhancementItemKey(itemHrid) {
        const normalizedHrid = mooncakeNormalizeEnhanceItemHrid(itemHrid);
        return normalizedHrid || '';
    }

    // This remains level-aware for the live panel lifecycle only.  Stored plans
    // deliberately use mooncakeGetLazyEnhancementPresetIdentity instead.
    function mooncakeGetLazyEnhancementPresetKey(itemHrid, startLevel) {
        const normalizedHrid = mooncakeGetLazyEnhancementItemKey(itemHrid);
        const normalizedLevel = Number(startLevel);
        if (!normalizedHrid || !Number.isInteger(normalizedLevel) || normalizedLevel < 0 || normalizedLevel > 20) return '';
        return `${normalizedHrid}::${normalizedLevel}`;
    }

    function mooncakeGetLazyEnhancementPresetIdentity(value) {
        const preset = mooncakeNormalizeLazyEnhancementPreset(value);
        if (!preset) return '';
        return `${preset.itemHrid}|${preset.targetLevel}|${preset.protectionItemHrid || ''}|${preset.protectionLevel || ''}`;
    }

    function mooncakeNormalizeLazyEnhancementPresetCollection(values) {
        const deduped = new Map();
        (Array.isArray(values) ? values : []).forEach(value => {
            const preset = mooncakeNormalizeLazyEnhancementPreset(value);
            if (!preset) return;
            const identity = mooncakeGetLazyEnhancementPresetIdentity(preset);
            const existing = deduped.get(identity);
            if (!existing || preset.updatedAt >= existing.updatedAt) deduped.set(identity, preset);
        });
        const presets = [...deduped.values()]
            .sort((left, right) => right.updatedAt - left.updatedAt)
            .slice(0, MOONCAKE_LAZY_ENHANCEMENT_PRESET_LIMIT);
        const defaultByItem = new Map();
        presets.forEach(preset => {
            const current = defaultByItem.get(preset.itemHrid);
            if (!current || (preset.isDefault && !current.isDefault)) defaultByItem.set(preset.itemHrid, preset);
        });
        return presets.map(preset => ({
            ...preset,
            isDefault: defaultByItem.get(preset.itemHrid)?.id === preset.id
        }));
    }

    function mooncakeGetLazyEnhancementPresets() {
        return mooncakeNormalizeLazyEnhancementPresetCollection(config.lazyEnhancementPresets);
    }

    function mooncakeSaveLazyEnhancementPresets(values) {
        config.lazyEnhancementPresets = mooncakeNormalizeLazyEnhancementPresetCollection(values);
        saveConfig();
        return config.lazyEnhancementPresets;
    }

    function mooncakeGetLazyEnhancementPresetsForItem(itemHrid) {
        const key = mooncakeGetLazyEnhancementItemKey(itemHrid);
        return key
            ? mooncakeGetLazyEnhancementPresets().filter(preset => preset.itemHrid === key)
            : [];
    }

    function mooncakeFindLazyEnhancementPreset(itemHrid) {
        return mooncakeGetLazyEnhancementPresetsForItem(itemHrid)
            .find(preset => preset.isDefault) || null;
    }

    function mooncakeFindLazyEnhancementAutoFillPreset(itemHrid, startLevel) {
        const defaultPreset = mooncakeFindLazyEnhancementPreset(itemHrid);
        const currentLevel = Number(startLevel);
        if (!Number.isInteger(currentLevel) || currentLevel < 0 || currentLevel > 20) return defaultPreset;

        // A default remains the user's first choice while it can still advance
        // the item. Once it is complete, continue with the nearest saved target.
        if (defaultPreset?.targetLevel > currentLevel) return defaultPreset;

        return mooncakeGetLazyEnhancementPresetsForItem(itemHrid)
            .filter(preset => preset.targetLevel > currentLevel)
            .sort((left, right) => {
                if (left.targetLevel !== right.targetLevel) return left.targetLevel - right.targetLevel;
                return Number(right.updatedAt || 0) - Number(left.updatedAt || 0);
            })[0] || defaultPreset;
    }

    function mooncakeFindLazyEnhancementPresetById(itemHrid, presetId) {
        const normalizedId = String(presetId || '').trim();
        if (!normalizedId) return null;
        return mooncakeGetLazyEnhancementPresetsForItem(itemHrid)
            .find(preset => preset.id === normalizedId) || null;
    }

    function mooncakeUpsertLazyEnhancementPreset(value, options = {}) {
        const draft = mooncakeNormalizeLazyEnhancementPreset(value);
        if (!draft) return null;
        const presets = mooncakeGetLazyEnhancementPresets();
        const identity = mooncakeGetLazyEnhancementPresetIdentity(draft);
        const existing = presets.find(item => mooncakeGetLazyEnhancementPresetIdentity(item) === identity) || null;
        const makeDefault = options.makeDefault !== false;
        const preset = mooncakeNormalizeLazyEnhancementPreset({
            ...draft,
            id: existing?.id || draft.id || `preset:${Date.now().toString(36)}:${Math.random().toString(36).slice(2, 8)}`,
            isDefault: makeDefault || existing?.isDefault === true,
            updatedAt: Date.now()
        });
        if (!preset) return null;
        const next = presets
            .filter(item => mooncakeGetLazyEnhancementPresetIdentity(item) !== identity)
            .map(item => item.itemHrid === preset.itemHrid && makeDefault ? { ...item, isDefault: false } : item);
        next.unshift(preset);
        mooncakeSaveLazyEnhancementPresets(next);
        return mooncakeFindLazyEnhancementPresetById(preset.itemHrid, preset.id) || preset;
    }

    function mooncakeSetLazyEnhancementPresetDefault(itemHrid, presetId) {
        const key = mooncakeGetLazyEnhancementItemKey(itemHrid);
        const normalizedId = String(presetId || '').trim();
        if (!key || !normalizedId) return false;
        const presets = mooncakeGetLazyEnhancementPresets();
        const target = presets.find(item => item.itemHrid === key && item.id === normalizedId);
        if (!target) return false;
        const next = presets.map(item => item.itemHrid === key
            ? { ...item, isDefault: item.id === normalizedId, updatedAt: item.id === normalizedId ? Date.now() : item.updatedAt }
            : item);
        mooncakeSaveLazyEnhancementPresets(next);
        return true;
    }

    function mooncakeDeleteLazyEnhancementPreset(itemHrid, presetId) {
        const key = mooncakeGetLazyEnhancementItemKey(itemHrid);
        const normalizedId = String(presetId || '').trim();
        if (!key || !normalizedId) return false;
        const presets = mooncakeGetLazyEnhancementPresets();
        const next = presets.filter(item => item.itemHrid !== key || item.id !== normalizedId);
        if (next.length === presets.length) return false;
        mooncakeSaveLazyEnhancementPresets(next);
        return true;
    }

    function mooncakeReadLazyEnhancementDraft(panel) {
        if (!panel || mooncakeIsEnhanceCurrentActionTab(panel)) return null;
        const itemHrid = mooncakeGetEnhanceBaseItemHrid(panel);
        const startLevel = mooncakeGetEnhanceBaseItemLevel(panel, false);
        const targetInput = mooncakeFindEnhanceTargetLevelInput(panel);
        const targetLevel = Number.parseInt(String(targetInput?.value ?? ''), 10);
        if (!itemHrid || !Number.isInteger(targetLevel) || targetLevel <= startLevel) return null;
        const selectedProtectionHrid = mooncakeGetEnhanceProtectionHrid(panel, itemHrid);
        const selectedProtectionLevel = selectedProtectionHrid
            ? mooncakeGetEnhanceProtectLevel(panel, targetLevel, false, selectedProtectionHrid)
            : null;
        return mooncakeNormalizeLazyEnhancementPreset({
            itemHrid,
            startLevel,
            targetLevel,
            protectionItemHrid: selectedProtectionHrid,
            protectionLevel: selectedProtectionLevel,
            updatedAt: Date.now()
        });
    }

    function mooncakeLazyEnhancementPresetsMatch(left, right) {
        const a = mooncakeNormalizeLazyEnhancementPreset(left);
        const b = mooncakeNormalizeLazyEnhancementPreset(right);
        if (!a || !b) return false;
        return mooncakeGetLazyEnhancementItemKey(a.itemHrid) === mooncakeGetLazyEnhancementItemKey(b.itemHrid) &&
            a.targetLevel === b.targetLevel &&
            mooncakeEnhanceHridsMatch(a.protectionItemHrid, b.protectionItemHrid) &&
            a.protectionLevel === b.protectionLevel;
    }

    function mooncakeGetLazyEnhancementPresetSignature(preset) {
        const normalized = mooncakeNormalizeLazyEnhancementPreset(preset);
        if (!normalized) return '';
        return `${normalized.id}|${normalized.updatedAt}|${normalized.isDefault ? 'default' : 'saved'}`;
    }

    function mooncakeHasExternalEnhancementPresetControls() {
        try {
            if (window.mwcEnhancementPresetApi) return true;
            if (typeof unsafeWindow !== 'undefined' && unsafeWindow?.mwcEnhancementPresetApi) return true;
        } catch (_) {}
        return !!document.querySelector(MOONCAKE_LAZY_ENHANCEMENT_EXTERNAL_CONTROLS_SELECTOR);
    }

    function mooncakeSetLazyEnhancementEnabled(value) {
        const enabled = value !== false;
        if (!config.features) config.features = {};
        config.features.lazyEnhancement = enabled;
        saveConfig();
        if (enabled) mooncakeStartLazyEnhancement();
        else mooncakeStopLazyEnhancement();
        try { mooncakeRefreshEnhancementSettingsPanel(); } catch (_) {}
    }

    function mooncakeResetLazyEnhancementAutoFillState() {
        mooncakeLazyEnhancementManualOverrideKey = '';
        mooncakeLazyEnhancementAutoFillSignature = '';
        mooncakeLazyEnhancementAutoFillAttemptSignature = '';
        mooncakeLazyEnhancementAutoFillAttemptCount = 0;
    }

    function mooncakeCreateLazyEnhancementManagerButton(label, tone = 'normal') {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = label;
        Object.assign(button.style, {
            minHeight: '28px', boxSizing: 'border-box', cursor: 'pointer', borderRadius: '4px',
            border: tone === 'danger' ? '1px solid rgba(232,113,132,.48)' : '1px solid rgba(151,171,236,.38)',
            background: tone === 'danger' ? 'rgba(104,47,61,.62)' : 'rgba(57,73,120,.78)',
            color: '#edf2ff', padding: '4px 8px', fontSize: '11px', fontWeight: '800', lineHeight: '1.2', whiteSpace: 'nowrap'
        });
        return button;
    }

    function mooncakeCreateLazyEnhancementSettingsManager(trigger = null) {
        const overlay = document.createElement('div');
        overlay.id = MOONCAKE_LAZY_ENHANCEMENT_MANAGER_ID;
        overlay.tabIndex = -1;
        overlay.setAttribute('role', 'presentation');
        overlay._mooncakeLazyEnhancementManagerTrigger = trigger || null;
        Object.assign(overlay.style, {
            position: 'fixed', inset: '0', zIndex: '2147483647', display: 'grid', placeItems: 'center',
            boxSizing: 'border-box', padding: 'max(12px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right)) max(12px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left))',
            background: 'rgba(4,6,11,.68)', color: '#edf2ff', fontFamily: '-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif'
        });
        const dialog = document.createElement('section');
        dialog.tabIndex = -1;
        dialog.setAttribute('role', 'dialog');
        dialog.setAttribute('aria-modal', 'true');
        dialog.setAttribute('aria-label', isZH ? '强化方案管理' : 'Enhancement plan manager');
        Object.assign(dialog.style, {
            width: 'min(760px, 100%)', maxHeight: 'min(720px, 100%)', minWidth: '0', display: 'flex', flexDirection: 'column',
            overflow: 'hidden', boxSizing: 'border-box', border: '1px solid rgba(145,165,229,.48)', borderRadius: '7px',
            background: '#151923', boxShadow: '0 22px 70px rgba(0,0,0,.62)'
        });
        const header = document.createElement('header');
        Object.assign(header.style, {
            flex: '0 0 auto', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '10px',
            padding: '13px 14px 10px', borderBottom: '1px solid rgba(151,166,217,.16)'
        });
        const heading = document.createElement('div');
        const title = document.createElement('strong');
        title.textContent = isZH ? '强化方案管理' : 'Enhancement plans';
        Object.assign(title.style, { display: 'block', color: '#f3f6ff', fontSize: '16px', fontWeight: '800', lineHeight: '1.25' });
        const subtitle = document.createElement('small');
        subtitle.setAttribute('data-mooncake-lazy-enhancement-manager-subtitle', '1');
        subtitle.textContent = isZH
            ? '默认方案会在同一装备的任意强化等级下自动填入。'
            : 'The default plan auto-fills for this item at any enhancement level.';
        Object.assign(subtitle.style, { display: 'block', marginTop: '3px', color: 'rgba(220,228,248,.62)', fontSize: '11px', lineHeight: '1.4' });
        heading.append(title, subtitle);
        const close = mooncakeCreateLazyEnhancementManagerButton('×');
        close.setAttribute('aria-label', isZH ? '关闭方案管理' : 'Close plan manager');
        close.title = close.getAttribute('aria-label');
        Object.assign(close.style, { width: '30px', minWidth: '30px', minHeight: '30px', padding: '0', fontSize: '22px', lineHeight: '26px', background: 'transparent', borderColor: 'transparent', color: 'rgba(232,238,253,.78)' });
        close.addEventListener('click', () => mooncakeCloseLazyEnhancementSettingsManager());
        header.append(heading, close);

        const tabs = document.createElement('div');
        tabs.setAttribute('role', 'tablist');
        tabs.setAttribute('data-mooncake-lazy-enhancement-manager-tabs', '1');
        Object.assign(tabs.style, {
            flex: '0 0 auto', display: 'flex', alignItems: 'center', gap: '4px', padding: '8px 14px 0',
            borderBottom: '1px solid rgba(151,166,217,.16)'
        });
        const createTab = (view, label) => {
            const button = mooncakeCreateLazyEnhancementManagerButton(label);
            button.setAttribute('role', 'tab');
            button.setAttribute('data-mooncake-lazy-enhancement-manager-tab', view);
            button.addEventListener('click', () => {
                overlay.dataset.activeView = view;
                mooncakeRenderLazyEnhancementSettingsManager();
            });
            return button;
        };
        tabs.append(
            createTab('shortcuts', isZH ? '快捷按钮' : 'Shortcuts'),
            createTab('presets', isZH ? '收藏方案' : 'Saved plans')
        );

        const intro = document.createElement('div');
        intro.setAttribute('data-mooncake-lazy-enhancement-manager-intro', '1');
        intro.textContent = isZH
            ? '在强化页设好目标等级、保护材料和保护起始等级后，点击 ☆ 保存。可为同一装备保留多套组合。'
            : 'Set the target level, protection material, and protection start level on the enhancement page, then choose ☆ to save. Multiple plans can be saved for one item.';
        Object.assign(intro.style, {
            flex: '0 0 auto', margin: '10px 14px 0', padding: '8px 10px', borderLeft: '3px solid rgba(121,148,238,.72)',
            background: 'rgba(55,66,111,.24)', color: 'rgba(224,231,249,.82)', fontSize: '11px', lineHeight: '1.5'
        });
        const host = document.createElement('div');
        host.setAttribute('data-mooncake-lazy-enhancement-manager-list', '1');
        Object.assign(host.style, {
            flex: '1 1 auto', minWidth: '0', minHeight: '0', overflowY: 'auto', overscrollBehavior: 'contain',
            display: 'grid', alignContent: 'start', gap: '13px', padding: '12px 14px 16px', boxSizing: 'border-box'
        });
        dialog.append(header, tabs, intro, host);
        overlay.appendChild(dialog);
        overlay.addEventListener('pointerdown', event => {
            if (event.target === overlay) mooncakeCloseLazyEnhancementSettingsManager();
        });
        overlay.addEventListener('keydown', event => {
            if (event.key === 'Escape') {
                event.preventDefault();
                mooncakeCloseLazyEnhancementSettingsManager();
            }
        });
        return overlay;
    }

    function mooncakeCloseLazyEnhancementSettingsManager(options = {}) {
        const overlay = document.getElementById(MOONCAKE_LAZY_ENHANCEMENT_MANAGER_ID);
        if (!overlay) return;
        const trigger = overlay._mooncakeLazyEnhancementManagerTrigger;
        overlay.remove();
        if (options.restoreFocus !== false && trigger?.isConnected && typeof trigger.focus === 'function') {
            requestAnimationFrame(() => trigger.focus({ preventScroll: true }));
        }
    }

    function mooncakeCreateLazyEnhancementManagerIcon(itemHrid) {
        const icon = document.createElement('span');
        Object.assign(icon.style, {
            width: '38px', height: '38px', minWidth: '38px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
            overflow: 'hidden', border: '1px solid rgba(140,157,220,.32)', borderRadius: '4px', background: 'rgba(31,37,57,.86)', color: '#aebeea', fontSize: '17px'
        });
        const svg = mooncakeCreateItemIconSvg(itemHrid, 34);
        if (svg) icon.appendChild(svg);
        else icon.textContent = '◇';
        return icon;
    }

    function mooncakeCreateLazyEnhancementEditorAction(label, title, tone = 'normal') {
        const button = mooncakeCreateLazyEnhancementManagerButton(label, tone);
        button.title = title || label;
        Object.assign(button.style, {
            minWidth: '26px', minHeight: '26px', height: '26px', padding: '0 6px', fontSize: '12px', lineHeight: '24px'
        });
        return button;
    }

    function mooncakeCreateLazyEnhancementEditorNumber(value, placeholder, minimum, maximum) {
        const input = document.createElement('input');
        input.type = 'number';
        input.inputMode = 'numeric';
        input.min = String(minimum);
        input.max = String(maximum);
        input.step = '1';
        input.placeholder = placeholder;
        input.value = value === '' || value === null || value === undefined ? '' : String(value);
        Object.assign(input.style, {
            boxSizing: 'border-box', width: placeholder === (isZH ? '次数' : 'Count') ? '68px' : '48px', minWidth: '0', height: '28px',
            padding: '3px 5px', border: '1px solid rgba(138,157,218,.38)', borderRadius: '4px',
            background: '#111622', color: '#edf2ff', fontSize: '12px', textAlign: 'center', outline: 'none'
        });
        return input;
    }

    function mooncakeMoveLazyEnhancementShortcutEditorRow(row, direction) {
        const list = row?.parentElement;
        if (!list || !Number.isFinite(direction) || direction === 0) return false;
        const sibling = direction < 0 ? row.previousElementSibling : row.nextElementSibling;
        if (!sibling || !sibling.matches?.(`[data-mooncake-lazy-enhancement-shortcut-editor-row="${row.getAttribute('data-mooncake-lazy-enhancement-shortcut-editor-row')}"]`)) {
            return false;
        }
        if (direction < 0) list.insertBefore(row, sibling);
        else list.insertBefore(sibling, row);
        return true;
    }

    function mooncakeClearLazyEnhancementShortcutEditorDragState(list) {
        if (!list) return;
        list.querySelectorAll('[data-mooncake-lazy-enhancement-shortcut-editor-row]').forEach(row => {
            row.style.opacity = '';
            row.style.transform = '';
            row.style.borderColor = 'rgba(142,160,220,.30)';
            row.style.background = 'rgba(24,30,46,.78)';
        });
        list._mooncakeLazyEnhancementDraggedRow = null;
    }

    function mooncakeCreateLazyEnhancementShortcutEditorRow(kind, value) {
        const row = document.createElement('div');
        row.setAttribute('data-mooncake-lazy-enhancement-shortcut-editor-row', kind);
        row.draggable = true;
        row.tabIndex = 0;
        row.setAttribute('role', 'group');
        row.setAttribute('aria-label', isZH ? '快捷按钮，可拖拽排序；按 Alt 加上下方向键调整顺序' : 'Shortcut. Drag to reorder, or use Alt plus arrow keys.');
        row.title = isZH ? '拖拽排序；按 Alt + 上下方向键调整顺序' : 'Drag to reorder, or use Alt + arrow keys.';
        Object.assign(row.style, {
            position: 'relative', display: 'inline-flex', alignItems: 'center', gap: '3px', minWidth: '0', minHeight: '30px',
            padding: '4px 7px', border: '1px solid rgba(142,160,220,.30)', borderRadius: '4px',
            background: 'rgba(24,30,46,.78)', cursor: 'grab', touchAction: 'manipulation', userSelect: 'none'
        });
        if (kind === 'combined') {
            const target = mooncakeCreateLazyEnhancementEditorNumber(value?.targetLevel, isZH ? '目标' : 'Target', 1, 20);
            target.setAttribute('data-mooncake-lazy-enhancement-shortcut-editor-value', 'targetLevel');
            target.setAttribute('aria-label', isZH ? '组合目标等级' : 'Combined target level');
            const protect = mooncakeCreateLazyEnhancementEditorNumber(value?.protectionLevel, isZH ? '保护' : 'Protect', 0, 19);
            protect.setAttribute('data-mooncake-lazy-enhancement-shortcut-editor-value', 'protectionLevel');
            protect.setAttribute('aria-label', isZH ? '组合保护等级' : 'Combined protection level');
            const repeat = mooncakeCreateLazyEnhancementEditorNumber(value?.repeatCount, isZH ? '次数' : 'Count', 0, 99999);
            repeat.setAttribute('data-mooncake-lazy-enhancement-shortcut-editor-value', 'repeatCount');
            repeat.setAttribute('aria-label', isZH ? '组合重复次数，0 为无限' : 'Combined repeat count, zero is unlimited');
            row.append(target, protect, repeat);
        } else {
            const bounds = kind === 'repeat' ? [1, 99999] : [1, kind === 'protect' ? 19 : 20];
            const input = mooncakeCreateLazyEnhancementEditorNumber(value, kind === 'repeat' ? (isZH ? '次数' : 'Count') : (isZH ? '等级' : 'Level'), bounds[0], bounds[1]);
            input.setAttribute('data-mooncake-lazy-enhancement-shortcut-editor-value', 'value');
            input.setAttribute('aria-label', kind === 'repeat'
                ? (isZH ? '重复次数' : 'Repeat count')
                : (kind === 'protect' ? (isZH ? '保护等级' : 'Protection level') : (isZH ? '目标等级' : 'Target level')));
            row.appendChild(input);
        }

        const remove = mooncakeCreateLazyEnhancementEditorAction('×', isZH ? '删除此快捷按钮' : 'Remove shortcut', 'danger');
        remove.setAttribute('aria-label', isZH ? '删除此快捷按钮' : 'Remove shortcut');
        Object.assign(remove.style, {
            position: 'absolute', top: '-7px', right: '-7px', zIndex: '1', width: '18px', minWidth: '18px', height: '18px', minHeight: '18px',
            padding: '0', borderRadius: '50%', lineHeight: '16px', fontSize: '12px', boxShadow: '0 1px 4px rgba(0,0,0,.42)'
        });
        remove.addEventListener('pointerdown', event => event.stopPropagation());
        remove.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            row.remove();
        });
        row.appendChild(remove);

        row.addEventListener('dragstart', event => {
            if (event.target !== row) {
                event.preventDefault();
                return;
            }
            const list = row.parentElement;
            if (!list) return;
            list._mooncakeLazyEnhancementDraggedRow = row;
            row.style.opacity = '.48';
            row.style.transform = 'scale(1.02)';
            if (event.dataTransfer) {
                event.dataTransfer.effectAllowed = 'move';
                event.dataTransfer.setData('text/plain', kind);
            }
        });
        row.addEventListener('dragover', event => {
            const list = row.parentElement;
            const dragged = list?._mooncakeLazyEnhancementDraggedRow;
            if (!dragged || dragged === row || dragged.parentElement !== list) return;
            event.preventDefault();
            if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
            list.querySelectorAll('[data-mooncake-lazy-enhancement-shortcut-editor-row]').forEach(item => {
                if (item !== row) {
                    item.style.borderColor = 'rgba(142,160,220,.30)';
                    item.style.background = 'rgba(24,30,46,.78)';
                }
            });
            row.style.borderColor = 'rgba(132,171,255,.92)';
            row.style.background = 'rgba(49,63,103,.68)';
        });
        row.addEventListener('dragleave', event => {
            if (!row.contains(event.relatedTarget)) {
                row.style.borderColor = 'rgba(142,160,220,.30)';
                row.style.background = 'rgba(24,30,46,.78)';
            }
        });
        row.addEventListener('drop', event => {
            const list = row.parentElement;
            const dragged = list?._mooncakeLazyEnhancementDraggedRow;
            if (!dragged || dragged === row || dragged.parentElement !== list) return;
            event.preventDefault();
            const bounds = row.getBoundingClientRect();
            const verticallyBefore = event.clientY < bounds.top + (bounds.height / 2);
            const horizontallyBefore = event.clientX < bounds.left + (bounds.width / 2);
            const isOnSameVisualLine = event.clientY >= bounds.top && event.clientY <= bounds.bottom;
            list.insertBefore(dragged, (isOnSameVisualLine ? horizontallyBefore : verticallyBefore) ? row : row.nextSibling);
            mooncakeClearLazyEnhancementShortcutEditorDragState(list);
        });
        row.addEventListener('dragend', () => mooncakeClearLazyEnhancementShortcutEditorDragState(row.parentElement));
        row.addEventListener('keydown', event => {
            if (!event.altKey || (event.key !== 'ArrowUp' && event.key !== 'ArrowDown')) return;
            event.preventDefault();
            event.stopPropagation();
            mooncakeMoveLazyEnhancementShortcutEditorRow(row, event.key === 'ArrowUp' ? -1 : 1);
        });
        return row;
    }

    function mooncakeCreateLazyEnhancementShortcutEditorSection(kind, title, values) {
        const section = document.createElement('section');
        section.setAttribute('data-mooncake-lazy-enhancement-shortcut-editor-section', kind);
        Object.assign(section.style, {
            display: 'grid', gap: '7px', minWidth: '0', padding: '9px', border: '1px solid rgba(151,166,217,.18)',
            borderRadius: '5px', background: 'rgba(22,27,41,.70)'
        });
        const heading = document.createElement('div');
        Object.assign(heading.style, { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '8px', minWidth: '0' });
        const name = document.createElement('strong');
        name.textContent = title;
        Object.assign(name.style, { display: 'block', color: '#f0f4ff', fontSize: '13px', fontWeight: '800', lineHeight: '1.25' });
        const add = mooncakeCreateLazyEnhancementEditorAction('+', isZH ? `添加${title}快捷按钮` : `Add ${title} shortcut`);
        Object.assign(add.style, { flex: '0 0 auto', fontSize: '17px', fontWeight: '800' });
        heading.append(name, add);
        const list = document.createElement('div');
        list.setAttribute('data-mooncake-lazy-enhancement-shortcut-editor-list', kind);
        Object.assign(list.style, { display: 'flex', flexWrap: 'wrap', gap: '10px 8px', minWidth: '0', padding: '3px 2px 2px' });
        (Array.isArray(values) ? values : []).forEach(value => list.appendChild(mooncakeCreateLazyEnhancementShortcutEditorRow(kind, value)));
        add.addEventListener('click', () => {
            if (list.querySelectorAll(`[data-mooncake-lazy-enhancement-shortcut-editor-row="${kind}"]`).length >= MOONCAKE_LAZY_ENHANCEMENT_SHORTCUT_LIMIT) return;
            const next = kind === 'combined'
                ? { targetLevel: '', protectionLevel: '', repeatCount: '' }
                : '';
            list.appendChild(mooncakeCreateLazyEnhancementShortcutEditorRow(kind, next));
        });
        section.append(heading, list);
        return section;
    }

    function mooncakeReadLazyEnhancementShortcutEditor(host) {
        const readNumberList = kind => [...host.querySelectorAll(`[data-mooncake-lazy-enhancement-shortcut-editor-list="${kind}"] [data-mooncake-lazy-enhancement-shortcut-editor-row]`)]
            .map(row => Number(row.querySelector('[data-mooncake-lazy-enhancement-shortcut-editor-value="value"]')?.value));
        const combined = [...host.querySelectorAll('[data-mooncake-lazy-enhancement-shortcut-editor-list="combined"] [data-mooncake-lazy-enhancement-shortcut-editor-row]')]
            .map(row => ({
                targetLevel: Number(row.querySelector('[data-mooncake-lazy-enhancement-shortcut-editor-value="targetLevel"]')?.value),
                protectionLevel: Number(row.querySelector('[data-mooncake-lazy-enhancement-shortcut-editor-value="protectionLevel"]')?.value),
                repeatCount: Number(row.querySelector('[data-mooncake-lazy-enhancement-shortcut-editor-value="repeatCount"]')?.value)
            }));
        return { target: readNumberList('target'), protect: readNumberList('protect'), repeat: readNumberList('repeat'), combined };
    }

    function mooncakeRenderLazyEnhancementShortcutEditor(host) {
        const shortcuts = mooncakeGetLazyEnhancementShortcuts();
        const intro = document.createElement('div');
        intro.textContent = isZH
            ? '这些按钮只写入强化页面的目标、保护起始等级和重复次数，不会开始强化或发送市场请求。组合中的次数填 0 表示无限。'
            : 'These buttons only write the enhancement target, protection start level, and repeat count. They never start enhancement or send a market request. A combo count of 0 means unlimited.';
        Object.assign(intro.style, {
            padding: '8px 10px', borderLeft: '3px solid rgba(121,148,238,.72)', background: 'rgba(55,66,111,.24)',
            color: 'rgba(224,231,249,.82)', fontSize: '11px', lineHeight: '1.5'
        });
        const sections = document.createElement('div');
        Object.assign(sections.style, { display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(250px,1fr))', gap: '8px', minWidth: '0' });
        sections.append(
            mooncakeCreateLazyEnhancementShortcutEditorSection('target', isZH ? '目标等级' : 'Target levels', shortcuts.target),
            mooncakeCreateLazyEnhancementShortcutEditorSection('protect', isZH ? '保护等级' : 'Protection levels', shortcuts.protect),
            mooncakeCreateLazyEnhancementShortcutEditorSection('repeat', isZH ? '重复次数' : 'Repeat counts', shortcuts.repeat),
            mooncakeCreateLazyEnhancementShortcutEditorSection('combined', isZH ? '组合快捷' : 'Combined shortcuts', shortcuts.combined)
        );
        const actions = document.createElement('div');
        Object.assign(actions.style, { display: 'flex', justifyContent: 'flex-end', flexWrap: 'wrap', gap: '7px', paddingTop: '2px' });
        const restore = mooncakeCreateLazyEnhancementManagerButton(isZH ? '恢复默认' : 'Restore defaults', 'danger');
        restore.addEventListener('click', () => {
            mooncakeRestoreLazyEnhancementShortcutDefaults();
            mooncakeRenderLazyEnhancementSettingsManager();
        });
        const save = mooncakeCreateLazyEnhancementManagerButton(isZH ? '保存快捷按钮' : 'Save shortcuts');
        Object.assign(save.style, { background: 'rgba(64,91,154,.88)', borderColor: 'rgba(144,169,249,.62)' });
        save.addEventListener('click', () => {
            mooncakeSaveLazyEnhancementShortcuts(mooncakeReadLazyEnhancementShortcutEditor(host));
            mooncakeRenderLazyEnhancementSettingsManager();
        });
        actions.append(restore, save);
        host.append(intro, sections, actions);
    }

    function mooncakeRenderLazyEnhancementSettingsManager(panel = null) {
        const presets = mooncakeGetLazyEnhancementPresets();
        const settingsPanel = panel || ui.configPanel || document.getElementById('better-loot-tracker-config-panel');
        const countTargets = new Set([
            ...document.querySelectorAll('[data-mooncake-lazy-enhancement-manager-count]'),
            ...(settingsPanel?.querySelectorAll?.('[data-mooncake-lazy-enhancement-manager-count]') || [])
        ]);
        countTargets.forEach(button => {
            const label = button.getAttribute('data-mooncake-lazy-enhancement-manager-label') || (isZH ? '管理' : 'Manage');
            button.textContent = `${label} (${presets.length})`;
        });

        const overlay = document.getElementById(MOONCAKE_LAZY_ENHANCEMENT_MANAGER_ID);
        const host = overlay?.querySelector?.('[data-mooncake-lazy-enhancement-manager-list]');
        if (!overlay || !host) return;
        const activeView = overlay.dataset.activeView === 'presets' ? 'presets' : 'shortcuts';
        overlay.dataset.activeView = activeView;
        overlay.querySelectorAll('[data-mooncake-lazy-enhancement-manager-tab]').forEach(button => {
            const active = button.getAttribute('data-mooncake-lazy-enhancement-manager-tab') === activeView;
            button.setAttribute('aria-selected', String(active));
            Object.assign(button.style, active ? {
                background: 'rgba(64,91,154,.88)', borderColor: 'rgba(144,169,249,.62)', color: '#fff'
            } : {
                background: 'rgba(57,73,120,.78)', borderColor: 'rgba(151,171,236,.38)', color: '#edf2ff'
            });
        });
        const subtitle = overlay.querySelector('[data-mooncake-lazy-enhancement-manager-subtitle]');
        if (subtitle) subtitle.textContent = activeView === 'shortcuts'
            ? (isZH ? '修改目标、保护、次数与组合快捷按钮。' : 'Edit target, protection, repeat, and combined shortcuts.')
            : (isZH
                ? `已保存 ${presets.length} 套方案；每件装备只能有一个默认自动填充方案。`
                : `${presets.length} saved plan(s); each item has one default auto-fill plan.`);
        const intro = overlay.querySelector('[data-mooncake-lazy-enhancement-manager-intro]');
        if (intro) {
            const isShortcutView = activeView === 'shortcuts';
            intro.hidden = isShortcutView;
            if (!isShortcutView) {
                intro.textContent = isZH
                    ? '在强化页设好目标等级、保护材料和保护起始等级后，点击 ☆ 保存。可为同一装备保留多套组合。'
                    : 'Set the target level, protection material, and protection start level on the enhancement page, then choose ☆ to save. Multiple plans can be saved for one item.';
            }
        }
        host.replaceChildren();
        if (activeView === 'shortcuts') {
            mooncakeRenderLazyEnhancementShortcutEditor(host);
            return;
        }
        if (!presets.length) {
            const empty = document.createElement('div');
            empty.textContent = isZH ? '暂无收藏方案。回到强化页，设好目标和保护后点击 ☆ 即可保存。' : 'No saved plans yet. Set a target and protection on the enhancement page, then choose ☆.';
            Object.assign(empty.style, {
                padding: '34px 18px', color: 'rgba(220,228,248,.62)', border: '1px dashed rgba(151,166,217,.24)',
                borderRadius: '5px', textAlign: 'center', fontSize: '12px', lineHeight: '1.55'
            });
            host.appendChild(empty);
            return;
        }
        const groups = new Map();
        presets.forEach(preset => {
            if (!groups.has(preset.itemHrid)) groups.set(preset.itemHrid, []);
            groups.get(preset.itemHrid).push(preset);
        });

        // Keep each item as a compact card. Multiple saved combinations live in
        // the same card instead of stretching the manager to one wide row/item.
        const cards = document.createElement('div');
        cards.setAttribute('data-mooncake-lazy-enhancement-preset-cards', '1');
        Object.assign(cards.style, {
            display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(210px, 1fr))',
            alignItems: 'start', gap: '8px', minWidth: '0'
        });
        [...groups.entries()].forEach(([itemHrid, itemPresets]) => {
            const orderedPresets = [...itemPresets].sort((left, right) => {
                if (left.isDefault !== right.isDefault) return left.isDefault ? -1 : 1;
                return Number(right.updatedAt || 0) - Number(left.updatedAt || 0);
            });
            const hasDefault = orderedPresets.some(preset => preset.isDefault);
            const card = document.createElement('article');
            Object.assign(card.style, {
                minWidth: '0', display: 'grid', gridTemplateColumns: '38px minmax(0,1fr)', alignItems: 'start',
                columnGap: '8px', rowGap: '7px', padding: '8px', boxSizing: 'border-box',
                border: hasDefault ? '1px solid rgba(103,210,152,.48)' : '1px solid rgba(151,166,217,.20)',
                borderRadius: '5px', background: hasDefault ? 'rgba(30,61,51,.28)' : 'rgba(27,32,48,.72)'
            });
            const icon = mooncakeCreateLazyEnhancementManagerIcon(itemHrid);
            Object.assign(icon.style, { gridColumn: '1', gridRow: '1' });
            const heading = document.createElement('div');
            Object.assign(heading.style, { minWidth: '0', display: 'grid', gap: '2px', paddingTop: '1px' });
            const name = document.createElement('strong');
            name.textContent = getItemName(itemHrid) || itemHrid;
            name.title = itemHrid;
            Object.assign(name.style, {
                minWidth: '0', overflow: 'hidden', color: '#f0f4ff', fontSize: '12px', fontWeight: '800',
                textOverflow: 'ellipsis', whiteSpace: 'nowrap', lineHeight: '1.25'
            });
            const amount = document.createElement('span');
            amount.textContent = `${orderedPresets.length} ${isZH ? '套方案' : 'plan(s)'}`;
            Object.assign(amount.style, { color: 'rgba(208,218,244,.58)', fontSize: '10px', fontWeight: '700', lineHeight: '1.25' });
            heading.append(name, amount);

            const plans = document.createElement('div');
            Object.assign(plans.style, { gridColumn: '1 / -1', display: 'grid', gap: '4px', minWidth: '0' });
            orderedPresets.forEach(preset => {
                const plan = document.createElement('div');
                Object.assign(plan.style, {
                    minWidth: '0', display: 'grid', gridTemplateColumns: 'minmax(0,1fr) auto', alignItems: 'center', gap: '5px',
                    padding: '5px 5px 5px 6px', borderRadius: '4px', boxSizing: 'border-box',
                    border: preset.isDefault ? '1px solid rgba(103,210,152,.34)' : '1px solid rgba(151,166,217,.14)',
                    background: preset.isDefault ? 'rgba(43,92,71,.30)' : 'rgba(13,17,27,.32)'
                });
                const summary = document.createElement('div');
                summary.title = mooncakeGetLazyEnhancementPresetTitle(preset);
                Object.assign(summary.style, { minWidth: '0', display: 'grid', gap: '1px' });
                const target = document.createElement('strong');
                target.textContent = `${isZH ? '目标' : 'Target'} +${preset.targetLevel}`;
                Object.assign(target.style, { color: '#f0f4ff', fontSize: '11px', fontWeight: '800', whiteSpace: 'nowrap', lineHeight: '1.25' });
                const protection = document.createElement('span');
                protection.textContent = preset.protectionItemHrid
                    ? `${isZH ? '保护' : 'Protect'} ${getItemName(preset.protectionItemHrid) || preset.protectionItemHrid} +${preset.protectionLevel}`
                    : (isZH ? '无保护' : 'No protection');
                Object.assign(protection.style, {
                    minWidth: '0', overflow: 'hidden', color: 'rgba(221,229,247,.68)', fontSize: '10px',
                    lineHeight: '1.25', textOverflow: 'ellipsis', whiteSpace: 'nowrap'
                });
                summary.append(target, protection);

                const actions = document.createElement('div');
                Object.assign(actions.style, { display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: '4px' });
                if (preset.isDefault) {
                    const defaultLabel = document.createElement('span');
                    defaultLabel.textContent = isZH ? '默认' : 'Default';
                    Object.assign(defaultLabel.style, { color: '#9de8bf', fontSize: '10px', fontWeight: '800', whiteSpace: 'nowrap', lineHeight: '1.3' });
                    actions.appendChild(defaultLabel);
                } else {
                    const defaultButton = mooncakeCreateLazyEnhancementManagerButton(isZH ? '设默认' : 'Default');
                    defaultButton.title = isZH ? '设为自动填充方案' : 'Set as auto-fill plan';
                    Object.assign(defaultButton.style, { minHeight: '24px', padding: '2px 6px', fontSize: '10px' });
                    defaultButton.addEventListener('click', () => {
                        if (!mooncakeSetLazyEnhancementPresetDefault(itemHrid, preset.id)) return;
                        mooncakeResetLazyEnhancementAutoFillState();
                        mooncakeRenderLazyEnhancementSettingsManager();
                        mooncakeScheduleLazyEnhancement();
                    });
                    actions.appendChild(defaultButton);
                }
                const deleteButton = mooncakeCreateLazyEnhancementManagerButton('×', 'danger');
                deleteButton.title = isZH ? '删除此收藏方案' : 'Delete this saved plan';
                deleteButton.setAttribute('aria-label', deleteButton.title);
                Object.assign(deleteButton.style, { width: '24px', minWidth: '24px', minHeight: '24px', padding: '0', fontSize: '17px', lineHeight: '20px' });
                deleteButton.addEventListener('click', () => {
                    if (!mooncakeDeleteLazyEnhancementPreset(itemHrid, preset.id)) return;
                    mooncakeResetLazyEnhancementAutoFillState();
                    mooncakeRenderLazyEnhancementSettingsManager();
                    mooncakeScheduleLazyEnhancement();
                });
                actions.appendChild(deleteButton);
                plan.append(summary, actions);
                plans.appendChild(plan);
            });
            card.append(icon, heading, plans);
            cards.appendChild(card);
        });
        host.appendChild(cards);
    }

    function mooncakeOpenLazyEnhancementSettingsManager(trigger = null, initialView = 'shortcuts') {
        let overlay = document.getElementById(MOONCAKE_LAZY_ENHANCEMENT_MANAGER_ID);
        if (!overlay) {
            overlay = mooncakeCreateLazyEnhancementSettingsManager(trigger);
            document.body.appendChild(overlay);
        } else if (trigger) {
            overlay._mooncakeLazyEnhancementManagerTrigger = trigger;
        }
        overlay.dataset.activeView = initialView === 'presets' ? 'presets' : 'shortcuts';
        mooncakeRenderLazyEnhancementSettingsManager();
        requestAnimationFrame(() => {
            const focusTarget = overlay.querySelector('button[aria-label]') || overlay.querySelector('[role="dialog"]');
            focusTarget?.focus?.({ preventScroll: true });
        });
    }

    function mooncakeRemoveLazyEnhancementBar() {
        document.getElementById(MOONCAKE_LAZY_ENHANCEMENT_BAR_ID)?.remove();
        document.querySelectorAll(`[${MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR}]`).forEach(control => control.remove());
    }

    function mooncakeSetLazyEnhancementBarStatus(message, tone = 'normal') {
        const status = document.querySelector(`#${MOONCAKE_LAZY_ENHANCEMENT_BAR_ID} [data-mooncake-lazy-enhancement-status]`);
        if (!status) return;
        status.textContent = message || '';
        status.hidden = !message;
        status.style.color = tone === 'success'
            ? '#8ce6a5'
            : tone === 'error'
                ? '#ff9d9d'
                : 'rgba(224,230,244,.72)';
    }

    function mooncakeMarkLazyEnhancementManualOverride(panel) {
        const itemHrid = mooncakeGetEnhanceBaseItemHrid(panel);
        const startLevel = mooncakeGetEnhanceBaseItemLevel(panel, false);
        const key = mooncakeGetLazyEnhancementPresetKey(itemHrid, startLevel);
        if (!key) return;
        mooncakeLazyEnhancementManualOverrideKey = key;
        mooncakeLazyEnhancementAutoFillSignature = '';
    }

    function mooncakeCreateLazyEnhancementButton(label, action, value, title) {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = label;
        button.title = title;
        button.setAttribute('aria-label', title);
        button.setAttribute('data-mooncake-lazy-enhancement-action', action);
        if (value !== undefined) button.dataset.value = String(value);
        Object.assign(button.style, {
            boxSizing: 'border-box',
            minWidth: action === 'count' ? '34px' : (action === 'save' || action === 'manage' ? '28px' : '29px'),
            height: '26px',
            padding: action === 'save' || action === 'manage' ? '0 4px' : '0 5px',
            border: '1px solid rgba(157,174,223,.3)',
            borderRadius: '4px',
            background: 'rgba(58,64,88,.82)',
            color: '#edf1fb',
            fontSize: action === 'save' || action === 'manage' ? '14px' : '11px',
            fontWeight: '700',
            lineHeight: '24px',
            letterSpacing: '0',
            whiteSpace: 'nowrap',
            cursor: 'pointer'
        });
        return button;
    }

    function mooncakeFormatLazyEnhancementPresetLabel(preset) {
        const normalized = mooncakeNormalizeLazyEnhancementPreset(preset);
        if (!normalized) return '';
        const protection = normalized.protectionItemHrid
            ? `${getItemName(normalized.protectionItemHrid) || normalized.protectionItemHrid} +${normalized.protectionLevel}`
            : (isZH ? '无保' : 'No P');
        return `+${normalized.targetLevel} · ${protection}`;
    }

    function mooncakeFormatLazyEnhancementPresetShortcutLabel(preset) {
        const normalized = mooncakeNormalizeLazyEnhancementPreset(preset);
        if (!normalized) return '';
        const protection = normalized.protectionItemHrid
            ? `+${normalized.protectionLevel}`
            : (isZH ? '无保' : 'None');
        return `+${normalized.targetLevel}/${protection}`;
    }

    function mooncakeGetLazyEnhancementPresetTitle(preset) {
        const normalized = mooncakeNormalizeLazyEnhancementPreset(preset);
        if (!normalized) return '';
        const protection = normalized.protectionItemHrid
            ? `${getItemName(normalized.protectionItemHrid) || normalized.protectionItemHrid} +${normalized.protectionLevel}`
            : (isZH ? '不使用保护材料' : 'No protection material');
        const defaultText = normalized.isDefault
            ? (isZH ? '默认自动填充' : 'Default auto-fill')
            : (isZH ? '点击填入方案' : 'Apply strategy');
        return `${defaultText}: +${normalized.targetLevel} · ${protection}`;
    }

    function mooncakeRenderLazyEnhancementPresetShortcuts(bar, itemHrid, knownPresets = null) {
        if (!bar) return;
        const group = bar.querySelector('[data-mooncake-lazy-enhancement-group="saved-presets"]');
        if (!group) return;
        const presets = Array.isArray(knownPresets) ? knownPresets : mooncakeGetLazyEnhancementPresetsForItem(itemHrid);
        const signature = presets.map(preset => [
            preset.id,
            preset.targetLevel,
            preset.protectionItemHrid || '',
            preset.protectionLevel || '',
            preset.isDefault ? '1' : '0'
        ].join(':')).join('|');
        if (group.dataset.signature === signature) return;
        group.dataset.signature = signature;
        group.replaceChildren();
        group.hidden = presets.length === 0;
        if (!presets.length) return;
        presets.forEach(preset => {
            const button = mooncakeCreateLazyEnhancementButton(
                `${preset.isDefault ? '★ ' : ''}${mooncakeFormatLazyEnhancementPresetShortcutLabel(preset)}`,
                'apply-preset',
                undefined,
                mooncakeGetLazyEnhancementPresetTitle(preset)
            );
            button.dataset.presetId = preset.id;
            button.setAttribute('aria-pressed', String(preset.isDefault));
            if (preset.isDefault) button.style.background = 'rgba(64,102,92,.9)';
            group.appendChild(button);
        });
    }

    async function mooncakeApplyLazyEnhancementRecommendation(panel, recommendation, options = {}) {
        const itemHrid = recommendation?.itemHrid;
        const startLevel = mooncakeGetEnhanceBaseItemLevel(panel, false);
        const key = mooncakeGetLazyEnhancementPresetKey(itemHrid, startLevel);
        if (!key || mooncakeLazyEnhancementApplyingKey || mooncakeHasExternalEnhancementPresetControls()) return null;

        mooncakeLazyEnhancementApplyingKey = key;
        const expectedToken = mooncakeEnhanceQuickApplyToken + 1;
        mooncakeLazyEnhancementApplyToken = expectedToken;
        mooncakeScheduleLazyEnhancement();
        try {
            const result = await mooncakeApplyEnhanceQuickRecommendation(panel, recommendation);
            const currentBar = document.getElementById(MOONCAKE_LAZY_ENHANCEMENT_BAR_ID);
            if (!options.auto && !result?.cancelled && currentBar?.dataset.contextKey === key) {
                mooncakeSetLazyEnhancementBarStatus(
                    result?.message || (isZH ? '方案未写入' : 'Strategy was not applied'),
                    result?.applied ? 'success' : 'error'
                );
            }
            return result;
        } finally {
            if (mooncakeLazyEnhancementApplyToken === expectedToken) mooncakeLazyEnhancementApplyToken = 0;
            if (mooncakeLazyEnhancementApplyingKey === key) mooncakeLazyEnhancementApplyingKey = '';
            mooncakeScheduleLazyEnhancement();
        }
    }

    function mooncakeCreateLazyEnhancementControlRoot(kind, contextKey, tagName = 'div') {
        const control = document.createElement(tagName);
        control.setAttribute(MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR, kind);
        control.setAttribute(MOONCAKE_LAZY_ENHANCEMENT_CONTEXT_ATTR, contextKey);
        control.dataset.contextKey = contextKey;
        Object.assign(control.style, {
            boxSizing: 'border-box', minWidth: '0', maxWidth: '100%'
        });
        return control;
    }

    function mooncakeGetLazyEnhancementControls(contextKey = '') {
        return [...document.querySelectorAll(`[${MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR}]`)]
            .filter(control => !contextKey || control.getAttribute(MOONCAKE_LAZY_ENHANCEMENT_CONTEXT_ATTR) === contextKey);
    }

    function mooncakeGetLazyEnhancementControl(kind, contextKey) {
        return mooncakeGetLazyEnhancementControls(contextKey)
            .find(control => control.getAttribute(MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR) === kind) || null;
    }

    function mooncakeBindLazyEnhancementControl(control) {
        control.addEventListener('click', event => {
            const button = event.target.closest?.('[data-mooncake-lazy-enhancement-action]');
            if (!button || button.disabled || !control.contains(button)) return;
            event.preventDefault();
            event.stopPropagation();
            void mooncakeHandleLazyEnhancementAction(button);
        });
        return control;
    }

    function mooncakeCreateLazyEnhancementButtonRow(values, action, options = {}) {
        const row = document.createElement('span');
        Object.assign(row.style, {
            display: 'inline-flex', alignItems: 'center', flexWrap: 'wrap', gap: '3px', minWidth: '0', maxWidth: '100%'
        });
        if (options.label) {
            const label = document.createElement('span');
            label.textContent = options.label;
            label.setAttribute('aria-hidden', 'true');
            Object.assign(label.style, {
                padding: '0 1px', color: 'rgba(215,222,240,.66)', fontSize: '10px', fontWeight: '700', whiteSpace: 'nowrap'
            });
            row.appendChild(label);
        }
        (Array.isArray(values) ? values : []).forEach(value => {
            const prefix = options.prefix === false ? '' : '+';
            const label = `${prefix}${value}`;
            const title = options.titleFactory?.(value) || label;
            const button = mooncakeCreateLazyEnhancementButton(label, action, value, title);
            Object.assign(button.style, { minWidth: '30px' });
            row.appendChild(button);
        });
        return row;
    }

    function mooncakeCreateLazyEnhancementBar() {
        const shortcuts = mooncakeGetLazyEnhancementShortcuts();
        const bar = mooncakeCreateLazyEnhancementControlRoot('top', '', 'div');
        bar.id = MOONCAKE_LAZY_ENHANCEMENT_BAR_ID;
        bar.setAttribute('role', 'toolbar');
        bar.setAttribute('aria-label', isZH ? '懒鬼按钮目标与方案快捷栏' : 'Lazy target and plan shortcuts');
        Object.assign(bar.style, {
            display: 'flex', flexFlow: 'row wrap', alignItems: 'center', gap: '4px 5px', width: '100%',
            margin: '7px 0 3px', padding: '0', border: '0', background: 'transparent'
        });
        const targetGroup = mooncakeCreateLazyEnhancementButtonRow(shortcuts.target, 'target', {
            titleFactory: value => isZH ? `目标等级 +${value}` : `Target level +${value}`
        });
        const planGroup = document.createElement('span');
        Object.assign(planGroup.style, { display: 'inline-flex', alignItems: 'center', gap: '3px', flex: '0 0 auto' });
        planGroup.append(
            mooncakeCreateLazyEnhancementButton('☆', 'save', undefined, isZH ? '收藏当前目标、保护材料与保护等级' : 'Save the current target and protection plan'),
            mooncakeCreateLazyEnhancementButton('⚙', 'manage', undefined, isZH ? '编辑快捷按钮与收藏方案' : 'Edit shortcuts and saved plans')
        );
        const savedPresetGroup = document.createElement('span');
        savedPresetGroup.setAttribute('data-mooncake-lazy-enhancement-group', 'saved-presets');
        Object.assign(savedPresetGroup.style, {
            display: 'inline-flex', flex: '0 1 auto', flexWrap: 'wrap', alignItems: 'center', gap: '3px', minWidth: '0', maxWidth: '100%'
        });
        const status = document.createElement('span');
        status.setAttribute('data-mooncake-lazy-enhancement-status', '1');
        status.setAttribute('aria-live', 'polite');
        Object.assign(status.style, {
            flex: '0 1 100%', minWidth: '0', overflow: 'hidden', color: 'rgba(224,230,244,.72)', fontSize: '10px',
            lineHeight: '1.25', textAlign: 'left', textOverflow: 'ellipsis', whiteSpace: 'nowrap'
        });
        status.hidden = true;
        bar.append(targetGroup, planGroup, savedPresetGroup, status);
        return mooncakeBindLazyEnhancementControl(bar);
    }

    function mooncakeCreateLazyEnhancementCombinedShortcuts(contextKey) {
        const shortcuts = mooncakeGetLazyEnhancementShortcuts();
        const control = mooncakeCreateLazyEnhancementControlRoot('combined', contextKey);
        control.setAttribute('role', 'toolbar');
        control.setAttribute('aria-label', isZH ? '懒鬼按钮组合快捷' : 'Lazy combined shortcuts');
        Object.assign(control.style, {
            display: 'flex', flexFlow: 'row wrap', alignItems: 'center', gap: '4px 5px', width: '100%', margin: '3px 0 7px', padding: '0'
        });
        shortcuts.combined.forEach(shortcut => {
            const label = `${shortcut.targetLevel}+${shortcut.protectionLevel}${shortcut.repeatCount ? `×${shortcut.repeatCount}` : ''}`;
            const button = mooncakeCreateLazyEnhancementButton(label, 'combined', undefined, isZH
                ? `填入目标 +${shortcut.targetLevel}、保护 +${shortcut.protectionLevel}${shortcut.repeatCount ? `、次数 ${shortcut.repeatCount}` : '、无限次数'}`
                : `Apply target +${shortcut.targetLevel}, protection +${shortcut.protectionLevel}${shortcut.repeatCount ? `, repeat ${shortcut.repeatCount}` : ', unlimited'}`);
            button.dataset.targetLevel = String(shortcut.targetLevel);
            button.dataset.protectionLevel = String(shortcut.protectionLevel);
            button.dataset.repeatCount = String(shortcut.repeatCount);
            Object.assign(button.style, { minWidth: '61px', padding: '0 7px' });
            control.appendChild(button);
        });
        control.hidden = shortcuts.combined.length === 0;
        return mooncakeBindLazyEnhancementControl(control);
    }

    function mooncakeCreateLazyEnhancementProtectionShortcuts(contextKey) {
        const shortcuts = mooncakeGetLazyEnhancementShortcuts();
        const control = mooncakeCreateLazyEnhancementControlRoot('protect', contextKey);
        control.setAttribute('role', 'toolbar');
        control.setAttribute('aria-label', isZH ? '懒鬼按钮保护快捷' : 'Lazy protection shortcuts');
        Object.assign(control.style, {
            display: 'flex', flexFlow: 'row wrap', alignItems: 'center', gap: '4px 5px', width: '100%', margin: '5px 0 2px', padding: '0'
        });
        control.appendChild(mooncakeCreateLazyEnhancementButtonRow(shortcuts.protect, 'protect', {
            label: isZH ? '保护' : 'Protect', titleFactory: value => isZH ? `保护起始等级 +${value}` : `Protection start +${value}`
        }));
        control.hidden = shortcuts.protect.length === 0;
        return mooncakeBindLazyEnhancementControl(control);
    }

    function mooncakeCreateLazyEnhancementRepeatShortcuts(contextKey, nativeButton = null) {
        const shortcuts = mooncakeGetLazyEnhancementShortcuts();
        const control = mooncakeCreateLazyEnhancementControlRoot('repeat', contextKey, 'span');
        control.setAttribute('role', 'toolbar');
        control.setAttribute('aria-label', isZH ? '懒鬼按钮次数快捷' : 'Lazy repeat shortcuts');
        Object.assign(control.style, { display: 'inline-flex', alignItems: 'center', gap: '4px', flex: '0 0 auto', margin: '0 4px' });
        shortcuts.repeat.forEach(value => {
            const button = mooncakeCreateLazyEnhancementButton(String(value), 'count', value, isZH ? `重复次数 ${value}` : `Repeat count ${value}`);
            if (nativeButton?.className) button.className = nativeButton.className;
            Object.assign(button.style, { minWidth: '0', height: nativeButton ? '' : '26px', padding: nativeButton ? '' : '0 6px', lineHeight: nativeButton ? '' : '24px' });
            control.appendChild(button);
        });
        control.hidden = shortcuts.repeat.length === 0;
        return mooncakeBindLazyEnhancementControl(control);
    }

    function mooncakeMountLazyEnhancementCombinedShortcuts(panel, contextKey, anchor) {
        let control = mooncakeGetLazyEnhancementControl('combined', contextKey);
        if (!control) control = mooncakeCreateLazyEnhancementCombinedShortcuts(contextKey);
        if (anchor?.isConnected && anchor.nextElementSibling !== control) anchor.insertAdjacentElement('afterend', control);
        return control;
    }

    function mooncakeMountLazyEnhancementProtectionShortcuts(panel, contextKey) {
        const input = mooncakeFindEnhanceProtectionLevelInput(panel);
        const anchor = input?.closest?.('[class*="protectionMinLevelInputContainer"], [class*="ProtectionMinLevelInputContainer"]');
        let control = mooncakeGetLazyEnhancementControl('protect', contextKey);
        if (!anchor) {
            control?.remove();
            return null;
        }
        if (!control) control = mooncakeCreateLazyEnhancementProtectionShortcuts(contextKey);
        if (anchor.nextElementSibling !== control) anchor.insertAdjacentElement('afterend', control);
        return control;
    }

    function mooncakeMountLazyEnhancementRepeatShortcuts(panel, contextKey) {
        const input = mooncakeFindEnhanceRepeatCountInput(panel);
        const anchor = input?.closest?.('[class*="maxActionCountInput"], [class*="maxActionCountInputContainer"]');
        let control = mooncakeGetLazyEnhancementControl('repeat', contextKey);
        if (!anchor) {
            control?.remove();
            return null;
        }
        const nativeButtons = [...anchor.querySelectorAll('button')].filter(button => !button.closest(`[${MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR}]`));
        const infinityButton = nativeButtons.find(button => /∞|无限|unlimited|infinity/i.test(button.textContent || '')) || nativeButtons.at(-1) || null;
        if (!infinityButton) {
            control?.remove();
            return null;
        }
        if (!control) control = mooncakeCreateLazyEnhancementRepeatShortcuts(contextKey, infinityButton);
        const buttonParent = infinityButton.parentElement;
        if (!buttonParent) {
            control.remove();
            return null;
        }
        if (infinityButton.previousElementSibling !== control) buttonParent.insertBefore(control, infinityButton);
        return control;
    }

    function mooncakeMountLazyEnhancementBar(panel, contextKey) {
        mooncakeGetLazyEnhancementControls().forEach(control => {
            if (control.getAttribute(MOONCAKE_LAZY_ENHANCEMENT_CONTEXT_ATTR) !== contextKey) control.remove();
        });
        let bar = document.getElementById(MOONCAKE_LAZY_ENHANCEMENT_BAR_ID);
        if (!bar || bar.getAttribute(MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR) !== 'top') {
            bar?.remove();
            bar = mooncakeCreateLazyEnhancementBar();
        }
        bar.setAttribute(MOONCAKE_LAZY_ENHANCEMENT_CONTEXT_ATTR, contextKey);
        bar.dataset.contextKey = contextKey;
        const primaryItemAndNotes = panel.querySelector('[class*="SkillActionDetail_primaryItemAndNotes"]');
        const notes = primaryItemAndNotes?.querySelector?.('[class*="SkillActionDetail_notes"]');
        if (notes) {
            if (notes.lastElementChild !== bar) notes.appendChild(bar);
        } else if (primaryItemAndNotes?.parentElement) {
            if (primaryItemAndNotes.nextElementSibling !== bar) primaryItemAndNotes.insertAdjacentElement('afterend', bar);
        } else {
            const actionContainer = panel.querySelector('[class*="SkillActionDetail_actionContainer"]');
            if (!actionContainer) {
                bar.remove();
                return null;
            }
            if (actionContainer.firstElementChild !== bar) actionContainer.prepend(bar);
        }
        mooncakeMountLazyEnhancementCombinedShortcuts(panel, contextKey, primaryItemAndNotes || bar);
        mooncakeMountLazyEnhancementProtectionShortcuts(panel, contextKey);
        mooncakeMountLazyEnhancementRepeatShortcuts(panel, contextKey);
        return bar;
    }

    function mooncakeUpdateLazyEnhancementBar(bar, panel, itemHrid, startLevel) {
        if (!bar) return;
        const contextKey = bar.dataset.contextKey;
        const busy = mooncakeLazyEnhancementApplyingKey === contextKey;
        const targetLevel = mooncakeGetEnhanceTargetLevel(panel, false);
        const protectionItemHrid = mooncakeGetEnhanceProtectionHrid(panel, itemHrid);
        const draft = mooncakeReadLazyEnhancementDraft(panel);
        const savedPresets = mooncakeGetLazyEnhancementPresetsForItem(itemHrid);
        const savedPresetsById = new Map(savedPresets.map(preset => [preset.id, preset]));
        const same = !!draft && savedPresets.some(preset => mooncakeLazyEnhancementPresetsMatch(draft, preset));
        const repeatInput = mooncakeFindEnhanceRepeatCountInput(panel);
        mooncakeRenderLazyEnhancementPresetShortcuts(bar, itemHrid, savedPresets);

        mooncakeGetLazyEnhancementControls(contextKey).forEach(control => {
            control.querySelectorAll('[data-mooncake-lazy-enhancement-action]').forEach(button => {
                const action = button.getAttribute('data-mooncake-lazy-enhancement-action');
                const value = Number(button.dataset.value);
                let disabled = busy && action !== 'manage';
                if (action === 'save') disabled ||= !draft;
                if (action === 'target') disabled ||= !Number.isInteger(value) || value <= startLevel || value > 20;
                if (action === 'protect') disabled ||= !protectionItemHrid || !Number.isInteger(targetLevel) || value < 1 || value >= targetLevel;
                if (action === 'count') disabled ||= !repeatInput;
                if (action === 'combined') {
                    const combinedTarget = Number(button.dataset.targetLevel);
                    const combinedProtect = Number(button.dataset.protectionLevel);
                    const combinedRepeat = Number(button.dataset.repeatCount);
                    disabled ||= !Number.isInteger(combinedTarget) || combinedTarget <= startLevel || combinedTarget > 20 ||
                        !Number.isInteger(combinedProtect) || combinedProtect < 0 || combinedProtect >= combinedTarget ||
                        !Number.isInteger(combinedRepeat) || combinedRepeat < 0 || combinedRepeat > 99999 ||
                        (combinedProtect > 0 && !protectionItemHrid) || !repeatInput;
                }
                if (action === 'apply-preset') {
                    const preset = savedPresetsById.get(button.dataset.presetId) || null;
                    disabled ||= !preset || preset.targetLevel <= startLevel;
                    button.setAttribute('aria-pressed', String(!!preset?.isDefault));
                    button.style.background = preset?.isDefault ? 'rgba(64,102,92,.9)' : 'rgba(58,64,88,.82)';
                }
                button.disabled = disabled;
                button.style.opacity = disabled ? '.42' : '1';
                button.style.cursor = disabled ? 'default' : 'pointer';
                if (action === 'save') {
                    const nextText = same ? '★' : '☆';
                    if (button.textContent !== nextText) button.textContent = nextText;
                    const title = same
                        ? (isZH ? '当前组合已收藏，点击取消收藏' : 'This plan is saved. Click to remove it.')
                        : (isZH ? '收藏当前目标、保护材料与保护等级' : 'Save the current target and protection plan');
                    button.title = title;
                    button.setAttribute('aria-label', title);
                    button.setAttribute('aria-pressed', String(same));
                    button.style.background = same ? 'rgba(83,115,72,.9)' : 'rgba(58,64,88,.82)';
                }
            });
        });
    }

    function mooncakeApplyLazyEnhancementRepeatShortcut(panel, repeatCount) {
        const input = mooncakeFindEnhanceRepeatCountInput(panel);
        if (!input) return false;
        const normalized = Math.round(Number(repeatCount));
        if (!Number.isInteger(normalized) || normalized < 0 || normalized > 99999) return false;
        if (normalized > 0) return mooncakeWriteNativeEnhanceRepeatCount(panel, input, normalized);
        const container = input.closest?.('[class*="maxActionCountInput"], [class*="maxActionCountInputContainer"]');
        const infinityButton = [...(container?.querySelectorAll?.('button') || [])]
            .find(button => !button.closest(`[${MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR}]`) && /∞|无限|unlimited|infinity/i.test(button.textContent || ''));
        if (!infinityButton || infinityButton.disabled) return false;
        infinityButton.click();
        return true;
    }

    async function mooncakeHandleLazyEnhancementAction(button) {
        if (!mooncakeIsLazyEnhancementEnabled() || mooncakeHasExternalEnhancementPresetControls()) return;
        const control = button.closest(`[${MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR}]`);
        const panel = mooncakeFindEnhancingPanel();
        if (!control || !panel || mooncakeIsEnhanceCurrentActionTab(panel)) return;
        const itemHrid = mooncakeGetEnhanceBaseItemHrid(panel);
        const startLevel = mooncakeGetEnhanceBaseItemLevel(panel, false);
        const key = mooncakeGetLazyEnhancementPresetKey(itemHrid, startLevel);
        if (!key || control.getAttribute(MOONCAKE_LAZY_ENHANCEMENT_CONTEXT_ATTR) !== key) return;

        const action = button.getAttribute('data-mooncake-lazy-enhancement-action');
        const value = Number(button.dataset.value);
        if (action === 'save') {
            const draft = mooncakeReadLazyEnhancementDraft(panel);
            const existing = draft
                ? mooncakeGetLazyEnhancementPresetsForItem(itemHrid).find(preset => mooncakeLazyEnhancementPresetsMatch(draft, preset))
                : null;
            if (existing) {
                if (!mooncakeDeleteLazyEnhancementPreset(itemHrid, existing.id)) return;
                mooncakeResetLazyEnhancementAutoFillState();
                mooncakeSetLazyEnhancementBarStatus(isZH ? '已取消收藏' : 'Removed', 'success');
                mooncakeRenderLazyEnhancementSettingsManager();
                mooncakeScheduleLazyEnhancement();
                return;
            }
            const saved = mooncakeUpsertLazyEnhancementPreset(draft, { makeDefault: true });
            if (!saved) {
                mooncakeSetLazyEnhancementBarStatus(isZH ? '当前方案不完整' : 'Current strategy is incomplete', 'error');
                return;
            }
            mooncakeLazyEnhancementManualOverrideKey = '';
            mooncakeLazyEnhancementAutoFillSignature = mooncakeGetLazyEnhancementPresetSignature(saved);
            mooncakeSetLazyEnhancementBarStatus(isZH ? '已保存' : 'Saved', 'success');
            mooncakeRenderLazyEnhancementSettingsManager();
            mooncakeScheduleLazyEnhancement();
            return;
        }
        if (action === 'manage') {
            mooncakeOpenLazyEnhancementSettingsManager(button, 'shortcuts');
            return;
        }
        if (action === 'apply-preset') {
            const preset = mooncakeFindLazyEnhancementPresetById(itemHrid, button.dataset.presetId);
            if (!preset || preset.targetLevel <= startLevel) {
                mooncakeSetLazyEnhancementBarStatus(isZH ? '该方案不适用于当前等级' : 'This strategy is not valid at the current level', 'error');
                return;
            }
            mooncakeMarkLazyEnhancementManualOverride(panel);
            await mooncakeApplyLazyEnhancementRecommendation(panel, {
                itemHrid: preset.itemHrid,
                expectedStartLevel: startLevel,
                targetLevel: preset.targetLevel,
                protectAt: preset.protectionItemHrid ? preset.protectionLevel : preset.targetLevel,
                protectionItemHrid: preset.protectionItemHrid
            });
            return;
        }
        if (action === 'count') {
            if (mooncakeApplyLazyEnhancementRepeatShortcut(panel, value)) {
                mooncakeSetLazyEnhancementBarStatus(isZH ? `次数 ${value}` : `Count ${value}`, 'success');
            }
            mooncakeScheduleLazyEnhancement();
            return;
        }

        const currentTarget = mooncakeGetEnhanceTargetLevel(panel, false);
        const protectionItemHrid = mooncakeGetEnhanceProtectionHrid(panel, itemHrid);
        mooncakeMarkLazyEnhancementManualOverride(panel);
        if (action === 'target') {
            const protectAt = protectionItemHrid
                ? mooncakeGetEnhanceProtectLevel(panel, value, false, protectionItemHrid)
                : value;
            await mooncakeApplyLazyEnhancementRecommendation(panel, {
                itemHrid,
                expectedStartLevel: startLevel,
                targetLevel: value,
                protectAt,
                protectionItemHrid: protectionItemHrid && protectAt < value ? protectionItemHrid : null
            });
            return;
        }
        if (action === 'protect' && protectionItemHrid && Number.isInteger(currentTarget) && value < currentTarget) {
            await mooncakeApplyLazyEnhancementRecommendation(panel, {
                itemHrid,
                expectedStartLevel: startLevel,
                targetLevel: currentTarget,
                protectAt: value,
                protectionItemHrid
            });
            return;
        }
        if (action === 'combined') {
            const targetLevel = Number(button.dataset.targetLevel);
            const protectionLevel = Number(button.dataset.protectionLevel);
            const repeatCount = Number(button.dataset.repeatCount);
            if (!Number.isInteger(targetLevel) || !Number.isInteger(protectionLevel) || !Number.isInteger(repeatCount)) return;
            if (targetLevel <= startLevel || protectionLevel < 0 || protectionLevel >= targetLevel || repeatCount < 0 || repeatCount > 99999) return;
            if (protectionLevel > 0 && !protectionItemHrid) {
                mooncakeSetLazyEnhancementBarStatus(isZH ? '请先选择保护材料' : 'Choose a protection material first', 'error');
                return;
            }
            const result = await mooncakeApplyLazyEnhancementRecommendation(panel, {
                itemHrid,
                expectedStartLevel: startLevel,
                targetLevel,
                protectAt: protectionLevel > 0 ? protectionLevel : targetLevel,
                protectionItemHrid: protectionLevel > 0 ? protectionItemHrid : null
            });
            if (result?.applied && mooncakeApplyLazyEnhancementRepeatShortcut(panel, repeatCount)) {
                mooncakeSetLazyEnhancementBarStatus(
                    isZH ? `已填入 +${targetLevel}+${protectionLevel}${repeatCount ? `×${repeatCount}` : '×∞'}` : `Applied +${targetLevel}+${protectionLevel}`,
                    'success'
                );
            }
        }
    }

    function mooncakeCancelLazyEnhancementApply() {
        if (mooncakeLazyEnhancementApplyToken && mooncakeEnhanceQuickApplyToken === mooncakeLazyEnhancementApplyToken) {
            mooncakeEnhanceQuickApplyToken += 1;
        }
        mooncakeLazyEnhancementApplyToken = 0;
        mooncakeLazyEnhancementApplyingKey = '';
    }

    function ensureMooncakeLazyEnhancement() {
        if (!mooncakeIsLazyEnhancementEnabled()) {
            mooncakeRemoveLazyEnhancementBar();
            return;
        }
        if (mooncakeHasExternalEnhancementPresetControls()) {
            if (!mooncakeLazyEnhancementExternalSuppressed) {
                mooncakeLazyEnhancementExternalSuppressed = true;
                mooncakeLazyEnhancementAutoFillSignature = '';
                mooncakeLazyEnhancementAutoFillAttemptSignature = '';
                mooncakeLazyEnhancementAutoFillAttemptCount = 0;
                mooncakeCancelLazyEnhancementApply();
            }
            mooncakeRemoveLazyEnhancementBar();
            return;
        }
        if (mooncakeLazyEnhancementExternalSuppressed) {
            mooncakeLazyEnhancementExternalSuppressed = false;
            mooncakeLazyEnhancementAutoFillSignature = '';
            mooncakeLazyEnhancementAutoFillAttemptSignature = '';
            mooncakeLazyEnhancementAutoFillAttemptCount = 0;
        }

        const panel = mooncakeFindEnhancingPanel();
        if (!panel || mooncakeIsEnhanceCurrentActionTab(panel)) {
            if (mooncakeLazyEnhancementApplyingKey) mooncakeCancelLazyEnhancementApply();
            // A shortcut is only a temporary override for the currently open
            // item.  Returning to the item later should restore its default.
            mooncakeLazyEnhancementContextKey = '';
            mooncakeLazyEnhancementManualOverrideKey = '';
            mooncakeLazyEnhancementAutoFillSignature = '';
            mooncakeLazyEnhancementAutoFillAttemptSignature = '';
            mooncakeLazyEnhancementAutoFillAttemptCount = 0;
            mooncakeRemoveLazyEnhancementBar();
            return;
        }
        const itemHrid = mooncakeGetEnhanceBaseItemHrid(panel);
        const startLevel = mooncakeGetEnhanceBaseItemLevel(panel, false);
        const contextKey = mooncakeGetLazyEnhancementPresetKey(itemHrid, startLevel);
        if (!contextKey) {
            mooncakeRemoveLazyEnhancementBar();
            return;
        }

        if (mooncakeLazyEnhancementContextKey && mooncakeLazyEnhancementContextKey !== contextKey) {
            mooncakeLazyEnhancementManualOverrideKey = '';
            mooncakeLazyEnhancementAutoFillSignature = '';
            mooncakeLazyEnhancementAutoFillAttemptSignature = '';
            mooncakeLazyEnhancementAutoFillAttemptCount = 0;
            mooncakeLazyEnhancementProtectionPickerKey = '';
            mooncakeLazyEnhancementProtectionPickerArmedUntil = 0;
            if (mooncakeLazyEnhancementApplyingKey) mooncakeCancelLazyEnhancementApply();
        }
        mooncakeLazyEnhancementContextKey = contextKey;
        const bar = mooncakeMountLazyEnhancementBar(panel, contextKey);
        mooncakeUpdateLazyEnhancementBar(bar, panel, itemHrid, startLevel);

        const preset = mooncakeFindLazyEnhancementAutoFillPreset(itemHrid, startLevel);
        if (!preset || mooncakeLazyEnhancementManualOverrideKey === contextKey || mooncakeLazyEnhancementApplyingKey) return;
        const signature = mooncakeGetLazyEnhancementPresetSignature(preset);
        if (mooncakeLazyEnhancementAutoFillAttemptSignature !== signature) {
            mooncakeLazyEnhancementAutoFillAttemptSignature = signature;
            mooncakeLazyEnhancementAutoFillAttemptCount = 0;
        }
        if (!signature || signature === mooncakeLazyEnhancementAutoFillSignature) return;
        // A saved target at or below the current item level is already complete.
        // Do not keep retrying it while this panel remains open.
        if (preset.targetLevel <= startLevel) {
            mooncakeLazyEnhancementAutoFillSignature = signature;
            return;
        }
        const draft = mooncakeReadLazyEnhancementDraft(panel);
        if (draft && mooncakeLazyEnhancementPresetsMatch(draft, preset)) {
            mooncakeLazyEnhancementAutoFillSignature = signature;
            mooncakeUpdateLazyEnhancementBar(bar, panel, itemHrid, startLevel);
            return;
        }
        if (!mooncakeFindEnhanceTargetLevelInput(panel)) return;
        if (preset.protectionItemHrid && !mooncakeGetEnhanceProtectionSlot(panel)) return;
        if (mooncakeLazyEnhancementAutoFillAttemptCount >= 2) return;

        mooncakeLazyEnhancementAutoFillSignature = signature;
        mooncakeLazyEnhancementAutoFillAttemptCount += 1;
        void mooncakeApplyLazyEnhancementRecommendation(panel, {
            itemHrid: preset.itemHrid,
            expectedStartLevel: startLevel,
            targetLevel: preset.targetLevel,
            protectAt: preset.protectionItemHrid ? preset.protectionLevel : preset.targetLevel,
            protectionItemHrid: preset.protectionItemHrid
        }, { auto: true }).then(result => {
            if (!result || result.cancelled) return;
            const currentBar = document.getElementById(MOONCAKE_LAZY_ENHANCEMENT_BAR_ID);
            if (currentBar?.dataset.contextKey !== contextKey) return;
            if (
                !result.applied &&
                mooncakeLazyEnhancementManualOverrideKey !== contextKey &&
                mooncakeLazyEnhancementAutoFillAttemptSignature === signature &&
                mooncakeLazyEnhancementAutoFillAttemptCount < 2
            ) {
                mooncakeLazyEnhancementAutoFillSignature = '';
                mooncakeScheduleLazyEnhancement();
            }
            if (!result.applied) {
                mooncakeSetLazyEnhancementBarStatus(
                    result.message || (isZH ? '自动回填失败' : 'Auto-fill failed'),
                    'error'
                );
            }
        });
    }

    function mooncakeScheduleLazyEnhancement() {
        if (!mooncakeIsLazyEnhancementEnabled() || mooncakeLazyEnhancementFrame) return;
        mooncakeLazyEnhancementFrame = requestAnimationFrame(() => {
            mooncakeLazyEnhancementFrame = 0;
            try {
                ensureMooncakeLazyEnhancement();
            } catch (error) {
                console.error('[MoonCake] 懒鬼按钮刷新失败:', error);
            }
        });
    }

    function mooncakeLazyEnhancementNodeTouchesFeature(node) {
        const element = node instanceof Element
            ? node
            : node?.parentElement instanceof Element
                ? node.parentElement
                : null;
        if (!element) return false;
        if (mooncakeIsLazyEnhancementInternalNode(element)) return false;
        const selector = `[class*="EnhancingPanel_enhancingPanel"], ${MOONCAKE_LAZY_ENHANCEMENT_EXTERNAL_CONTROLS_SELECTOR}`;
        return element.matches?.(selector) ||
            !!element.closest?.(selector) ||
            !!element.querySelector?.(selector);
    }

    function mooncakeIsLazyEnhancementInternalNode(node) {
        const element = node instanceof Element
            ? node
            : node?.parentElement instanceof Element
                ? node.parentElement
                : null;
        if (!element) return false;
        const selector = [
            `#${MOONCAKE_ENH_PROTECTION_BUY_ID}`,
            `#${MOONCAKE_ENH_CURRENT_PLAN_ID}`,
            `#${MOONCAKE_ENH_MARKET_PLAN_COLUMN_ID}`,
            `[${MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR}]`,
            `[${MOONCAKE_ENH_COST_MARKET_ATTR}="1"]`
        ].join(', ');
        return element.matches?.(selector) || !!element.closest?.(selector);
    }

    function mooncakeHandleLazyEnhancementMutations(mutations) {
        if (!mooncakeIsLazyEnhancementEnabled()) return;
        for (const mutation of mutations) {
            const changed = [...(mutation.addedNodes || []), ...(mutation.removedNodes || [])];
            // Framed market rows and our own controls mutate the enhancement panel
            // frequently. They do not change the native inputs that lazy fill owns.
            if (changed.length && changed.every(mooncakeIsLazyEnhancementInternalNode)) continue;
            if (mooncakeLazyEnhancementNodeTouchesFeature(mutation.target)) {
                mooncakeScheduleLazyEnhancement();
                return;
            }
            if (changed.some(mooncakeLazyEnhancementNodeTouchesFeature)) {
                mooncakeScheduleLazyEnhancement();
                return;
            }
        }
    }

    function mooncakeHandleLazyEnhancementTrustedEdit(event) {
        if (!mooncakeIsLazyEnhancementEnabled() || event.isTrusted !== true || mooncakeHasExternalEnhancementPresetControls()) return;
        const target = event.target instanceof Element ? event.target : null;
        if (!target || target.closest(`[${MOONCAKE_LAZY_ENHANCEMENT_CONTROL_ATTR}]`)) return;
        if (event.type === 'click' && target.closest('[role="tab"], [class*="NavigationBar_navigationLink"]')) {
            mooncakeScheduleLazyEnhancement();
        }
        const panel = mooncakeFindEnhancingPanel();
        if (!panel || mooncakeIsEnhanceCurrentActionTab(panel)) return;
        const itemHrid = mooncakeGetEnhanceBaseItemHrid(panel);
        const startLevel = mooncakeGetEnhanceBaseItemLevel(panel, false);
        const contextKey = mooncakeGetLazyEnhancementPresetKey(itemHrid, startLevel);
        if (!contextKey) return;

        let changed = false;
        if (event.type === 'input' || event.type === 'change') {
            changed = target === mooncakeFindEnhanceTargetLevelInput(panel) ||
                target === mooncakeFindEnhanceProtectionLevelInput(panel);
        } else if (event.type === 'click') {
            const targetLevelControl = target.closest('[class*="enhancingMaxLevelInputContainer"], [class*="EnhancingMaxLevelInputContainer"]');
            const protectionControl = target.closest('[class*="protectionMinLevelInputContainer"], [class*="ProtectionMinLevelInputContainer"], [class*="protectionItemInputContainer"]');
            if (targetLevelControl && panel.contains(targetLevelControl)) changed = true;
            if (protectionControl && panel.contains(protectionControl)) {
                changed = true;
                mooncakeLazyEnhancementProtectionPickerKey = contextKey;
                mooncakeLazyEnhancementProtectionPickerArmedUntil = Date.now() + 5000;
            }
            if (
                mooncakeLazyEnhancementProtectionPickerKey === contextKey &&
                Date.now() <= mooncakeLazyEnhancementProtectionPickerArmedUntil &&
                target.closest('[class*="ItemSelector_itemList"] [class*="ItemSelector_itemContainer"], [class*="ItemSelector_removeButton"]')
            ) {
                changed = true;
                mooncakeLazyEnhancementProtectionPickerArmedUntil = 0;
            }
        }
        if (!changed) return;
        if (mooncakeLazyEnhancementApplyingKey === contextKey) {
            mooncakeCancelLazyEnhancementApply();
        }
        mooncakeMarkLazyEnhancementManualOverride(panel);
        mooncakeScheduleLazyEnhancement();
    }

    function mooncakeStartLazyEnhancement() {
        if (!mooncakeIsLazyEnhancementEnabled()) return;
        if (!mooncakeLazyEnhancementUnsubscribe) {
            mooncakeLazyEnhancementUnsubscribe = subscribeDocumentMutations(
                'lazy-enhancement',
                mooncakeHandleLazyEnhancementMutations
            );
            document.addEventListener('input', mooncakeHandleLazyEnhancementTrustedEdit, true);
            document.addEventListener('change', mooncakeHandleLazyEnhancementTrustedEdit, true);
            document.addEventListener('click', mooncakeHandleLazyEnhancementTrustedEdit, true);
        }
        mooncakeScheduleLazyEnhancement();
    }

    function mooncakeStopLazyEnhancement() {
        if (mooncakeLazyEnhancementUnsubscribe) {
            mooncakeLazyEnhancementUnsubscribe();
            mooncakeLazyEnhancementUnsubscribe = null;
        }
        document.removeEventListener('input', mooncakeHandleLazyEnhancementTrustedEdit, true);
        document.removeEventListener('change', mooncakeHandleLazyEnhancementTrustedEdit, true);
        document.removeEventListener('click', mooncakeHandleLazyEnhancementTrustedEdit, true);
        if (mooncakeLazyEnhancementFrame) {
            cancelAnimationFrame(mooncakeLazyEnhancementFrame);
            mooncakeLazyEnhancementFrame = 0;
        }
        mooncakeCancelLazyEnhancementApply();
        mooncakeRemoveLazyEnhancementBar();
        mooncakeCloseLazyEnhancementSettingsManager({ restoreFocus: false });
        mooncakeLazyEnhancementContextKey = '';
        mooncakeLazyEnhancementManualOverrideKey = '';
        mooncakeLazyEnhancementAutoFillSignature = '';
        mooncakeLazyEnhancementAutoFillAttemptSignature = '';
        mooncakeLazyEnhancementAutoFillAttemptCount = 0;
        mooncakeLazyEnhancementProtectionPickerKey = '';
        mooncakeLazyEnhancementProtectionPickerArmedUntil = 0;
        mooncakeLazyEnhancementExternalSuppressed = false;
    }

    const MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID = 'mooncake-enhancement-stop-reminder';
    const MOONCAKE_ENHANCEMENT_STOP_REMINDER_STYLE_ID = 'MooncakeEnhancementStopReminderStyle';
    let mooncakeEnhancementStopReminderUnsubscribe = null;
    let mooncakeEnhancementStopReminderFrame = 0;
    let mooncakeEnhancementStopReminderViewportHooked = false;

    function mooncakeIsEnhancementStopReminderEnabled() {
        return config.features?.enhancementStopReminder === true;
    }

    function mooncakeGetEnhancementReminderLevel() {
        const value = Math.round(Number(config.preferences?.enhancementReminderLevel));
        return Number.isFinite(value) ? Math.max(0, Math.min(20, value)) : 0;
    }

    function mooncakeSetEnhancementReminderLevel(value) {
        const parsed = Math.round(Number(String(value ?? '').trim()));
        if (!Number.isFinite(parsed) || parsed < 0 || parsed > 20) return false;
        if (!config.preferences) config.preferences = {};
        config.preferences.enhancementReminderLevel = parsed;
        saveConfig();
        mooncakeScheduleEnhancementStopReminder();
        try { mooncakeRefreshEnhancementSettingsPanel(); } catch (_) {}
        return true;
    }

    function mooncakeSetEnhancementStopReminderEnabled(value) {
        if (!config.features) config.features = {};
        const enabled = value === true;
        const changed = config.features.enhancementStopReminder !== enabled;
        config.features.enhancementStopReminder = enabled;
        if (changed) saveConfig();
        if (enabled) mooncakeStartEnhancementStopReminder();
        else mooncakeStopEnhancementStopReminder();
        try { mooncakeRefreshEnhancementSettingsPanel(); } catch (_) {}
    }

    function mooncakeGetPrimaryRunningEnhanceAction() {
        const firstRunning = mooncakeSortCharacterActions(
            mooncakeCharacterActions.filter(action => action && action.isDone !== true)
        )[0] || null;
        return mooncakeIsWarehouseEnhanceAction(firstRunning) ? firstRunning : null;
    }

    function mooncakeGetEnhancementStopReminderLevel(action) {
        const parsed = parseMooncakeEnhanceItemHash(action?.primaryItemHash || '');
        const level = Number(parsed?.level);
        return Number.isFinite(level) ? Math.max(0, Math.min(20, Math.trunc(level))) : null;
    }

    function mooncakeShouldShowEnhancementStopReminder(level) {
        if (!Number.isFinite(Number(level))) return false;
        const threshold = mooncakeGetEnhancementReminderLevel();
        return threshold === 0 ? Number(level) === 0 : Number(level) < threshold;
    }

    function mooncakeIsUsableTopActionStopButton(button, scope) {
        if (!(button instanceof HTMLButtonElement) || !button.isConnected || !scope?.contains(button)) return false;
        if (button.disabled || button.getAttribute('aria-disabled') === 'true') return false;
        if (!/^(?:停止|stop)$/i.test(String(button.textContent || '').trim())) return false;
        const rect = button.getBoundingClientRect();
        const style = getComputedStyle(button);
        return rect.width > 0 && rect.height > 0 && style.display !== 'none' && style.visibility !== 'hidden';
    }

    function mooncakeFindTopActionStopButton() {
        const scopes = Array.from(document.querySelectorAll('[class*="Header_currentAction"]'));
        for (const scope of scopes) {
            const button = Array.from(scope.querySelectorAll('button')).find(candidate =>
                mooncakeIsUsableTopActionStopButton(candidate, scope)
            );
            if (button) return button;
        }
        return null;
    }

    function mooncakeGetEnhancementStopViewport() {
        const viewport = window.visualViewport;
        return {
            left: Number(viewport?.offsetLeft) || 0,
            top: Number(viewport?.offsetTop) || 0,
            width: Math.max(1, Number(viewport?.width) || window.innerWidth || 1),
            height: Math.max(1, Number(viewport?.height) || window.innerHeight || 1)
        };
    }

    function mooncakeResizeEnhancementStopReminder(overlay, requestedWidth, requestedHeight) {
        if (!overlay) return;
        const viewport = mooncakeGetEnhancementStopViewport();
        const inset = 8;
        const maxWidth = Math.max(120, viewport.width - inset * 2);
        const maxHeight = Math.max(82, viewport.height - inset * 2);
        const minWidth = Math.min(150, maxWidth);
        const minHeight = Math.min(94, maxHeight);
        const width = Math.min(maxWidth, Math.max(minWidth, Number(requestedWidth) || minWidth));
        const height = Math.min(maxHeight, Math.max(minHeight, Number(requestedHeight) || minHeight));
        overlay.style.width = `${Math.round(width)}px`;
        overlay.style.height = `${Math.round(height)}px`;
    }

    function mooncakeClampEnhancementStopReminder(overlay, requestedLeft, requestedTop) {
        if (!overlay) return;
        const viewport = mooncakeGetEnhancementStopViewport();
        const width = overlay.offsetWidth || 176;
        const height = overlay.offsetHeight || 98;
        const inset = 8;
        const minLeft = viewport.left + inset;
        const minTop = viewport.top + inset;
        const maxLeft = Math.max(minLeft, viewport.left + viewport.width - width - inset);
        const maxTop = Math.max(minTop, viewport.top + viewport.height - height - inset);
        const left = Math.min(maxLeft, Math.max(minLeft, Number(requestedLeft) || minLeft));
        const top = Math.min(maxTop, Math.max(minTop, Number(requestedTop) || minTop));
        overlay.style.left = `${Math.round(left)}px`;
        overlay.style.top = `${Math.round(top)}px`;
    }

    function mooncakeEnsureEnhancementStopReminderStyle() {
        if (document.getElementById(MOONCAKE_ENHANCEMENT_STOP_REMINDER_STYLE_ID)) return;
        const style = document.createElement('style');
        style.id = MOONCAKE_ENHANCEMENT_STOP_REMINDER_STYLE_ID;
        style.textContent = `
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} { position:fixed; z-index:2147483644; width:176px; min-width:150px; min-height:94px; max-width:calc(100vw - 16px); max-height:calc(100vh - 16px); display:flex; flex-direction:column; box-sizing:border-box; overflow:hidden; border:1px solid rgba(230,107,116,.62); border-radius:6px; background:#171a23; color:#f2f5ff; box-shadow:0 12px 30px rgba(0,0,0,.48); font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-drag] { min-height:34px; display:flex; align-items:center; justify-content:space-between; gap:8px; padding:7px 9px; box-sizing:border-box; cursor:grab; touch-action:none; user-select:none; border-bottom:1px solid rgba(230,107,116,.24); color:#ffd5d9; font-size:11px; font-weight:800; line-height:1.25; }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-drag]:active { cursor:grabbing; }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-level] { color:#ffbd68; font-variant-numeric:tabular-nums; white-space:nowrap; }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-button] { display:block; flex:1 1 auto; width:calc(100% - 14px); min-height:52px; margin:7px; cursor:pointer; border:1px solid #ff8a92; border-radius:5px; background:#c94751; color:#fff; padding:7px 10px; font:inherit; font-size:16px; font-weight:900; line-height:1.15; letter-spacing:0; }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-button]:hover:not(:disabled) { background:#d6535d; }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-button]:disabled { cursor:not-allowed; opacity:.48; }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-resize] { position:absolute; z-index:3; right:0; bottom:0; display:block; width:32px; height:32px; box-sizing:border-box; cursor:nwse-resize; touch-action:none; user-select:none; -webkit-user-select:none; -webkit-tap-highlight-color:transparent; opacity:.86; }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-resize]::after { content:''; position:absolute; right:6px; bottom:6px; width:12px; height:12px; border-right:2px solid rgba(255,213,217,.94); border-bottom:2px solid rgba(255,213,217,.94); box-shadow:4px 4px 0 -2px rgba(255,213,217,.62); }
            #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-resize]:hover { opacity:1; }
            @media (pointer:coarse) { #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-resize] { width:36px; height:36px; } }
            @media (max-width:480px) { #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} { width:158px; } #${MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID} [data-mooncake-enhancement-stop-button] { min-height:48px; font-size:15px; } }
        `;
        document.head?.appendChild(style);
    }

    function mooncakeSaveEnhancementStopReminderGeometry(overlay) {
        if (!overlay) return;
        const rect = overlay.getBoundingClientRect();
        if (!config.ui) config.ui = {};
        config.ui.enhancementStopReminderPosition = { left: rect.left, top: rect.top };
        config.ui.enhancementStopReminderSize = { width: rect.width, height: rect.height };
        saveConfig();
    }

    function mooncakeBindEnhancementStopReminderDrag(overlay) {
        const handle = overlay.querySelector('[data-mooncake-enhancement-stop-drag]');
        if (!handle) return;
        let drag = null;
        handle.addEventListener('pointerdown', event => {
            if (!event.isPrimary || (event.pointerType === 'mouse' && event.button !== 0)) return;
            const rect = overlay.getBoundingClientRect();
            drag = {
                pointerId: event.pointerId,
                startX: event.clientX,
                startY: event.clientY,
                startLeft: rect.left,
                startTop: rect.top,
                moved: false
            };
            try { handle.setPointerCapture(event.pointerId); } catch (_) {}
            event.preventDefault();
        });
        handle.addEventListener('pointermove', event => {
            if (!drag || event.pointerId !== drag.pointerId) return;
            const deltaX = event.clientX - drag.startX;
            const deltaY = event.clientY - drag.startY;
            if (!drag.moved && Math.hypot(deltaX, deltaY) < 5) return;
            drag.moved = true;
            mooncakeClampEnhancementStopReminder(overlay, drag.startLeft + deltaX, drag.startTop + deltaY);
            event.preventDefault();
        });
        const finish = event => {
            if (!drag || event.pointerId !== drag.pointerId) return;
            const moved = drag.moved;
            try { handle.releasePointerCapture(event.pointerId); } catch (_) {}
            drag = null;
            if (moved) mooncakeSaveEnhancementStopReminderGeometry(overlay);
        };
        handle.addEventListener('pointerup', finish);
        handle.addEventListener('pointercancel', finish);
    }

    function mooncakeBindEnhancementStopReminderResize(overlay) {
        const handle = overlay.querySelector('[data-mooncake-enhancement-stop-resize]');
        if (!handle) return;
        let resize = null;
        handle.addEventListener('pointerdown', event => {
            if (!event.isPrimary || (event.pointerType === 'mouse' && event.button !== 0)) return;
            const rect = overlay.getBoundingClientRect();
            resize = {
                pointerId: event.pointerId,
                startX: event.clientX,
                startY: event.clientY,
                startWidth: rect.width,
                startHeight: rect.height,
                startLeft: rect.left,
                startTop: rect.top,
                moved: false
            };
            try { handle.setPointerCapture(event.pointerId); } catch (_) {}
            event.preventDefault();
            event.stopPropagation();
        });
        handle.addEventListener('pointermove', event => {
            if (!resize || event.pointerId !== resize.pointerId) return;
            const deltaX = event.clientX - resize.startX;
            const deltaY = event.clientY - resize.startY;
            if (!resize.moved && Math.hypot(deltaX, deltaY) < 4) return;
            resize.moved = true;
            mooncakeResizeEnhancementStopReminder(
                overlay,
                resize.startWidth + deltaX,
                resize.startHeight + deltaY
            );
            mooncakeClampEnhancementStopReminder(overlay, resize.startLeft, resize.startTop);
            event.preventDefault();
            event.stopPropagation();
        });
        const finish = event => {
            if (!resize || event.pointerId !== resize.pointerId) return;
            const moved = resize.moved;
            try { handle.releasePointerCapture(event.pointerId); } catch (_) {}
            resize = null;
            if (moved) mooncakeSaveEnhancementStopReminderGeometry(overlay);
            event.preventDefault();
            event.stopPropagation();
        };
        handle.addEventListener('pointerup', finish);
        handle.addEventListener('pointercancel', finish);
    }

    function mooncakeTriggerEnhancementStop() {
        const action = mooncakeGetPrimaryRunningEnhanceAction();
        const level = mooncakeGetEnhancementStopReminderLevel(action);
        if (!action || !mooncakeShouldShowEnhancementStopReminder(level)) return false;
        const nativeButton = mooncakeFindTopActionStopButton();
        if (!nativeButton) return false;
        nativeButton.click();
        return true;
    }

    function mooncakeEnsureEnhancementStopReminder() {
        let overlay = document.getElementById(MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID);
        if (overlay) return overlay;
        mooncakeEnsureEnhancementStopReminderStyle();
        overlay = document.createElement('aside');
        overlay.id = MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID;
        overlay.setAttribute('role', 'status');
        overlay.setAttribute('aria-live', 'polite');
        const handle = document.createElement('div');
        handle.setAttribute('data-mooncake-enhancement-stop-drag', '1');
        handle.title = isZH ? '拖动悬浮按钮' : 'Move floating stop control';
        const label = document.createElement('span');
        label.textContent = isZH ? '强化等级提醒' : 'Enhancement alert';
        const level = document.createElement('span');
        level.setAttribute('data-mooncake-enhancement-stop-level', '1');
        handle.append(label, level);
        const button = document.createElement('button');
        button.type = 'button';
        button.setAttribute('data-mooncake-enhancement-stop-button', '1');
        button.textContent = isZH ? '停止强化' : 'Stop enhancing';
        button.title = isZH ? '停止顶部行动条中的当前强化' : 'Stop the current enhancement in the top action bar';
        button.addEventListener('click', event => {
            if (event.isTrusted !== true) return;
            event.preventDefault();
            event.stopPropagation();
            mooncakeTriggerEnhancementStop();
        });
        const resizeHandle = document.createElement('span');
        resizeHandle.setAttribute('data-mooncake-enhancement-stop-resize', '1');
        resizeHandle.setAttribute('role', 'separator');
        resizeHandle.setAttribute('aria-label', isZH ? '调整提醒浮窗大小' : 'Resize enhancement alert');
        resizeHandle.title = isZH ? '拖动调整大小' : 'Drag to resize';
        overlay.append(handle, button, resizeHandle);
        document.body.appendChild(overlay);
        mooncakeBindEnhancementStopReminderDrag(overlay);
        mooncakeBindEnhancementStopReminderResize(overlay);
        const savedSize = config.ui?.enhancementStopReminderSize;
        if (Number.isFinite(Number(savedSize?.width)) && Number.isFinite(Number(savedSize?.height))) {
            mooncakeResizeEnhancementStopReminder(overlay, Number(savedSize.width), Number(savedSize.height));
        }
        const saved = config.ui?.enhancementStopReminderPosition;
        const viewport = mooncakeGetEnhancementStopViewport();
        const fallbackLeft = viewport.left + viewport.width - (overlay.offsetWidth || 176) - 18;
        const fallbackTop = viewport.top + 110;
        mooncakeClampEnhancementStopReminder(
            overlay,
            Number.isFinite(Number(saved?.left)) ? Number(saved.left) : fallbackLeft,
            Number.isFinite(Number(saved?.top)) ? Number(saved.top) : fallbackTop
        );
        return overlay;
    }

    function mooncakeUpdateEnhancementStopReminder() {
        const action = mooncakeIsEnhancementStopReminderEnabled()
            ? mooncakeGetPrimaryRunningEnhanceAction()
            : null;
        const level = mooncakeGetEnhancementStopReminderLevel(action);
        if (!action || !mooncakeShouldShowEnhancementStopReminder(level)) {
            document.getElementById(MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID)?.remove();
            return;
        }
        const overlay = mooncakeEnsureEnhancementStopReminder();
        const threshold = mooncakeGetEnhancementReminderLevel();
        const levelNode = overlay.querySelector('[data-mooncake-enhancement-stop-level]');
        if (levelNode) {
            levelNode.textContent = threshold === 0
                ? `+${level}`
                : `+${level} / +${threshold}`;
        }
        const button = overlay.querySelector('[data-mooncake-enhancement-stop-button]');
        if (button) {
            const available = !!mooncakeFindTopActionStopButton();
            button.disabled = !available;
            button.setAttribute('aria-disabled', String(!available));
            button.textContent = available
                ? (isZH ? '停止强化' : 'Stop enhancing')
                : (isZH ? '等待行动条' : 'Waiting for action bar');
        }
        const rect = overlay.getBoundingClientRect();
        mooncakeClampEnhancementStopReminder(overlay, rect.left, rect.top);
    }

    function mooncakeScheduleEnhancementStopReminder() {
        if (!mooncakeIsEnhancementStopReminderEnabled() || mooncakeEnhancementStopReminderFrame) return;
        mooncakeEnhancementStopReminderFrame = requestAnimationFrame(() => {
            mooncakeEnhancementStopReminderFrame = 0;
            mooncakeUpdateEnhancementStopReminder();
        });
    }

    function mooncakeEnhancementStopMutationRelevant(node) {
        const element = node instanceof Element
            ? node
            : node?.parentElement instanceof Element
                ? node.parentElement
                : null;
        if (!element) return false;
        const selector = '[class*="Header_currentAction"], [class*="Header_stopButtonContainer"], [class*="Header_myActions"]';
        return element.matches?.(selector) || !!element.closest?.(selector) || !!element.querySelector?.(selector);
    }

    function mooncakeHandleEnhancementStopMutations(mutations) {
        if (!mooncakeIsEnhancementStopReminderEnabled()) return;
        for (const mutation of mutations) {
            if (mooncakeEnhancementStopMutationRelevant(mutation.target) ||
                [...(mutation.addedNodes || []), ...(mutation.removedNodes || [])].some(mooncakeEnhancementStopMutationRelevant)) {
                mooncakeScheduleEnhancementStopReminder();
                return;
            }
        }
    }

    function mooncakeHandleEnhancementStopViewportChange() {
        const overlay = document.getElementById(MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID);
        if (!overlay) return;
        const rect = overlay.getBoundingClientRect();
        mooncakeResizeEnhancementStopReminder(overlay, rect.width, rect.height);
        mooncakeClampEnhancementStopReminder(overlay, rect.left, rect.top);
    }

    function mooncakeStartEnhancementStopReminder() {
        if (!mooncakeIsEnhancementStopReminderEnabled()) return;
        if (!mooncakeEnhancementStopReminderUnsubscribe) {
            mooncakeEnhancementStopReminderUnsubscribe = subscribeDocumentMutations(
                'enhancement-stop-reminder',
                mooncakeHandleEnhancementStopMutations
            );
        }
        if (!mooncakeEnhancementStopReminderViewportHooked) {
            window.addEventListener('resize', mooncakeHandleEnhancementStopViewportChange, { passive: true });
            window.visualViewport?.addEventListener('resize', mooncakeHandleEnhancementStopViewportChange, { passive: true });
            mooncakeEnhancementStopReminderViewportHooked = true;
        }
        mooncakeScheduleEnhancementStopReminder();
    }

    function mooncakeStopEnhancementStopReminder() {
        if (mooncakeEnhancementStopReminderUnsubscribe) {
            mooncakeEnhancementStopReminderUnsubscribe();
            mooncakeEnhancementStopReminderUnsubscribe = null;
        }
        if (mooncakeEnhancementStopReminderViewportHooked) {
            window.removeEventListener('resize', mooncakeHandleEnhancementStopViewportChange);
            window.visualViewport?.removeEventListener('resize', mooncakeHandleEnhancementStopViewportChange);
            mooncakeEnhancementStopReminderViewportHooked = false;
        }
        if (mooncakeEnhancementStopReminderFrame) {
            cancelAnimationFrame(mooncakeEnhancementStopReminderFrame);
            mooncakeEnhancementStopReminderFrame = 0;
        }
        document.getElementById(MOONCAKE_ENHANCEMENT_STOP_REMINDER_ID)?.remove();
    }

