    function mooncakeCreateEnhancementSettingsSection(title, description = '') {
        const section = document.createElement('section');
        section.setAttribute('data-mooncake-enhancement-settings-section', '1');
        const heading = document.createElement('div');
        heading.setAttribute('data-mooncake-enhancement-settings-section-heading', '1');
        const titleNode = document.createElement('h3');
        titleNode.textContent = title;
        heading.appendChild(titleNode);
        if (description) {
            const descriptionNode = document.createElement('p');
            descriptionNode.textContent = description;
            heading.appendChild(descriptionNode);
        }
        const rows = document.createElement('div');
        rows.setAttribute('data-mooncake-enhancement-settings-rows', '1');
        section.append(heading, rows);
        return { section, rows };
    }

    function mooncakeCreateEnhancementSettingsToggle(key, title, description, titleText = '', rowTag = 'label') {
        const isStandaloneControlRow = rowTag === 'div';
        const row = document.createElement(isStandaloneControlRow ? 'div' : 'label');
        row.setAttribute('data-mooncake-enhancement-settings-row', '1');
        row.setAttribute('data-mooncake-enhancement-settings-row-kind', 'toggle');
        row.title = titleText;
        const text = document.createElement('span');
        text.setAttribute('data-mooncake-enhancement-settings-row-copy', '1');
        const strong = document.createElement('strong');
        strong.textContent = title;
        const detail = document.createElement('small');
        detail.textContent = description;
        text.append(strong, detail);
        const right = document.createElement('span');
        right.setAttribute('data-mooncake-enhancement-settings-row-control', '1');
        const state = document.createElement('span');
        state.setAttribute('data-mooncake-enhancement-settings-toggle-state', key);
        const input = document.createElement('input');
        input.type = 'checkbox';
        input.checked = mooncakeGetEnhancementSettingsToggleValue(key);
        input.setAttribute('role', 'switch');
        input.setAttribute('aria-label', title);
        input.setAttribute('data-mooncake-enhancement-settings-toggle', key);
        right.append(state, input);
        row.append(text, right);
        if (isStandaloneControlRow) {
            text.style.cursor = 'pointer';
            text.addEventListener('click', () => input.click());
        }
        return row;
    }

