        const donationRanking = document.createElement('section');
        donationRanking.setAttribute('data-mooncake-enhancement-settings-donation-ranking', '1');
        const donationRankingHeader = document.createElement('div');
        donationRankingHeader.setAttribute('data-mooncake-enhancement-settings-donation-ranking-header', '1');
        const donationRankingTitle = document.createElement('strong');
        donationRankingTitle.textContent = isZH ? '赞助鸣谢列表' : 'Supporter acknowledgements';
        const donationRankingControls = document.createElement('div');
        donationRankingControls.setAttribute('data-mooncake-enhancement-settings-donation-ranking-controls', '1');
        const donationRankingNote = document.createElement('span');
        donationRankingNote.setAttribute('data-mooncake-enhancement-settings-donation-ranking-note-status', '1');
